window.JASTROW_CHUNKS[28]={"11200":{"h":"חכינותא","r":"H00927","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲבֵרוּת\">חֲבִי׳</a></div>","alt":[]},"11201":{"h":"חֲכִינָנָא","r":"H00928","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חֲכִינָא\">חֲכִינָא</a>) <i>wound, snake-like; insidious</i>. <span class=\"citation\">Targ. Prov. XVIII, 8</span> Var. ed. Lag. (ed. Lag. a. oth. <a href=\"#\" data-headword=\"חבננא\">חבננא</a>, oth. ed. <a href=\"#\" data-headword=\"שִׁיגּוּשׁ\">שיגושא</a>; h. text <span dir=\"rtl\">נרגן</span>).</div>","alt":[]},"11202":{"h":"חֲכִינְתָּה","r":"H00929","html":"<div class=\"sense\"> f. ch. = h. <a href=\"#\" data-headword=\"חֲכִינָה\">חֲכִינָה</a>. <span class=\"citation\">Y. Sabb. VI, end, 8ᵈ</span></div>","alt":[]},"11203":{"h":"חַכִּיר","r":"H00930","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">חכר</span>, cmp. <span dir=\"rtl\">חכינא</span>) <i>bent, bowed down</i>. <span class=\"citation\">Targ. Ps. XXXV, 14</span>; <span class=\"citation\">XXXVIII, 7</span> (Ar. <a href=\"#\" data-headword=\"הֲבִיר\">הֲבִיר</a>; Ms. <a href=\"#\" data-headword=\"חַמָּר I\"><span dir=\"rtl\">חַמָּר</span> I</a>).</div>","alt":["חֲכִיר"]},"11204":{"h":"חָכִיר","r":"H00931","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָכַר\">חָכַר</a>) </div><div class=\"sense\"><b>1)</b> <i>tenant</i> on a fixed rent payable in kind, v. <a href=\"#\" data-headword=\"אָרִיס II\"><span dir=\"rtl\">אָרִיס</span> II</a>. <span class=\"citation\">Y. Bicc. I, end, 64ᵇ</span> <span dir=\"rtl\">ח׳ לשעה</span> a tenant for a fixed term, <span dir=\"rtl\">ח׳ לעולם</span> a permanent tenant (on ground rent). <span class=\"citation\">B. Mets. 104ᵃ</span> <a href=\"#\" data-headword=\"חוֹכֵר\">חוֹכֵר</a>; a. fr.—Pl. <span dir=\"rtl\">חֲכִירִין</span>, <span dir=\"rtl\">חֲכוּ׳</span>, <a href=\"#\" data-headword=\"חֲכִירוּת\">חֲכִירוֹת</a>, <span dir=\"rtl\">(<span dir=\"rtl\">חוֹכְרִין</span>) <a href=\"#\" data-headword=\"חֲכִירוּת\">חֲכוּרוֹת</a></span>. Y. Bicc. l. c. <span dir=\"rtl\">חֲכוּרֵי בתי אבות</span> hereditary tenants. <span class=\"citation\">Tosef. Peah III, 1</span>. Ib. <span class=\"citation\">Ter. II, 11</span> <span dir=\"rtl\">חוכרין</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"חֲכִירוּת\">חכורות</a>, <a href=\"#\" data-headword=\"חֲכִירוּת\">חכירות</a>). Y. M. Kat. III, 82ᵇ bot. <span dir=\"rtl\">חֲכִירָיו</span>.</div><div class=\"sense\"><b>—2)</b> <i>the fixed annual rent in kind</i>. <span class=\"citation\">B. Mets. IX, 2</span> (<span class=\"citation\">103ᵇ</span>) <span dir=\"rtl\">מנכה לו מן חֲכִירוֹ</span> Talm. ed. (Mish. <span dir=\"rtl\">חֲכוּ׳</span>) he deducts from the stipulated rent (in proportion). Ib. 4 (105ᵃ) <span dir=\"rtl\">הואיל ואני נותן לך חֲכִירְךָ</span> (Y. ed. <span dir=\"rtl\">חֲכוּרְךָ</span>, Mish. <span dir=\"rtl\">חֲכוּרָהּ</span>) as long as I give thee thy rent (Mish.: the rent for it).</div>","alt":["חָכוּר"]},"11205":{"h":"חֲכִירָא","r":"H00932","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">חֲכִירֵי</span>. <span class=\"citation\">B. Mets. 68ᵃ</span>, v. <a href=\"#\" data-headword=\"נַרְשָׁאָה\">נַרְשָׁאָה</a>.</div>","alt":[]},"11206":{"h":"חכירא","r":"H00933","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֲבִירָא\">הֲבִירָא</a></div>","alt":["חכיריא"]},"11207":{"h":"חֲכִירוּת","r":"H00934","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָכִיר\">חָכִיר</a>) </div><div class=\"sense\"><b>1)</b> <i>tenancy, tenure</i> on rent in kind. <span class=\"citation\">Bicc. I, 11</span> בעלי אריסות וח׳ <i>landlords</i> of properties held in tenure, on shares, or on fixed rent; or <i>tenants</i> on &amp;c.; expl. Y. ib. 64ᵇ either <span dir=\"rtl\">חכירי בתי אבות</span> (v. <a href=\"#\" data-headword=\"חָכִיר\">חָכִיר</a>), or <span dir=\"rtl\">בעלי אריסיות וחֲכִירִיּוֹת</span> (not <span dir=\"rtl\">וחכורות</span>).</div><div class=\"sense\"><b>—2)</b> <i>stipulated rent</i>. <span class=\"citation\">Tosef. B. Mets. IX, 24</span> ח׳ של שתי שנים Var. (ed. Zuck. only <span dir=\"rtl\">חכורי</span>) the rent for two years in advance.—Pl. <span dir=\"rtl\">חֲכִירִיּוֹת</span>, v. supra.</div>","alt":["(חֲכוּרוּת)"]},"11208":{"h":"חָכַךְ I","r":"H00935","html":"<div class=\"sense\"> (v. Fl. to Levy Talm. Dict. II, 204<sup>2</sup>) </div><div class=\"sense\"><b>1)</b> <i>to restrain, fasten, hook</i>.—Denom. <a href=\"#\" data-headword=\"חַכָּה\">חַכָּה</a>.</div><div class=\"sense\"><b>—2)</b> <i>to grasp</i> (one another), <i>to wrestle</i>; v. <a href=\"#\" data-headword=\"*חָבַב II\"><span dir=\"rtl\">חָבַב</span> II</a>.</div>","alt":[]},"11209":{"h":"חָכַךְ II","r":"H00936","html":"<div class=\"sense\"> (onomatop.) </div><div class=\"sense\"><b>1)</b> <i>to be rough; to rub, scratch</i>. <span class=\"citation\">Naz. 59ᵃ</span> <span dir=\"rtl\">מהו לָחוֹךְ</span> how about (removing the hair by) rubbing (Tosaf.: <span dir=\"rtl\">לחוך ולהִתְחַכֵּךְ</span> about rubbing or being rubbed)?</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"חָרַט\">חָרַט</a>, a. <a href=\"#\" data-headword=\"*חַיָּיךְ\">חַיָּיךְ</a>) <i>to hesitate</i>. <span class=\"citation\">Ned. I, 1</span> <span dir=\"rtl\">היה חוֹכֵךְ בזה להחמיר</span> had some hesitation about deciding in favor of greater stringency (for the expression <span dir=\"rtl\">מנודה</span>; oth. opin. in R. N. to Bab. <span class=\"citation\">ib. 7ᵃ</span>: denom. of <a href=\"#\" data-headword=\"חֵךְ\">חֵךְ</a>, <i>had a taste for</i></div><div class=\"sense\"><b>Hithpa. הִתְחַכִּךְ</b> </div><div class=\"sense\"><b>Nithpa. נִתְחַכֵּךְ</b> <div class=\"sense\"><i>to rub one’s self against a rough object; to be rubbed</i>. <span class=\"citation\">B. Kam. IV, 6</span> <span dir=\"rtl\">שור שהיה מִתְחַכֵּךְ וכ׳</span> an ox that scratched himself against a wall; <span class=\"citation\">Tosef. ib. IV, 6</span>. <span class=\"citation\">B. Kam. 3ᵃ</span> <span dir=\"rtl\">נִתְחַכְּכָה וכ׳</span> she (the animal) scratched herself against a wall for her gratification (without intention to do injury) &amp;c.—<span class=\"citation\">Naz. 59ᵃ</span>, v. supra; a. fr.</div></div><div class=\"sense\"><b>Pi. חִיכֵּךְ</b> <div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חוּךְ II\"><span dir=\"rtl\">חוּךְ</span> II</a>) <i>to hawk; to deride</i>. <span class=\"citation\">Gen. R. s. 67</span> (play on <a href=\"#\" data-headword=\"הָכִי\">הכי</a>, <span class=\"citation\">Gen. XXVII, 36</span>) <span dir=\"rtl\">התחיל מְחַכֵּךְ בגרונו וכ׳</span> he began to hawk with his throat (to express contempt), like one that hawks and spits; Tanḥ. Ki Thetsé 10; Pesik. Zakh., p. 27ᵇ, v. <a href=\"#\" data-headword=\"זְמוֹרָה\">זְמוֹרָה</a>; [Ar. ed. Koh. s. v. <span dir=\"rtl\">זמר</span>: <span dir=\"rtl\">חִיכְחֵךְ</span>, <i>Pilp</i>.]—Cmp. <a href=\"#\" data-headword=\"כָּחַח\">כָּחַח</a>.</div></div>","alt":[]},"11210":{"h":"חֲכַךְ","r":"H00937","html":"<div class=\"sense\"><i>Ithpa.</i> <a href=\"#\" data-headword=\"מְכַךְ\">אִתְחַכֵּךְ</a> as <a href=\"#\" data-headword=\"חָכַךְ II\">preced.</a> <i>Hithpa.</i> <span class=\"citation\">B. Kam. 44ᵃ</span>.</div>","alt":[]},"11211":{"h":"חֲכָךְ","r":"H00938","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲכַךְ\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>scab, sore;</i> trnsf. <i>tribulation, visitation</i>. <span class=\"citation\">Y. M. Kat. III, 81ᵈ</span> top; (<span class=\"citation\">B. Mets. 59ᵇ</span> <a href=\"#\" data-headword=\"אַךְ I\">אַךְ</a>, Var. <a href=\"#\" data-headword=\"אַף I\">אַף</a>).—Pl. <span dir=\"rtl\">חֲכָכִים</span> <i>inflammations</i>. <span class=\"citation\">Gen. R. s. 19</span>, beg. (v., however, <a href=\"#\" data-headword=\"אַכְאָבִית\">אַבְאָבִית</a>).</div><div class=\"sense\"><b>—2)</b> <i>cough, catarrh</i>. <span class=\"citation\">Y. Snh. X, 29ᵇ</span> bot. <span dir=\"rtl\">בתחלה הוא … ח׳</span> first He causes a cold to enter them; (Tanḥ., ed. Bub., R’eh 10 <a href=\"#\" data-headword=\"חִיכּוּךְ\">חִיכּוּךְ</a>); Pesik. Asser 97ᵇ <span dir=\"rtl\">הקב&quot;ה ח׳</span> (insert <span dir=\"rtl\">מכניס בהם</span>); v. <a href=\"#\" data-headword=\"וָהּ\">וָהּ</a>.</div>","alt":[]},"11212":{"h":"חָכַם","r":"H00939","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"חָכָם\">חָכָם</a>) </div><div class=\"sense\"><b>1)</b> <i>to be wise, to know</i>. <span class=\"citation\">Nidd. 70ᵇ</span> <span dir=\"rtl\">מה יעשה אדם ויֶחְכַּם</span> what must one do in order to be wise?</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"חָכָם\">חָכָם</a>) <i>to meet for deliberation</i>. Ib. <span dir=\"rtl\">לכשיחיו נֶחְכַּם להן</span> when they resurrect, we shall meet to discuss their case.</div><div class=\"sense\"><b>Hif. הֶחְכִּים</b> <div class=\"sense\"><b>1)</b> <i>to grow wise, to become a scholar</i>. <span class=\"citation\">B. Bath. 25ᵇ</span> <span dir=\"rtl\">הרוצה שיַחְכִּים</span> he who desires to become a scholar; <span class=\"citation\">ib. 175ᵇ</span> (<span class=\"citation\">Ber. 63ᵇ</span> <span dir=\"rtl\">שיִתְחַכֵּם</span>). <span class=\"citation\">Ab. II, 5</span> … <span dir=\"rtl\">לא כל … מַחְכִּים</span> not every one that has a large trade, becomes wise (experienced); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to make wise, to stimulate a person’s mind by ingenious suggestions, questions</i> &amp;c. <span class=\"citation\">Ḥag. 14ᵃ</span> <span dir=\"rtl\">תלמיד המַחְכִּים וכ׳</span> a student who enlightens his teachers. <span class=\"citation\">B. Mets. 107ᵇ</span> <span dir=\"rtl\">ומַחְכִּימַת פתי</span> and makes the simple wise.</div><div class=\"sense\"><b>—3)</b> <i>to subtilize, philosophize</i>. <span class=\"citation\">Ex. R. s. 6</span>, beg. <span dir=\"rtl\">ה׳ על גזרתו וכ׳</span> philosophized on (tried to find out the reasons for) the Lord’s law. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מה שהייתי מַחְכִּים וכ׳</span></div></div><div class=\"sense\"><b>Hithpa. הִתְחַכֵּם</b> </div><div class=\"sense\"><b>Nithpa. נִתְחַכֵּם</b> <div class=\"sense\"><i>to become wise</i>. <span class=\"citation\">Ber. 63ᵇ</span>, v. supra. <span class=\"citation\">B. Bath. 25ᵇ</span> <span dir=\"rtl\">מתוך שמִתְחַכֵּם מתעשר</span> because by becoming wise, he will get rich. <span class=\"citation\">Pesik. R. s. 33</span> beg. <span dir=\"rtl\">מאליו נתח׳</span> became wise by his own speculation.</div></div>","alt":[]},"11213":{"h":"חֲכַם","r":"H00940","html":"<div class=\"sense\"> (adj. with verbal inflection) </div><div class=\"sense\"><b>1)</b> <i>to be wise, shrewd; to be learned</i>. <span class=\"citation\">Targ. I Kings V, 11</span>. <span class=\"citation\">Targ. O. Ex. XV, 8</span> <span dir=\"rtl\">חֲכִימוּ</span> (<span dir=\"rtl\">חַכִּ׳</span>, h. text <span dir=\"rtl\">נערמו</span>!). <span class=\"citation\">Targ. Is. XXIX, 16</span>; a. fr.—<span class=\"citation\">Gitt. 56ᵇ</span> <span dir=\"rtl\">דחַכְמִיתוּ וכ׳</span> that you are so wise. <span class=\"citation\">Taan. 23ᵇ</span> <span dir=\"rtl\">דנִיחְכִּים טובא</span> that we may become well-learned; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to recognize, to know, remember</i>. <span class=\"citation\">Targ. Y. II, Gen. XXXVII, 33</span> (some ed. <a href=\"#\" data-headword=\"חָכַם\">חַכַּם</a> <i>Pa.</i>).—Targ. II Esth. II, 18; a. fr.—<span class=\"citation\">Lev. R. s. 30</span> <span dir=\"rtl\">ח׳ את וכ׳</span> doest thou know anything in favor of this man?—Y. M. Kat. III, 83ᵇ top, v. <a href=\"#\" data-headword=\"בְּאַר\">בְּאַר</a>—<span class=\"citation\">Y. Ber. II, 4ᵈ</span> top <span dir=\"rtl\">וחַכְמִין אינון כלום</span> do they (the dead) know anything?—<span class=\"citation\">Y. Shek. VII, 50ᶜ</span> bot. <span dir=\"rtl\">יֶחְכְּמוּן שפייא קיטריהון</span> let the wine-dealers identify their knots (marks on the wine bottles). <span class=\"citation\">Y. Keth. V, 30ᵃ</span> bot. [read:] <span dir=\"rtl\">חֲכִים אנא לחייתא דמילדא לי</span> (or <a href=\"#\" data-headword=\"חֲכַם\">חַכִּים</a>) I (as an infant) recognized the midwife that assisted at my birth (when she came to nurse my mother). <span class=\"citation\">Y. Ter. XI, end, 48ᵇ</span> לא אנא ח׳ לאבא I never knew my father. <span class=\"citation\">Y. Ḥag. II, 78ᵃ</span> top <span dir=\"rtl\">יַחְכּוּם</span> shall select (Y. Snh. VI, 23ᵃ bot. <span dir=\"rtl\">יטול</span>), v. <a href=\"#\" data-headword=\"זוֹגָא\">זוֹגָא</a>.—2) (euphem. = b. h. <a href=\"#\" data-headword=\"יָדַע\">יָדַע</a>) <i>to sleep with</i>. <span class=\"citation\">Targ. Y. Gen. IV, 1</span> Ar. (ed. <span dir=\"rtl\">ידע</span>). Targ. Y. II ib. XX, 16; a. e.—Y. Maas. Sh. IV, 55ᵇ bot.; <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד כותאי 1) a.e.</div><div class=\"sense\"><b>—3)</b> <i>to be clear, evident</i>. <span class=\"citation\">Snh. 42ᵃ</span>, v. <a href=\"#\" data-headword=\"זָקֵן I\"><span dir=\"rtl\">זָקֵן</span> I</a>.</div><div class=\"sense\"><b>Pa. חַכֵּים</b> <div class=\"sense\"><b>1)</b> <i>to make wise, teach</i>. <span class=\"citation\">Targ. Y. Deut. XXXIV, 10</span>. <span class=\"citation\">Targ. Job XXXV, 11</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to outwit</i>. <span class=\"citation\">Targ. O. Gen. XXVII, 36</span> (Rashi a. l. quotes <span dir=\"rtl\">וכמני</span>, v. <a href=\"#\" data-headword=\"כְּמַן\">כְּמַן</a>, v. Berl. Targ. O. II, p. 10).</div></div><div class=\"sense\"><b>Ithpa. אִתְחַכֵּים</b> <div class=\"sense\"><b>1)</b> <i>to become wise</i>. <span class=\"citation\">Targ. Ps. CV, 22</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be informed, aware; to learn</i>. Ib. XXXV, 8. <span class=\"citation\">Targ. Y. Ex. II, 4</span>.</div><div class=\"sense\"><b>—3)</b> <i>to hold counsel</i>. <span class=\"citation\">Targ. O. Ex. I, 10</span>.</div><div class=\"sense\"><b>—4)</b> <i>to be recognized</i>. Y. Sot. IX, 23ᶜ bot.; Y. Yeb. XVI, 15ᶜ <span dir=\"rtl\">מאן דבעי דלא מִתְחַכְּמָה</span> he who desires to disguise himself; <span dir=\"rtl\">לא מִתְחַכְּמִין</span> they were not recognized, v. <a href=\"#\" data-headword=\"נְחִירָא\">נְחִירָא</a>.</div></div><div class=\"sense\"><b>Af. אַחְכִּים</b> <div class=\"sense\"><i>to teach, make wise</i>. <span class=\"citation\">Targ. Ez. III, 2</span>; a. e.—<span class=\"citation\">B. Bath. 158ᵇ</span> <span dir=\"rtl\">אוירא דא&quot;י מַהְכּים</span> the climate of Palestine makes wise.</div></div>","alt":["חֲכִים","חַכִּים"]},"11214":{"h":"חָכָם","r":"H00941","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. Fl. to Levy Talm. Dict. II, 204<sup>2</sup>) [<i>retentive</i>,] </div><div class=\"sense\"><b>1)</b> <i>one who knows</i>. <span dir=\"rtl\">חֲכַם הרזים</span> He who knows the secrets (minds of men). <span class=\"citation\">Ber. 58ᵃ</span>; Tosef. ib. VII (VI), 2; <span class=\"citation\">Num. R. s. 21</span>, beg.</div><div class=\"sense\"><b>—2)</b> <i>wise man, scholar;</i> esp. <i>Ḥakham</i>, a scholar’s title, less than Rabbi. <span class=\"citation\">Ab. IV, 1</span> <span dir=\"rtl\">איזהו ח׳</span> who is a wise man? <span class=\"citation\">Snh. 21ᵃ</span> (ref. to <span class=\"citation\">II Sam. XIII, 3</span>) <span dir=\"rtl\">איש ח׳ לרשעה</span> a man wise for wickedness (artful). <span class=\"citation\">Gitt. 67ᵃ</span> <span dir=\"rtl\">ח׳ וסופר</span> is a scholar and a scribe; <span dir=\"rtl\">ח׳ לכשירצה</span> might be a scholar, if he wanted. <span class=\"citation\">Hor. 13ᵇ</span> ר&quot;מ ח׳ R. M. was the <i>Ḥakham</i> (counselor); a. v. fr.—Pl. <span dir=\"rtl\">חֲכָמִים</span>, frequ. in the sense of <i>a number of scholars</i>, as opposed to a single authority. <span class=\"citation\">Ḥull. 85ᵃ</span> ראה רבי … ושנאו בלשון ח׳ Rabbi approving of R. Meir’s opinion …, recorded it in the Mishnah as the opinion of ‘scholars’. <span class=\"citation\">Ber. I, 1</span>; a. v. fr.—<span dir=\"rtl\">חַכְמֵי אומות העולם</span> gentile scholars (philosophers), <span dir=\"rtl\">חכמי ישראל</span> Jewish scholars. <span class=\"citation\">R. Hash. 12ᵃ</span>. <span class=\"citation\">Pes. 94ᵇ</span>; a. fr.—<span dir=\"rtl\">תַּלְמִיד חָכָם</span> (= <span dir=\"rtl\">תלמיד וח׳</span>, cmp. <a href=\"#\" data-headword=\"חָבֵר\">חָבֵר</a>, abbr. <span dir=\"rtl\">ת&quot;ח</span>) title of a student, <i>disciple, scholar</i>. <span class=\"citation\">Ḥag. 15ᵇ</span> <span dir=\"rtl\">ת&quot;ח אע&quot;פ שסרח וכ׳</span> a scholar’s learning is not to be despised, even if he has gone astray. <span class=\"citation\">Ḥull. 9ᵃ</span> <span dir=\"rtl\">ת&quot;ח צריך וכ׳</span> in order to be recognised as a <i>Talmid Ḥakham</i>, one must have learned three things &amp;c.; a. v. fr.—Pl. <span dir=\"rtl\">תַּלְמִידֵי חֲכָמִים</span>. <span class=\"citation\">Ber. 64ᵃ</span> <span dir=\"rtl\">ת&quot;ה מרבים וכ׳</span> scholars increase the peace of the world; a. v. fr.</div>","alt":[]},"11215":{"h":"חכם","r":"H00942","html":"<div class=\"sense\">, <span class=\"citation\">Y. Erub. IX, end, 25ᵈ</span> <span dir=\"rtl\">והח׳</span>, read <span dir=\"rtl\">והחמם</span>, v. <a href=\"#\" data-headword=\"חֲמָם\">חֲמָם</a></div>","alt":[]},"11216":{"h":"חָכְמָא","r":"H00943","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוּכְמָא\">חוּכְמָא</a></div>","alt":[]},"11217":{"h":"חַכְמַאי","r":"H00944","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḥakhmai</i>. <span class=\"citation\">M. Kat. 9ᵃ</span> bot. <span dir=\"rtl\">ר׳ יונתן בן ח׳</span> Ms. M. (ed. <span dir=\"rtl\">עסמיי</span>, read: <span dir=\"rtl\">עכ׳</span>); <span class=\"citation\">Y. Ter. XI, end, 48ᵇ</span> <a href=\"#\" data-headword=\"עַכְמַאי\">עַכְמַאי</a>.</div>","alt":[]},"11218":{"h":"חֲכָמָה","r":"H00945","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  fem. of <a href=\"#\" data-headword=\"חָכָם\">חָכָם</a>. <span class=\"citation\">Y. Shek. V, 48ᵈ</span> top <span dir=\"rtl\">הרי זו ח׳</span> that is a wise court; <span class=\"citation\">Snh. 17ᵇ</span> <span dir=\"rtl\">שלישית ח׳</span> a Sanhedrin containing three orators is a wise one.</div><div class=\"sense\"><b>—2)</b> <i>female physician, midwife</i>. <span class=\"citation\">R. Hash. II, 5</span>; <span class=\"citation\">Erub. 45ᵃ</span> <span dir=\"rtl\">ח׳ הבאה לילד</span> a midwife called for assisting at birth. <span class=\"citation\">Sabb. XVIII, 3</span> <span dir=\"rtl\">וקורין לה ח׳ וכ׳</span> and we must call for her a midwife from another place (on the Sabbath); a. fr.</div>","alt":[]},"11219":{"h":"חָכְמָה","r":"H00946","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>wisdom, learning, art</i>. <span class=\"citation\">Ber. 17ᵃ</span> <span dir=\"rtl\">תכלית ח׳ וכ׳</span> the perfection of wisdom is repentance and good deeds. <span class=\"citation\">Ib. 33ᵃ</span> <span dir=\"rtl\">ברכת ח׳</span> the benediction of wisdom (the fourth of the Prayer of Benedictions). <span class=\"citation\">Gen. R. s. 17</span> <span dir=\"rtl\">חָכְמָתוֹ מרובה וכ׳</span> his (Adam’s) wisdom is greater than yours. <span class=\"citation\">R. Hash. 29ᵇ</span> <span dir=\"rtl\">שהיא ח׳ ואינה מלאכה</span> it is an art and not a labor; a. v. fr.—לשון ח׳ <i>enigmatical speech</i>. <span class=\"citation\">Erub. 53ᵇ</span>.—<span dir=\"rtl\">חָכְמַת יונית</span>, v. <a href=\"#\" data-headword=\"יְוָנִי\">יְוָנִי</a>.</div>","alt":[]},"11220":{"h":"חַכְמָנִית","r":"H00947","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָכְמָה\">preced.</a>) <i>well-educated, smart.</i> <i>—</i> Pl. <span dir=\"rtl\">חַכְמָנִיּוֹת</span>. <span class=\"citation\">B. Bath. 119ᵇ</span></div>","alt":[]},"11221":{"h":"חָכְמְתָא","r":"H00948","html":"<div class=\"sense\">, v. <span dir=\"rtl\">חוּכְ׳</span></div>","alt":[]},"11222":{"h":"חכן","r":"H00949","html":"<div class=\"sense\">, <span class=\"citation\">Y. Erub. VI, 23ᵈ</span> bot., read <a href=\"#\" data-headword=\"הָכֵן\">הָכֵן</a>.</div>","alt":[]},"11223":{"h":"חָכַר","r":"H00950","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"חָכַךְ I\">חָכַךְ</a>) <i>to contract, farm</i>, esp. <i>to give</i> or <i>to take in rent on a fixed annual rental payable in kind</i>, contrad. to <a href=\"#\" data-headword=\"אָרַס\">אָרַס</a>, <a href=\"#\" data-headword=\"שָׂכַר\">שָׂכַר</a> or <a href=\"#\" data-headword=\"קָבַל I\">קִבֵּל</a> q. v.—<span class=\"citation\">B. Mets. IX, 2</span> <span dir=\"rtl\">חֲכוֹר לי וכ׳</span> give me in rent &amp;c. <span class=\"citation\">Tosef. Dem. VI, 2</span> <span dir=\"rtl\">החוֹכֵר שדה</span> if one takes in rent a field. Ib. <span dir=\"rtl\">מה בין שוכר לחוכר</span> what is the difference between the <i>sokher</i> and the <i>ḥokher?;</i> a. fr.—V. <a href=\"#\" data-headword=\"חָכִיר\">חָכִיר</a>.</div><div class=\"sense\"><b>Hif. הֶחְכִּיר</b> <div class=\"sense\"><i>to give in rent.</i> <i> Part.</i> מַחְכִּיר <i>landlord</i>. <span class=\"citation\">B. Mets. 104ᵃ</span>; a. e.—<i>Part. pass</i>. <span dir=\"rtl\">מוּחְכָּר</span>, f. <span dir=\"rtl\">מוּחְכֶּרֶת</span>. <span class=\"citation\">B. Bath. 123ᵇ</span>, sq. <span dir=\"rtl\">פרה מ׳</span> a cow rented out <i>for half-profit</i> (Rashi).</div></div>","alt":[]},"11224":{"h":"חֲכַר","r":"H00951","html":"<div class=\"sense\"><span class=\"citation\">B. Mets. 68ᵃ</span> <span dir=\"rtl\">חַכְרָהּ</span>, v. <a href=\"#\" data-headword=\"מַשְׁכֵּן\">מַשְׁכֵּן</a>. <span class=\"citation\">Y. Maas. Sh. V, 56ᵇ</span> bot. [read:] <span dir=\"rtl\">כד … חַכְרִין … תַחְכְּרוּן וכ׳</span> when you rent land, rent only from God-fearing men.</div>","alt":[]},"11225":{"h":"חַכְרָנוּתָא","r":"H00952","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲכַר\">preced.</a>) <i>tenancy</i>. <span class=\"citation\">B. Mets. 104ᵃ</span> (Rashi: <a href=\"#\" data-headword=\"חֲכִירוּת\">חֲכִירוּת</a>).</div>","alt":[]},"11226":{"h":"חכשרה","r":"H00953","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַכְשָׁרָה\">הַכְשָׁרָה</a></div>","alt":[]},"11227":{"h":"חל","r":"H00954","html":"<div class=\"sense\">, Y. Ned. IV, beg. 39ᶜ bot <span dir=\"rtl\">כגון החל מן נונייה</span>, read: <span dir=\"rtl\">כגון הדין חֶלְמוֹן נ׳</span> as, for instance, <i>fish-raw</i>.—<span class=\"citation\">Y. Ab. Zar. II, 40ᵈ</span> top <span dir=\"rtl\">כחל לה</span>, read: <span dir=\"rtl\">כחללה</span>, v. <a href=\"#\" data-headword=\"חֲלָלָא\">חֲלָלָא</a>.</div>","alt":[]},"11228":{"h":"חָל","r":"H00955","html":"<div class=\"sense\">, perf. a. part. of <a href=\"#\" data-headword=\"חוּל\">חוּל</a>.</div>","alt":[]},"11229":{"h":"חַל I","r":"H00956","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲלַל I\">חֲלַל</a></div>","alt":[]},"11230":{"h":"חַל II","r":"H00957","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָלַל\">חלל</a>, cmp. <a href=\"#\" data-headword=\"חָלֵי\">חָלֵי</a>) <i>weak, mild</i> (wine). <span class=\"citation\">Targ. Y. Deut. VIII, 8</span>, opp. <a href=\"#\" data-headword=\"חָרִיף\">חָרִיף</a>.</div>","alt":[]},"11231":{"h":"חַל III","r":"H00958","html":"<div class=\"sense\"><i>vinegar</i>, v. <a href=\"#\" data-headword=\"חָלָא III\"><span dir=\"rtl\">חָלָא</span> III</a>.</div>","alt":[]},"11232":{"h":"חַלָּא","r":"H00959","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָלַל\">חלל</a>, cmp. <span dir=\"rtl\">גלל</span>) <i>a globular concretion</i>.—Pl. <a href=\"#\" data-headword=\"חֲלִי\">חַלֵּי</a>. <span class=\"citation\">Bekh. 7ᵇ</span> <span dir=\"rtl\">ח׳ דיחמורתא</span> ball-like concretions found in the <i>yaḥmur</i> (fallow-deer), v. <a href=\"#\" data-headword=\"יַחְמוּרָא\">יַחְמוּרָא</a>.</div>","alt":[]},"11233":{"h":"חָלָא I","r":"H00960","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"חוֹל I\"><span dir=\"rtl\">חוֹל</span> I</a>, <i>sand</i>. <span class=\"citation\">Targ. Gen. XXXII, 13</span>; a. fr.—<span class=\"citation\">Pes. 113ᵃ</span>, v. <a href=\"#\" data-headword=\"אַדְּ־\">אַדְּ־</a>.—Pl. <span dir=\"rtl\">חָלָתָא</span> (fem.). <span class=\"citation\">Sabb. 110ᵃ</span> <a href=\"#\" data-headword=\"חוֹזָאֵי\">בי ח׳</a> between the sand-mounds.</div>","alt":[]},"11234":{"h":"חָלָא II","r":"H00961","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"חוֹל II\"><span dir=\"rtl\">חוֹל</span> II</a>. <span class=\"citation\">Targ. Job XXIX, 18</span>.</div>","alt":[]},"11235":{"h":"חָלָא III","r":"H00962","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חוּל\">חול</a> or <a href=\"#\" data-headword=\"חָלַל\">חלל</a>) [<i>turned, spoiled</i>,] <i>vinegar</i>. <span class=\"citation\">Targ. O. Num. VI, 3</span> <a href=\"#\" data-headword=\"חָלָא III\">חַל</a>; Y. <a href=\"#\" data-headword=\"חֲלָא\">חֲלָא</a>. <span class=\"citation\">Targ. Ps. LXIX, 22</span> <a href=\"#\" data-headword=\"חֲסַף II\">חָ׳</a> ed. (Ms. <a href=\"#\" data-headword=\"חָבִיב\">חֲ׳</a>). <span class=\"citation\">Targ. Prov. XXV, 20</span> <a href=\"#\" data-headword=\"חָלָא I\">חלא</a> ed. Lag. (ed. <a href=\"#\" data-headword=\"חֵילְתָא\">חֵילָא</a>, Ms. <a href=\"#\" data-headword=\"חוּדַאי\">חוֹ׳</a>). <span class=\"citation\">Targ. Ruth II, 14</span>.—<span class=\"citation\">Ab. Zar. 12ᵇ</span>. <span class=\"citation\">Gen. R. s. 39</span>, v. <a href=\"#\" data-headword=\"זוּל\">זוּל</a> I ch.—<span class=\"citation\">Ḥull. 120ᵃ</span> ח׳ דקריש Ar. (ed. <span dir=\"rtl\">חלב</span>) a jellied vinegar sauce of meat; a. fr.—<span class=\"citation\">Y. Maasr. III, 50ᵈ</span> bot. <span dir=\"rtl\">ח׳ בר חמרא</span> a deteriorated son, v. <a href=\"#\" data-headword=\"חוֹמֶץ\">חוֹמֶץ</a>; <span class=\"citation\">Ḥull. 105ᵃ</span>. [Y. Ter. VII, 45ᵈ bot. <span dir=\"rtl\">בחלא</span>, read: <span dir=\"rtl\">בחַקְלָא</span>.]</div>","alt":["חֲלָא","חַל"]},"11236":{"h":"חֲלָא","r":"H00963","html":"<div class=\"sense\"><i>to be sick</i>, v. <a href=\"#\" data-headword=\"חֲלִי\">חֲלִי</a>.</div>","alt":[]},"11237":{"h":"חֶלְאָה","r":"H00964","html":"<div class=\"sense\"> (b. h.) pr. n. f. <i>Ḥelah</i>, an Agadic surname of Miriam. <span class=\"citation\">Ex. R. s. 1</span>, v. <a href=\"#\" data-headword=\"נָעַר I\">נָעַר</a>.</div>","alt":[]},"11238":{"h":"חֳלָאִים","r":"H00965","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֳלִי\">חֳלִי</a></div>","alt":[]},"11239":{"h":"חָלָב","r":"H00966","html":"<div class=\"sense\"> (b. h.) [<i>secretion</i>,] <i>milk</i>. <span class=\"citation\">Ab. Zar. II, 6</span> <span dir=\"rtl\">ח׳ שחֲלָבוֹ וכ׳</span> milk (of a cow) milked by a gentile. <span class=\"citation\">Makhsh. VI, 5</span> <span dir=\"rtl\">מי ח׳</span> serum of milk; a. fr.—בשר בח׳ <i>the boiling of meat with milk, the prohibitory law concerning</i> &amp;c. (<span class=\"citation\">Ex. XXIV, 19</span>; <span class=\"citation\">XXXIV, 26</span>; <span class=\"citation\">Deut. XIV, 21</span>). <span class=\"citation\">Pes. 54ᵇ</span>, v. <a href=\"#\" data-headword=\"חִידּוּשׁ\">חִידּוּשׁ</a>.—<span class=\"citation\">Ḥull. 110ᵃ</span> <span dir=\"rtl\">לא גמירי דב׳ בח׳ אסור</span> they did not know that boiling meat with milk was forbidden; a. fr.—חֲלֵב בֵּיצִים <i>white of eggs</i>. <span class=\"citation\">Y. Ter. X, 47ᵇ</span> bot., cmp. <a href=\"#\" data-headword=\"חֶלְבּוֹן\">חֶלְבּוֹן</a>.—<a href=\"#\" data-headword=\"נֵץ\">נֵץ</a> (<a href=\"#\" data-headword=\"ה\">ה</a>)ח׳ <i>ornithogalum, Star of Bethlehem</i>, a bulbous plant. <span class=\"citation\">Shebi. VII, 1</span>, v. <a href=\"#\" data-headword=\"חַלְבֵּצִין\">חֶלְבֵּצִין</a>; <span class=\"citation\">Ukts. III, 2</span>.—Trnsf. <span dir=\"rtl\">הח׳</span> <i>white wine</i>. <span class=\"citation\">Gen. R. s. 98</span>, opp. <span dir=\"rtl\">אדום</span>.</div>","alt":["חֲלֵב"]},"11240":{"h":"חֲלָב","r":"H00967","html":"<div class=\"sense\"><span class=\"citation\">Targ. Gen. XVIII, 8</span>. <span class=\"citation\">Targ. Job X, 10</span>; a. fr.—<span class=\"citation\">Y. Ter. VIII, 46ᵃ</span> <span dir=\"rtl\">חַלְבּוּן חֲ׳</span> milked. <span class=\"citation\">Ḥull. 109ᵇ</span>, v. <a href=\"#\" data-headword=\"בִּשְׂרָא\"><span dir=\"rtl\">בִּשְׂרָא</span> I</a>. <span class=\"citation\">Ib. 110ᵃ</span>; a. e.</div>","alt":["חַלְבָּא","חֶלְ׳"]},"11241":{"h":"חָלַב","r":"H00968","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"חָלָב\">חָלָב</a>) <i>to milk; to yield milk</i>. <span class=\"citation\">Ab. Zar. II, 6</span>, v. <a href=\"#\" data-headword=\"חָלָב\">חָלָב</a>. <span class=\"citation\">Bekh. 20ᵇ</span> <span dir=\"rtl\">רוב … חוֹלְבוֹת וכ׳</span> the majority of animals secrete no milk unless they have given birth; a. fr.</div><div class=\"sense\"><b>Nif. נֶחֱלַב</b> <div class=\"sense\"><i>to be milked</i>. <span class=\"citation\">Sabb. 53ᵇ</span> <span dir=\"rtl\">לֵיחָלֵב</span> when the bag is tied on for milking purposes (to support the udders), opp. <span dir=\"rtl\">ליבש</span> for drying up.</div></div>","alt":[]},"11242":{"h":"חֲלַב","r":"H00969","html":"<div class=\"sense\"><span class=\"citation\">Y. Ter. VIII, 46ᵃ</span>, v. <a href=\"#\" data-headword=\"חֲלָב\">חֲלָב</a></div>","alt":[]},"11243":{"h":"חֵלֶב","r":"H00970","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>fatty concretion</i> (cmp. <a href=\"#\" data-headword=\"חַלָּא\">חַלָּא</a>), esp. <i>that abdominal fat of cattle which it is forbidden to eat, ḥeleb</i> (<span class=\"citation\">Lev. III, 17</span>), contrad. to <a href=\"#\" data-headword=\"שׁוּמָן\">שומן</a>. <span class=\"citation\">Kerith. III, 1</span>. <span class=\"citation\">Ḥull. 113ᵇ</span> <span dir=\"rtl\">המבשל חֵ׳ בחָלָב</span> if one boils fat with milk. <span class=\"citation\">Snh. 4ᵇ</span> חֵלֶב וחָלָב דכי וכ׳ <i>ḥeleb</i> a. <i>ḥalab</i> which are written alike, v. <a href=\"#\" data-headword=\"אֵם\">אֵם</a>; a. fr.—Pl. <span dir=\"rtl\">חֲלָבִים</span>, <span dir=\"rtl\">חֲלָבִין</span>. <span class=\"citation\">Ber. I, 1</span> <span dir=\"rtl\">ח׳ ואברים</span> the pieces of fat and the limbs belonging to the altar; <span class=\"citation\">Tam. VII, 3</span> <span dir=\"rtl\">שלחן הח׳</span> the (marble) table designated for the fat-pieces (and limbs).—<span class=\"citation\">Ker. 12ᵃ</span>, sq. <span dir=\"rtl\">חֲלָבִין</span> laws concerning the eating of <i>ḥeleb;</i> <span class=\"citation\">Y. Yeb. X, 11ᵃ</span> top <span dir=\"rtl\">מדמי לה לח׳</span> (not <span dir=\"rtl\">לחלבון</span>); a. fr.—[<span class=\"citation\">Y. Ter. X, 47ᵇ</span> bot. <span dir=\"rtl\">לובן חלבין</span>, v. <a href=\"#\" data-headword=\"חֶלְבּוֹן\">חֶלְבּוֹן</a>.]—<span dir=\"rtl\">גוּשׁ הֵ׳</span>, v. <a href=\"#\" data-headword=\"גּוּשׁ I\">גּוּשׁ</a>.</div>","alt":[]},"11244":{"h":"*חֵלֶב","r":"H00971","html":"<div class=\"sense\"> ch. m. (<a href=\"#\" data-headword=\"חֵלֶב\">preced.</a>) <i>a viscous substance, glair</i>. <span class=\"citation\">Ḥull. 120ᵃ</span> <span dir=\"rtl\">ח׳ דקריש</span> ed. (v. Rashi); v. <a href=\"#\" data-headword=\"חָלָא III\"><span dir=\"rtl\">חָלָא</span> III</a>.</div>","alt":[]},"11245":{"h":"חֶלְבּוֹן","r":"H00972","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*חֵלֶב\">preced.</a> wds.) <i>glair, white of an egg</i>. <span class=\"citation\">Ab. Zar. 40ᵃ</span>; <span class=\"citation\">Ḥull. 64ᵃ</span>, v. <a href=\"#\" data-headword=\"חֶלְמוֹן\">חֶלְמוֹן</a>; a. fr.—<span class=\"citation\">Y. Ter. X, 47ᵇ</span> bot. <span dir=\"rtl\">בלובן חלבין</span>, read: <span dir=\"rtl\">בחלבון</span> (v. cit. in Tosaf. to <span class=\"citation\">Ḥull. 64ᵇ</span>).</div>","alt":["(הֶלְבּוֹן"]},"11246":{"h":"חֶלְבּוֹנָא","r":"H00973","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. Gen. XXXIX, 14</span>; <span class=\"citation\">20</span>. <span class=\"citation\">Targ. Job VI, 6</span>.</div>","alt":["חֶלְבּוֹן"]},"11247":{"h":"חֶלְבֵּיצִין","r":"H00974","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חַלְבֵּצִין\">חֶלְבֵּצִין</a></div>","alt":[]},"11248":{"h":"חֶלְבָּנָא","r":"H00975","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִלְבְּנֵיתָא\">חֶלְבְּנֵיתָא</a></div>","alt":["חֶלְבָּנַיָּא"]},"11249":{"h":"חֶלְבְּנָה","r":"H00976","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"חִילְתִּית\">חִילְתִּית</a>) <i>galbanum</i>, a gum-resin used as an ingredient of frank-incense, smelling like asafoetida. <span class=\"citation\">Ker. 6ᵃ</span>. <span class=\"citation\">Ib. 6ᵇ</span>; <span class=\"citation\">Yalk. Ex. 389</span> <span dir=\"rtl\">ח׳ ריחה רע ומנאה וכ׳</span> the smell of galb. is evil, and yet the Bible counts it among the spices (so are the wicked with the righteous combined in prayer).</div>","alt":[]},"11250":{"h":"חִלְבְּנֵיתָא","r":"H00977","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Ex. XXX, 34</span>; Targ. Y. <a href=\"#\" data-headword=\"חֶלְבָּנָא\">חֶלְבָּנַיָּא</a>, pl.—<span class=\"citation\">Gitt. 69ᵃ</span>, v. <a href=\"#\" data-headword=\"דּוּבְשָׁנִיתָא\">דּוּבְשָׁנִיתָא</a></div>","alt":["(חֶלְבְּנֵתָא","חֶלְבָּנְתָּא)"]},"11251":{"h":"חַלְבֵּצִין","r":"H00978","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (compound of <a href=\"#\" data-headword=\"חָלָב\">חָלָב</a> a. <a href=\"#\" data-headword=\"בֵּיצָה\">בֵּיצָה</a>) <i>bulb of ornithogalum.</i> <span class=\"citation\">Shebi. VII, 2</span>; expl. Y. ib. 37ᵇ bot. <span dir=\"rtl\">בֵּיצֵי נֵץ חָלָב</span> eggs (bulbs) of &amp;c., v. <a href=\"#\" data-headword=\"חָלָב\">חָלָב</a>; <span class=\"citation\">Tosef. ib. V, 6</span>; <span class=\"citation\">Nidd. 62ᵃ</span> <span dir=\"rtl\">הַלְּבֵיצִין</span> (absorbing <a href=\"#\" data-headword=\"ח\">ח</a>); <span class=\"citation\">Sabb. 90ᵃ</span> <span dir=\"rtl\">החל׳</span>. <span class=\"citation\">Tosef. Kil. III, 12</span> <span dir=\"rtl\">הלבוצין</span>.</div>","alt":["חַלְבֵּי׳"]},"11252":{"h":"חֲלַגְלוֹג","r":"H00979","html":"<div class=\"sense\"> (<span dir=\"rtl\">חלג</span>, cmp. <span dir=\"rtl\">חלק</span>) <i>purslane</i>. <span class=\"citation\">Erub. 28ᵃ</span> <span dir=\"rtl\">ובחל׳</span> (Ms. M. <span dir=\"rtl\">ובגלוגות</span>, read: <span dir=\"rtl\">ובַלַּגְל׳</span>, v. Rabb. D. S. a. l. note, <a href=\"#\" data-headword=\"ח׳\">ח׳</a> absorbed, v. <a href=\"#\" data-headword=\"חַלְבֵּצִין\">preced.</a>); <span class=\"citation\">Y. Peah VIII, 21ᵃ</span> top; Y. Erub. III, 20ᵈ top, expl. <span dir=\"rtl\">פרפחיניה</span>. <span class=\"citation\">Shebi. IX, 1</span> (Mish. ed. <span dir=\"rtl\">גית …</span>, read: … <span dir=\"rtl\">גות</span>; v. Rabb. D. S. a. l. note). Y. ib. 38ᶜ (Rabbi’s maid said) <span dir=\"rtl\">נתפזרו חֲלוֹגְלגוֹתֶיךָ</span> thy purslane plants have been scattered; <span class=\"citation\">R. Hash. 26ᵇ</span> <span dir=\"rtl\">חֲלוֹגְלוֹגְךָ</span> (Ms. M. <span dir=\"rtl\">לגלוגך</span>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא ידעי רבנן מאי חלוגל׳</span> (Mss. <span dir=\"rtl\">לגל׳</span>).</div>","alt":["חֲלַגְלוֹגוֹת","חֲלַגְלוֹגִין"]},"11253":{"h":"חָלַך","r":"H00980","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"חָלַל\">חלל</a>) <i>to undermine, cave, dig</i>. <span class=\"citation\">Pes. 118ᵇ</span> שחוֹלֶדֶת בעיקרי וכ׳ Ms. M. (ed. as in <span class=\"citation\">Ḥull. 20ᵇ</span> <span dir=\"rtl\">הדרה</span>) which undermines the foundations &amp;c. V. <a href=\"#\" data-headword=\"חוּלְדָּה I\">חוּלְדָּה</a>.</div><div class=\"sense\"><b>Hif. הֶחְלִיד</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"חֲלַגְלוֹג\">same</a>. Y. Kil. IX, 32ᶜ top <span dir=\"rtl\">מַחִלִיד הב&quot;ה … את וכ׳</span> the Lord caves the ground before them and they roll &amp;c.; Y. Keth. XII, 35ᵇ top <span dir=\"rtl\">מהלך … אל</span> (corr. acc.). <span class=\"citation\">B. Bath. 19ᵇ</span> <span dir=\"rtl\">מפני שמַחְלִידִין וכ׳</span> because their roots undermine the ground.</div><div class=\"sense\"><b>—2)</b> <i>to pass the slaughtering knife under cover, to squeeze in</i>. <span class=\"citation\">Ḥull. II, 4</span>. <span class=\"citation\">Ib. 20ᵇ</span>; a. fr.—<span class=\"citation\">Tosef. Kel. B. Bath. I, 5</span> <span dir=\"rtl\">מפני שהכובס אומן מַחֲלִידוֹ לתוכו</span> (R. S. to <span class=\"citation\">Kel. XXI, 1</span>) because so much of it does the professional fuller fold up for inserting a rod into it (v. <a href=\"#\" data-headword=\"חוֹב II\"><span dir=\"rtl\">חוֹב</span> II</a>, 2).</div></div>","alt":[]},"11254":{"h":"חֲלַד","r":"H00981","html":"<div class=\"sense\">; Part. pass. <span dir=\"rtl\">חָלִיד</span> <i>covered with earth, mouldering</i>. <span class=\"citation\">Targ. Job XI, 17</span> Ms. (ed. <span dir=\"rtl\">דחלך</span>, <span dir=\"rtl\">דהלך</span>, corr. acc.).</div>","alt":[]},"11255":{"h":"חֶלֶד","r":"H00982","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"חֲלַד\">preced.</a>) <i>mould;</i> trnsf. <i>earthly life</i>. <span class=\"citation\">Midr. Till. to Ps. XVII, 14</span> אין ח׳ אלא ארץ <i>ḥeled</i> means earth (ref. to <span class=\"citation\">Ps. XLIX, 2</span>). Tanḥ. Ki Thabo 2 (ref. to <span class=\"citation\">Ps. XVII, 14</span>) <span dir=\"rtl\">הן מתים מח׳</span> they die away from this world, v. <a href=\"#\" data-headword=\"חֲלוּדָה\">חֲלוּדָה</a>.</div>","alt":[]},"11256":{"h":"חֲלָדָה","r":"H00983","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (חָלַד Hif.) <i>passing the knife under cover</i>. <span class=\"citation\">Ḥull. 9ᵃ</span>; <span class=\"citation\">27ᵃ</span>; a. e.</div>","alt":[]},"11257":{"h":"חלדואות","r":"H00984","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲלוּדָה\">חֲלוּדָה</a></div>","alt":[]},"11258":{"h":"חַלְדּוּתָא","r":"H00985","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , <i>rust</i>. <span class=\"citation\">Targ. Y. Num. XXXI, 22</span> (v. Rashi a. l.).</div>","alt":[]},"11259":{"h":"*חִלְדִּין","r":"H00986","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חַלְדּוּתָא\">preced.</a> wds.) <i>cave-dwellers</i>. <span class=\"citation\">Gen. R. s. 37</span>, transl. of <a href=\"#\" data-headword=\"חִוֵּי\">חִוִּי</a> (<span class=\"citation\">Gen. X, 17</span>); cmp. <a href=\"#\" data-headword=\"חִוֵּי\">חִוְיָא</a>.</div>","alt":[]},"11260":{"h":"חָלָה","r":"H00987","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חלי\">חלי</a></div>","alt":[]},"11261":{"h":"חַלָּה","r":"H00988","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  [<i>rolled, rounded</i>] <i>cake</i>.—Pl. <span dir=\"rtl\">חַלּוֹת</span>. <span class=\"citation\">Ukts. III, 5</span> <span dir=\"rtl\">ח׳ חריע</span> (<span class=\"citation\">Tosef. Maas. Sh. I, 13</span> <span dir=\"rtl\">חַלַּת</span> (collect. noun), a. e., v. <a href=\"#\" data-headword=\"חֲרִיעַ\">חֲרִיעַ</a>.—<span class=\"citation\">Men. III, 6</span> <span dir=\"rtl\">שתי ח׳</span> the two loaves (offered on the Feast of Weeks, <span class=\"citation\">Lev. XXIII, 17</span>).—<span class=\"citation\">B. Bath. V, 3</span>; <span class=\"citation\">Ukts. III, 11</span> ח׳ דבש <i>honey-combs;</i> a. fr.</div><div class=\"sense\"><b>—2)</b>  (with ref. to <span class=\"citation\">Num. XV, 20</span>, sq.) <i>Ḥallah</i>, <i>the priest’s share of the dough</i>. <span class=\"citation\">Sabb. II, 6</span>, v. <a href=\"#\" data-headword=\"זָהִיר\">זָהִיר</a>. <span class=\"citation\">Ḥall. I, 1</span> <span dir=\"rtl\">חייבין בח׳</span> are subject to the law of <i>Ḥallah</i>.—Ib. II, 7 <span dir=\"rtl\">שעור הח׳</span> the quantity to be set aside for the priest. Ib. 8 מעיסה שלא הורמה חַלָּתָהּ Ms. M. (v. Rabb. D. S. a. l. note) from a dough from which the priest’s share has not yet been taken; a. fr.—<i>Pl.</i> as ab. Pesik. Shimu, p. 118ᵃ <span dir=\"rtl\">שתי ח׳</span> two portions (one for being burnt, and one for the priest); <span class=\"citation\">Y. Erub. III, end, 21ᶜ</span>; <span class=\"citation\">Cant. R. to I 6</span>; a. e.—Trnsf. <i>ḥallah</i>, <i>the sanctification of creation, man</i>. <span class=\"citation\">Gen. R. s. 14</span>, beg.; <span class=\"citation\">Yalk. Prov. 962</span>, a. e. (ref. to <span class=\"citation\">Prov. XXIX, 4</span>, <span dir=\"rtl\">ואיש תרומות</span>) that is Adam <span dir=\"rtl\">שהיה גמר חַלָּתוֹ וכ׳</span> who was the final sanctification of the world; <span class=\"citation\">Gen. R. s. 17</span>, end.—<i>Ḥallah</i>, name of a treatise of the Mishnah, Tosefta a. Talm. Y., of the Order of Z’raïm.</div>","alt":[]},"11262":{"h":"חֲלוֹגְלוֹג","r":"H00989","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲלַגְלוֹג\">חֲלַגְלוֹג</a></div>","alt":[]},"11263":{"h":"חֲלוּדָה","r":"H00990","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲלַד\">חָלַד</a>) [<i>covering of earth &amp;c., mouldering from being in a cave</i>,] </div><div class=\"sense\"><b>1)</b> <i>rust, mould.</i> <span class=\"citation\">Kel. XIII, 5</span> <span dir=\"rtl\">העלתה ה׳</span> became rusty; <span class=\"citation\">Tosef. Kel. B. Mets. III, 10</span>; a. fr.—Trnsf. <i>sin</i>. Tanḥ. Ki Thabo 2 (ref. to <span dir=\"rtl\">חלד</span> <span class=\"citation\">Ps. XVII, 14</span>) [read:] <span dir=\"rtl\">אמרו זה לזה ח׳ הם מלאין חטאין יש בידן</span> (v. Tanḥ. ed. Bub. ib. 4) they (the gentiles) say to one another, they (the Israelites) are full of rust, there are sins in their hands.</div><div class=\"sense\"><b>—2)</b> <i>a skin disease arising from living in caves</i>. <span class=\"citation\">Midr. Till. to Ps. XVII, 14</span> (v. supra) <span dir=\"rtl\">אלו שהעלה גופן ח׳</span> they are those (persecuted Jews) whose bodies became afflicted with sores, &amp;c.; <span class=\"citation\">Y. Shebi. IX, 38ᵈ</span>; <span class=\"citation\">Gen. R. s. 79</span>.—Pl. <span dir=\"rtl\">חֲלוּדוֹת</span>. Pesik. B’shall., p. 88ᵇ; <span class=\"citation\">Esth. R. to I, 9</span> <span dir=\"rtl\">חֲלוּדָאוֹת</span> (some ed. <a href=\"#\" data-headword=\"חלדואות\">חלדואות</a>, corr. acc.).</div>","alt":[]},"11264":{"h":"חַלְוָון","r":"H00991","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Halvan</i> (<i>Ḥolvân</i>) in Assyria (b. h. , v. P. Sm. 1277, Neub. Géogr. p. 373). <span class=\"citation\">Kidd. 72ᵃ</span>; <span class=\"citation\">Yeb. 16ᵇ</span> Ms. M. (ed. <a href=\"#\" data-headword=\"חִלָּזוֹן\">חלזון</a>, corr. acc.).</div>","alt":[]},"11265":{"h":"חֲלוּז","r":"H00992","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲלַז\">חלז</a>) <i>knot </i>or<i> sling of the upper garment when lifted</i>, (<i>sinus</i>). Targ. II Esth. I, 2 (3) <span dir=\"rtl\">וחליזת חִילּוּזָהּ</span> she lifted her garment.—<span class=\"citation\">Pes. 113ᵃ</span> <span dir=\"rtl\">תמרי בחֲלוּזָךְ וכ׳</span> if thou bringest dates home, with thy <i>sinus</i> (before ungirding) run to the brewery; [comment.: with the dates tied up in thy <i>bag</i>]. V. <a href=\"#\" data-headword=\"חוּלְזָא\">חוּלְזָא</a>.</div>","alt":["חִילּוּזָא","(הִי׳)"]},"11266":{"h":"חִלּוּט","r":"H00993","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"הֶחְלֵט\">הֶחְלֵט</a>. <span class=\"citation\">Tosef. Neg. VIII, 6</span> <span dir=\"rtl\">בימי חִלּוּטוֹ</span> during his days of declared leprosy.</div>","alt":[]},"11267":{"h":"חָלוּט","r":"H00994","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"חָלַט I\">חָלַט</a></div>","alt":[]},"11268":{"h":"חֲלוּטִין","r":"H00995","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (חָלַט II) <i>final action, decision</i>. <span dir=\"rtl\">לחֲ׳</span> <i>finally, permanently, absolutely</i> (b. h. <span dir=\"rtl\">לִצְמִיתוּת</span>). <span class=\"citation\">Targ. Lev. XXV, 23</span>; a. e.—<span class=\"citation\">Ex. R. s. 3</span>; <span class=\"citation\">Arakh. 15ᵇ</span>; <span class=\"citation\">Snh. 106ᵇ</span>.—<span class=\"citation\">Lev. R. s. 7</span>, end, v. <span dir=\"rtl\">יְרִיבָה</span>.—V. <a href=\"#\" data-headword=\"חַלְטָנִית\">חַלְטָנִית</a>.—בח׳ <i>by final decision</i> (from which there is no appeal). <span class=\"citation\">Gen. R. s. 42</span>; <span class=\"citation\">Yalk. ib. 72</span>; <span class=\"citation\">Koh. R. to V, 15</span> היך מה דאתא בחלו׳ וכ׳ Ar. (ed. <span dir=\"rtl\">בחלי׳</span>) as man enters this world by final decision, so does he leave it it (cmp. <span class=\"citation\">Ab. IV, 22</span>).—[<span class=\"citation\">Gen. R. s. 94</span>, beg. <a href=\"#\" data-headword=\"חֲלוּטִין\">חלוטין</a>, v. <a href=\"#\" data-headword=\"חֲלִיטָא III\"><span dir=\"rtl\">חֲלִיטָא</span> III</a>.]</div>","alt":[]},"11269":{"h":"חִלּוּי","r":"H00996","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"חִלָּזוֹן\">חִילּ׳</a>.</div>","alt":["חִלּוּל"]},"11270":{"h":"חָלוּל","r":"H00997","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָלַל\">חָלַל</a>) <i>hollowed; pipe, channel</i>.—Pl. <span dir=\"rtl\">חֲלוּלִים</span>, <span dir=\"rtl\">חֲלוּלִין</span>. Sifra K’dosh. Par. 1; <span class=\"citation\">Yalk. Lev. 604</span> the idols are called <span dir=\"rtl\">אֱלִילִים</span>, <span dir=\"rtl\">על שם שהם ח׳</span> because they are hollow.—<span class=\"citation\">Ber. 60ᵇ</span> ח׳ ח׳ Ms. F. a. oth. (ed. <span dir=\"rtl\">חֲלָלִים</span></div>","alt":[]},"11271":{"h":"חָלוּם","r":"H00998","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>sane</i>, v. <a href=\"#\" data-headword=\"חָלַם I\"><span dir=\"rtl\">חָלַם</span> I</a>.</div>","alt":[]},"11272":{"h":"חֲלוֹם","r":"H00999","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"חָלַם II\"><span dir=\"rtl\">חָלַם</span> II</a>) <i>dream</i>. <span class=\"citation\">Ber. 55ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">חֲלוֹמוֹת</span>. <span class=\"citation\">Ib.ᵇ</span>; a. fr.—<span class=\"citation\">Ib. 10ᵇ</span> <span dir=\"rtl\">בעל הח׳</span> the genius of dream.—[<span dir=\"rtl\">חלומות דהרואה</span> that portion of the chapter Haroëh, in B’rakhoth, treating of dreams: <span class=\"citation\">Ber. 55ᵃ</span> to 57ᵇ; often quoted in Ar. a. oth.]</div>","alt":[]},"11273":{"h":"חַלּוֹן","r":"H01000","html":"<div class=\"sense\"> c. (b. h.; <i>perforation, aperture, window</i>. <span class=\"citation\">B. Bath. III, 6</span> <span dir=\"rtl\">ח׳ המצרית וכ׳</span> the Egyptian window (a very small aperture in the wall) gives no privilege (v. <a href=\"#\" data-headword=\"חֲזָקָה\">חֲזָקָה</a>), i.e. the neighbor may build against it, contrad. to <span dir=\"rtl\">הצורית</span> a Tyrian window. <span class=\"citation\">Gen. R. s. 31</span>, expl. <span dir=\"rtl\">צהר</span> (<span class=\"citation\">Gen. VI, 16</span>); a. v. fr.—Pl. <span dir=\"rtl\">חַלּוֹנוֹת</span>. <span class=\"citation\">Y. R. Hash. II, 58ᵃ</span>; <span class=\"citation\">Ex. R. s. 15</span> שס&quot;ה ח׳ וכ׳ 365 apertures did the Lord create in the sky; a. fr.</div>","alt":[]},"11274":{"h":"חִלּוּף","r":"H01001","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִלָּזוֹן\">חִילּ׳</a></div>","alt":["חִלּוּפָא"]},"11275":{"h":"חִלּוּץ","r":"H01002","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָלַץ\">חָלַץ</a><i>Hif.</i>) <i>strength, quickness</i>. <span class=\"citation\">Ber. 16ᵇ</span> <span dir=\"rtl\">חיים של ח׳ עצמות</span> (missing in Mss., v. Rabb. D. S. a. l. note 5) a life of healthfull energy (v. <span class=\"citation\">Is. LVIII, 11</span>).</div>","alt":[]},"11276":{"h":"חֲלוּצָא","r":"H01003","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> or district <i>Ḥălutsa.</i> <span class=\"citation\">Targ. Y. II, Gen. XVI, 7</span>; <span class=\"citation\">Ex. XV, 22</span> (h. text <a href=\"#\" data-headword=\"שׁוּר\">שׁוּר</a>). <span class=\"citation\">Targ. Y. Gen. XVI, 14</span> (h. text <a href=\"#\" data-headword=\"בָּרָד\">בָּרֶד</a>).—<span class=\"citation\">Gen. R. s. 45</span>; <span class=\"citation\">Yalk. ib. 79</span> (expl. <span dir=\"rtl\">בדרך שור</span>, <span class=\"citation\">Gen. XVI, 7</span>) <span dir=\"rtl\">באורחא דח׳</span> on the road of Ḥ.—V. <a href=\"#\" data-headword=\"חַגְרָא I\"><span dir=\"rtl\">חַגְרָא</span> I</a>.</div>","alt":["חֲלוּצָה I"]},"11277":{"h":"חֲלוּצָה II","r":"H01004","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"חָלַץ\">חָלַץ</a></div>","alt":[]},"11278":{"h":"חָלוּק I","r":"H01005","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָלַק\">חָלַק</a>, v. <a href=\"#\" data-headword=\"חָלָק\">חָלָק</a>) <i>plain, smooth garment</i>, in gen. <i>undershirt.</i> <span class=\"citation\">Kel. XXVIII, 9</span>, v. <a href=\"#\" data-headword=\"חוּץ II\"><span dir=\"rtl\">חוּץ</span> II</a>.—<span class=\"citation\">M. Kat. 14ᵃ</span>, a. e. <span dir=\"rtl\">כל … אלא ח׳ אחד</span> he who has only one shirt. <span class=\"citation\">Ab. Zar. 34ᵃ</span> <span dir=\"rtl\">ח׳ לבן</span> a plain white frock, v. <a href=\"#\" data-headword=\"אִימְּרָה\">אִימְּרָה</a>. <span class=\"citation\">Y. Taan. II, 65ᵈ</span> (ref. to <span class=\"citation\">I Sam. VII, 6</span>) <span dir=\"rtl\">לבש שמואל חֲלוּקָן וכ׳</span> Samuel put on the common shirt of all Israelites, i.e. included himself among the sinners; a. fr.—Trnsf. a) <i>a shirt-shaped bandage</i>. <span class=\"citation\">Sabb. XIX, 2</span> (drawn over the circumcised membrum).—b) <i>a row, layer</i>. <span class=\"citation\">Y. Pes. I, 27ᵇ</span> bot. <span dir=\"rtl\">מפשיטו ח׳ אחד</span> he strips it of one shirt, i.e. removes one row all around the pile of bottles.—Pl. <span dir=\"rtl\">חֲלוּקִים</span>, <span dir=\"rtl\">חֲלוּקִין</span>, <span dir=\"rtl\">חֲלוּקוֹת</span>. <span class=\"citation\">M. Kat. 22ᵇ</span>. Y. l. c. <span dir=\"rtl\">שני חלקות</span> (read: <span dir=\"rtl\">חלוק׳</span>) two rows. <span class=\"citation\">Tosef. Kil. V, 6</span> <span dir=\"rtl\">שני ח׳</span> two shirts of different materials <a href=\"#\" data-headword=\"כִּלְאַיִם\">(כִּלְאַיִם</a>). Lam. R. introd. (R. Abbahu 2); ib. to III, 13 <span dir=\"rtl\">והח׳ שלו עליו</span> (the camel) with his covers on; a. fr.</div>","alt":[]},"11279":{"h":"חָלוּק II","r":"H01006","html":"<div class=\"sense\"><b>1)</b> <i>divided</i>, v. <a href=\"#\" data-headword=\"חָלַק\">חָלַק</a>; </div><div class=\"sense\"><b>2)</b> <i>empty, smooth</i>, v. <a href=\"#\" data-headword=\"חָלָק\">חָלָק</a>.</div>","alt":[]},"11280":{"h":"חִלּוּק","r":"H01007","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִילּוּק\">חִילּוּק</a></div>","alt":[]},"11281":{"h":"חֲלוּק","r":"H01008","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"חָלוּק I\"><span dir=\"rtl\">חָלוּק</span> I</a>. <span class=\"citation\">Targ. Y. Ex. XXII, 26</span> <span dir=\"rtl\">ח׳ תותביה</span> ed. pr. (later ed. only <span dir=\"rtl\">תות׳</span>).—Lam. R. introd. (R. Abbahu 5); ib. to III, 13 <span dir=\"rtl\">כח׳ דיהודאי וכ׳</span> as long as a Jewish Sabbath shirt (transmitted from father to son).—<span class=\"citation\">Sabb. 134ᵃ</span> <span dir=\"rtl\">ח׳ דינוקא</span> the child’s bandage, v. <a href=\"#\" data-headword=\"חָלוּק I\"><span dir=\"rtl\">חָלוּק</span> I</a></div>","alt":["חֲלוּקָא"]},"11282":{"h":"חֲלוּקָּה","r":"H01009","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>division, partition</i>. <span class=\"citation\">B. Bath. 122ᵃ</span> <span dir=\"rtl\">לא כח׳ של עוה&quot;ז וכ׳</span> the distribution of land in the future will not be like the one of the present. <span class=\"citation\">Ib. 126ᵃ</span> <span dir=\"rtl\">יש לו לבכור קודם ח׳</span> the first-born is the legal owner of his share before the partition has taken place. <span class=\"citation\">Keth. 26ᵃ</span> <span dir=\"rtl\">בתורת ח׳</span> as an heir’s share. <span class=\"citation\">Ib. 94ᵇ</span> <span dir=\"rtl\">ח׳ עדיפא</span> division among two claimants (where evidence is wanted) is preferable (to discretionary adjudication to one, v. <a href=\"#\" data-headword=\"שׁוּדָא\">שׁוּדָּא</a>); a. e.</div>","alt":[]},"11283":{"h":"*חֲלוּקָה","r":"H01010","html":"<div class=\"sense\">, only in <span dir=\"rtl\">(<span dir=\"rtl\">פול</span>) <span dir=\"rtl\">ח׳ נפש</span></span> [<i>smoothing the soul</i>,] name of a species of <i>bean</i> = <a href=\"#\" data-headword=\"שְׁעוּעִית\">שעועית</a>. <span class=\"citation\">Nidd. IX, 7</span> (expl. <span dir=\"rtl\">מי גריסין</span>) <span dir=\"rtl\">לעיסת גריסין של פול ח׳ נ׳</span> a chewed mass of grist of beans named <i>ḥălukath nefesh</i> (Rashi: <i>beans split to the core</i>, v. <a href=\"#\" data-headword=\"חֶילְקָא II\"><span dir=\"rtl\">חֶילְקָא</span> II</a>); [<span class=\"citation\">Tosef. ib. VIII, 9</span> <span dir=\"rtl\">עז עיקת נפש</span> ed. Zuck. (Var. <span dir=\"rtl\">ער עוקת נתש</span>); <span class=\"citation\">Gen. R. s. 94</span>, beg. <span dir=\"rtl\">פול שהוא על עיקת נפש</span>; <span class=\"citation\">Yalk. ib. 152</span> <span dir=\"rtl\">שבאין על עקת נפש</span> the bean-grist used for (relieving) the pressure of the soul; cmp. <span class=\"citation\">Y. Kil. I, 27ᵇ</span> top, etymol. of <a href=\"#\" data-headword=\"שְׁעוּעִית\">שְׁעוּעִית</a>, a. <span class=\"citation\">B. Bath. 16ᵃ</span>, quot. s. v. <a href=\"#\" data-headword=\"עֲדָשָׁה\">עֲדַשָּׁה</a>.—Our w. is prob. a popular re-adaptation of <i>Alica</i>, v. Sm. Ant. s. v.]</div>","alt":["חֲלוּקַת"]},"11284":{"h":"חֶלְוָתָא","r":"H01011","html":"<div class=\"sense\"><i>hosts</i>, v. <a href=\"#\" data-headword=\"חֵיל II\"><span dir=\"rtl\">חֵילָא</span> I</a>.</div>","alt":[]},"11285":{"h":"חֲלַז","r":"H01012","html":"<div class=\"sense\">, <i>Pa.</i> <a href=\"#\" data-headword=\"חַלֵּיז\">חַלֵּיז</a> (cmp. <span dir=\"rtl\">חלץ</span>) <i>to gird, to form a sinus; to lift the cloak</i>. Targ. II Esth. I, 2 (3), v. <a href=\"#\" data-headword=\"חֲלוּז\">חֲלוּז</a>.—<i>Part. pass</i>. <span dir=\"rtl\">מְחַלַּז</span>. Ib. IV, 11 <span dir=\"rtl\">ומְחַלְּזִין חולזוי</span> his loins girt (his cloak lifted up, ready for labor).</div>","alt":[]},"11286":{"h":"חִלָּזוֹן","r":"H01013","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חֲלַז\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>conchiferous animal, snail, oyster</i>, esp. <i>purple-fish, purple-shell used for dying t’kheleth</i> <a href=\"#\" data-headword=\"תְּכֵלֶת\">(תְּכֵלֶת</a>). <span class=\"citation\">Snh. 91ᵃ</span> <span dir=\"rtl\">ח׳ אחד</span> (ed. <span dir=\"rtl\">אחת</span>, v. Rabb. D. S. a. l. note 60 a. Ar. s. v.). Pesik. B’shall. p. 92ᵃ <span dir=\"rtl\">ח׳ הזה וכ׳</span> as the snail grows, its shell grows with it; <span class=\"citation\">Deut. R. s. 7</span>, end—<span class=\"citation\">Sabb. 26ᵃ</span> (expl. <span dir=\"rtl\">יגבים</span>, <span class=\"citation\">Jer. LII, 16</span>) <span dir=\"rtl\">ציידי ח׳ וכ׳</span> the shellfishers from &amp;c. <span class=\"citation\">Men. 44ᵃ</span>. <span class=\"citation\">Meg. 6ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">חִלְזוֹנוֹת</span>. Snh. l. c.</div><div class=\"sense\"><b>—2)</b>  name of a <i>beetle</i> or <i>locust</i>, v. next w.—<span class=\"citation\">Y. Sabb. I, 3ᵇ</span>. <span class=\"citation\">Yalk. Ex. 185</span>; Tanḥ. Vaera, ed. Bub. 19.</div><div class=\"sense\"><b>—3)</b>  (cmp. Lat. Cochlea) <i>a snail-shaped piece of a chain, screw.</i> <span class=\"citation\">Kel. XII, 1</span>; <span class=\"citation\">Tosef. Kel. B. Mets. II, 3</span>.</div><div class=\"sense\"><b>—4)</b> <i>an eye-disease</i>, also called <a href=\"#\" data-headword=\"נְחַשׁ I\">נחש</a>. <span class=\"citation\">Bekh. VI, 2</span>; <span class=\"citation\">ib. 38ᵇ</span>. Sifra Emor ch. II, Par. 3.—[<span class=\"citation\">Kidd. 72ᵃ</span>; <span class=\"citation\">Yeb. 16ᵇ</span>, v. <a href=\"#\" data-headword=\"חַלְוָון\">חַלְוָון</a>.]</div>","alt":["חִילָּ׳","חֲלָ׳"]},"11287":{"h":"חִלְזוֹנָא","r":"H01014","html":"<div class=\"sense\"><b>1)</b> <i>purple-fish; snail</i>. <span class=\"citation\">Targ. Y. I Deut. XXXIII, 19</span> (v. <span class=\"citation\">Meg. 6ᵃ</span>).—Pl. <span dir=\"rtl\">חִלְזוֹנֵי</span>. <span class=\"citation\">Ab. Zar. 28ᵇ</span>, v. <a href=\"#\" data-headword=\"*מִשְׁקְדֵי\">מִשְׁקְדֵי</a>.</div><div class=\"sense\"><b>—2)</b> <i>beetle</i> or <i>locust</i>. <span class=\"citation\">Targ. Y. Deut. XXVIII, 42</span> Ar. (ed. <a href=\"#\" data-headword=\"חלנונא\">חלנונא</a>, h. text <span dir=\"rtl\">צלצל</span>).</div><div class=\"sense\"><b>—3)</b> <i>an affection of the eye</i>. <span class=\"citation\">Targ. Y. I Lev. XXI, 20</span> Ar. a. oth. (ed. <a href=\"#\" data-headword=\"חִלָּזוֹן\">חִלָּזוֹן</a>; Y. II <span dir=\"rtl\">יחלזווה</span>, read: <span dir=\"rtl\">דחִלְזוֹנָה</span>; v. <a href=\"#\" data-headword=\"חִלִּיז\">חִלִּיז</a>).</div>","alt":[]},"11288":{"h":"חִלְחוּל","r":"H01015","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חִלְחֵל\">חִלְחֵל</a>) <i>penetration of a poisonous substance, poison</i>. Tanḥ. <span class=\"citation\">Mishp. 18</span>; ed. Bub. 12 (<a href=\"#\" data-headword=\"חַלְטָנִית\">חול׳</a>, corr. acc.) <span dir=\"rtl\">הח׳ היה נכנס וכ׳</span> the poison (of the flies) entered their bodies; <span class=\"citation\">Yalk. Ex. 359</span>.</div>","alt":["חִילְחוּל"]},"11289":{"h":"חַלְחוֹלִית","r":"H01016","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חִלְחוּל\">preced.</a>) <i>winding;</i> pl. <a href=\"#\" data-headword=\"חוּלְחוֹלִית\">חַלְחוֹלִיּוֹת</a> <i>intrigues</i>. <span class=\"citation\">Lev. R. s. 20</span> (expl. <span dir=\"rtl\">להוללים</span>, <span class=\"citation\">Ps. LXXV, 5</span>) <span dir=\"rtl\">למערבביא אלו שלבם … ח׳ רעות</span> (some ed. <span dir=\"rtl\">חַלְחֹלִיּוֹת</span>) to those creating confusion, those whose hearts are full of evil intrigues; Tanḥ. Aḥăré 2 <span dir=\"rtl\">חלחל׳</span>; <span class=\"citation\">Yalk. Lev. 524</span> <a href=\"#\" data-headword=\"חוּלְחָלִית\">חוּלְחָלִיּוֹת</a>; <span class=\"citation\">Yalk. Ps. 811</span>; [<span class=\"citation\">Lev. R. s. 17</span> (ref. to <span class=\"citation\">Ps. LXXIII, 3</span>) <span dir=\"rtl\">במערבא אומרים אלו … הוֹלֵלוֹת וכ׳</span> (read: <span dir=\"rtl\">במְעַרְבָּבַיָּא אלו</span>), v. <a href=\"#\" data-headword=\"הוֹלֵלָה\">הוֹלֵלָה</a>].</div>","alt":[]},"11290":{"h":"חַלְחוֹלֶת","r":"H01017","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חִלְחֵל\">next w.</a>; v. <a href=\"#\" data-headword=\"חַלְחוֹלִית\">preced.</a> wds.) <i>mesentery</i>, a membrane keeping the entrails in position. <span class=\"citation\">Ḥull. 50ᵃ</span></div>","alt":[]},"11291":{"h":"חִלְחֵל","r":"H01018","html":"<div class=\"sense\"><b>1)</b> <i>to penetrate into cavities; to perforate</i>. <span class=\"citation\">Sot. 7ᵇ</span>; <span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">מְחַלְחֵל ויורד</span> (the powder on a wound) penetrates and goes down (into the body). <span class=\"citation\">Gen. R. s. 98</span> <span dir=\"rtl\">ריסו מח׳ וכ׳</span> its venom penetrates (the body of the bitten one) after (the serpent’s) death.</div><div class=\"sense\"><b>—2)</b> <i>to shake, roll</i> (in a vessel &amp;c.); <i>to rinse.</i> <span class=\"citation\">Makhsh. III, 6</span> <span dir=\"rtl\">ח׳ לתוכן</span> if he washed olives by rolling them in the rain water.—<i>Part. pass</i>. <span dir=\"rtl\">מְחוּלְחָל</span>, f. <span dir=\"rtl\">מְחוּלְחֶלֶת</span> <i>hollow, blown up</i>;<i> loosely put in</i>. Oh. IX, 7 <span dir=\"rtl\">כלי מח׳</span> a hollow vessel (not packed entirely), opp. <span dir=\"rtl\">אֲפוּצָה</span>. <span class=\"citation\">Kel. X, 3</span> <span dir=\"rtl\">מגופת החבית המח׳ וכ׳</span> (Bart. <span dir=\"rtl\">המִתְחַלְחֶ׳</span>) the stopper of a keg which can be moved around, without, however, falling out of itself. Teb. Yom I, 1; a. fr.</div><div class=\"sense\"><b>Hithpalp. הִתְחַלְחֵל</b> <div class=\"sense\">, <i>Nithpalp</i>. <span dir=\"rtl\">נִתְהַלְחֵל</span> </div><div class=\"sense\"><b>1)</b> <i>to permeate</i>. <span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">שהם מִתְחַלְחֲלִים וכ׳</span> that they will permeate all her limbs.</div><div class=\"sense\"><b>—2)</b> <i>to be shaken in a hollow space, to be thrown about.</i> <span class=\"citation\">Mikv. IV, 3</span> <span dir=\"rtl\">היו צרורות מתח׳ וכ׳</span> if pebbles rolled about in the spout.</div><div class=\"sense\"><b>—3)</b> <i>to be permeated</i> (with poison) <i>to be affected, injured</i>. Y. B. Kam. I, beg. 2ᵇ <span dir=\"rtl\">ונתח׳ כולו</span></div><div class=\"sense\"><b>—4)</b>  (cmp. <a href=\"#\" data-headword=\"חָלָה\">חָלָה</a>) <i>to be weakened, be neutralized</i>. Y. Ter. VIII, 46ᵃ top <span dir=\"rtl\">ע&quot;י מליחה מתח׳</span> through salting it, the poison is neutralized.</div></div>","alt":[]},"11292":{"h":"חַלְחֵל","r":"H01019","html":"<div class=\"sense\">, <i>to penetrate, to hollow out</i>. <span class=\"citation\">Ḥull. 119ᵇ</span> <span dir=\"rtl\">חַלְחוּלֵי מְחַלְחֵל</span> the hair perforates the skin.—<i>Part. pass</i>. <span dir=\"rtl\">מְחַלְחַל</span> <i>hollow; loosely filled</i>. <span class=\"citation\">Ber. 59ᵃ</span> <span dir=\"rtl\">ענני חלחולי מְחַלְחֲלֵי</span> (Ms. F. <span dir=\"rtl\">עיבא … מִיחַלְחַל</span>) the clouds are not entirely filled with water. <span class=\"citation\">Pes. 74ᵃ</span> <span dir=\"rtl\">איידי דמח׳</span> because the wood is hollow (having marrow inside); a. e.</div><div class=\"sense\"><b>Ithpalp. אִתְחַלְחַל  אִיחַלְחַל</b> <div class=\"sense\"><b>1)</b> <i>to be perforated, be open</i>. Ber. l. c. Ms. F. v. supra.—Esp. <i>to be permeated by poison, feel the effect of poison</i>. Y. Ab. Zar. II, 41ᵃ bot.; Y. Ter. VIII, 45ᶜ bot. <span dir=\"rtl\">לא אספיק … עד דאיתח׳</span> he had scarcely drank of it when he became affected (collapsed). Y. Ab. Zar. II, 40ᵈ top <span dir=\"rtl\">חמתה מִתְהַלְחֲלָה</span> he saw that the plaster was poisoned.</div><div class=\"sense\"><b>—2)</b> <i>to tremble</i>. <span class=\"citation\">Targ. Ps. XCVII, 4</span>. <span class=\"citation\">Targ. Y. Ex. XXXII, 11</span> (h. text <span dir=\"rtl\">ויחל</span>); a. e.</div></div>","alt":[]},"11293":{"h":"חָלַט I","r":"H01020","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָלַט II\"><span dir=\"rtl\">חָלַט</span> II</a>, a. Syr. <a href=\"#\" data-headword=\"חֲלַט\">חלט</a> P. Sm. 1277) <i>bind up, mix</i>, esp. <i>to stir flour in hot water</i>, v. <a href=\"#\" data-headword=\"חֲלִיטָה II\"><span dir=\"rtl\">חֲלִיטָה</span> II</a>.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"חָלוּט\">חָלוּט</a> a paste prepared by stirring, <i>dumpling</i>. <span class=\"citation\">Y. Ḥall. I, 58ᵃ</span> top; <span class=\"citation\">Y. Maasr. I, 49ᵇ</span> <span dir=\"rtl\">ח׳ ברור</span> a real <i>ḥalut</i> (concerning which there is no doubt as to the obligation of <i>Ḥallah</i>). <span class=\"citation\">Y. Ab. Zar. II, 42ᵃ</span> top <span dir=\"rtl\">ה׳ מחוסר וכ׳</span> the <i>ḥalut</i> (prepared by a gentile) wants finishing through fire (frying or boiling); a. fr.</div><div class=\"sense\"><b>Nif. נֶחְלַט</b> <div class=\"sense\"><i>to become consistent through stirring</i>. Y. Ḥall. l. c. <span dir=\"rtl\">נֶחְלְטָה כל צורכה</span> sufficiently stirred to be a consistent paste-ball.</div></div>","alt":[]},"11294":{"h":"חֲלַט","r":"H01021","html":"<div class=\"sense\"><b>1)</b> <i>to make a paste</i>. <span class=\"citation\">Targ. II Sam. XIII, 6</span>.</div><div class=\"sense\"><b>—2)</b>  (cmp. next wds. a. <span dir=\"rtl\">צמת</span>) <i>to cause contraction</i> by scalding or by putting in vinegar. <i>Part. pass</i>. <span dir=\"rtl\">חָלִיט</span>. <span class=\"citation\">Ḥull. 111ᵃ</span> ח׳ הוי מעיקרא Rashi (ed. <span dir=\"rtl\">מִיּחֲלַט הוה ח׳ ליה וכ׳</span>) it (the liver) was first scalded (so as to emit no blood in boiling).</div><div class=\"sense\"><b>Pa. חַלֵּיט</b> <div class=\"sense\"><i>to cause contraction, to scald, put in vinegar</i>. Ib. <span dir=\"rtl\">חַלְּטֵי ליה וכ׳</span>. <span class=\"citation\">Pes. 74ᵇ</span> bot. <span dir=\"rtl\">חלא דח׳ ביה וכ׳</span> vinegar which one has used once for drawing the blood from meat and contracting the blood vessels, must not be used a second time.</div></div><div class=\"sense\"><b>Ithpa. אִתְחַלַּט</b> </div><div class=\"sense\"><b>Ithpe. אִיתְחֲלַט  אִיחְלט</b> <div class=\"sense\"><b>1)</b> <i>to be mixed up, to mingle</i>. <span class=\"citation\">Targ. Prov. XX, 19</span>; <span class=\"citation\">XXIV, 21</span> (h. text <span dir=\"rtl\">תתערב</span>).</div><div class=\"sense\"><b>—2)</b> <i>to be confused</i>. Ib. XIV, 16 (h. text <span dir=\"rtl\">מתעבר</span>!).</div><div class=\"sense\"><b>—3)</b> <i>to be contracted</i>, v. supra.</div></div>","alt":[]},"11295":{"h":"חָלַט II","r":"H01022","html":"<div class=\"sense\"> [<i>to surround, tie up</i> (corresp. to b. h. <span dir=\"rtl\">צמת</span>),] </div><div class=\"sense\"><b>1)</b> <i>to make final.</i> <i> Part. pass</i>. <a href=\"#\" data-headword=\"חָלוּט\">חָלוּט</a>, f. <span dir=\"rtl\">חֲלוּטָה</span> <i>permanently sold, irredeemable</i>. <span class=\"citation\">Arakh. IX, 4</span> <span dir=\"rtl\">הגיע … היה ח׳ וכו׳</span> (Talm. ed. 31ᵃ <span dir=\"rtl\">היתה ח׳</span>, read: <span dir=\"rtl\">חלוטה</span>) when the last day … had passed and it (the house) was not redeemed, it was his forever …, for we read <span dir=\"rtl\">לצמיתות</span> (<span class=\"citation\">Lev. XXV, 30</span>); (Tosef. ib. V, 10 <span dir=\"rtl\">צמת</span>). Arakh. l. c. <span dir=\"rtl\">בראשונה … שיהא ח׳ לו</span> formerly the purchaser used to hide himself on the last day … in order that it might become his irredeemably; Sifra B’har ch. V, Par. 4 <span dir=\"rtl\">שתהא חלוטה לו</span>. <span class=\"citation\">Arakh. 31ᵇ</span> <span dir=\"rtl\">למי ח׳</span> to which (of the two buyers) did it belong finally?; a. fr.—V. <a href=\"#\" data-headword=\"חֲלוּטִין\">חֲלוּטִין</a>.</div><div class=\"sense\"><b>—2)</b> <i>to pass final judgment on a leper</i> after probationary enclosure (<span class=\"citation\">Lev. XIII</span>). <span class=\"citation\">Zeb. 102ᵃ</span> אני מסגירה ואני חוֹלְטָהּ וכ׳ I will lock her up, declare her a leper and discharge her.</div><div class=\"sense\"><b>Hif. הֶחֱלִיט</b> <div class=\"sense\"><b>1)</b> <i>to pass final judgment, to make valid; to adjudicate</i>. Y. Dem. VII, beg. 26ᵃ <span dir=\"rtl\">צריך להַחֲלִיט וכ׳</span> he must make the consecrating conditions valid by speech. Y. Keth. X, 33ᵈ bot. <span dir=\"rtl\">אי זה … להַחֲלִיט מַחֲלִיטִין</span> which of them the court chooses to declare valid, it may &amp;c. <span class=\"citation\">Gen. R. s. 61</span> <span dir=\"rtl\">שלא תַחֲלִיט להם וכ׳</span> lest thou surrender the country to them (through bad argument); <span class=\"citation\">Yalk. ib. 110</span> (insert <a href=\"#\" data-headword=\"לָהַם\">להם</a>). Y. Ab. Zar. I, 39ᵇ top <span dir=\"rtl\">גסות … היא הֶחֱלִיטָתוֹ</span> his haughtiness made Jerob. a confirmed sinner; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to declare a person a leper</i>. Y. M. Kat. I, 80ᶜ bot. <span dir=\"rtl\">מטמא ומַחֲלִיט</span> declares him unclean and this a decided leper; <span dir=\"rtl\">ורבנן … ומַחֲלִיטִין</span> and the Rabbis say, he must be examined as if it were a new case, but at all events they declare &amp;c.—<i>Part. pass</i>. <span dir=\"rtl\">מוּחֲלָט</span>, f. <span dir=\"rtl\">מוּחֲלֶטֶת</span> 1) <i>irrevocable, confirmed</i>. <span class=\"citation\">Yoma 86ᵇ</span> <span dir=\"rtl\">תשובת המוּחֲלָטִין</span> the repentance of the confirmed sinners.—2) <i>the declared leper</i>, opp. to <span dir=\"rtl\">מוּסְגָּר</span>. <span class=\"citation\">Meg. I, 7</span>. <span class=\"citation\">Yeb. 103ᵇ</span>. <span class=\"citation\">Tosef. Naz. VI, 1</span> <span dir=\"rtl\">מ׳ בספק</span> one declared a leper from doubt; Y. ib. VIII, end, 57ᵇ; a. fr.</div></div>","alt":[]},"11296":{"h":"חֲלַט ²","r":"H01023","html":"<div class=\"sense\"><b>1)</b> <i>Part.</i> <i> pass</i>. <span dir=\"rtl\">חָלִיט</span>, <a href=\"#\" data-headword=\"חֲלִיטָא I\">חֲלִיטָא</a> <i>irredeemably sold</i>. <span class=\"citation\">Targ. Y. Gen. XLVII, 20</span>.</div><div class=\"sense\"><b>—2)</b> <i>to sentence a leper</i>. <span class=\"citation\">Targ. Y. Deut. XXI, 5</span> <span dir=\"rtl\">למִחְלוֹט</span>, v. <i>Af.</i></div><div class=\"sense\"><b>Pa. חַלֵּיט</b> <div class=\"sense\"><i>to sell irredeemably, to forfeit</i>. Y. Pes. IV, 31ᵇ bot. <span dir=\"rtl\">ולא יְחַלְּטוּן בניהון</span> that they might not forfeit their pledged children. Y. Shebi. VI, 36ᶜ bot. [read:] <span dir=\"rtl\">בגין דלא תְחַלְּטוּן … בידן</span> that you might not surrender the government to their (the Samaritans’) hands. Y. Keth. IX, 33ᵇ bot. <span dir=\"rtl\">אנן מְחַלְּטִין וכ׳</span> we shall declare their property forfeited. <span class=\"citation\">Arakh. 31ᵇ</span> <span dir=\"rtl\">ולחַלְּטֵיה הקדש</span> let the sacred treasury be declared its permanent owner; a. e.</div></div><div class=\"sense\"><b>Af. אַחְלַט</b> <div class=\"sense\"><i>to sentence a leper</i>. <span class=\"citation\">Targ. Y. Lev. XIII, 11</span>.—Part. pass. <span dir=\"rtl\">מַחְלַט</span>, f. <span dir=\"rtl\">מַחְלְטָא</span>. <span class=\"citation\">Ib. 51</span>.</div></div><div class=\"sense\"><b>Ithpe. אִיחֲלַט</b> <div class=\"sense\"><i>to become irredeemable</i>. <span class=\"citation\">Arakh. 32ᵇ</span> <span dir=\"rtl\">וירושלים מי מִיחֲלַט בה</span> are buildings in Jerusalem ever irredeemable?</div></div>","alt":[]},"11297":{"h":"חַלְטָא","r":"H01024","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲלַט ²\">preced.</a>) <i>final decision, adjudication</i>.—Pl. <span dir=\"rtl\">חַלְטָאתָא</span>. <span class=\"citation\">B. Mets. 16ᵇ</span> <span dir=\"rtl\">שטרי ח׳</span> legal documents giving the claimant the title for the seized property.</div>","alt":[]},"11298":{"h":"חַלְטָנִית","r":"H01025","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"חֲלוּטִין\">חֲלוּטִין</a>, <i>final action;</i> לח׳ <i>irredeemably</i>. <span class=\"citation\">Y. Gitt. IV, end, 46ᵇ</span> (expl. <span dir=\"rtl\">לצמיתות</span>, <span class=\"citation\">Lev. XXV, 23</span>) <span dir=\"rtl\">לחול׳</span>; Y. Dem. IV, 24ᵈ bot.—<span class=\"citation\">Gen. R. s. 28</span>, end, v. <a href=\"#\" data-headword=\"זְרִיבָה\">זְרִיבָה</a>; a. e.</div>","alt":["חוּלְ׳"]},"11299":{"h":"חֲלִטְרַיָּא","r":"H01026","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲלִיטָר\">חֲלִיטַר</a></div>","alt":[]},"11300":{"h":"חַלְּטָתָא","r":"H01027","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>lizzard</i>, v. <a href=\"#\" data-headword=\"הַלְטָתָא\">הַלְטָתָא</a>.</div>","alt":[]},"11301":{"h":"חלי","r":"H01028","html":"<div class=\"sense\"><b>1)</b> <i>to be lax, to be sick, faint away, grieve</i>. <span class=\"citation\">Ex. R. s. 43</span> (expl. <span dir=\"rtl\">ויחל</span>, <span class=\"citation\">Ex. XXXII, 11</span> ח׳ משה Moses was sick (grieved). <span class=\"citation\">Kidd. 71ᵇ</span>, a. e. <span dir=\"rtl\">מדי חוֹלָה</span> Media is sick, v. <a href=\"#\" data-headword=\"גֹּוסֵס\">גּוֹסֵס</a>.—<span class=\"citation\">Ber. 28ᵇ</span> <span dir=\"rtl\">כשח׳ וכ׳</span> when R. … fell sick; a. fr.—V. <a href=\"#\" data-headword=\"חוֹלֶה\">חוֹלֶה</a>.</div><div class=\"sense\"><b>—2)</b> <i>to be smooth</i> (to the taste), <i>sweet</i>.</div><div class=\"sense\"><b>Pi. חִלָּה</b> <div class=\"sense\"><b>1)</b> <i>to soften, sweeten; to soothe, assuage</i> (by prayer, gifts &amp;c.). Ex. R. l. c. <span dir=\"rtl\">מהו וַיְחַל שהכניס וכ׳</span> what does <i>vayḥal</i> (Ex. l. c.) mean? He offered &amp;c. (ref. to <span class=\"citation\">Ps. XLV, 13</span>). Ib. <span dir=\"rtl\">מהו ויחל עשה את המר וכ׳</span> he made sweet what was bitter. Ib. <span dir=\"rtl\">חַלֵּי מרירתן וכ׳</span> sweeten thou the bitterness (sin) of Israel &amp;c.—Ib. <span dir=\"rtl\">מי שיְחַלֶּה וכ׳</span> one to sweeten the bitterness &amp;c. (by prayer). <span class=\"citation\">Yalk. Ex. 392</span> <span dir=\"rtl\">אביי אמר עד שחִילֵּהוּ להקב&quot;ה בתפילתו</span> (v. infra) Ab. explained <i>vayḥal</i>, until he assuaged (the anger of) the Lord &amp;c. <span class=\"citation\">Deut. R. s. 3</span> <span dir=\"rtl\">הרי בניך מרים חַלֵּה אותן</span> thy children are bitter, sweeten them. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">היאך יהא א&quot;ל הוי חל אתה רחמים</span>, read: <span dir=\"rtl\">היאך אהא אומר א&quot;ל הוי אומר חַלֵּה את המרים</span> what shall I say? Said He, Say, sweeten &amp;c.; <span class=\"citation\">Yalk. Ex. 392</span>. <span class=\"citation\">Lam. R. to I, 2</span> <span dir=\"rtl\">לא חִלִּינוּ פניך</span> we did not assuage thee by repentance; <span class=\"citation\">Ex. R. s. 45</span> <span dir=\"rtl\">חלִּינוּ מלפני הקב&quot;ה</span> we prayed &amp;c.; a. fr.</div></div><div class=\"sense\"><b>Hif. הֶחֱלָה</b> <div class=\"sense\"><b>1)</b> <i>to assuage, soften</i>. <span class=\"citation\">Ber. 32ᵃ</span> אביי אמר עד שהֶחֱלֵהוּ להקב&quot;ה בתפלה Ms. M. (v. D. S. a. l.) until he assuaged &amp;c., v. supra. [<span class=\"citation\">Ib.</span> <span dir=\"rtl\">שה׳ עליהם וכ׳</span>, read: <span dir=\"rtl\">שהֵחֵל</span>, v. <a href=\"#\" data-headword=\"חָלַל\">חָלַל</a>.]</div><div class=\"sense\"><b>—2)</b> <i>to make sick, wear out</i>. Ib. <span dir=\"rtl\">עמד משה … עד שהחלהו</span> (Ms. M. <span dir=\"rtl\">עד שחלה</span>) Moses stood in prayer … until He wore Him out (by his persistency, v. Rashi a. l. a. Rabb. D. S. a. l. note 3).—3) (v. <a href=\"#\" data-headword=\"חָלַל\">חָלַל</a> a. <a href=\"#\" data-headword=\"חִלְחֵל\">חִלְחֵל</a>) <i>to permeate, affect</i>. <span class=\"citation\">B. Mets. 107ᵇ</span> bile is called <i>maḥlah</i> (v. <a href=\"#\" data-headword=\"מַחֲלָה\">מַחְלָה</a>) <span dir=\"rtl\">שהיא מַחְלָה וכ׳</span> (Ms. F. <span dir=\"rtl\">שמְחַלֶּלֶת</span>) for it goes through the entire body [perh. <a href=\"#\" data-headword=\"מְחִלָּה\">מְחַלָּה</a>, fr. <a href=\"#\" data-headword=\"חָלַל\">חָלַל</a>].</div></div><div class=\"sense\"><b>Hof. הוּחֲלָה</b> <div class=\"sense\"><i>to be made sick</i>. Ber. l. c. <span dir=\"rtl\">עמד … עד שה׳</span> ed. Sonc. a. oth. (v. supra) until He was worn out.</div></div>","alt":["חָלָה"]},"11302":{"h":"חֲלִי","r":"H01029","html":"<div class=\"sense\"><b>1)</b> <i>to be soft, sweet</i>. <span class=\"citation\">Targ. Prov. XXVII, 7</span>. <span class=\"citation\">Targ. Y. II, Lev. II, 11</span> (h. text <span dir=\"rtl\">דבש</span>); a. e.— </div><div class=\"sense\"><b>2)</b> <i>to be sick, grieve</i>. <span class=\"citation\">Yoma 22ᵇ</span>; <span class=\"citation\">B. Kam. 20ᵇ</span> <span dir=\"rtl\">כמה לא ח׳ וכ׳</span> how little does he whom the Lord supports need to grieve or trouble himself!</div><div class=\"sense\"><b>—3)</b> <i>to remit</i>. <span class=\"citation\">Keth. 86ᵃ</span> top <span dir=\"rtl\">ותִיחֲלָה</span>, v. <a href=\"#\" data-headword=\"חוּל\">חוּל</a> II ch.</div><div class=\"sense\"><b>Pa. חַלֵּי</b> <div class=\"sense\"><b>1)</b> <i>to sweeten</i>.—<i>Part. pass</i>. f. <span dir=\"rtl\">מְחַלְיָא</span>. <span class=\"citation\">Cant. R. to III, 4</span> <span dir=\"rtl\">בשעת מְחַלְיַית שינתא</span> during the sweetest sleep. <span class=\"citation\">Ab. Zar. 39ᵃ</span> מח׳ שמנוניתא Ms. M. the fatty substance (absorbed in the knife) becomes sweet again (loses its bad taste); ed. <span dir=\"rtl\">מְחַלְּיָּא ליה ש׳</span> (read: <a href=\"#\" data-headword=\"לִישָׁן\">לש׳</a>) it (the strong taste of assa foetida) sweetens &amp;c. [<span class=\"citation\">Ber. 6ᵇ</span> <span dir=\"rtl\">קא מחליין</span> ed., Ms. <span dir=\"rtl\">מחללי</span>, v. <a href=\"#\" data-headword=\"חֲלַל I\"><span dir=\"rtl\">חֲלַל</span> I</a>.]</div></div><div class=\"sense\"><b>Ithpe. (אִתַּחֲלִי) אִתְחֲלִי</b> <div class=\"sense\"><i>to become sweet</i>. <span class=\"citation\">Targ. Y. II, Ex. XV, 25</span>.</div></div>","alt":["חֲלָא"]},"11303":{"h":"חָלֵי","r":"H01030","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲלִי\">preced.</a>) <i>sweet</i>. <span class=\"citation\">Targ. Y. II, Gen. XLIX, 21</span>. <span class=\"citation\">Targ. Y. II, Deut. XXIX, 17</span> (ed. Amst. <a href=\"#\" data-headword=\"חֲלִי\">חֲלֵי</a>; Y. I <a href=\"#\" data-headword=\"חוּלֵי\">חוֹלֵי</a>, <a href=\"#\" data-headword=\"חוּלֵי\">חוּלֵי</a>).—<span class=\"citation\">Arakh. 10ᵇ</span> (play on <a href=\"#\" data-headword=\"חָלִיל\">חָלִיל</a>) <span dir=\"rtl\">דח׳ קליה</span> because its sound is sweet.—<i>Fem.</i> <a href=\"#\" data-headword=\"חַלְיָא\">חַלְיָא</a>, <a href=\"#\" data-headword=\"חֲלִיאֲתָא\">חֲלִיאֲתָא</a>, <a href=\"#\" data-headword=\"חֲלִיתָא\">חֲלִיתָא</a>. <span class=\"citation\">Targ. Prov. XXIV, 13</span> <span dir=\"rtl\">דחליא</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">דחֵילָא</span>, corr. acc.).—<span class=\"citation\">Targ. Ps. XIX, 11</span> (Ms. <span dir=\"rtl\">חֲלָיָיאתָא</span>, pl.)—<span class=\"citation\">Sabb. 109ᵇ</span> <span dir=\"rtl\">אתרוגא חליתא</span> a sweet orange.—Pl. <a href=\"#\" data-headword=\"חִלִּין\">חַלְיָן</a>, <span dir=\"rtl\">(<span dir=\"rtl\">חוּלְיֵי</span>) <span dir=\"rtl\">חַלְיָין</span></span>. <span class=\"citation\">Targ. Ps. CXIX, 103</span>. <span class=\"citation\">Targ. Prov. IX, 17</span> (some ed. <span dir=\"rtl\">חלים</span>, corr. acc.) <span class=\"citation\">Ib. II, 16</span>.—<span class=\"citation\">Ab. Zar. 38ᵇ</span> <span dir=\"rtl\">חוּלְיֵי</span> as to sweet ones, v. <a href=\"#\" data-headword=\"אֲהִינָא\">אֲהִינָא</a>.</div>","alt":[]},"11304":{"h":"חֳלִי","r":"H01031","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>disease</i>. <span class=\"citation\">Snh. 64ᵃ</span> <span dir=\"rtl\">אם תעמוד … מחָלְיָהּ</span> if this woman (I) shall rise from her sickness. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מוטב שתחזור … לחוֹלְיָהּ</span> I would rather relapse into my disease; a. fr.—<span class=\"citation\">B. Mets. 87ᵃ</span> <span dir=\"rtl\">דחָלָה ח׳ אחריתי</span> (missing in Mss., v. Rabb. D. S. a. l. note) that he had been sick once before.—Pl. <a href=\"#\" data-headword=\"חֳלָאִים\">חֳלָאִים</a>, <a href=\"#\" data-headword=\"חֳלָאִים\">חֳלָאִין</a>, <span dir=\"rtl\">חֳלָיִם</span>, <a href=\"#\" data-headword=\"חֳלָאִים\">חֳלָיִים</a>. <span class=\"citation\">Sot. 47ᵃ</span>. <span class=\"citation\">Gen. R. s. 56</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (sub. <span dir=\"rtl\">בעל</span>) <i>patient, sufferer</i>. <span class=\"citation\">Ḥull. 110ᵃ</span>; a. fr.</div>","alt":["חוֹלִי"]},"11305":{"h":"חַלְיָא","r":"H01032","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חלי\">חלי</a>) <i>secretion, serum</i>. <span class=\"citation\">Pes. 74ᵇ</span> <span dir=\"rtl\">חַלְיֵיה אסיר</span> its serum is forbidden. [<span class=\"citation\">Ib. 115ᵇ</span> <span dir=\"rtl\">חלייה דתבלין</span>, v. <a href=\"#\" data-headword=\"חוּלְיָא II\"><span dir=\"rtl\">חוּלְיָא</span> II</a>.]</div>","alt":[]},"11306":{"h":"חֲלִיאֲתָא","r":"H01033","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָלֵי\">חָלֵי</a></div>","alt":[]},"11307":{"h":"חִלִּיז","r":"H01034","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חִלָּזוֹן\">חִלָּזוֹן</a>) <i>one afflicted with an eye-disease called</i> <a href=\"#\" data-headword=\"חִלָּזוֹן\">חִלָּזוֹן</a>. <span class=\"citation\">Targ. O. Lev. XXI, 20</span> (ed. Berl. <a href=\"#\" data-headword=\"חִלִּין\">חִלִּין</a>, v. Berl. Masorah p. 72).</div>","alt":["חִילִּ׳"]},"11308":{"h":"חַלֵּיז","r":"H01035","html":"<div class=\"sense\">, <i>Pa.</i> of <a href=\"#\" data-headword=\"חֲלַז\">חֲלַז</a>.</div>","alt":[]},"11309":{"h":"חֲלִיטָא I","r":"H01036","html":"<div class=\"sense\"> f. part. of <a href=\"#\" data-headword=\"חֲלַט\">חֲלַט</a>.</div>","alt":[]},"11310":{"h":"חֲלִיטָא II","r":"H01037","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָלַט II\"><span dir=\"rtl\">חָלַט</span> II</a>) <i>strings, necklace</i>. <span class=\"citation\">Targ. Is. III, 20</span> (h. text <span dir=\"rtl\">לחשים</span>). <span class=\"citation\">Targ. Hos. II, 15</span> <span dir=\"rtl\">חֲלִיטַת וכ׳</span> (constr.) her pearl-strings (h. text <span dir=\"rtl\">חליה</span>).</div>","alt":["חֲלִיטָתָא"]},"11311":{"h":"חֲלִיטָא III","r":"H01038","html":"<div class=\"sense\"> c. ch. = h. or <a href=\"#\" data-headword=\"חָלוּט\">חָלוּט</a> (v. <a href=\"#\" data-headword=\"חָלַט I\"><span dir=\"rtl\">חָלַט</span> I</a>). <span class=\"citation\">Y. Ned. VI, beg. 39ᶜ</span>; Y. Naz. V, 55ᶜ top. <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> bot. <a href=\"#\" data-headword=\"חֲלִיטָא III\">חֲלִיטָן</a> their (the Samaritans’) <i>ḥalut.</i>—<i>Pl.</i> (fem.) <a href=\"#\" data-headword=\"חֲלִיטָא II\">חֲלִיטָתָא</a>; (masc.) <span dir=\"rtl\">חֲלִיטִין</span>. <span class=\"citation\">Targ. II Sam. XIII, 6</span>; <span class=\"citation\">8</span>.—<span class=\"citation\">Y. Ḥall. I, 57ᵈ</span> ח׳ דשוק <i>ḥ</i>. sold in the market (mixed with oil), v. <a href=\"#\" data-headword=\"אִסְקְרִיטִין\">אִסְקְרִיטִין</a>.—<span class=\"citation\">Ib.</span> (expl. <span dir=\"rtl\">חלת מסרת</span>) <span dir=\"rtl\">ח׳ דמיי</span> water-<i>ḥ</i>. (for which <span class=\"citation\">Pes. 37ᵇ</span> <span dir=\"rtl\">חלוט של בעלי בתים</span>). <span class=\"citation\">Y. Erub. III, 20ᵈ</span> <span dir=\"rtl\">אכל חליטן</span> (read: <span dir=\"rtl\">חליטין</span> or <a href=\"#\" data-headword=\"חֲלִיטָא I\">חליטא</a>); <span class=\"citation\">Gen. R. s. 94</span>, beg. <a href=\"#\" data-headword=\"חֲלוּטִין\">חֲלוּטִין</a> (Ar. <span dir=\"rtl\">אְלִיטִין</span>, dial. for <span dir=\"rtl\">הֲ׳</span>).</div>","alt":["(חֲלִיטָה","חֲלוּ׳)"]},"11312":{"h":"חֲלִיטָה I","r":"H01039","html":"<div class=\"sense\"> f. = ch. <a href=\"#\" data-headword=\"חֲלִיטָא II\"><span dir=\"rtl\">חֲלִיטָא</span> II</a>. <span class=\"citation\">Y. Meg. I, 71ᶜ</span> bot. <span dir=\"rtl\">היה עשוי כחצי ח׳</span> if the writing was in the shape of half a necklace (of three or more strings, i.e. in decreasing lines).</div>","alt":[]},"11313":{"h":"חֲלִיטָה II","r":"H01040","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"חָלוּט\">חָלוּט</a>, v. <a href=\"#\" data-headword=\"חָלַט I\"><span dir=\"rtl\">חָלַט</span> I</a>) <i>a paste made of flour stirred in boiling water, dumpling.</i> <span class=\"citation\">Ḥall. I, 6</span>; Y. ib. 58ᵃ top <span dir=\"rtl\">ח׳ קמח לתוך חמין</span> <i>ḥălitah</i> is flour put into hot water, contrad. to <a href=\"#\" data-headword=\"מְעִיסָה\">מעיסה</a> which is <span dir=\"rtl\">חמין לתוך קמח</span> (v. <span class=\"citation\">Tosef. ib. I, 1</span>); <span class=\"citation\">Pes. 37ᵇ</span> (Ms. O. <span dir=\"rtl\">החלטה</span>; v. vers. in Rabb. D. S. a. l. note 6); Y. ib. II, 29ᶜ.—<span class=\"citation\">Y. Ber. VI, 10ᵇ</span></div>","alt":["(הַחֲלָטָה)"]},"11314":{"h":"חֲלִיטָה III","r":"H01041","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (חָלַט II, v. <a href=\"#\" data-headword=\"הֶחְלֵט\">הֶחְלֵט</a>) <i>the priest’s final decision on leprosy</i>. Sifra Thazr. Par. 3, ch. IV <span dir=\"rtl\">לאחר חֲלִיטַת מחיה וכ׳</span> (R. S. to <span class=\"citation\">Neg. VIII, 1</span> <a href=\"#\" data-headword=\"חִלּוּט\">חִלּוּט</a>) immediately after having originally declared it unclean on account of a sound spot in the sore (<span class=\"citation\">Lev. XIII, 10</span>, sq.). [Ib. <span dir=\"rtl\">החלט מחיה</span>].</div>","alt":[]},"11315":{"h":"חֲלִיטָר","r":"H01042","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"חֲלִיטָא III\"><span dir=\"rtl\">חֲלִיטָא</span> III</a>) <i>seller of pastry, confectioner</i>. Y. B. Bath. II, beg., 13ᵇ, v. <a href=\"#\" data-headword=\"אִיסטֵיב\">אִיסְטֵיב</a>. <span class=\"citation\">Y. Ḥall. II, 58ᶜ</span> bot.; a. e.—Pl. <a href=\"#\" data-headword=\"חֲלִטְרַיָּא\">חֲלִיטְרַיָּא</a>. <span class=\"citation\">Y. Shebi. VII, 37ᶜ</span> top <a href=\"#\" data-headword=\"חֲלִטְרַיָּא\">חלטריא</a>.</div>","alt":["חֲלִיטְרָא"]},"11316":{"h":"חלייה","r":"H01043","html":"<div class=\"sense\">, <span class=\"citation\">Pes. 115ᵇ</span>, v. <a href=\"#\" data-headword=\"חוּלְיָא II\"><span dir=\"rtl\">חוּלְיָא</span> II</a></div>","alt":[]},"11317":{"h":"חָלֵיל","r":"H01044","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָלַל\">חָלַל</a>) <i>to turn, bore, chisel</i>. <span class=\"citation\">Targ. Is. X, 15</span>.</div>","alt":[]},"11318":{"h":"חָלִיל","r":"H01045","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"חָלֵיל\">preced.</a>) <i>fife, flute; </i>frequ. <span dir=\"rtl\">הֶחָלִיל</span> <i>the flute-players, the music in the procession</i>. <span class=\"citation\">Arakh. II, 3</span> <span dir=\"rtl\">הח׳ מכה וכ׳</span> the fluters play in front of the altar. <span class=\"citation\">Ib. 10ᵇ</span> היינו ח׳ היינו אבוב <i>ḥalil</i> and <i>abbub</i> are the same. <span class=\"citation\">Bicc. III, 3</span> <span dir=\"rtl\">הח׳ מכה לפניהם</span> the fluters precede them playing. <span class=\"citation\">Succ. V, 1</span> <span dir=\"rtl\">הח׳ חמשה וכ׳</span> for musical performance (on the Succoth festival) there are five and six days respectively; a. fr.—Pl. <a href=\"#\" data-headword=\"חֲלִיפִים\">חֲלִילִים</a>, <a href=\"#\" data-headword=\"חֲלִיפִים\">חֲלִילִין</a>. <span class=\"citation\">Arakh. II, 3</span>. <span class=\"citation\">B. Mets. VI, 1</span> <span dir=\"rtl\">להביא ח׳ וכ׳</span> to bring pipers for a wedding or a funeral. Kinnim III, 6; a. fr.</div>","alt":[]},"11319":{"h":"חָלִילָא","r":"H01046","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Deut. XVI, 14</span>.—Pl. <a href=\"#\" data-headword=\"חֲלִיפִים\">חֲלִילִין</a>. <span class=\"citation\">Targ. Ps. CL, 4</span> (h. text <a href=\"#\" data-headword=\"מִנִּי\">מִנִּים</a>).</div>","alt":[]},"11320":{"h":"חֲלִילָא","r":"H01047","html":"<div class=\"sense\"> c. (v. <a href=\"#\" data-headword=\"חָלִילָא\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>hollow</i>. Constr. <a href=\"#\" data-headword=\"חָלִיל\">חֲלִיל</a>. <span class=\"citation\">Targ. Ex. XXVII, 8</span> (h. text <a href=\"#\" data-headword=\"נָבוּב\">נְבוּב</a>).</div><div class=\"sense\"><b>—2)</b> <i>rounded, going all around</i>. <span class=\"citation\">B. Bath. 61ᵃ</span>, v. <a href=\"#\" data-headword=\"*בַּרְקָא III\"><span dir=\"rtl\">בַּרְקָא</span> III</a>.—<span class=\"citation\">Ab. Zar. 10ᵇ</span>, v. <span dir=\"rtl\">קמוניא</span>.—Pl. <span dir=\"rtl\">חֲלִילַיָּא</span>, f. <a href=\"#\" data-headword=\"חֲלִיטָא II\">חֲלִילָתָא</a>. <span class=\"citation\">Targ. II Chr. XXVI, 15</span>.—<span class=\"citation\">Sabb. 57ᵃ</span> <span dir=\"rtl\">תיכי ח׳</span> chains composed of chord rings (v. <a href=\"#\" data-headword=\"חוּלְיָא I\"><span dir=\"rtl\">חוּלְיָא</span> I</a>).</div>","alt":[]},"11321":{"h":"חָלִילָה","r":"H01048","html":"<div class=\"sense\"> adv. (v. <a href=\"#\" data-headword=\"חֲלִילָא\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>round about, in turn</i>. <span class=\"citation\">Succ. V, 6</span> <span dir=\"rtl\">חוזרין ח׳</span> they take turns all around. <span class=\"citation\">Keth. X, 6</span>. <span class=\"citation\">Tosef. Zeb. I, 1</span> <span dir=\"rtl\">חזרנו ח׳</span> we are moving in a circle, i.e. this way of arguing will lead to no conclusion; <span class=\"citation\">Zeb. 10ᵇ</span> <span dir=\"rtl\">חוזרני ח׳</span> ed. I am moving &amp;c.; a. e.</div><div class=\"sense\"><b>—2)</b> (b. h.; <i>outside, foreign to</i>. <span class=\"citation\">Gen. R. s. 49</span>; <span class=\"citation\">Yalk. ib. 83</span> (expl. <span dir=\"rtl\">חללה</span>, <span class=\"citation\">Gen. XVIII, 25</span>), v. <a href=\"#\" data-headword=\"בָּרָאָה\">בָּרָאָה</a>, a. <a href=\"#\" data-headword=\"חוֹל III\"><span dir=\"rtl\">חוֹל</span> III</a>; Tanḥ. Vayera 8 <span dir=\"rtl\">חֲלָלָה כתיב</span> it may be read <i>ḥălalah</i> (desecration), <span dir=\"rtl\">לא חול הוא לך</span> is it not too profane for thee?</div>","alt":[]},"11322":{"h":"חַלִּים","r":"H01049","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(cmp. <a href=\"#\" data-headword=\"חָלוּם\">חָלוּם</a> s. v. <a href=\"#\" data-headword=\"חָלַם I\"><span dir=\"rtl\">חָלַם</span> I</a>) <i>sound, capable of restoration to the original strength</i> or <i>form</i>. <span class=\"citation\">Ab. Zar. 69</span><sub>q</sub> <span dir=\"rtl\">זימנין דח׳</span> sometimes the disturbed pitching of the stopper resumes its original shape (by melting and hardening again). <span class=\"citation\">Ḥull. 123ᵇ</span> <span dir=\"rtl\">עור ח׳</span> leather (if split or rent) can be so mended as to regain its original strength. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כי אמרינן דח׳ וכ׳</span> when do we say, leather can be mended &amp;c., when it is split straight through.—[<span class=\"citation\">R. Hash. 28ᵃ</span>, v. <a href=\"#\" data-headword=\"חָלַם I\"><span dir=\"rtl\">חָלַם</span> I</a>].—[<span class=\"citation\">Targ. Prov. IX, 17</span> <span dir=\"rtl\">חלים</span> some ed., v. <a href=\"#\" data-headword=\"חָלֵי\">חָלֵי</a>.]</div>","alt":[]},"11323":{"h":"חֲלִים","r":"H01050","html":"<div class=\"sense\"><i>dreaming</i>, v. <a href=\"#\" data-headword=\"חָלַם II\"><span dir=\"rtl\">חֲלַם</span> II</a>.</div>","alt":[]},"11324":{"h":"חַלֵּים","r":"H01051","html":"<div class=\"sense\">, <i>Pa.</i> of <a href=\"#\" data-headword=\"חָלַם I\"><span dir=\"rtl\">חֲלַם</span> I</a>.</div>","alt":[]},"11325":{"h":"חֲלִימָה","r":"H01052","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֶלְמָה\">חֶלְמָה</a></div>","alt":[]},"11326":{"h":"חִלִּין","r":"H01053","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִלִּיז\">חִלִּיז</a></div>","alt":[]},"11327":{"h":"חֲלֵיף","r":"H01054","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲלַף I\">חֲלַף</a></div>","alt":[]},"11328":{"h":"חַלִּיף","r":"H01055","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָלַף\">חָלַף</a>) <i>sharp knife, slaughtering-knife</i>.—Pl. <span dir=\"rtl\">חַלִּיפוֹת</span>.—<span dir=\"rtl\">בית הח׳</span> the place in the Temple where the slaughtering knives were kept. <span class=\"citation\">Midd. IV, 7</span> (Talm. ed. <span dir=\"rtl\">פת …</span>, corr. acc.); <span class=\"citation\">Yoma 36ᵃ</span> מן בית הח׳ וכ׳ Ms. M. a. Ar. (ed. <span dir=\"rtl\">מן הח׳</span>) inside of the knives’ cell.</div>","alt":[]},"11329":{"h":"חֲלִיפָא","r":"H01056","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḥălifa</i>. <span class=\"citation\">B. Bath. 123ᵃ</span> bot. <span dir=\"rtl\">אבא ח׳</span> (Ms. M. <span dir=\"rtl\">חלפתא</span>, Var. <a href=\"#\" data-headword=\"חִילְפָא I\">חילפא</a>, <a href=\"#\" data-headword=\"חִלְפָא\">חלפא</a>, <a href=\"#\" data-headword=\"סִלְסוּל\">סיל׳</a>, v. Rabb. D. S. a. l. note).</div>","alt":[]},"11330":{"h":"חֲלִיפָה","r":"H01057","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>replacement, substitution</i>. <span class=\"citation\">Y. Ber. II, 5ᶜ</span> when a scholar dies, <span dir=\"rtl\">מי מביא לנו חֲלִיפָתוֹ</span> who will get us one to take his place?</div><div class=\"sense\"><b>—2)</b>  pl. <span dir=\"rtl\">חֲלִיפוֹת</span> <i>shoots</i>, v. <a href=\"#\" data-headword=\"חֵלֶף II\"><span dir=\"rtl\">חֵלֶף</span> I</a>.</div>","alt":[]},"11331":{"h":"חֲלִיפִים","r":"H01058","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָלַף\">חָלַף</a>) </div><div class=\"sense\"><b>1)</b> <i>exchange, substitution</i>. <span class=\"citation\">Kidd. I, 6</span> <span dir=\"rtl\">כיון … זה בחֲלִיפָיו</span> as soon as one of the parties to the exchange has taken possession, the other takes the risk for its exchange. <span class=\"citation\">Y. Ber. II, 5ᶜ</span>, a. e. <span dir=\"rtl\">יש להן ח׳</span> can be replaced; a. fr.—Esp. <i>ḥălifin</i>, a form of possession by handing to the purchaser an object as a symbolical substitute (v. <span class=\"citation\">Ruth IV, 7</span>). <span class=\"citation\">Kidd. 22ᵇ</span> <span dir=\"rtl\">אף כח׳</span> a slave, may be taken possession of also by symbol. <span class=\"citation\">B. Mets. 45ᵇ</span>, a. fr. <span dir=\"rtl\">אין מטבע נעשה ח׳</span> coins cannot be used for symbolical delivery; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>young shoots</i> (coming out of a stump). <span class=\"citation\">Shebi. I, 8</span>. <span class=\"citation\">Tosef. B. Kam. II, 1</span> (Y. ib. 3ᵃ top <a href=\"#\" data-headword=\"חִילְפִין\">חִילְפִין</a>).</div>","alt":["חֲלִיפִין"]},"11332":{"h":"חָלִיץ","r":"H01059","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָלַץ\">חָלַץ</a>) <i>knot, loop-knot</i>.—Pl. <span dir=\"rtl\">חֲלִיצִין</span>. <span class=\"citation\">Tosef. Neg. V, 10</span> <span dir=\"rtl\">ח׳ שבבקעת</span> ed. Zuck. (Var. <span dir=\"rtl\">שבפקע׳</span>; some ed. incorr. <span dir=\"rtl\">הליצו</span>) the loops in a skein.</div>","alt":[]},"11333":{"h":"חֲלִיצָה","r":"H01060","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָלַץ\">חָלַץ</a>) <i>taking out; untying, putting off</i>. <span class=\"citation\">Tosef. Neg. VI, 10</span> <span dir=\"rtl\">בח׳</span> as regards taking out the leprous stone (<span class=\"citation\">Lev. XIV, 40</span>), v. <a href=\"#\" data-headword=\"נְתִיצָה\">נְתִיצָה</a>. <span class=\"citation\">Y. Ber. III, beg. 5ᵈ</span> <span dir=\"rtl\">בח׳</span> as regards taking off the T’fillin.—Esp. (= <span dir=\"rtl\">חֲלִיצַת מַנְעָל</span>) <i>Hălitsah</i>, the ceremony of taking off the Yabam’s shoe (<span class=\"citation\">Deut. XXV, 5—11</span>). <span class=\"citation\">Yeb. XII, 1</span> <span dir=\"rtl\">מצות ח׳ וכ׳</span> the proper way of performing the <i>Ḥ</i>. is before three men acting as judges. Ib. <span dir=\"rtl\">חֲלִיצָתָהּ פסולה</span> the act &amp;c. is invalid; a. v. fr.</div>","alt":[]},"11334":{"h":"חֲלִיצְתָּא","r":"H01061","html":"<div class=\"sense\"> <span class=\"citation\">Yeb. 102ᵃ</span> <span dir=\"rtl\">ח׳ מעליתא</span> a fully legal <i>Ḥălitsah</i>. <span class=\"citation\">Ib. 106ᵇ</span> <span dir=\"rtl\">גיטא דח׳</span> a document testifying to the performance of the <i>Ḥălitsah</i></div>","alt":[]},"11335":{"h":"חָלִיק","r":"H01062","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֵילֶק II\"><span dir=\"rtl\">חֵילֶק</span> II</a></div>","alt":["חֲלִיקֵי"]},"11336":{"h":"חֲלִיקָה","r":"H01063","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֶילְקָא II\"><span dir=\"rtl\">חֶילְקָא</span> II</a></div>","alt":[]},"11337":{"h":"חליקוסתא","r":"H01064","html":"<div class=\"sense\">, <span class=\"citation\">B. Kam. 31ᵃ</span> Ar., Ms. H., v. <a href=\"#\" data-headword=\"סְלִיקוּסְתָּא\">סְלִיקוּסְתָּא</a></div>","alt":["חלקוסתא"]},"11338":{"h":"חֲלִיקוּפְרִי","r":"H01065","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (patron. of Σόλοι Κύπριοι) <i>one from Soloe</i> (<i>Aligora</i>), a sea-port town of Cyprus. <span class=\"citation\">Makhsh. I, 3</span> Abba José ח׳ איש טבעון Ar. (ed. two words) of Soloe, a citizen of Tibon.</div>","alt":["חֲלִי קוּפְרִי"]},"11339":{"h":"חָלִישׁ","r":"H01066","html":"<div class=\"sense\"><i>to be weak</i>, v. <a href=\"#\" data-headword=\"חֲלַשׁ\">חֲלַשׁ</a>.</div>","alt":[]},"11340":{"h":"חֲלִישׁ","r":"H01067","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"חַלָּשׁ\">חַלָּשׁ</a>, <i>weak, sick</i>. <span class=\"citation\">Targ. Joel IV, 10</span> (ed. Lag. <a href=\"#\" data-headword=\"חֲלַשׁ\">חֲלַשׁ</a>).—<i>Fem.</i> <span dir=\"rtl\">חַלִּישָׁא</span>. <span class=\"citation\">Targ. Lam. I, 13</span> (Var. <a href=\"#\" data-headword=\"חֲלִי\">חֲלִי׳</a>; h. text <a href=\"#\" data-headword=\"דָּוָה\">דָּוָה</a>). <span class=\"citation\">Targ. I Sam. IX, 21</span> <a href=\"#\" data-headword=\"חַלָּשׁ ²\">חֲלָשָׁא</a>.</div>","alt":["חָלִישׁ"]},"11341":{"h":"חֲלִישׁוּת","r":"H01068","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲלִישׁ\">preced.</a>) <i>weakening, faintness</i>. <span dir=\"rtl\">ח׳ דעת</span> <i>humiliation, defeated pride</i>. <span class=\"citation\">Num. R. s. 6</span> לא אעשה להם ח׳ ד׳ I will not make them feel humiliated.</div>","alt":[]},"11342":{"h":"חֲלִישׁוּתָא","r":"H01069","html":"<div class=\"sense\"><span class=\"citation\">Targ. Hos. VII, 9</span> (h. text <a href=\"#\" data-headword=\"שֵׂיבָה\">שֵׂיבָה</a>, ed. Lag. <a href=\"#\" data-headword=\"חַלָּשׁוּת\">חַלָּשׁוּ׳</a>).</div>","alt":[]},"11343":{"h":"חלישתא","r":"H01070","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲשִׁילְתָּא\">חֲשִׁילְתָּא</a></div>","alt":[]},"11344":{"h":"חֲלִיתָא","r":"H01071","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>sweet</i>, v. <a href=\"#\" data-headword=\"חָלֵי\">חָלֵי</a>.</div>","alt":[]},"11345":{"h":"חלך","r":"H01072","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Job XI, 17</span>, v. <a href=\"#\" data-headword=\"חֲלַד\">חֲלַד</a></div>","alt":[]},"11346":{"h":"חָלַל","r":"H01073","html":"<div class=\"sense\"> H. Dict.<sup>10</sup> s. vv. <span dir=\"rtl\">חלל I</span>, II) </div><div class=\"sense\"><b>1)</b>  (v. <a href=\"#\" data-headword=\"חוּל\">חוּל</a>) <i>to roll, turn</i>. <span class=\"citation\">Ber. 32ᵃ</span> (ref. to <span dir=\"rtl\">ייחל</span>, <span class=\"citation\">Ex. XXXII, 11</span>) <span dir=\"rtl\">שחַל עליהם מדת הדין למדת הרחמים</span> Ms. M. (v. <a href=\"#\" data-headword=\"חָלָה\">חָלָה</a>) he (Moses) turned justice into mercy in their behalf; <span class=\"citation\">Yalk. Ex. 392</span> <a href=\"#\" data-headword=\"חָלַל\">הֵחֵל</a> (<i>Hif.</i>).—[Tanḥ. Yithro 1 <span dir=\"rtl\">מת חולל</span>, read <span dir=\"rtl\">וחָלָל</span>.]</div><div class=\"sense\"><b>—2)</b> <i>to bore, hollow, pierce</i>, v. <a href=\"#\" data-headword=\"חָלִיל\">חָלִיל</a>, <a href=\"#\" data-headword=\"חָלָל I\"><span dir=\"rtl\">חָלָל</span> I</a>. I.</div><div class=\"sense\"><b>—3)</b> <i>to surround; to place outside a circle</i>, v. <a href=\"#\" data-headword=\"חוֹל III\"><span dir=\"rtl\">חוֹל</span> III</a>, <a href=\"#\" data-headword=\"חִילּוֹנִי\">חִילּוֹנִי</a>.</div><div class=\"sense\"><b>Nif. נֶחְלַל</b> <div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָלָל I\"><span dir=\"rtl\">חָלָל</span> I</a>) <i>to be cut all around, be severed</i>. <span class=\"citation\">Naz. 54ᵃ</span> (ref. to <span class=\"citation\">Num. XIX, 18</span>) <span dir=\"rtl\">בחלל זה אבר הנ׳ מן החי וכ׳</span> ‘on something severed’, that means a limb which has been cut off a living body, and on which there was not flesh enough to have made healing possible; <span dir=\"rtl\">במת זה אבר הנ׳ וכ׳</span> ‘on something dead’, that means a limb severed from a corpse; ib. 53ᵇ</div></div><div class=\"sense\"><b>Nif. נָחוֹל</b> <div class=\"sense\"><i>to become</i> <a href=\"#\" data-headword=\"חוּלִּין\">חוּלִּין</a>, <i>to cease to be sacred.</i> <span class=\"citation\">Shebi. I, 8</span> <span dir=\"rtl\">עד שיֵחוֹלּוּ</span> until the fruits become available for private use; Y. ib. 33ᶜ top <span dir=\"rtl\">מהו עד שיח׳ עד שיפדו או עד שיעשו חולין וכ׳</span> what does <i>ad sheyeḥôllu</i> mean? Until they are redeemed (in the fourth year), or until they become <i>ḥullin</i> of themselves (in the fifth year)?</div></div><div class=\"sense\"><b>Hif. הֵיחֵל</b> <div class=\"sense\"><b>1)</b>  [ [<i>to set in motion</i>,] <i>to begin</i>. <span class=\"citation\">Sifré Num. 134</span> (ref. to <span class=\"citation\">Deut. III, 24</span>) <span dir=\"rtl\">אתה הֲחִילּוֹתָ וכ׳</span> thou hast begun to open the door &amp;c. <span class=\"citation\">Dem. VII, 4</span> ומֵיחֵל ושותה Y. ed. (v. Rabb. D. S. a. l. note) and he may at once commence drinking (Maim.; v. infra).</div><div class=\"sense\"><b>—2)</b> <i>to make</i> <a href=\"#\" data-headword=\"חוּלִּין\">חוּלִּין</a>; <i>to break a vow; to profane</i>. Ber. l. c. (ref. to <span class=\"citation\">Num. XXX, 3</span>) <span dir=\"rtl\">הוא אינו מֵיחֵל אבל אחרים מְחַלִּין לו</span> he himself cannot break a vow, but others may break it for him (absolve him; <span class=\"citation\">Ḥag. 10ᵃ</span> … <span dir=\"rtl\">מיחל … מוֹחֲלִין</span>; <span class=\"citation\">Ex. R. s. 43</span> <span dir=\"rtl\">מוחל אבל … חכם מוֹחֵל</span>, corr. acc.). Dem. l. c. <span dir=\"rtl\">ומיחל ושותה</span> and thus he <i>redeems</i>, and he may drink (R. S.); Tosef. ib. VIII, 7 <span dir=\"rtl\">ומ׳ ושותה מיד</span>.—<span class=\"citation\">Kidd. 77ᵃ</span> (ref. to <span class=\"citation\">Lev. XXI, 15</span>) <span dir=\"rtl\">מֵיחֵל</span> he <i>produces profanation</i> (begets degraded priests), v. <a href=\"#\" data-headword=\"חָלָל II\"><span dir=\"rtl\">חָלָל</span> II</a>.—3) <i>to turn, change</i>. <span class=\"citation\">Yalk. Ex. 392</span>, v. supra.</div></div><div class=\"sense\"><b>Pi. חִלֵּל</b> <div class=\"sense\"><b>1)</b> <i>to break a vow, to profane, to desecrate; to degrade</i>. <span class=\"citation\">Deut. R. s. 2</span> (play on <span dir=\"rtl\">החלת</span>, <span class=\"citation\">Deut. III, 24</span>) <span dir=\"rtl\">חִלַּלְתָּ וכ׳</span> hast thou not broken the oath? (<span class=\"citation\">Sifré Num. 134</span> <span dir=\"rtl\">הֲחִלּוֹתָ</span>, v. supra). <span class=\"citation\">Ab. III, 11</span> <span dir=\"rtl\">המְחַלֵּל את הקדשים</span> who treats profanely sacred things (causes them to be carried out and burnt). <span class=\"citation\">Ab. Zar. 28ᵃ</span> <span dir=\"rtl\">מְחַלְּלִין עליה וכ׳</span> you may desecrate the Sabbath for the sake of curing it; a. fr.—Esp. <i>to cause the loss of the priestly status</i>. <span class=\"citation\">Macc. 2ᵃ</span> <span dir=\"rtl\">המְחַלֵּל אינו מִתְחַלֵּל</span> he (the priest marrying a divorced woman) who causes the loss of priestly status (to his issue) does not lose the priestly status himself; <span dir=\"rtl\">הבא לחַלֵּל ולא חִילֵּל</span> he who intended to cause the loss of priestly status (by false testimony) and did not succeed.</div><div class=\"sense\"><b>—2)</b>  (v. <span class=\"citation\">Deut. XIV, 24</span>, sq.) <i>to redeem, to make available for private use.</i> <span class=\"citation\">Maas. Sh. I, 2</span>; a. fr.</div></div><div class=\"sense\"><b>Pa. חוּלָּל</b> <div class=\"sense\"><b>1)</b> <i>to be removed from the priestly status, become a</i> <a href=\"#\" data-headword=\"חָלָל I\">חָלָל</a>. <span class=\"citation\">Kidd. 77ᵃ</span> (ref. to <span class=\"citation\">Lev. XXI, 15</span> ‘he shall not degrade’) <span dir=\"rtl\">לא יְחוּלָּל זה וכ׳</span> no degradation shall be caused—which can only refer to a person who had a status and now becomes degraded (i.e. his wife).</div><div class=\"sense\"><b>—2)</b> <i>to be redeemed, to become secular again</i>. Part. <span dir=\"rtl\">מְחוּלָּל</span>, f. <span dir=\"rtl\">מְחוּלֶּלֶת</span>. <span class=\"citation\">Dem. V, 1</span>, a. fr. <span dir=\"rtl\">ומח׳ על המעות</span> and it is redeemed by setting aside its value. <span class=\"citation\">Maas. Sh. II, 10</span> <span dir=\"rtl\">מה … סלע זו ח׳ עליו</span> (not <span dir=\"rtl\">על זו</span>, v. Rabb. D. S. a. l.) this Sela (which has been set apart as an equivalent for second tithes) shall be redeemed against the wine which the clean (sons of mine) may drink in Jerusalem, i.e. I buy with this Sela only that portion of the wine which the clean may drink. Ib. <span dir=\"rtl\">הרי מעות האלו מְחוּלָּלִים וכ׳</span> that money (dedicated for purchasing equivalents in Jerusalem) shall be redeemed against thy fruits; a. v. fr.</div><div class=\"sense\"><b>—3)</b> <i>to be loosely joined, to be a movable link</i>. <span class=\"citation\">Sabb. 52ᵇ</span> <span dir=\"rtl\">במְחוּלָּלִין</span> referring to movable links, (v. <a href=\"#\" data-headword=\"חוּלְיָא I\"><span dir=\"rtl\">חוּלְיָא</span> I</a>). Y. Pes. I, 27ᶜ top <span dir=\"rtl\">במְחוּלָּלוֹת</span> when the vessels can be rolled about, opp. <span dir=\"rtl\">אפוצות</span> close together (v. <a href=\"#\" data-headword=\"חִלְחֵל\">חִלְחֵל</a>).</div></div><div class=\"sense\"><b>Hithpa. הִתְחַלֵּל</b> </div><div class=\"sense\"><b>Nithpa. נִתְחַלֵּל</b> <div class=\"sense\"><b>1)</b>  [ [<i>to be perforated</i>,] (of bowels) <i>to be loose</i>. <span class=\"citation\">Esth. R. to I, 8</span> <span dir=\"rtl\">שיִתְחַלְּלוּ מעיו</span>.</div><div class=\"sense\"><b>—2)</b> <i>to be profaned, desecrated, degraded.</i> <span class=\"citation\">Ab. I, 11</span>. <span class=\"citation\">Macc. 2ᵃ</span>, v. supra. <span class=\"citation\">Yeb. 79ᵃ</span> <span dir=\"rtl\">ואל יתְחַלֵּל וכ׳</span> rather than that the name of the Lord be profaned in public; a. fr.</div></div>","alt":[]},"11347":{"h":"חֲלַל I","r":"H01074","html":"<div class=\"sense\"><b>1)</b> <i>to perforate</i>, v. <a href=\"#\" data-headword=\"חָלֵיל\">חָלֵיל</a>.</div><div class=\"sense\"><b>—2)</b> <i>to degrade, profane</i>. Part. pass. <a href=\"#\" data-headword=\"חָלִיל\">חָלִיל</a>, f. <a href=\"#\" data-headword=\"חֲלִילָא\">חֲלִילָא</a>. <span class=\"citation\">Targ. O. Lev. XXI, 14</span>.</div><div class=\"sense\"><b>—3)</b>  (denom. of <a href=\"#\" data-headword=\"חוּלָּא\">חוּלָּא</a>) <i>to be profaned</i>. <span class=\"citation\">Targ. Ez. XXII, 26</span> <span dir=\"rtl\">וְחַלַת</span>.</div><div class=\"sense\"><b>Pa. חַלֵּיל</b> <div class=\"sense\"><b>1)</b> <i>to desecrate, profane, degrade</i>. <span class=\"citation\">Targ. Prov. XXX, 9</span>; a. e.—<i>Part. pass</i>. <span dir=\"rtl\">מְחַלַּל</span>, f. <a href=\"#\" data-headword=\"מְאַלְלָא\">מְחַלְלָא</a>, <a href=\"#\" data-headword=\"מְחִלָּא\">מְחַלָּא</a>. <span class=\"citation\">Targ. O. Lev. XXI, 7</span> (ed. Berl. <a href=\"#\" data-headword=\"מְחִלָּא\">מַחְלָא</a>, Regia <a href=\"#\" data-headword=\"מְחִלָּא\">מְחָלָא</a>).—Y. Kil. IX, 32ᵇ top, a. e. <span dir=\"rtl\">דילמא דחַלְּלִינָן וכ׳</span> did we perhaps desecrate the Sabbath?—<span class=\"citation\">Ber. 6ᵃ</span> מְחַלְּלֵי Ms. (ed. <span dir=\"rtl\">מחליין</span>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to redeem</i>. <span class=\"citation\">B. Mets. 44ᵇ</span> <span dir=\"rtl\">טבעא אפירא לא מְחַלְּלִינָן</span> we dare not redeem coins with goods.</div></div><div class=\"sense\"><b>Af. אַחֵיל  אָחֵיל</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חָלַל\">same</a>, <i>to desecrate</i>. <span class=\"citation\">Targ. O. Lev. XIX, 8</span>. <span class=\"citation\">Targ. Am. II, 7</span> <span dir=\"rtl\">לאָחָלָא</span> (ed. Lag. <span dir=\"rtl\">לאפסא</span>); a. fr.—Part. pass. f. <a href=\"#\" data-headword=\"מְחִלָּא\">מַחְלָא</a>, v. supra.</div></div><div class=\"sense\"><b>Ittaf. אִתָּחַל  אִתַּחַל</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"חֲלַל I\">אִתְּחַל</a> <i>to be profaned</i>. <span class=\"citation\">Targ. Ez. XXXVI, 23</span> (not <a href=\"#\" data-headword=\"חֲלַל I\">אַתְּחַל</a>). <span class=\"citation\">Ib. VII, 24</span>; a. fr.—<span class=\"citation\">Snh. 51ᵃ</span> <span dir=\"rtl\">היכא דמִיתַּחֲלָא השתא</span> if she degraded herself now; <span dir=\"rtl\">מית׳ וקיימא</span> she was degraded before this.</div></div>","alt":[]},"11348":{"h":"חֲלַל II","r":"H01075","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">חלחל</span>), (mostly) <i>Pa.</i> <a href=\"#\" data-headword=\"חֲלַל I\">חַלֵּיל</a> (v. <a href=\"#\" data-headword=\"חֲלַל I\">preced.</a>) [<i>to turn in a hollow space</i>,] <i>to wash, rinse</i>. <span class=\"citation\">Targ. II Chr. IV, 6</span>. <span class=\"citation\">Targ. Lev. I, 9</span>; a. fr.—<span class=\"citation\">Ḥull. 113ᵃ</span> <span dir=\"rtl\">דחַלְּלֵי בי טבחא</span> when they washed the meat in the slaughter house.</div><div class=\"sense\"><b>Af. אַחְלִיל</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חֲלַל I\">same</a>. <span class=\"citation\">Targ. Ruth III, 3</span>.—<span class=\"citation\">Ḥull. 95ᵇ</span> top <span dir=\"rtl\">מַחְלִיל רישא וכ׳</span> (or <span dir=\"rtl\">מְחַלֵּיל</span>) Ar. (ed. <a href=\"#\" data-headword=\"מְחַוֵּור\">מחוור</a>) he was washing an animal’s head in the river, v. <a href=\"#\" data-headword=\"חֲוַר\">חֲוַר</a></div></div>","alt":[]},"11349":{"h":"חָלָל I","r":"H01076","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>cut all around, beheaded</i>, in gen. <i>slain</i>. <span class=\"citation\">Sot. 45ᵇ</span> (ref. to <span class=\"citation\">Deut. XXI, 1</span>) <span dir=\"rtl\">ח׳ ולא חנוק</span> slain but not strangled, <span dir=\"rtl\">ח׳ ולא מפרפר וכ׳</span> slain but not rolling in dying agony. Ib. IX, 4 <span dir=\"rtl\">ממקום שנעשה ח׳ מצוארו</span> from the place where he has been cut, that means, (the measurement starts) from his throat, v. <a href=\"#\" data-headword=\"חָלָל III\"><span dir=\"rtl\">חָלָל</span> III</a>. <span class=\"citation\">Y. Naz. VII, 56ᶜ</span> (ref. to <span class=\"citation\">Num. XIX, 18</span>) <span dir=\"rtl\">בח׳ כל שהוא ח׳</span> <i>beḥalal</i> means whoever is slain, <span dir=\"rtl\">בח׳ זה אבר וכ׳</span> <i>beḥalal</i> means a severed limb … without sufficient flesh, v. <a href=\"#\" data-headword=\"חָלַל\">חָלַל</a>, <i>Nif.</i>—<span class=\"citation\">Ḥull. 3ᵃ</span>, a. e. (ref. to <span class=\"citation\">Num. XIX, 16</span>) <span dir=\"rtl\">חרב הרי הוא כח׳</span> a sword (with which a person has been killed) has the same levitical status as a slain body. <span class=\"citation\">Koh. R. to VIII, 10</span>; <span class=\"citation\">Yalk. Ps. 808</span>, a. e. (play on <span dir=\"rtl\">מתחולל</span> <span class=\"citation\">Job XV, 20</span>) <span dir=\"rtl\">מת וח׳</span> (the wicked man even in his life-time) is dead and beheaded; Tanḥ. Yithro 1 <span dir=\"rtl\">מת חולל</span> (corr. acc.); ib. ed. Bub.; a. fr.—Pl. <span dir=\"rtl\">חֲלָלִים</span>. <span class=\"citation\">Sot. 45ᵃ</span>; a. e.</div>","alt":[]},"11350":{"h":"חָלָל II","r":"H01077","html":"<div class=\"sense\"> [<i>put outside,</i>] <i>ḥalal</i>, <i>one unfit for priesthood on account of his father’s illegitimate connection</i> (<span class=\"citation\">Lev. XXI, 7</span>; <span class=\"citation\">14</span>, sq.). <span class=\"citation\">Kidd. IV, 6</span>. <span class=\"citation\">Snh. 51ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">חֲלָלִים</span>, <span dir=\"rtl\">חֲלָלִין</span>. <span class=\"citation\">Kidd. 77ᵃ</span>, v. <a href=\"#\" data-headword=\"מִקְוֵה I\">מִקְוֵה</a>; a. e.—Fem. <a href=\"#\" data-headword=\"חֲלָלָה\">חֲלָלָה</a> <i>the female issue of a priest’s illegitimate connection</i>, or <i>a priest’s wife illegitimately married to him</i>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ח׳ מוזכרת</span>, v. <a href=\"#\" data-headword=\"זָכַר\">זָכַר</a>; a. fr.—Pl. <span dir=\"rtl\">חֲלָלוֹת</span>. Ib., v. <a href=\"#\" data-headword=\"מִקְוֵה I\">מִקְוֵה</a>; a. e.</div>","alt":[]},"11351":{"h":"חָלָל III","r":"H01078","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָלַל\">חָלַל</a>) </div><div class=\"sense\"><b>1)</b> <i>cavity, empty space, hollow; throat; inside.</i> <span class=\"citation\">Ukts. II, 8</span> <span dir=\"rtl\">ממעך את חֲלָלָהּ</span> you squeeze its cavity (compress it); <span class=\"citation\">Y. Yoma VIII, 44ᵈ</span> bot. (v. Löw, Pfl. p. 123). <span class=\"citation\">Ab. Zar. 28ᵃ</span> <span dir=\"rtl\">מכה של ח׳</span> an internal sore (as in the mouth, throat &amp;c.). Y. ib. II, 40ᵈ top; <span class=\"citation\">Y. Sabb. XIV, 14ᵈ</span> top <span dir=\"rtl\">כל שהוא מן הח׳ ולפנים וכ׳</span> whatever is in the throat and farther inside may be cured on the Sabbath, opp. to <span dir=\"rtl\">מן השפה</span>; cmp. <span class=\"citation\">Sot. 45ᵇ</span> quot. s. v. <a href=\"#\" data-headword=\"חָלָל I\"><span dir=\"rtl\">חָלָל</span> I</a>. <span class=\"citation\">Ḥull. III, 1</span> if the heart is perforated <span dir=\"rtl\">לבית חֲלָלוֹ</span> up to its chamber. <span class=\"citation\">Ber. 19ᵇ</span> <span dir=\"rtl\">ח׳ טפח</span> a hollow space of one hand-breadth. <span class=\"citation\">Ḥull. 44ᵇ</span>. <span class=\"citation\">Pes. 54ᵃ</span> <a href=\"#\" data-headword=\"חֲלָלָה\">חֲלָלָהּ</a> the formation of its interior; a. fr.—Pl. <span dir=\"rtl\">חֲלָלִים</span>. <span class=\"citation\">Ber. 60ᵇ</span>, v. <a href=\"#\" data-headword=\"חָלוּל\">חָלוּל</a>.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"חַלְחוֹלִית\">חַלְחוֹלִית</a>) <i>intricacy, devices</i>. <span class=\"citation\">Sabb. 11ᵃ</span> <span dir=\"rtl\">חֲלָלָהּ של רשות</span> the devices of political government.</div>","alt":[]},"11352":{"h":"חֲלָלָא","r":"H01079","html":"<div class=\"sense\"><b>1)</b> <i>space, cavern, hole</i>. <span class=\"citation\">Targ. Y. Lev. XXIII, 42</span>.—Y. Kil. IX, 32ᶜ bot.; <span class=\"citation\">Y. Keth. XII, 35ᵇ</span> <span dir=\"rtl\">יהבון בח׳</span> put them into a cavern. <span class=\"citation\">Ab. Zar. 28ᵇ</span> <span dir=\"rtl\">ח׳ דבי צוארא</span> neck-hole of a garment. Y. ib. II, 40ᵈ top <span dir=\"rtl\">עביר עינא כחללה</span> (not <span dir=\"rtl\">כחל לה</span>) considers the eye like an inner organ (for treatment on the Sabbath, v. <a href=\"#\" data-headword=\"חָלָל III\">preced.</a>).</div><div class=\"sense\"><b>—2)</b>  pl. <span dir=\"rtl\">חֲלָלֵי</span>, in <span dir=\"rtl\">ח׳ דעלמא</span> <i>the underground treasures of the world</i>. <span class=\"citation\">Snh. 97ᵃ</span>; <span class=\"citation\">B. Mets. 49ᵃ</span> (<a href=\"#\" data-headword=\"חֲלָלָא\">חללא</a>, corr. acc., v. Rabb. D. S. a. l. note 6).</div><div class=\"sense\"><b>—3)</b> <i>secrets</i>. <span class=\"citation\">Sabb. 77ᵇ</span> if they asked him <span dir=\"rtl\">כל ח׳ עלמא</span> about all the secret processes of nature.</div>","alt":["חֲלָלָה"]},"11353":{"h":"חֲלָלָה","r":"H01080","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"חָלָל II\"><span dir=\"rtl\">חָלָל</span> II</a>, a <a href=\"#\" data-headword=\"חֲלָלָא\">preced. w.</a></div>","alt":[]},"11354":{"h":"חָלַם I","r":"H01081","html":"<div class=\"sense\"> [<i>to be soft, moist, viscous</i>,] <i>to have good humors, to be well</i>. Part. pass. <a href=\"#\" data-headword=\"חָלוּם\">חָלוּם</a>, f. <span dir=\"rtl\">חֲלוּמָה</span> <i>sane</i>, opp. to <span dir=\"rtl\">שוטה</span>; <i>well</i>, opp. to <a href=\"#\" data-headword=\"חוֹלֶה\">חולה</a>. <span class=\"citation\">Tosef. Ter. I, 3</span> <span dir=\"rtl\">פעמים … ח׳</span> if one is at times insane, at times sane; <span class=\"citation\">R. Hash. 28ᵃ</span> <a href=\"#\" data-headword=\"חַלִּים\">חַלִּים</a> (Ch. form).—<span class=\"citation\">Y. Gitt. VII, beg. 48ᶜ</span>.—<span class=\"citation\">Pes. 78ᵇ</span>.—Fem. <span dir=\"rtl\">חֲלוּמָה</span>. <span class=\"citation\">Y. Yeb. XIV, beg. 14ᵇ</span></div>","alt":[]},"11355":{"h":"חֲלַם","r":"H01082","html":"<div class=\"sense\">v. <a href=\"#\" data-headword=\"חַלִּים\">חַלִּים</a></div><div class=\"sense\"><b>Pa. חַלֵּים</b> <div class=\"sense\"><i>to join closely</i>. <span class=\"citation\">Kidd. 25ᵃ</span> זמנין דח׳ שפוותיה Ar. (ed. <span dir=\"rtl\">שפתיה</span>) sometimes a man closes his lips firmly.</div></div>","alt":[]},"11356":{"h":"חָלַם II","r":"H01083","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"חֲלַם\">preced.</a> wds.) [<i>to gather humors, to sleep well</i> (cmp. <a href=\"#\" data-headword=\"יָשַׁן\">יָשַׁן</a>).—Denom. <a href=\"#\" data-headword=\"חֲלוֹם\">חֲלוֹם</a> (cmp. ἐνύπνιος, somnium) <i>dream;</i> from which <a href=\"#\" data-headword=\"חָלַם I\">חָלַם</a>] <i>to dream</i>. <span class=\"citation\">Ber. 55ᵇ</span> חלום חָלַמְתִּי I had a dream. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חלום שׁח׳ לו חבירו</span> a dream which his neighbor had about him. <span class=\"citation\">Tosef. Sabb. VI</span> (<span class=\"citation\">VII), 7</span> <span dir=\"rtl\">שתהא חוֹלֵם חלומות</span> that you may have dreams; a. fr.</div>","alt":[]},"11357":{"h":"חֲלַם ²","r":"H01084","html":"<div class=\"sense\"><span class=\"citation\">Targ. Gen. XXXVII, 5</span>. <span class=\"citation\">Ib. XLI, 1</span>; a. fr.</div><div class=\"sense\"><b>Af. אַחְלֵם</b> <div class=\"sense\"><i>to consult an interpreter of dreams</i> or <i>a dreamer</i>. <span class=\"citation\">Targ. Jer. XXIX, 8</span>, v. <a href=\"#\" data-headword=\"חָלְמָא\">חָלְמָא</a>.</div></div>","alt":["חֲלִים"]},"11358":{"h":"חֲלֹם","r":"H01085","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲלוֹם\">חֲלוֹם</a></div>","alt":[]},"11359":{"h":"חֶלְמָא","r":"H01086","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">Targ. Gen. XXXVII, 6</span>; a. fr.—<span class=\"citation\">Ber. 56ᵃ</span> <span dir=\"rtl\">חֶלְמָאִי</span> my dream. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בחֶלְמִין</span> in our dream; a. fr.—Pl. <a href=\"#\" data-headword=\"חלמין\">חֶלְמִין</a>, <span dir=\"rtl\">חֶלְמַיָּא</span>, <a href=\"#\" data-headword=\"חֶלְמָא\">חִילְ׳</a>. <span class=\"citation\">Targ. Joel III, 1</span>; a. fr.—[<span class=\"citation\">Targ. Job VI, 6</span> <span dir=\"rtl\">מרי חלמיא</span>, ed. Lag. <a href=\"#\" data-headword=\"לְחֵם\">לחמא</a>, ed. Wil. <span dir=\"rtl\">רירא דחלמונא</span>.]</div>","alt":["חִילְ׳"]},"11360":{"h":"חָלְמָא","r":"H01087","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֶלְמָא\">preced.</a>, v. P. Sm. 1284) <i>dreamer, or interpreter of dreams</i>.—Pl. <span dir=\"rtl\">חָלְמַיָּא</span>, constr. <span dir=\"rtl\">חַלְמֵי</span>. <span class=\"citation\">Targ. Jer. XXIX, 8</span> <span dir=\"rtl\">חַלְמֵי חֶלְמֵיכוֹן וכ׳</span> (not <a href=\"#\" data-headword=\"חֲלָב\">חֶלְ׳</a>, <a href=\"#\" data-headword=\"חֶלְמָא\">חִילְ׳</a>) your dreamers (or interpreters) whom you consult.</div>","alt":[]},"11361":{"h":"חֲלָמָא","r":"H01088","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (חָלם I) <i>a sort of cement</i> used for making vessels. <span class=\"citation\">Kel. XI, 4</span> (Ar. a. ed. Dehrenb. <a href=\"#\" data-headword=\"חֶלְמָה\">חלמה</a>); <span class=\"citation\">Tosef. Kel. B. Mets. I, 4</span>, sq.</div>","alt":["(חְלָמָה  I)"]},"11362":{"h":"חֲלָמָה II","r":"H01089","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חֲלָמָא\">preced.</a>) <i>joint, seam in leather;</i> cmp. <a href=\"#\" data-headword=\"חֲלִים\">חֲלִים</a>. <span class=\"citation\">Sabb. 91ᵇ</span> bot. <span dir=\"rtl\">מקום ח׳</span> the place where the bag is joined (which the thief might rip to take possession of its contents).</div>","alt":[]},"11363":{"h":"חֶלְמָה","r":"H01090","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (חָלַם I) name of several <i>mucilaginous plants</i> (v. P. Sm. 1284 s. v. <span dir=\"rtl\">חלמתא</span>), prob. <i>mallows</i>. <span class=\"citation\">Y. Kil. V, end, 30ᵃ</span>; <span class=\"citation\">Y. Ber. VI, 10ᵇ</span> bot. <a href=\"#\" data-headword=\"חֲלִימָה\">חלימה</a> (read: <a href=\"#\" data-headword=\"חֶלְקָא\">חֶילְ׳</a>); <span class=\"citation\">Tosef. Kil. III, 12</span> <a href=\"#\" data-headword=\"חִילְמִית\">חִילְמִית</a> ed. Zuck. (Var. <span dir=\"rtl\">חלמית</span>).</div>","alt":["חִלְמִית"]},"11364":{"h":"חֶלְמוֹן","r":"H01091","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חֶלְמָה\">preced.</a>) <i>yolk, yellow of an egg</i>. <span class=\"citation\">Ab. Zar. 40ᵃ</span>; <span class=\"citation\">Ḥull. 64ᵃ</span> (corr. as in Ab. Zar. l. c.). <span class=\"citation\">Y. Ter. X, 47ᵇ</span> bot. <span dir=\"rtl\">בלובן חלמין</span> (read: <span dir=\"rtl\">בחלמון</span>, v. Tosaf. to <span class=\"citation\">Ḥull. 64ᵇ</span>, s. v. <span dir=\"rtl\">והוא</span>); v. <a href=\"#\" data-headword=\"חֶלְבּוֹן\">חֶלְבּוֹן</a>. [Ar. reads <a href=\"#\" data-headword=\"חֶלְמוֹן\">חלמון</a>.]</div>","alt":["(הֶלְ׳)"]},"11365":{"h":"חֶלְמוֹנָא","r":"H01092","html":"<div class=\"sense\"><span class=\"citation\">Targ. Job VI, 6</span> ed. Wil. (v. <a href=\"#\" data-headword=\"חֶלְמָא\">חֶלְמָא</a>).</div>","alt":[]},"11366":{"h":"חַלָּמוּת","r":"H01093","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.?; v. <a href=\"#\" data-headword=\"חֶלְמוֹנָא\">preced.</a> wds.) <i>mucilaginous juice</i> of mallows, used for the preservation of gourd seed. <span class=\"citation\">Kil. I, 8</span> (Y. ed. a. Ar.  …, Mish. a. Babli ed. <span dir=\"rtl\">ות …</span>).</div>","alt":["חַלָּמִית"]},"11367":{"h":"חלמין","r":"H01094","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֶלְמוֹן\">חֶלְמוֹן</a></div>","alt":[]},"11368":{"h":"חַלָּמִישׁ","r":"H01095","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ḥallamish</i> (<i>Rock</i>), a place near Naveh (v. <a href=\"#\" data-headword=\"נָוֶה II\"><span dir=\"rtl\">נָוֶה</span> III</a>) and inhabited by hostile gentiles. <span class=\"citation\">Lev. R. s. 23</span>; <span class=\"citation\">Cant. R. to II, 2</span>; <span class=\"citation\">Lam. R. to I, 17</span>.</div>","alt":[]},"11369":{"h":"חִלְמִית","r":"H01096","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֶלְמָה\">חֶלְמָה</a>; <a href=\"#\" data-headword=\"חַלָּמוּת\">חַלָּמִית</a>, v. <a href=\"#\" data-headword=\"חַלָּמוּת\">חַלָּמוּת</a>.</div>","alt":[]},"11370":{"h":"חלנונא","r":"H01097","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִלְזוֹנָא\">חִלְזוֹנָא</a></div>","alt":[]},"11371":{"h":"חָלַף","r":"H01098","html":"<div class=\"sense\"> [<i>to be smooth, glistening, sharp-edged</i>,] </div><div class=\"sense\"><b>1)</b> <i>to cut</i>. Denom. <a href=\"#\" data-headword=\"חַלִּיף\">חַלִּיף</a>, <a href=\"#\" data-headword=\"חֵילֶף\">חֵילֶף</a>.</div><div class=\"sense\"><b>—2)</b>  (cmp <a href=\"#\" data-headword=\"גּוּז\">גּוּז</a>) <i>to pass by, be gone</i>. <span class=\"citation\">Num. R. s. 10</span> (ref. to <a href=\"#\" data-headword=\"חִלּוּף\">חלוף</a>, <span class=\"citation\">Prov. XXXI, 8</span>) <span dir=\"rtl\">שח׳ והלך וכ׳</span></div><div class=\"sense\"><b>—3)</b> <i>to change, exchange</i>. <span class=\"citation\">Y. Ber. II, 5ᶜ</span> top <span dir=\"rtl\">נַחֲלוֹף את וכ׳</span> let us change our meeting-place. <span class=\"citation\">Dem. III, 5</span> <span dir=\"rtl\">חשודה לַחֲלוֹף</span> (Y. ed. <span dir=\"rtl\">לחַלֵּף</span>, <i>Pi.</i>) suspected of exchanging (the provision in her trust). Ib. 6 <span dir=\"rtl\">לח׳ את המתקלקל</span> to replace what has been spoiled; a. fr.</div><div class=\"sense\"><b>Pa. חִלֵּף</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חלנונא\">same</a>. <span class=\"citation\">Yalk. Gen. 148</span> <span dir=\"rtl\">מי מְחַלְּפוֹ</span> who will replace him? (v. <a href=\"#\" data-headword=\"חֲלִיפִים\">חֲלִיפִין</a>). <span class=\"citation\">Dem. III, 5</span>, v. supra; a. e.</div></div><div class=\"sense\"><b>Hif. הֶחֱלִיף</b> <div class=\"sense\"><b>1)</b> <i>to exchange, barter</i>. <span class=\"citation\">B. Mets. VIII, 4</span> <span dir=\"rtl\">המַחֲלִיף פרה ב־</span> if one exchanges a cow for an ass.—Dem. l. c. <span dir=\"rtl\">חשודה להַחֲלִיף</span>, v. supra; <span class=\"citation\">Ḥull. 6ᵇ</span> <span dir=\"rtl\">חשודה מַחֲלֶפֶת</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to drive young shoots, to grow again</i>. <span class=\"citation\">Erub. 100ᵇ</span>; a. e., v. <a href=\"#\" data-headword=\"גֶּזַע\">גֶּזַע</a>. <span class=\"citation\">Pesik. R. s. 11</span> <span dir=\"rtl\">מַחֲלִיף וכ׳</span>, v. <a href=\"#\" data-headword=\"גָּזַז\">גָּזַז</a>.</div><div class=\"sense\"><b>—3)</b> <i>to change; to reverse</i>. <span class=\"citation\">Erub. 9ᵃ</span> <span dir=\"rtl\">ובלבד שלא יַחֲלִיפוּ</span> provided they do not change carriers. <span class=\"citation\">Sabb. 8ᵇ</span>; a. fr.—<span class=\"citation\">Erub. 99ᵃ</span> <span dir=\"rtl\">לעולם לא תַחֲלִיף</span> it is not necessary to reverse (the authorities; <span class=\"citation\">Bets. 3ᵇ</span>, a. e. <span dir=\"rtl\">תיפוך</span>, v. <a href=\"#\" data-headword=\"אֲפַךְ\">אֲפַךְ</a>).—Part. pass. <span dir=\"rtl\">מוּחֲלָף</span>, f. <span dir=\"rtl\">מוּחֲלֶפֶת</span>. Ib. <span dir=\"rtl\">מ׳ השיטה</span> the statement must be reversed (the authorities for the two opinions must be exchanged); <span class=\"citation\">Bets. 3ᵃ</span></div><div class=\"sense\"><b>—4)</b> <i>to be ambiguous, to equivocate</i>. <span class=\"citation\">Snh. 92ᵃ</span>; a. e. <span dir=\"rtl\">כל המחליף וכ׳</span> he who equivocates in his speech, is like an idolater.</div></div><div class=\"sense\"><b>Nif. נֶחֱלַף</b> </div><div class=\"sense\"><b>Hithpa. הִתְחַלֵּף</b> <div class=\"sense\">, <i>Nithpa.</i> <a href=\"#\" data-headword=\"חָלַל\">נִתְחַלֵּף</a> </div><div class=\"sense\"><b>1)</b> <i>to be exchanged, mixed up</i>. Y. Pes. VI, 33ᶜ bot. <span dir=\"rtl\"><span dir=\"rtl\">דבר שאין דרכו</span> (<span dir=\"rtl\">לֵחָלֵף</span>) <span dir=\"rtl\">לִיתְחַלֵּף</span></span> a thing which is not likely to be exchanged (by mistake); <span class=\"citation\">ib.</span> <span dir=\"rtl\">להִתְחַלֵּיף</span>; ib.ᵈ top. <span class=\"citation\">Ab. Zar. 17ᵇ</span> <span dir=\"rtl\">מעות … נִתְחַלְּפוּ לי וכ׳</span> money set aside for Purim was mixed up with money &amp;c. <span class=\"citation\">Nidd. 52ᵃ</span> <span dir=\"rtl\">ונִתְחַלְּפָה לך וכ׳</span> and thou madest a mistake between <i>Iyob</i> and <i>oyeb;</i> <span class=\"citation\">B. Bath. 16ᵃ</span> <span dir=\"rtl\">ונתחלף</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא נ׳ לי</span> I make no mistake; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to change </i>(<i>in appearance</i>). <span class=\"citation\">Pesik. R. s. 29</span> (—30—30) <span dir=\"rtl\">נִתְחַלַּפְתֶּם מן הרעב</span> you have changed (beyond recognition) through starvation; <span dir=\"rtl\">יש לכם להִתְחַלֵּף וכ׳</span> you will change through plenty. <span class=\"citation\">Yalk. Gen. 133</span> <span dir=\"rtl\">מאיזה שם אני מִתְחַלֵּף</span> (prob. <span dir=\"rtl\">לאיזה</span>) what name I may be ordered to assume in turn.</div><div class=\"sense\"><b>—3)</b> <i>to be succeeded, relieved, transferred</i>. <span class=\"citation\">Lev. R. s. 23</span>, end <span dir=\"rtl\">נתח׳ המלך</span> the king has been succeeded (displaced; <span class=\"citation\">Num. R. s. 9</span>, beg. <span dir=\"rtl\">מת וכ׳</span>). <span class=\"citation\">Yalk. Deut. 813</span> <span dir=\"rtl\">כיון שנ׳ וכ׳</span> when the governor was recalled and another &amp;c. <span class=\"citation\">Num. R. s. 5</span>, beg. <span dir=\"rtl\">להִתְחַלֵּף מעבודה וכ׳</span> to be transferred from one service to another. Y. Taan. II, beg. 65ᵃ <span dir=\"rtl\">היו מִתְחַלְּפִין עליה</span> took turns in guarding it.</div></div>","alt":[]},"11372":{"h":"חֲלַף I","r":"H01099","html":"<div class=\"sense\">, <i>to pass by, be gone</i>. <span class=\"citation\">Targ. Cant. II, 11</span>. <span class=\"citation\">Targ. Job IX, 11</span>. <span class=\"citation\">Ib. 26</span>; a. e.</div><div class=\"sense\"><b>Pa. חַלֵּיף</b> <div class=\"sense\"><b>1)</b> <i>to pass repeatedly, promenade</i>. <span class=\"citation\">Kidd. 12ᵇ</span> <span dir=\"rtl\">ח׳ אבבא וכ׳</span> went up and down in front of the house of his father-in-law (to attract the attention of his mother-in-law).</div><div class=\"sense\"><b>—2)</b> <i>to exchange</i>. <span class=\"citation\">Targ. O. Lev. XXVII, 10</span>; a. e.—<span class=\"citation\">Ḥull. 6ᵇ</span> <span dir=\"rtl\">חַלּוּפֵי מבעיא</span> so much the more may she be suspected of exchanging (substituting something of her own). <span class=\"citation\">Meg. 7ᵇ</span> <span dir=\"rtl\">מְחַלְּפֵי וכ׳</span> (v. Rabb. D. S. a. l. note 8; some ed. <a href=\"#\" data-headword=\"מִחְוַר\">מִיחַ׳</a> <i>Ithpa.</i>) used to exchange their meals (on Purim).—<i>Part. pass</i>. f. <span dir=\"rtl\">מְחַלְּפָא</span>. Y. Peah IV, 18ᵈ bot., a. e. <span dir=\"rtl\">מח׳ שיטתיה</span>, v. <a href=\"#\" data-headword=\"חָלַף\">preced.</a> <i>Hif.</i></div></div><div class=\"sense\"><b>Af. אַחֲלִיף</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חָלַף\">same</a>. Targ. O. l. c.; a. e.</div></div><div class=\"sense\"><b>Ithpa. אִתְחַלֵּף  אִיחַלֵּף</b> </div><div class=\"sense\"><b>Ithpe. אִיחֲלִיף</b> <div class=\"sense\"><i>to be exchanged; to change; to disappear</i>. <span class=\"citation\">Targ. Ps. XC, 5</span>; a. fr.—<span class=\"citation\">Gen. R. s. 78</span>, beg. <span dir=\"rtl\">מִתְחַלְּפִין</span> change their names. Ḥull. l. c. <span dir=\"rtl\">ולאִיחַלּוּפֵי לא וכ׳</span> Rashi (ed. <span dir=\"rtl\">לחַלּוּפֵי</span>) and do we not apprehend an exchange?—Meg. l. c., v. supra.—<span class=\"citation\">B. Mets. 59ᵇ</span>, v. <a href=\"#\" data-headword=\"חָסֵר II\"><span dir=\"rtl\">חָסֵר</span> II</a>.</div></div>","alt":["חֲלֵיף"]},"11373":{"h":"חִלֶף I","r":"H01100","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲלַף I\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>shoot</i>.—Pl. <span dir=\"rtl\">חֲלָפִים</span>, constr. <span dir=\"rtl\">הֶלְפֵי</span>, <a href=\"#\" data-headword=\"חֶלְקָא\">חֶילְ׳</a>. <span class=\"citation\">Bets. 3ᵇ</span>; <span class=\"citation\">Yeb. 81ᵇ</span>; <span class=\"citation\">Zeb. 72ᵇ</span> <span dir=\"rtl\">ח׳ תרדין</span> the young shoots of beet growing out of the root; <span class=\"citation\">Orl. III, 7</span> Ms. M. (ed. <a href=\"#\" data-headword=\"חוֹלְפָה\">חוֹלְפוֹת</a>; Y. ed. <a href=\"#\" data-headword=\"חִילְפוֹת\">חִילְפּוֹת</a>); <span class=\"citation\">Tosef. Ter. V, 10</span> <span dir=\"rtl\">חֲלִיפוֹת</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"חִילְפוֹת\">חילפות</a>); <span class=\"citation\">Ukts. I, 4</span> <a href=\"#\" data-headword=\"חִלְפוֹת\">חִלְפּוֹת</a>. V. <a href=\"#\" data-headword=\"חֲלִיפִים\">חֲלִיפִין</a>, <a href=\"#\" data-headword=\"חֲלִיפָה\">חֲלִיפָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>rush</i>, v. <a href=\"#\" data-headword=\"חֵילֶף\">חֵילֶף</a>.</div>","alt":[]},"11374":{"h":"חֵלֶף II","r":"H01101","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חִלֶף I\">preced.</a> wds.) <i>reversion</i>. <span class=\"citation\">Y. Sabb. VII, 9ᶜ</span> <span dir=\"rtl\">או ח׳</span> is not perhaps the reverse the case?</div>","alt":[]},"11375":{"h":"חֶלֶף","r":"H01102","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (b. h.) <i>Ḥelef</i>, a place in Naftali. <span class=\"citation\">Y. Meg. I, 70ᵃ</span> bot. (ref. to <span class=\"citation\">Josh. XIX, 33</span>) <span dir=\"rtl\">מחלף ח׳</span> <i>me-Helef</i> is (the present) <i>Ḥ</i>. Y. Erub. II, 20ᵃ top <span dir=\"rtl\">ר׳ … בהורי ח׳ וכ׳</span></div>","alt":[]},"11376":{"h":"חֲלַף II","r":"H01103","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> st. constr. (<span dir=\"rtl\">חלף</span>) <i>in place of, instead</i>. <span class=\"citation\">Targ. Ex. XXI, 24</span>; a. fr.—<span class=\"citation\">Sabb. 129ᵃ</span> <span dir=\"rtl\">נפשא ח׳ נפשא</span> life for life (meat is required after bloodletting), <span dir=\"rtl\">סומקא ח׳ סומקא</span> red (wine) for red (blood).—Pl. <a href=\"#\" data-headword=\"חִילְפַי\">חֲלָפֵי</a>, with suffix <a href=\"#\" data-headword=\"חִלְפוֹת\">חֲלָפוֹי</a> in his place. <span class=\"citation\">Targ. Prov. XI, 8</span> Ms. (ed. <span dir=\"rtl\">תחותוהי</span>, ed. Lag. both words).—<span dir=\"rtl\">חֲלַף סִדְרָא</span> f. (an adaptation of κλεψύδρα) [<i>change of order</i>,] <i>clepsydra</i>, a water clock used in courts of justice for measuring the time given for argument. <span class=\"citation\">Gen. R. s. 49</span> (not <a href=\"#\" data-headword=\"סרדה\">סרדה</a>); <span class=\"citation\">Yalk. ib. 83</span>.</div>","alt":["חוֹלַף"]},"11377":{"h":"חִלְפָא","r":"H01104","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֶלְמָא\">חִילְ׳</a></div>","alt":[]},"11378":{"h":"חִלְפוֹת","r":"H01105","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֵלֶף II\"><span dir=\"rtl\">חֵלֶף</span> I</a></div>","alt":["חֲלָפוֹת"]},"11379":{"h":"חִלְפַיי","r":"H01106","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִלְכְתָא\">הִילְ׳</a></div>","alt":[]},"11380":{"h":"חֲלַפְתָּא","r":"H01107","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḥălafta</i>, R. Ḥ., a Tannai, father of R. José. <span class=\"citation\">Ab. III, 6</span>. <span class=\"citation\">Taan. II, 5</span>. <span class=\"citation\">B. Kam. 70ᵃ</span> <span dir=\"rtl\">אבא ח׳</span> my father Ḥ.; <span class=\"citation\">Tosef. B. Bath. II, 10</span> (read: <span dir=\"rtl\">אבא ח׳</span>); a. fr.—V. <a href=\"#\" data-headword=\"חֲלִיפָא\">חֲלִיפָא</a>.</div>","alt":[]},"11381":{"h":"חִלְפְּתָא","r":"H01108","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חִילְפָא II\"><span dir=\"rtl\">חִילְפָא</span> II</a>) a species of <i>willow</i>, corresp. to h. <a href=\"#\" data-headword=\"צַפְצָפָה\">צַפְצָפָה</a>. <span class=\"citation\">Succ. 34ᵃ</span> <span dir=\"rtl\">ח׳ ערבתא וכ׳</span> what formerly was called <i>ḥ</i>. is now named <i>ărabta</i> and vice versa; (Rashi reads <a href=\"#\" data-headword=\"חִילְפָא I\">חילפא</a>, Ms. M. corrupt vers., v. Rabb. D. S. a. l. note; <span class=\"citation\">Sabb. 36ᵃ</span> <span dir=\"rtl\">ערבה צפצפה וכ׳</span>).</div>","alt":["חֲלַפְתָּא"]},"11382":{"h":"חָלַץ","r":"H01109","html":"<div class=\"sense\"> v. Ges. H. Dict.<sup>10</sup> s. v. <span dir=\"rtl\">חלץ I</span>, II) </div><div class=\"sense\"><b>1)</b> <i>to surround, fortify; to gird, arm</i>. <span class=\"citation\">Yalk. Gen. 133</span> (fr. Midr. Vayis‛u) <span dir=\"rtl\">חָלְצוּ עצמם</span> they armed themselves, v. <i>Pi</i>. a. <i>Hif.</i></div><div class=\"sense\"><b>—2)</b> <i>to untie, loosen, tear out; to strip, lay bare</i>. <span class=\"citation\">M. Kat. 22ᵇ</span> <a href=\"#\" data-headword=\"חוֹלֵץ\">חוֹלֵץ</a> one bares the shoulder (in mourning). <span class=\"citation\">Ib. IV, 7</span> (<span class=\"citation\">24ᵇ</span>) <span dir=\"rtl\">חוֹלְצִין</span>. <span class=\"citation\">B. Mets. 59ᵇ</span> <span dir=\"rtl\">וח׳ מנעליו</span> and took his shoes off. <span class=\"citation\">Y. M. Kat. III, 82ᵇ</span> <span dir=\"rtl\">חוֹלְצָן</span> he takes them (the T’fillin) off; <span class=\"citation\">Ber. 23ᵃ</span>; Y. ib. II, 4ᶜ.—<span class=\"citation\">Pes. 4ᵃ</span>; <span class=\"citation\">M. Kat. 20ᵇ</span> <span dir=\"rtl\">חֲלוֹץ לי מנעלי</span> take my shoes off. <span class=\"citation\">Ḥull. 90ᵇ</span> <span dir=\"rtl\">חוֹלְצוֹ לתפוח</span> he takes the sinew out and puts it on the pile &amp;c. <span class=\"citation\">Tosef. Neg. VI, 10</span> <span dir=\"rtl\">בזמן שחוא חוֹלֵץ</span> when he has to tear out (a leprous stone), v. <a href=\"#\" data-headword=\"נָתַץ\">נָתַץ</a>.—Y. Ab. Zar. II, end, 42ᵃ; <span class=\"citation\">Tosef. ib. IV</span> (<span class=\"citation\">V), 8</span> <span dir=\"rtl\">כדי שיהו חוֹלְצִין את גלעיניהן</span> in order to loosen the stones (of the olives); a. fr.—Part. pass. <a href=\"#\" data-headword=\"חִלּוּץ\">חָלוּץ</a>, f. <a href=\"#\" data-headword=\"חֲלוּצָא\">חֲלוּצָה</a>, pl. <span dir=\"rtl\">חֲלוּצִים</span>, f. <span dir=\"rtl\">חֲלוּצוֹת</span>. <span class=\"citation\">Y. Sot. I, beg. 16ᵇ</span> <span dir=\"rtl\">וזרועותיה ח׳</span> her arms bared.—<span class=\"citation\">Sabb. 137ᵃ</span>, a. e. <span dir=\"rtl\">חֲלָצַתּוֹ חמה</span> the fever left him.—Esp. <i>to perform the ceremony of taking off the Yabam’s shoe</i> (v. <a href=\"#\" data-headword=\"יָבָם\">יָבָם</a>); <span dir=\"rtl\">ח׳ ביבמה</span> <i>to arrange the Ḥălitsah, to act as judge;</i> ח׳ ל־ <i>to have the shoe taken off for refusing the leviratical marriage;</i> ח׳ מ־ <i>to take the shoe off</i>. <span class=\"citation\">Yeb. 102ᵃ</span> <span dir=\"rtl\">כלום ראית שח׳ וכ׳</span> did you ever see him act as a judge at a <i>Ḥălitsah?</i> <span class=\"citation\">Ib. IV, 1</span> <span dir=\"rtl\">החוֹלֵץ ליבמתו וכ׳</span> if one gave <i>ḥălitsah</i> to his sister-in-law, and it was found out afterwards &amp;c. <span class=\"citation\">Ib. III, 1</span> <span dir=\"rtl\">חוֹלְצוֹת ולא מתיבמות</span> they must be released by <i>ḥăl.</i>, but must not be married by the <i>yabam</i>. <span class=\"citation\">Ib. XII, 1</span> <span dir=\"rtl\">חָלְצָה במנעל</span> if she performed the ceremony with a leather shoe. <span class=\"citation\">Ib. 102ᵃ</span> <span dir=\"rtl\">חוֹלְצִין במנעל</span> you may have the ceremony performed with &amp;c. <span class=\"citation\">Ib. 102ᵇ</span> <span dir=\"rtl\">שמא חָלְצָה סנדל לאחד וכ׳</span> perhaps she has performed the ceremony of <i>ḥal</i>. on one of the brothers. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">החוֹלֶצֶת מן וכ׳</span> if one performed the ceremony on an adult … <span class=\"citation\">Ib.</span> (ref. to <span class=\"citation\">Hos. V, 6</span>) <span dir=\"rtl\">מי כתיב ח׳ להם ה׳ מהם וכ׳</span> is it written, He had his shoe taken off by them (the Lord being the rejecting party)? It is written, He took their shoe off &amp;c., v. <a href=\"#\" data-headword=\"חֲלַץ\">next w.</a>; a. v. fr.—חֲלוּצָה <i>a woman released from leviratical marriage by ḥălitsah</i>. Ib. VII, 1. Ib. IV, 12 <span dir=\"rtl\">חֲלוּצָתוֹ</span> his rejected sister-in-law; a. fr.</div><div class=\"sense\"><b>Nif. נֶחֶלַץ</b> <div class=\"sense\"><i>to be peeled off</i>. Y. Sabb. XX, 17ᶜ bot. <span dir=\"rtl\">ועורו נ׳</span> and his skin will peel itself off.</div></div><div class=\"sense\"><b>Pi. חִלֵּץ</b> <div class=\"sense\"><b>1)</b> <i>to extract, loosen, to deliver</i>.</div><div class=\"sense\"><b>—2)</b> <i>to gird, strengthen</i>. <span class=\"citation\">Yeb. 102ᵇ</span> (in a discussion about the meaning of <span dir=\"rtl\">וחלצה</span>, <span class=\"citation\">Deut. XXV, 9</span>) <span dir=\"rtl\">והכתיב יְחַלּץ עני</span> but do we not read (<span class=\"citation\">Job XXXVI, 15</span>), He <i>girds</i> the poor? Answ. <span dir=\"rtl\">יְחַלְּצוֹ מדינה וכ׳</span> It means, He will <i>deliver him</i> from the judgment &amp;c. Ib. (after ref. to <span dir=\"rtl\">יחליץ</span>, <span class=\"citation\">Is. LVIII, 11</span>) the root <span dir=\"rtl\">חלץ</span> means both (girding and loosening), but here (Deut. l. c.), if it meant <i>tying on</i>, it would read <span dir=\"rtl\">וחלצה נעלו ברגלו</span> she shall tie his shoe <i>on</i> his foot.</div></div><div class=\"sense\"><b>Hif. הֶחֱלִיץ</b> <div class=\"sense\"><b>1)</b> <i>to loosen, untie;</i></div><div class=\"sense\"><b>2)</b> <i>to gird, arm;</i></div><div class=\"sense\"><b>3)</b> <i>to deliver;</i></div><div class=\"sense\"><b>4)</b> <i>to smoothen, give ease of mind</i>. <span class=\"citation\">Lev. R. s. 34</span> (ref. to <span dir=\"rtl\">יחליץ</span>, Is. l. c.) <span dir=\"rtl\">יזיין</span> (Ar. <span dir=\"rtl\">ישלוף</span>) <span dir=\"rtl\">ישמוט ישזיב ויניח</span> (which means) He shall <i>loosen</i> as in Deut. l. c., <i>gird</i> as ib. III, 18, <i>deliver</i> as in <span class=\"citation\">Ps. CXL, 2</span>, and <i>give ease</i> as in the Sabbath prayer after meal <span dir=\"rtl\">רצה והַחֲלִיצֵנוּ</span> be pleased to give us ease of mind. V. <a href=\"#\" data-headword=\"חִלּוּץ\">חִלּוּץ</a>.</div></div>","alt":[]},"11383":{"h":"חֲלַץ","r":"H01110","html":"<div class=\"sense\"><b>1)</b> <i>to take off, undress</i>. Part. pass. <a href=\"#\" data-headword=\"חָלִיץ\">חָלִיץ</a>. <span class=\"citation\">Targ. II Sam. VI, 20</span>.—Lam. R. introd (R. Joh. 1) <span dir=\"rtl\">חֲלִיצֵי מסאני</span> without shoes. <span class=\"citation\">M. Kat. 22ᵇ</span> <span dir=\"rtl\">למִיחֲלַץ</span> to bare their shoulders.</div><div class=\"sense\"><b>—2)</b> <i>to withdraw</i>. <span class=\"citation\">Yeb. 102ᵇ</span> <span dir=\"rtl\">עמא דח׳ ליה … מיניה</span> a people from which its lord has withdrawn (with ref. to <span dir=\"rtl\">חלץ מהם</span>, <span class=\"citation\">Hos. V, 6</span>).</div><div class=\"sense\"><b>—3)</b> <i>to perform the rite of ḥălitsah;</i> v. infra.</div><div class=\"sense\"><b>Pa. חַלֵּיץ</b> <div class=\"sense\"><b>1)</b> <i>to perform or arrange the rite of ḥălitsah</i>. Ib. <span dir=\"rtl\">לה אחין וכ׳</span> (or <span dir=\"rtl\">דחלְצוּ</span>) <span dir=\"rtl\">ואילו יבמה דחַלְּצוּ</span> suppose brothers would untie the shoe of their sister-in-law, would this be of any legal consequence? Ib.ᵃ אנא לא הואי חַלִּיצְנָא וכ׳ I should not have allowed a <i>ḥălitsah</i> except &amp;c.; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to undress, strip</i>. <span class=\"citation\">Targ. I Sam. XXXI, 9</span>. <span class=\"citation\">Ib. 8</span> (h. text <span dir=\"rtl\">לפשט</span>); <span class=\"citation\">Targ. I Kings XI, 15</span> (h. text <span dir=\"rtl\">לקבר</span>!).</div></div>","alt":[]},"11384":{"h":"חֲלָצַיִם","r":"H01111","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> du. (b. h.; <a href=\"#\" data-headword=\"חָלַץ\">חָלַץ</a> 1) <i>loins</i>. <span class=\"citation\">Ḥag. 14ᵇ</span> <span dir=\"rtl\">יצא מחֲלָצֶיךָ</span> is thy offspring; a. e.</div>","alt":[]},"11385":{"h":"חָלַק","r":"H01112","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to be smooth, to be viscous</i>. V. <a href=\"#\" data-headword=\"חָלָק\">חָלָק</a>.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"חֵלֶק\">חֵלֶק</a>) <i>to assign, allot</i>.—ח׳ כבוד <i>to honor, pay regards</i>. <span class=\"citation\">Ber. 19ᵇ</span>, a. e. <span dir=\"rtl\">כל מקום … אין חוֹלְקִין וכ׳</span> wherever the desecration of the name of the Lord is threatened, no regards must be paid to a teacher. <span class=\"citation\">Zeb. 102ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—3)</b>  (denom. of <a href=\"#\" data-headword=\"חֵלֶק\">חֵלֶק</a>) <i>to divide </i>(<i>by lot</i>)<i>; to part; to take a share.</i> <span class=\"citation\">Peah III, 5</span> <span dir=\"rtl\">האחין שחָלְקוּ</span> brothers who divided an estate. <span class=\"citation\">B. Mets. I, 1</span>, a. fr. <span dir=\"rtl\">יַחֲלוֹקוּ</span> they shall divide the object (equally). <span class=\"citation\">Zeb. XII, 1</span> <span dir=\"rtl\">אינן חוֹלְקִין וכ׳</span> take no share &amp;c. <span class=\"citation\">Ḥull. 65ᵃ</span> <span dir=\"rtl\">אם חוֹלֵק את רגליו וכ׳</span> if the birds parts its toes (on the rope) so that there be two on each side &amp;c. <span class=\"citation\">Y. Sabb. VII, 9ᶜ</span> bot. <span dir=\"rtl\">דבר … אינו חולק</span> if a prohibition (included in a law) is specified again for a purpose, it does not intimate a division (that each single act of the class must be atoned for singly, v. <a href=\"#\" data-headword=\"הַבְעָרָה\">הַבְעָרָה</a>). <span class=\"citation\">Tosef. Dem. VI, 1</span> <span dir=\"rtl\">חוֹלְקָן</span> he divides the fruits with the landlord. [<span class=\"citation\">Ib. 2</span> <span dir=\"rtl\">החולק</span>, read: <span dir=\"rtl\">החוֹכֵר</span>.] Y. ib. VI, beg. 25ᵃ <span dir=\"rtl\">מישראל חולק</span> if the property is farmed from an Israelite, he divides the produces (before separating T’rumah); a. v. fr.</div><div class=\"sense\"><b>—4)</b>  (with <span dir=\"rtl\">על</span>) <i>to differ with, object, oppose</i>. <span class=\"citation\">Y. Sabb. XV, beg. 15ᵃ</span> <span dir=\"rtl\">מה חוֹלְקִין על וכ׳</span> how is it? do they differ with &amp;c.?—<span class=\"citation\">Ber. 27ᵇ</span> <span dir=\"rtl\">החולק על ישיבתו וכ׳ וכ׳</span>; <span class=\"citation\">Snh. 110ᵃ</span> <span dir=\"rtl\">הח׳ על רבו</span> (Ar. <span dir=\"rtl\">הנֶחְלַק</span>, <i>Nif.</i>) he who opposes (the school of) his teacher. Ber. l. c. <span dir=\"rtl\">כלום יש אדם חוֹלֵק בדבר זה</span> is there any one here differing from this opinion?; a. v. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"חָלָק\">חָלוּק</a>, pl. <span dir=\"rtl\">חֲלוּקִים</span>, <span dir=\"rtl\">חֲלוּקִין</span> <i>divided, interrupted; disputed; of different opinion.</i> <span class=\"citation\">Mikv. VIII, 2</span> <span dir=\"rtl\">מים ח׳</span> interrupted flow of urin.—<span class=\"citation\">B. Bath. 176ᵃ</span> ח׳ היה ר׳ וכ׳ R. … differed &amp;c. <span class=\"citation\">Ib. IX, 10</span> (<span class=\"citation\">158ᵇ</span>) <span dir=\"rtl\">על החֲלוּקִין ואתה בא לחַלֵּק עלינו וכ׳ …</span> we grieve over the divided opinions, and you come to assert a division for us on things on which they (the schools of Shammai and Hillel) agree?; (<span class=\"citation\">Y. Shek. III, beg. 47ᵇ</span> <span dir=\"rtl\">לַחֲלוֹק</span>). <span class=\"citation\">Y. Keth. I, end, 26ᵃ</span> <span dir=\"rtl\">ח׳ על אביו</span> differs with his father; a. fr.—Tosef. Yoma V (IV), 6, a. e. <span dir=\"rtl\">ארבעה חֲלוּקֵי כפרה</span> there are four persons under different categories as to atonement. <span class=\"citation\">Arakh. 10ᵇ</span> <span dir=\"rtl\">דחֲלוּקָה בקרבנותיה</span> which differs (from other days) as regards sacrifices. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חֲלוּקִין וכ׳</span> the numbers of sacrifices are different each day.</div><div class=\"sense\"><b>Nif. נֶחְלַק</b> <div class=\"sense\"><b>1)</b> <i>to be divided, distributed</i>. <span class=\"citation\">Midr. Till. to Ps. XXVII</span> (ref. to <span dir=\"rtl\">אחלק</span>, <span class=\"citation\">Ex. XV, 9</span>) <span dir=\"rtl\">אֵיחָלֵק</span> I shall be divided (plundered).</div><div class=\"sense\"><b>—2)</b> <i>to differ.</i> <span class=\"citation\">Ḥag. 16ᵇ</span> <span dir=\"rtl\">נֶחְלְקוּ בה וכ׳</span> the great men of the age differ about it. <span class=\"citation\">Ber. 27ᵇ</span>; <span class=\"citation\">Snh. 110ᵃ</span>, v. supra. <span class=\"citation\">Keth. XIII, 1</span>; a. fr.</div></div><div class=\"sense\"><b>Hif. הֶחֱלִיק</b> <div class=\"sense\"><b>1)</b> <i>to smoothen, make even, level; to improve the appearance.</i> <span class=\"citation\">Maasr. I, 8</span> <span dir=\"rtl\">משיַחֲלִיקֶנּוּ</span> from the moment that he smoothens the cake of figs (by rubbing it with figs or grapes). Ib. <span dir=\"rtl\">המַחֲלִיק בענבים</span> if one uses grapes for smoothening.—<span class=\"citation\">Shebi. IV, 4</span> <span dir=\"rtl\">במַחֲלִיק</span> when one levels a field (by taking out plants); expl. ib. <span dir=\"rtl\">המח׳ ג׳ זה בצד זה</span> <i>levelling</i> means taking out (at least) three plants next to each other, contrad. to <span dir=\"rtl\">המדל</span>, taking out one or two plants.—<span class=\"citation\">Peah III, 3</span>, v. <a href=\"#\" data-headword=\"אֶחָד\">אֶחָד</a>; a. e.—Trnsf. <i>to close a tune softly</i> (piano). <span class=\"citation\">Arakh. II, 3</span> (<span class=\"citation\">10ᵃ</span>) <span dir=\"rtl\">ולא היה מַחֲלִיק אלא … מפני שהוא מחליק יפה</span> (Talm. ed. <span dir=\"rtl\">ולא היה מְחַלֵּק מחליק וכ׳ …</span>) none but a flute solo was used for closing a tune, because it makes a pleasant finale.—3) <i>to glide, slip</i>. <span class=\"citation\">Erub. X, 14</span> <span dir=\"rtl\">בשביל שלא יַחֲלִיקוּ</span> that the priests might not slip. <span class=\"citation\">B. Mets. VI, 3</span> <span dir=\"rtl\">אם הֶחֱלִיקָה</span> if the animal injured herself by slipping.—4) <i>to be smooth</i>. <span class=\"citation\">Yeb. 80ᵇ</span> <span dir=\"rtl\">בשרו מַחֲלִיק</span> his flesh is smooth.</div></div><div class=\"sense\"><b>Hof. הוּחֲלַק</b> <div class=\"sense\"><b>1)</b> <i>to be injured by slipping</i>. <span class=\"citation\">B. Kam. 47ᵇ</span> <span dir=\"rtl\">הוּחְלְקָה בהן</span> the animal was injured by tripping over the fruits.</div><div class=\"sense\"><b>—2)</b> <i>to be smoothed</i>. Part. <span dir=\"rtl\">מוּחֲלָק</span>, pl. <span dir=\"rtl\">מוּחֲלָקִין</span>. <span class=\"citation\">B. Mets. 103ᵇ</span> <span dir=\"rtl\">קנים המ׳</span> smoothed (peeled) poles.—[</div><div class=\"sense\"><b>3)</b> <i>to be divided up</i>, v. infra.]</div></div><div class=\"sense\"><b>Pi. חִילֵּק</b> <div class=\"sense\"><i>to divide, distribute, part.</i> Y. Keth. II, beg. 26ᵃ <span dir=\"rtl\">בוא וחַלֵּק וכ׳</span> come and divide with me &amp;c. Y. Peah VIII, 20ᶜ top; Y. Shebi. VI, beg. 36ᵇ <span dir=\"rtl\">שבע שחִילְּקוּ</span> the seven years during which they distributed the land (among the tribes); <span class=\"citation\">Zeb. 118ᵇ</span>.—<span class=\"citation\">B. Bath. IX, 7</span> <span dir=\"rtl\">המְחַלֵּק נכסיו וכ׳</span> if one disposes (wills) … by word of mouth; a. fr.—<span class=\"citation\">Sabb. 70ᵃ</span>, a. e. <span dir=\"rtl\">לחַלֵּק</span>, v. <a href=\"#\" data-headword=\"הַבְעָרָה\">הַבְעָרָה</a>.—[<span class=\"citation\">Arakh. II, 3</span> (<span class=\"citation\">10ᵃ</span>), v. supra.]—<i>Part. pass</i>. <span dir=\"rtl\">מְחוּלָּק</span> a) <i>divided up, plundered</i>. <span class=\"citation\">Yalk. Ex. 249</span> (ref. to <span dir=\"rtl\">אחלק</span>, <span class=\"citation\">Ex. XV, 9</span>) <span dir=\"rtl\">מ׳ אני להם</span> I shall be divided up among them, v. <i>Nif.</i>; Mekh. B’shall., Shirah, s. 7 <span dir=\"rtl\">מוחלק</span>.—b) <i>distinct, separate</i>. Tanḥ. Ḥuck. 6 <span dir=\"rtl\">והן מְחוּלָּקִין זה מזה</span> and they are different from one another (in the range of their intellects).</div></div><div class=\"sense\"><b>Hithpa. הִתְחַלֵּק</b> </div><div class=\"sense\"><b>Nithpa. נִתְחַלֵּק</b> <div class=\"sense\"><i>to be divided, distributed; to part, separate.</i> <span class=\"citation\">Par. III, 11</span> <span dir=\"rtl\">היה מִתְחַלֵּק וכ׳</span> was distributed among &amp;c.—<span class=\"citation\">Snh. 34ᵃ</span>, v. <a href=\"#\" data-headword=\"נִיצוֹץ\">נִיצוֹץ</a>.—<span class=\"citation\">Sifré Num. 132</span> <span dir=\"rtl\">ליוצאי מצרים נִתְחַלְּקָה וכ׳</span> the land was divided up according to the census taken at their going out from Egypt. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא נתח׳ … לכל שנט וכ׳</span> the land was allotted to each tribe (in a lump), according to its population. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא נתח׳ … אלא בשמיון</span> it was divided according to value; <span class=\"citation\">B. Bath. 122ᵃ</span> <span dir=\"rtl\">לא נ׳ אלא בכסף</span>.—<span class=\"citation\">Midr. Till. to Ps. XVIII, 2</span> <span dir=\"rtl\">היה מתח׳ מחיילותיו</span> he separated himself from his armies (for prayer). Ib. <span dir=\"rtl\">וכשהיה המחנה שלו מתח׳</span> and because his camp was thus divided (some praying, others not praying); a. fr.</div></div>","alt":[]},"11386":{"h":"חָלָק","r":"H01113","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָלַק\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>smooth, blank</i> (paper); <i>empty</i>. <span class=\"citation\">Y. Sabb. VIII, 11ᵇ</span> <span dir=\"rtl\">אם יש בו ח׳ וכ׳</span> if there is blank space on it enough for &amp;c. <span class=\"citation\">Snh. 17ᵃ</span> <span dir=\"rtl\">ושנים הניח ח׳</span> and two ballots he left blank; a. fr.—<span dir=\"rtl\">יצא ח׳</span> (= <span dir=\"rtl\">ריקם</span>) <i>to go out without having effected anything</i>. <span class=\"citation\">Sifré Num. 131</span> <a href=\"#\" data-headword=\"חָלוּק I\">חלוק</a> ed.; <span class=\"citation\">Yalk. Lev. 631</span> (<span class=\"citation\">Yalk. Ex. 178</span> <span dir=\"rtl\">ריקם</span>); <span class=\"citation\">Yalk. Hos. 517</span> <a href=\"#\" data-headword=\"חָלוּק I\">חלוק</a>.—<span class=\"citation\">Gen. R. s. 11</span> להוציאך ח׳ אי אפשר I cannot dismiss you without an answer; a. e.—Fem. <span dir=\"rtl\">חֲלָקָה</span>. <span class=\"citation\">Kel. XXIV, 7</span> <span dir=\"rtl\">וח׳</span> and a plain board (without a receptacle). <span class=\"citation\">Midd. II, 5</span>; <span class=\"citation\">Succ. 51ᵇ</span> <span dir=\"rtl\">ח׳ היתה בראשונה</span> formerly the compartment was plain (without a guarded balcony), v. <a href=\"#\" data-headword=\"בְּצוֹצְרָה\">בְּצוֹצְרָה</a>.—Pl. <span dir=\"rtl\">חֲלָקוֹת</span>. <span class=\"citation\">Tosef. Ohol. XV, 1</span>.—</div><div class=\"sense\"><b>*2)</b> <i>division</i>. <span class=\"citation\">Kerith. 7ᵃ</span>, a. fr. <span dir=\"rtl\">אך ח׳</span>, v. <a href=\"#\" data-headword=\"אַךְ I\">אַךְ</a> I [prob. to be read: <a href=\"#\" data-headword=\"חָלָק\">חַלֵּק</a>, divide!]</div>","alt":["(חָלוּק)"]},"11387":{"h":"חֵלֶק","r":"H01114","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"חָלָק\">preced.</a> wds.) [<i>smooth stone</i> used for casting lots, v. <span class=\"citation\">I Sam. XVII, 40</span> <span dir=\"rtl\">חַלֻּקֵי</span>; cmp. <a href=\"#\" data-headword=\"גּוֹרָל\">גורל</a>, <a href=\"#\" data-headword=\"גַּוָּוזָא I\">גווזא</a>; cmp. <span class=\"citation\">Is. XXXIV, 17</span>; <span class=\"citation\">Ps. XXII, 19</span>,] <i>lot, share, portion</i>. <span class=\"citation\">Snh. X </span>(XI), 1 <span dir=\"rtl\">ח׳ לעו&quot;הב</span> a share in the world to come. <span class=\"citation\">Sabb. 118ᵇ</span> יהא חֶלְקִי מ־ Oh, that my lot fell among &amp;c.; <span class=\"citation\">M. Kat. 18ᵇ</span> <span dir=\"rtl\">יהא חלקי עם</span>; a. fr.—<span class=\"citation\">Sifré Deut. 312</span> <span dir=\"rtl\">תנו לי חֶלְקִי</span> give me my estate (my title) back, v. <a href=\"#\" data-headword=\"נָכַר\">נָכַר</a>.—Pl. <span dir=\"rtl\">חֲלָקִים</span>. <span class=\"citation\">B. Mets. I, 1</span> <span dir=\"rtl\">שלשה ח׳</span> three portions (fourths). <span class=\"citation\">Sabb. 34ᵇ</span> <span dir=\"rtl\">שלשה חֶלְקֵי מיל</span> three parts of a mile, expl. three fourths; <span dir=\"rtl\">ב׳ ח׳ מיל</span> two thirds; a. fr.</div>","alt":[]},"11388":{"h":"חִלָּק","r":"H01115","html":"<div class=\"sense\">, a fictitious name, v. <a href=\"#\" data-headword=\"חִילָּק\">חִילָּק</a></div>","alt":["חֵלֶק"]},"11389":{"h":"חֲלַק","r":"H01116","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(b. h. <a href=\"#\" data-headword=\"חֶילְקָא II\">חֶלְקָה</a>, v. <a href=\"#\" data-headword=\"חֵלֶק\">חֵלֶק</a>) <i>lot, field</i>. <span class=\"citation\">Targ. Y. II, Gen. XLIX, 21</span> (Var. <a href=\"#\" data-headword=\"חֲקַל\">חַקְלָא</a>).—Pl. constr. <span dir=\"rtl\">חַלְקֵי</span>. <span class=\"citation\">Targ. I Chr. VIII, 8</span> Var. (ed. <span dir=\"rtl\">חקלי</span>).</div>","alt":[]},"11390":{"h":"חֶלְקָא","r":"H01117","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲלַק\">preced.</a>) </div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"חֲלַק\">same</a>, <i>lot, field</i>. <span class=\"citation\">Targ. Prov. XXIII, 10</span>.—Pl. <a href=\"#\" data-headword=\"חֻלַּקְתָּא\">חֶלְקָתָא</a>. <span class=\"citation\">Targ. Mic. II, 4</span> <span dir=\"rtl\">חֶלְקַתְהוֹן</span> (Var. <span dir=\"rtl\">חֻלַּקְתְּהוֹן</span>, ed. Lag. <span dir=\"rtl\">חַקְלַתְהוֹן</span>; h. text <span dir=\"rtl\">שָׂדֵינוּ</span>).</div><div class=\"sense\"><b>—2)</b> <i>share, portion, ḥelka</i>, a market term for a certain portion of meat; cmp. <a href=\"#\" data-headword=\"אוּזְיָא\">אוּזְיָא</a>. <span class=\"citation\">Bets. 29ᵃ</span></div>","alt":["חֶילְ׳"]},"11391":{"h":"חֻלָּקָא","r":"H01118","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חוּלַּק\">חוּלַּק</a></div>","alt":[]},"11392":{"h":"חִלְקָא","r":"H01119","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"חָלָק\">חָלוּק</a>) [<i>shirt</i>,] <i>husk</i>.—Pl. <span dir=\"rtl\">חִלְקַיָּא</span>. <span class=\"citation\">M. Kat. 13ᵇ</span> <span dir=\"rtl\">דשקל חִלְקַיְיהוּ</span> (Rashi <span dir=\"rtl\">דשקיל</span>) its husks are taken off; (Ms. M. <span dir=\"rtl\">דשַׁוֵּי חֶילְקַיְיהוּ</span> he made its parts even, divided the grain into two); v. <a href=\"#\" data-headword=\"חֶילְקָא II\"><span dir=\"rtl\">חֶילְקָא</span> II</a>.</div>","alt":[]},"11393":{"h":"חלקוסתא","r":"H01120","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְלִיקוּסְתָּא\">סְלִיקוּסְתָּא</a></div>","alt":[]},"11394":{"h":"חִלְקִיָּה","r":"H01121","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Ḥilkiya, Hilkiah</i>, </div><div class=\"sense\"><b>1)</b>  the high priest in the reign of Josiah. <span class=\"citation\">Meg. 14ᵇ</span>; <span class=\"citation\">Yalk. Josh. 9</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  father of Jeremiah the prophet. <span class=\"citation\">Num. R. s. 8</span>, end. <span class=\"citation\">Snh. 95ᵃ</span>, a. fr.</div><div class=\"sense\"><b>—3)</b>  name of several Amoraim. <span class=\"citation\">Y. B. Bath. III, 14ᵃ</span>; Bab. <span class=\"citation\">B. Bath. 39ᵇ</span>.—<span class=\"citation\">Y. Shek. I, 46ᵇ</span>; a. e. (v. Fr. M’bo p. 85ᵃ).—<span class=\"citation\">Kidd. 33ᵇ</span>.—<span class=\"citation\">Yeb. 9ᵃ</span>.—<span class=\"citation\">B. Mets. 96ᵇ</span>; a. e.</div>","alt":[]},"11395":{"h":"חֻלַּקְתָּא","r":"H01122","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֶלְקָא\">חֶלְקָא</a></div>","alt":[]},"11396":{"h":"חָלַשׁ","r":"H01123","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to relax, be weak, prostrated</i> (cmp. <a href=\"#\" data-headword=\"חָלָה\">חָלָה</a>).—V. <a href=\"#\" data-headword=\"חַלָּשׁ\">חַלָּשׁ</a>.</div><div class=\"sense\"><b>—2)</b>  [<i>to round, smoothen</i>, denom. <a href=\"#\" data-headword=\"חִלֶשׁ\">חֵלֶשׁ</a> <i>smooth stone;</i> (cmp. <a href=\"#\" data-headword=\"חֵלֶק\">חֵלֶק</a>) <i>ballot;</i> fr. which <a href=\"#\" data-headword=\"חָלַשׁ\">חָלַשׁ</a>] <i>to cast a lot; to assign</i>. Pesik. Zakh., p. 22ᵃ expl. <span dir=\"rtl\">ויחלש</span>, (<span class=\"citation\">Ex. XVIII, 13</span>) <span dir=\"rtl\">הפיל עליהן גורלות</span> he (Joshua) cast lots over them (for their destruction). <span class=\"citation\">Arakh. IX, 4</span> (<span class=\"citation\">31ᵇ</span>) <span dir=\"rtl\">שיהא חוֹלֵשׁ … ללשכה</span> (Mish. ed. <span dir=\"rtl\">בלשכה</span>) that he might assign his redeeming money to the Temple fund (deposit it there, to assert his privilege of redemption).</div>","alt":[]},"11397":{"h":"חֲלַשׁ","r":"H01124","html":"<div class=\"sense\"><b>1)</b> <i>to be weak, get sick</i>. <span class=\"citation\">Targ. Is. II, 9</span>. <span class=\"citation\">Targ. Lam. V, 17</span>; a. e.—<span class=\"citation\">Pes. 50ᵃ</span>; <span class=\"citation\">B. Bath. 10ᵇ</span>, v. <a href=\"#\" data-headword=\"נְגַד\">נְגַד</a>.—<span class=\"citation\">R. Hash. 17ᵃ</span>; a. fr.—<span class=\"citation\">Yoma 18ᵃ</span> <span dir=\"rtl\">חַלְשָׁא דעתיה</span> he might feel discouraged.</div><div class=\"sense\"><b>—2)</b> <i>to pass away</i>. R. Hash. l. c. <span dir=\"rtl\">חזייה דחליש ליה עלמא</span> (<span class=\"citation\">Yalk. Mic. 559</span> … <span dir=\"rtl\">חזא דחלש</span>) he saw that his world (life) was passing away (he was sinking rapidly).</div><div class=\"sense\"><b>—3)</b> <i>to be smooth and fine</i>. <span class=\"citation\">Ḥull. 48ᵃ</span> <span dir=\"rtl\">סכינא דחָ׳ פומיה</span> a knife whose edge is very fine.—</div><div class=\"sense\"><b>*4)</b> <i>to untie, undress</i>. <span class=\"citation\">Gen. R. s. 22</span> דין אמר חֲלוֹשׁ Ar. ed. Koh. (ed., a. Yalk. ib. 38 <a href=\"#\" data-headword=\"חִלּוּץ\">חֲלוֹץ</a>) the one (Abel) said, Take thy clothes off. <span class=\"citation\">Gen. R. s. 75</span> ח׳ פורפירא Ar. (ed. <span dir=\"rtl\">שלח</span>) he took off the purple cloak.</div><div class=\"sense\"><b>Pa. חַלֵּישׁ</b> <div class=\"sense\"><b>1)</b> <i>to weaken, reduce</i>. <span class=\"citation\">Targ. Job XII, 21</span> Ms. (ed. <span dir=\"rtl\">מַחֲלִישׁ</span>, <span dir=\"rtl\">מַחֲלֵשׁ</span> <i>Af.</i>).</div><div class=\"sense\"><b>—2)</b> <i>to smoothen, polish</i>, <i>forge</i> (armour). <span class=\"citation\">Ab. Zar. 16ᵃ</span> <span dir=\"rtl\">משׁום דחַלְּשֵׁי וכ׳</span> (Ms. M. <span dir=\"rtl\">דחשלי</span>; v. infra) because they forge of them their polished armour.</div></div><div class=\"sense\"><b>Af. אַחֲלִישׁ</b> <div class=\"sense\"><b>1)</b> <i>to weaken</i>, v. supra.</div><div class=\"sense\"><b>—2)</b> <i>to cut with a sharp and smooth edge</i>, opp. to <a href=\"#\" data-headword=\"בְּזַע\">בזע</a> to tear with a notched knife. <span class=\"citation\">Ḥull. 17ᵇ</span> (Rashi quoting Ab. Zar. l. c. <span dir=\"rtl\">דחשלי</span>, a. <span class=\"citation\">Keth. 77ᵃ</span> <span dir=\"rtl\">חשלי דודי</span> appears to have read <span dir=\"rtl\">מחשיל</span>).—</div><div class=\"sense\"><b>*3)</b> <i>to strip</i>. <span class=\"citation\">Targ. Y. II, Lev. I, 6</span> (O. a. Y. I <span dir=\"rtl\">שלח</span>). <span class=\"citation\">Targ. Y. II, Num. XX, 26</span> <span dir=\"rtl\">ותחלישׁ</span> (some ed. <span dir=\"rtl\">ותשליח</span>).</div></div>","alt":["חָלִישׁ"]},"11398":{"h":"חִלֶשׁ","r":"H01125","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָלַשׁ\">חָלַשׁ</a>, cmp. <a href=\"#\" data-headword=\"חֵלֶק\">חֵלֶק</a>) <i>lot, ballot</i>. Pesik. Zakh., p. 22ᵃ (ref. to <span dir=\"rtl\">ויחלש</span>, <span class=\"citation\">Ex. XIII, 13</span>) <span dir=\"rtl\">בח׳ לקה וכ׳</span> Amalek was smitten by ballot (v. <a href=\"#\" data-headword=\"חָלַשׁ\">חָלַשׁ</a>). Ib. <span dir=\"rtl\">ארבעה שמות נקראו לגורל ח׳ וכ׳</span> the lot has four names, <i>Ḥêlesh, pûr</i> &amp;c.; <span class=\"citation\">Yalk. Ex. 265</span>.—Pl. <span dir=\"rtl\">חֲלָשִׁים</span>, <span dir=\"rtl\">חֲלָשִׁין</span>. <span class=\"citation\">Ib.</span> (quotation) <span dir=\"rtl\">וכאשר יטילו ח׳ על המנות</span>; <span class=\"citation\">Sabb. XXIII, 2</span> (<span class=\"citation\">148ᵇ</span>) <span dir=\"rtl\">מטילין ח׳ וכ׳</span> lots may be cast for shares of sacred meat &amp;c. <span class=\"citation\">Sabb. 149ᵇ</span> <span dir=\"rtl\">מאי משמע דהאי ח׳ וכ׳</span> what evidence is there that <i>ḥălashim</i> means lot? (Answ. ref. to <span class=\"citation\">Is. XIV, 12</span>).</div>","alt":[]},"11399":{"h":"חֵלַשׁ","r":"H01126","html":"<div class=\"sense\"><i>reed</i>, v. <a href=\"#\" data-headword=\"חֵילַשׁ\">חֵילַשׁ</a>.</div>","alt":["חִלַּשׁ"]},"11400":{"h":"חַלָּשׁ","r":"H01127","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>weak</i>. <span class=\"citation\">Sabb. 77ᵇ</span> <span dir=\"rtl\">אימת ח׳ וכ׳</span> the fear with which the weak inspires the strong person.—<span class=\"citation\">Ex. R. s. 24</span>; <span class=\"citation\">Sifré Deut. 309</span>; a. e.—Pl. <span dir=\"rtl\">חַלָּשִׁים</span>, <span dir=\"rtl\">חַלָּשִׁין</span>. Ex. R. l. c.</div>","alt":[]},"11401":{"h":"חַלָּשׁ ²","r":"H01128","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲלִישׁ\">חֲלִישׁ</a>. <span class=\"citation\">Targ. O. Deut. XXVIII, 44</span>. <span class=\"citation\">Targ. I Sam. IX, 21</span>.—Pl. <span dir=\"rtl\">חַלָּשִׁין</span>, <a href=\"#\" data-headword=\"חִלָּזוֹן\">חֲלָ׳</a>. <span class=\"citation\">Targ. Ex. XXXII, 18</span>.</div>","alt":["חֲלָשׁ","חֲלָשָׁא"]},"11402":{"h":"חַלָּשׁוּת","r":"H01129","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חַלָּשׁ ²\">preced.</a>) <i>weakness, laxity</i>. <span class=\"citation\">Targ. I Kings XII, 10</span> <span class=\"citation\">Targ. Koh. X, 17</span>; a. e.</div>","alt":["חַלָּשׁוּתָא"]},"11403":{"h":"חַלְּתָא","r":"H01130","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> ; esp. <i>the priest’s portion</i>. <span class=\"citation\">Targ. Num. XV, 20</span>.—<span class=\"citation\">Erub. 83ᵃ</span> <span dir=\"rtl\">אייתי ח׳ שדי עליהו</span> he brought the priest’s portion in addition to it.</div>","alt":[]},"11404":{"h":"חַלְתָּא","r":"H01131","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָלַל\">חלל</a>, cmp. <a href=\"#\" data-headword=\"חֵילַת I\"><span dir=\"rtl\">חֵילַת</span> I</a>) <i>a loose wicker-work</i> used for making bee-hives, strainers, for wine presses, screens &amp;c. <span class=\"citation\">Snh. 107ᵃ</span> <span dir=\"rtl\">תותי ח׳</span> behind a screen (Rashi: bee-hive; <span class=\"citation\">Yalk. Sam. 148</span> <a href=\"#\" data-headword=\"כִּילְתָא I\">כילתא</a>). Ib. <span dir=\"rtl\">פתקה לח׳</span> it (the arrow) made an opening in the screen. <span class=\"citation\">Sabb. 35ᵃ</span> <span dir=\"rtl\">ח׳ בת תרי כורי</span> a basket containing two <i>khor</i>. <span class=\"citation\">Ib. 74ᵇ</span> <span dir=\"rtl\">האי מאן דעבד ח׳</span> he who makes a wicker-work on the Sabbath (going through the whole process of cutting reeds &amp;c.).—Pl. <span dir=\"rtl\">חַלָּאתָא</span>, <a href=\"#\" data-headword=\"חַלְּתָא\">חַלָּתָא</a>. <span class=\"citation\">Ab. Zar. 75ᵃ</span> חלתא דיקולי וכ׳ Ms. M. (ed. <span dir=\"rtl\">דקולי וחלא׳</span>, Ar. incorr. <span dir=\"rtl\">ח׳ דדיק׳</span>) the palm or reed strainers which are twined with ropes of palm-rind.</div>","alt":[]},"11405":{"h":"חלתותא","r":"H01132","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֶלְמָא\">חִילְ׳</a></div>","alt":["חִלְתִּית","חִלְתִּיתָא"]},"11406":{"h":"חַם","r":"H01133","html":"<div class=\"sense\">, perf. of <a href=\"#\" data-headword=\"חֲמַם\">חֲמַם</a>.</div>","alt":[]},"11407":{"h":"חָם I","r":"H01134","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Ham</i>, the son of Noah. <span class=\"citation\">Snh. 69ᵇ</span> ח׳ גדול וכ׳ H. was the elder of Japheth by one year &amp;c. <span class=\"citation\">Ib. 108ᵇ</span> ח׳ לקה בעורו H. was punished on his skin (was made black); <span class=\"citation\">Gen. R. s. 36</span> יצא ח׳ מפוהם Ḥ. came out (of the ark) blackened; a. e.</div>","alt":[]},"11408":{"h":"חָם II","r":"H01135","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>warm, hot, boiling</i>. <span class=\"citation\">Pes. 75ᵇ</span>, sq.; a. fr.—<span class=\"citation\">Nidd. 43ᵃ</span> <span dir=\"rtl\">בשרו חם</span> his membrum excited.—Pl. <a href=\"#\" data-headword=\"חַמִּים\">חַמִּים</a>, <a href=\"#\" data-headword=\"חַמִּין\">חַמִּין</a> (sub. <a href=\"#\" data-headword=\"מַיִם\">מים</a>) <i>hot water</i>. <span class=\"citation\">Sabb. 134ᵇ</span> <span dir=\"rtl\">ח׳ שהוחמו וכ׳</span> hot water which was made hot on the Sabbath; a. fr.—חַמֵּי טבריה <i>the hot springs of Tiberias</i>, in gen. <i>natural hot water</i>, opp. to <span dir=\"rtl\">חמי האור</span> water heated by fire. <span class=\"citation\">Ḥull. 8ᵃ</span> (<span class=\"citation\">Neg. IX, 1</span> <a href=\"#\" data-headword=\"מִי I\">מֵי</a>); a. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"חַמָּה\">חַמָּה</a>. <span class=\"citation\">Makhsh. III, 3</span> <span dir=\"rtl\">פת ח׳</span> hot bread.</div>","alt":[]},"11409":{"h":"חָם III","r":"H01136","html":"<div class=\"sense\"> v. Ges. H. Dict.<sup>10</sup> s. v.) <i>father-in-law</i>, <i>husband’s father, wife’s father</i>. <span class=\"citation\">Yeb. XV, 7</span> <a href=\"#\" data-headword=\"חֲמִי\">חָמִי</a> my husband’s father. <span class=\"citation\">Ib. I, 1</span> <span dir=\"rtl\">חָמִיו</span> his (the <i>yabam’s</i>) father-in-law. <span class=\"citation\">Pes. 87ᵃ</span> <span dir=\"rtl\">כלה בבית חָמִיהָ</span> a bride in the house of her father-in-law (after being conducted to the husband’s home); a. v. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"חָמוֹת\">חָמוֹת</a> q. v.</div>","alt":[]},"11410":{"h":"חָמָא I","r":"H01137","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. XXXVIII, 13</span> <span dir=\"rtl\">חָמוּיִיךְ</span> (ed. Berl. <a href=\"#\" data-headword=\"חָבִיב\">חֲ׳</a>; oth. <span dir=\"rtl\">חָמוּךְ</span>). Targ. O. ib. 25 <a href=\"#\" data-headword=\"חֲמוּהָ\">חֲמוּהָא</a>. <span class=\"citation\">Targ. O. Ex. XVIII, 2</span> <a href=\"#\" data-headword=\"חֲמוּהָ\">חֲמוּהִי</a> ed. Berl. (oth. <a href=\"#\" data-headword=\"חֲסַף II\">חָ׳</a>, Y. <span dir=\"rtl\">חָמוֹי</span>); a. e.—Y. Ber. I, 2ᵈ bot. <span dir=\"rtl\">חמוי</span>. <span class=\"citation\">B. Mets. 74ᵇ</span> <span dir=\"rtl\">בי חַמְוֵה</span> in the house of <i>his daughter’s father-in-law</i>. <span class=\"citation\">Kidd. 12ᵇ</span>; <span class=\"citation\">Yeb. 52ᵃ</span> <a href=\"#\" data-headword=\"חֲמוּהָ\">חמוה</a> his father-in-law. <span class=\"citation\">Ib. 117ᵇ</span> <a href=\"#\" data-headword=\"חֲמוּהָ\">חֲמוּהָ</a> her father-in-law; a. fr.</div>","alt":[]},"11411":{"h":"חָמָא II","r":"H01138","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḥama</i>, name of several Amoraim. <span class=\"citation\">Y. Nidd. III, 50ᶜ</span> bot. R. Ḥ., father of R. Hoshaya.—<span class=\"citation\">Y. Peah VIII, 21ᵇ</span> top; <span class=\"citation\">Y. Shek. V, 49ᵃ</span> bot.; a. e. (v. Fr. M’bo, p. 85ᵇ).—Ib. 49ᵇ; <span class=\"citation\">Y. Sabb. VI, 8ᵃ</span>; <span class=\"citation\">B. Mets. 86ᵇ</span>, a. fr. R. Ḥ. bar Ḥănina.—<span class=\"citation\">B. Kam. 99ᵇ</span>; <span class=\"citation\">Y. Kidd. III, 64ᵈ</span>, a. fr. R. Ḥ. bar Gurya.—<span class=\"citation\">Y. Erub. VII, 23ᶜ</span>; Bab. <span class=\"citation\">Erub. 65ᵇ</span> bot. Ms. M. (ed. <a href=\"#\" data-headword=\"חֲנִינָא\">חנינא</a>, v. Rabb. D. S. a. l. note) R. Ḥ. bar Joseph.—<span class=\"citation\">Y. Kil. VIII, 31ᶜ</span> top, a. fr. R. Ḥ. bar Ukba.</div>","alt":[]},"11412":{"h":"חֲמָא","r":"H01139","html":"<div class=\"sense\"><i>to see</i>, v. <a href=\"#\" data-headword=\"חֲמִי\">חמי</a>.</div>","alt":[]},"11413":{"h":"חֵמָא","r":"H01140","html":"<div class=\"sense\"> , <i>anger.</i> <span class=\"citation\">Dan. III, 13</span>; <span class=\"citation\">19</span>.</div>","alt":["חֱמָא"]},"11414":{"h":"חַמָּא","r":"H01141","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">חמם</span>; cmp. <span dir=\"rtl\">חַמָּם</span>) <i>radish.</i> <span class=\"citation\">Ab. Zar. 28ᵇ</span> bot. <span dir=\"rtl\">ח׳ לחמה</span> Ms. M. a. Ar. (ed. <a href=\"#\" data-headword=\"חַמָּה\">חַמָּה</a>) radishes are good for fever. <span class=\"citation\">Pes. 116ᵃ</span> <span dir=\"rtl\">קפא דחסא ח׳ וכ׳</span></div>","alt":[]},"11415":{"h":"חֶמְאָה","r":"H01142","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"חֲמִי\">חמי</a>) [<i>pressed, thick</i>,] <i>cream</i> or <i>butter</i>. <span class=\"citation\">Ber. 63ᵇ</span> (ref. to <span class=\"citation\">Prov. XXX, 33</span>) <span dir=\"rtl\">ח׳ של תורה</span> the cream of the Law (sound knowledge). <span class=\"citation\">B. Mets. 86ᵇ</span> <span dir=\"rtl\">בשכר ח׳ וכ׳</span> as a reward for the offer of cream and milk (<span class=\"citation\">Gen. XVIII, 8</span>).</div>","alt":[]},"11416":{"h":"חֶמְאֲתָא","r":"H01143","html":"<div class=\"sense\"><span class=\"citation\">Targ. Prov. XXX, 33</span>, v. <a href=\"#\" data-headword=\"*חַאיְתָא\">חַאיְתָא</a>.</div>","alt":[]},"11417":{"h":"חָמַד","r":"H01144","html":"<div class=\"sense\"><b>1)</b>  [<i>to be hot</i>,] <i>to desire, covet; to be carnally excited</i>. <span class=\"citation\">Nidd. 20ᵇ</span> <span dir=\"rtl\">חֲמַדְתִּיו</span> (or <a href=\"#\" data-headword=\"חִימּוּץ\">חִמַּ׳</a> <i>Pi.</i>) I had a desire for his embrace. <span class=\"citation\">Midr. Till. to Ps. XIX, 11</span> <span dir=\"rtl\">מי חְמָדָן</span> which (of the two) holds them desirable; <span class=\"citation\">Yalk. ib. 676</span> [read]: <span dir=\"rtl\">מי החוֹמְדִין</span>. Mekh. Yithro, Baḥod. s. 8 <span dir=\"rtl\">שאתה חומד וכ׳</span> that you may desire his daughter for your son; <span dir=\"rtl\">ח׳ בדבור</span> expressing a desire by words (without thinking of means to obtain the object of his desire). [Ib. ed. Weiss, <span dir=\"rtl\">אם התאוה סופו לַחֲמוֹד</span> if one desires (what belongs to his neighbor), he will finally covet it (think of means to obtain it). Ib. <span dir=\"rtl\">אם ח׳ סופו וכ׳</span> if he covets, he will finally use force and rob. <span class=\"citation\">B. Mets. 5ᵇ</span> <span dir=\"rtl\">לאו דלא תַחְמוֹד</span>, v. <a href=\"#\" data-headword=\"לַאו\">לַאו</a>; a. fr.—<i>Part. pass</i>. <span dir=\"rtl\">חָמוּד</span>, f. <a href=\"#\" data-headword=\"חֲמוּדָה\">חֲמוּדָה</a> <i>desirable, precious</i>. <span class=\"citation\">Pesik. R. s. 36</span> <span dir=\"rtl\">ח׳ ונאה</span> precious and fine (of conduct).—<span class=\"citation\">Sabb. 88ᵇ</span> <span dir=\"rtl\">ח׳ גנוזה</span> ed., v. <a href=\"#\" data-headword=\"חֶמְדָּה\">חֶמְדָּה</a>.—[</div><div class=\"sense\"><b>2)</b>  (= <a href=\"#\" data-headword=\"חָמַר I\">חָמַר</a>) <i>to produce shrivelling</i> by heat. <span class=\"citation\">Snh. VII, 2</span> (<span class=\"citation\">52ᵃ</span>) Ar. (ref. to <span class=\"citation\">Dan. X, 3</span>; Var. <span dir=\"rtl\">חמר</span>).</div><div class=\"sense\"><b>Nif. נֶחְמַד</b> <div class=\"sense\"><b>1)</b> <i>to be desired, desirable</i>. Tanḥ. Vayera 5 <span dir=\"rtl\">שאתה נֶחְמָד לפני וכ׳</span> that thou art held desirable before the Lord; a. e.—[</div><div class=\"sense\"><b>2)</b> <i>to be shrivelled</i>. <span class=\"citation\">Ḥull. III, 3</span> Ar., Var. <a href=\"#\" data-headword=\"חָמַר II\">נחמר</a>, v. supra.]</div></div><div class=\"sense\"><b>Pi. חִימֵּד</b> <div class=\"sense\"><i>to covet</i>. <span class=\"citation\">Macc. III, 15</span> <span dir=\"rtl\">שנפשו … מתאוה להן ומְחַמַּדְתָּן</span> which man longs for and covets.</div></div><div class=\"sense\"><b>Hithpa. הִתְחַמֵּד</b> </div><div class=\"sense\"><b>Nithpa. נִתְחַמֵּד</b> <div class=\"sense\"> (with <a href=\"#\" data-headword=\"ל\">ל</a>) <i>to be anxious for; to be pleased with</i>. Tanḥ. <span class=\"citation\">Mishp. 17</span> <span dir=\"rtl\">ארץ שנִתְחַמְּדוּ לה וכ׳</span> a land which all the great men were anxious to possess (<span class=\"citation\">Yalk. Jer. 271</span> <span dir=\"rtl\">שהָמְדוּ</span>). <span class=\"citation\">Koh. R. to IX, 7</span> <span dir=\"rtl\">בוראך מִתְחַמֵּד לך</span> thy Creator is pleased with thee; <span dir=\"rtl\">תורתו מִתְחַמֶּדֶת לך</span></div></div>","alt":[]},"11418":{"h":"חֲמַד","r":"H01145","html":"<div class=\"sense\"><span class=\"citation\">Targ. Is. I, 29</span>; a. fr.—Part. f. <span dir=\"rtl\">(<span dir=\"rtl\">חֲמֵידַת</span>) <span dir=\"rtl\">חְמֵידָא</span></span>. <span class=\"citation\">Targ. Y. Gen. IV, 1</span>.</div><div class=\"sense\"><b>Pa. חַמֵּיד  חַמֵּד</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חָמַד\">same</a>, <i>to long</i>. <span class=\"citation\">Targ. O. Gen. XXXI, 30</span> (Y. <span dir=\"rtl\">מִתְחַמְדָּא חֲמִדְתָּא</span>).—<span class=\"citation\">Nidd. 66ᵃ</span> bot. <a href=\"#\" data-headword=\"מְחַמַּר\">מְחַמְּדָא</a>, v. <a href=\"#\" data-headword=\"חִימּוּד\">חִימּוּד</a>.</div></div><div class=\"sense\"><b>Ithpa. אִתְחַמַּד</b> </div><div class=\"sense\"><b>Ithpe. אִתְחֲמַד</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חָמַד\">same</a>.—Targ. Y. Gen. l. c.—Ib. XXVIII, 10.—Y. Taan. III, 66ᵈ top <span dir=\"rtl\">מִתְחֲמַד וכ׳</span> being desirous to hear her talk. Y. Sabb. VI, 8ᶜ bot. <span dir=\"rtl\">הוו מִתְחַמְּדִין וכ׳</span> were anxious to see &amp;c. <span class=\"citation\">Koh. R. to IX, 10</span>; a. e.</div></div>","alt":["חֲמִיד"]},"11419":{"h":"חַמְדָּא","r":"H01146","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲמַד\">preced.</a>) (<i>sexual</i>) <i>appetite</i>. <span class=\"citation\">Sabb. 152ᵃ</span> <span dir=\"rtl\">חַמְדֵּיה</span>.</div>","alt":[]},"11420":{"h":"חֶמְדָּה","r":"H01147","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"חַמְדָּא\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"חַמְדָּא\">same</a>. <span class=\"citation\">Sabb. 152ᵃ</span> (expl. <span dir=\"rtl\">אביונה</span>, <span class=\"citation\">Koh. XII, 5</span>) <span dir=\"rtl\">זו ח׳</span> that means the sexual appetite; (Koh. R. to l. c. <a href=\"#\" data-headword=\"תַּאֲוָה\">תַּאֲוָה</a>).).</div><div class=\"sense\"><b>—2)</b> <i>desirability, desirable object, precious gift</i>. Tanḥ. Sh’moth 29, a. e. <span dir=\"rtl\">דבר שהוא ח׳ מתוך ח׳</span> something which is the most desirable of all desirable things. <span class=\"citation\">Y. Taan. II, beg. 65ᵃ</span> <span dir=\"rtl\">כלי אחד של ח׳</span> the only precious vessel (the Torah) left to us. <span class=\"citation\">Sabb. 88ᵇ</span> ח׳ גנוזה Ms. M. (ed. <a href=\"#\" data-headword=\"חֲמוּדָה\">חמודה</a>) a reserved treasure (the Law); a. fr.</div>","alt":[]},"11421":{"h":"חַמְדָּן","r":"H01148","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַמְדָּן\">הַמְדָּן</a></div>","alt":[]},"11422":{"h":"חֶמְדָּתָא","r":"H01149","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"חֶמְדָּה\">חֶמְדָּה</a>. <span class=\"citation\">Targ. Zech. VII, 14</span>; <span class=\"citation\">Targ. Jer. III, 19</span>.  v. <a href=\"#\" data-headword=\"חֲמִידְתָּא\">חֲמִידְתָּא</a></div>","alt":["חֶמְדְּ׳"]},"11423":{"h":"חֲמָה","r":"H01150","html":"<div class=\"sense\"><i>to see</i>, v. <a href=\"#\" data-headword=\"חֲמִי\">חמי</a>.</div>","alt":[]},"11424":{"h":"חֵמָה","r":"H01151","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>heat, anger</i>. <span class=\"citation\">Snh. 82ᵇ</span> <span dir=\"rtl\">משיב ח׳ בן וכ׳</span> he is an allayer of (divine) anger, the son of &amp;c. <span class=\"citation\">Num. R. s. 20</span> <span dir=\"rtl\">נתמלא עליה ח׳</span> he became angry at her. <span class=\"citation\">Lam. R. to I, 6</span> <span dir=\"rtl\">חֲמָתוֹ של הב&quot;ה</span> the anger of the Lord; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>Ḥemah</i>, allegorical name of one of the angels of justice. <span class=\"citation\">Ex. R. s. 41</span>, end; a. e., v. <a href=\"#\" data-headword=\"אַף II\"><span dir=\"rtl\">אַף</span> II</a>.</div>","alt":["חֵי׳"]},"11425":{"h":"חַמָּה","r":"H01152","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>sun</i>. <span class=\"citation\">Ber. 59ᵇ</span> <span dir=\"rtl\">ח׳ בתקופתה</span> the sun starting on his new cycle (of twenty eight years). <span class=\"citation\">Num. R. s. 14</span> <span dir=\"rtl\">י&quot;ב הדשים לח׳</span> the twelve solar months. <span class=\"citation\">Ned. III, 7</span> <span dir=\"rtl\">רואי הח׳</span> those seeing (or feeling) the sun; <span dir=\"rtl\">שלא נתכוין … שהח׳ וכ׳</span> for he meant him whom the sun sees; a. v. fr.—<span class=\"citation\">Yeb. VIII, 4</span>, a. fr. <span dir=\"rtl\">סריס ח׳</span> a eunuch from the time of seeing the sun, i.e. born without visible testicles; opp. to <span dir=\"rtl\">סריס אדם</span>.</div><div class=\"sense\"><b>—2)</b> <i>fever</i>. <span class=\"citation\">Sabb. 137ᵃ</span>, a. e., v. <a href=\"#\" data-headword=\"חָלַץ\">חָלַץ</a>. <span class=\"citation\">Y. Sabb. XIX, end, 17ᵇ</span>, v. <a href=\"#\" data-headword=\"אָחַז\">אָחַז</a>. <span class=\"citation\">Gen. R. s. 19</span>, a. e., v. <a href=\"#\" data-headword=\"אַכְאָבִית\">אַבְאָבִית</a>. <span class=\"citation\">Y. Sabb. I, end, 4ᵇ</span> (prov.) <span dir=\"rtl\">פת חמה חַמָּתָהּ בצדה</span> hot bread has its heat by its side, i.e. eating hot bread causes fever; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>radish</i>. <span class=\"citation\">Ab. Zar. 28ᵇ</span> bot., v. <a href=\"#\" data-headword=\"חַמָּא\">חַמָּא</a>.—V. <a href=\"#\" data-headword=\"חַמַּת\">חַמַּת</a>.</div>","alt":[]},"11426":{"h":"חֲמוּדָא","r":"H01153","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"חֶמְדָּה\">חֶמְדָּה</a>. <span class=\"citation\">Targ. Jud. V, 30</span> (ed. Lag. <a href=\"#\" data-headword=\"חֲמוּדָה\">חֲמוּדָה</a>).</div>","alt":[]},"11427":{"h":"חָמוֹדָא","r":"H01154","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">חמד</span>) <i>covetous</i>.—Pl. <span dir=\"rtl\">חֲמוֹדִין</span>, <span dir=\"rtl\">חֲמוֹדַיָּא</span>. <span class=\"citation\">Targ. Y. Ex. XX, 14</span>; <span class=\"citation\">Deut. V, 18</span> (ed. Amst. <span dir=\"rtl\">חֲמוּ׳</span>).</div>","alt":[]},"11428":{"h":"חֲמוּדָה","r":"H01155","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָמַד\">חָמַד</a>, <a href=\"#\" data-headword=\"חֶמְדָּה\">חֶמְדָּה</a> a. <a href=\"#\" data-headword=\"חֲמוּדָא\"><a href=\"#\" data-headword=\"חֲמוּדָא\">חֲמוּדָא</a>.</a></div>","alt":[]},"11429":{"h":"חֲמוּהָ","r":"H01156","html":"<div class=\"sense\"> &amp;c., v. <a href=\"#\" data-headword=\"חָמָא I\"><span dir=\"rtl\">חָמָא</span> I</a></div>","alt":["חַמְוֵה","חֲמוּהִי"]},"11430":{"h":"חֲמוּטַלְיָא","r":"H01157","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֵמְטַלְיָא\">הֵמְטַלְיָא</a></div>","alt":[]},"11431":{"h":"חמולות","r":"H01158","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲמִילָה\">חֲמִילָה</a></div>","alt":[]},"11432":{"h":"חִמּוּם","r":"H01159","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִימּוּם\">חִימּוּם</a> a. <a href=\"#\" data-headword=\"חֲמָם\"><a href=\"#\" data-headword=\"חֲמָם\">חֲמָם</a>.</a></div>","alt":[]},"11433":{"h":"חַמּוּם","r":"H01160","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">חמם</span>) <i>heated, rash</i>.—Pl. <span dir=\"rtl\">חַמּוּמוֹת</span>. <span class=\"citation\">Y. Snh. VI, 23ᵇ</span> bot. <span dir=\"rtl\">היו ידיו ח׳</span> his hands were heated, i.e. he was very severe in executing judgment.</div>","alt":["חַמּוּמָה"]},"11434":{"h":"חִמּוּץ","r":"H01161","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֵימָרָא\">חִימּ׳</a></div>","alt":["חִמּוּצָא"]},"11435":{"h":"חַמּוּק","r":"H01162","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>rundle</i>.—Pl. <span dir=\"rtl\">חַמּוּקִים</span>. Yalk. Ex. 370 <span dir=\"rtl\">שתי ידות … ח׳</span> two handles (pins) of the shape of two rundles, v. <a href=\"#\" data-headword=\"חָרַץ\">חָרַץ</a>.</div>","alt":[]},"11436":{"h":"חֲמוֹר","r":"H01163","html":"<div class=\"sense\"> c. (b. h.; v. <a href=\"#\" data-headword=\"חָמַר II\"><span dir=\"rtl\">חָמַר</span> II</a> a. </div><div class=\"sense\"><b>1)</b>  [<i>load-carrier</i>, cmp. <a href=\"#\" data-headword=\"גָּמָל\">גָּמָל</a>.] <i>ass</i>. <span class=\"citation\">Nidd. 31ᵃ</span>, v. <a href=\"#\" data-headword=\"גָּרַם\">גָּרַם</a>. <span class=\"citation\">Sabb. 152ᵃ</span> <span dir=\"rtl\">דעל ח׳ וכ׳</span> he who rides an ass is a freeman. <span class=\"citation\">B. Bath. 143ᵃ</span> <span dir=\"rtl\">את וח׳</span> thou and the ass (shall own my property, a form of donation implying a rational and an irrational being).—<span class=\"citation\">Bekh. I, 2</span> <span dir=\"rtl\">ח׳ שילדה וכ׳</span> if an ass gave birth to &amp;c. <span class=\"citation\">Snh. 33ᵃ</span> <span dir=\"rtl\">הלכה חֲמוֹרְךָ וכ׳</span> thy ass is gone, Tarfon! (I shall have to make compensation for erroneous judgment); a. fr.</div><div class=\"sense\"><b>—2)</b>  (cmp. various uses of <i>horse</i>) <i>a contrivance for working-men, rest, jack, stocks</i> &amp;c. <span class=\"citation\">Kel. XIV, 3</span> <span dir=\"rtl\">ח׳ של נפחין</span> the smiths’ ass (‘on which the smith sits while using its head as an anvil’, Maim.; ‘the rest of the bellows’, R. S.). Ib. XVIII, 3 <span dir=\"rtl\">וח׳</span> a stand on which the bedstead is placed. <span class=\"citation\">Gen. R. s. 65</span>, end <span dir=\"rtl\">ח׳ של חרשים</span> carpenters’ sawing-jack (an instrument for torture); <span class=\"citation\">Gen. R. s. 70</span> (alluding to <span class=\"citation\">Prov. XXVII, 22</span>) <span dir=\"rtl\">אפי׳ … בח׳ של חרשים וכ׳</span> even if you put the wicked man on a carpenter’s jack, you cannot make anything useful out of him (sufferings will have no effect on him); <span class=\"citation\">Yalk. Kings 201</span>; <span class=\"citation\">Yalk. Prov. 961</span>; (Pesik. Shek., p. 15ᵃ <span dir=\"rtl\">במכתש</span>).—Pl. <span dir=\"rtl\">חֲמוֹרִים</span>. <span class=\"citation\">Sabb. 112ᵇ</span>. <span class=\"citation\">Gen. R. s. 75</span>; a. fr.—Denom. <a href=\"#\" data-headword=\"חַמָּר\">חַמָּר</a>, <a href=\"#\" data-headword=\"חָמַר I\">חִמִּר</a>.—<i>Fem.</i> <a href=\"#\" data-headword=\"חֲמוֹרָה\">חֲמוֹרָה</a>. <span class=\"citation\">Tosef. Kil. V, 5</span>.</div>","alt":[]},"11437":{"h":"חָמוּר","r":"H01164","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (חָמַר I) <i>heavy, weighty, important; strict, severe, stringent, restrictive.</i> <span class=\"citation\">Kel. I, 4</span> <span dir=\"rtl\">ח׳ שבכולם וכ׳</span> the most stringent of all are the laws concerning corpses.—<span dir=\"rtl\">איסור ח׳</span>, v. <a href=\"#\" data-headword=\"אִיסּוּר I\">אִיסּוּר</a>.—<span class=\"citation\">Snh. 50ᵃ</span> <span dir=\"rtl\">שריפה ח׳ וכ׳</span> death by burning is a severer punishment than &amp;c. <span class=\"citation\">Ib. IX, 4</span>, a. e. <span dir=\"rtl\">נידון בח׳</span> he suffers the severer penalty of the two. <span class=\"citation\">Ab. II, 1</span> <span dir=\"rtl\">כבחמורה</span> as in the observance of a difficult commandment (requiring self-denial); a. fr.—Pl. <span dir=\"rtl\">חֲמוּרִים</span>, <span dir=\"rtl\">חֲמוּרִין</span>, f. <span dir=\"rtl\">חֲמוּרוֹת</span>. <span class=\"citation\">Ḥull. XII, 5</span>; a. fr.—Y. Snh. X, 28ᵇ top <span dir=\"rtl\">חֲמוּרוֹתָיו של וכ׳</span> (not <span dir=\"rtl\">חומר׳</span>) the heaviest sins that Jeroboam committed.—<span dir=\"rtl\">דורשי חֲמוּרוֹת</span>, v. <a href=\"#\" data-headword=\"חוֹמֶר II\"><span dir=\"rtl\">חוֹמֶר</span> II</a>. <span dir=\"rtl\">קלים וחֲמוּרִים</span>, v. <a href=\"#\" data-headword=\"חוֹמֶר I\"><span dir=\"rtl\">חוֹמֶר</span> I</a>.</div>","alt":["חֲמוּרָה"]},"11438":{"h":"חֲמוֹרָה","r":"H01165","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲמוֹר\">חֲמוֹר</a></div>","alt":[]},"11439":{"h":"חֲמוֹרְתָּא","r":"H01166","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲמָר\">חֲמָר</a>) <i>a drove of asses</i>. <span class=\"citation\">Gen. R. s. 75</span>, v. <a href=\"#\" data-headword=\"גְּמַלְתָּא\">גְּמַלְתָּא</a>.</div>","alt":[]},"11440":{"h":"חָמוֹת","r":"H01167","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"חָם III\"><span dir=\"rtl\">חָם</span> III</a>) <i>mother-in-law</i>. <span class=\"citation\">Yeb. I, 1</span> <span dir=\"rtl\">חֲמוֹתוֹ</span> the <i>yabam’s</i> wife’s mother. <span class=\"citation\">Ib. XVI, 1</span> <span dir=\"rtl\">היתה לה ח׳ וכ׳</span> if the childless widow had a mother-in-law abroad (who may have given birth to a son), she need not take it into consideration (and may marry again); a. fr.</div>","alt":[]},"11441":{"h":"חֲמוֹתָא","r":"H01168","html":"<div class=\"sense\"><span class=\"citation\">Targ. Deut. XXVII, 23</span>; a. e.; v. <a href=\"#\" data-headword=\"חֲמָתָא\">חֲמָתָא</a></div>","alt":[]},"11442":{"h":"חֲמַט I","r":"H01169","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"חָמֵץ I\">חמץ</a>) </div><div class=\"sense\"><b>1)</b> <i>to be dark</i>.—Denom. <a href=\"#\" data-headword=\"חוּמְטָא I\">חוּמְטָא</a>.</div><div class=\"sense\"><b>—2)</b> <i>to be bitter, salty</i>, v. <a href=\"#\" data-headword=\"חוּמְטוֹן\">חוּמְטוֹן</a>.</div><div class=\"sense\"><b>Ithpe. אִיחֲמַט</b> <div class=\"sense\"><i>to be inflamed, become pestered</i>. <span class=\"citation\">Sabb. 54ᵇ</span> Ar., v. <a href=\"#\" data-headword=\"חֲמַט II\">next w.</a></div></div>","alt":[]},"11443":{"h":"חֲמַט II","r":"H01170","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"חֶבֶט I\">חבט</a>) <i>to knock down</i>.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"חֲמַט II\">חָמֵיט</a>, <a href=\"#\" data-headword=\"חֲמַט II\">חֲמִיט</a> <i>prostrated, kneeling</i>, (as verb) <i>to kneel</i>. <span class=\"citation\">Targ. Is. XLVI, 1</span>. <span class=\"citation\">Targ. Ps. XCV, 6</span> <span dir=\"rtl\">נַחֲמוֹט</span> (some ed. <span dir=\"rtl\">נַחֲמִיט</span>). <span class=\"citation\">Targ. Y. Deut. XXVIII, 35</span> <span dir=\"rtl\">חֲמִיטְתּוּן … עבירתא</span> (some ed. <a href=\"#\" data-headword=\"חַמִּים\">חַמִּי׳</a> incorr.; not <a href=\"#\" data-headword=\"עֲבִידָא\">עבידתא</a>); cmp. <span class=\"citation\">Targ. Job IV, 4</span> <span dir=\"rtl\">דחָמְטָן</span>. [<span class=\"citation\">Koh. R. to IV, 9</span>, end <span dir=\"rtl\">חמטת</span>, some ed., read: <span dir=\"rtl\">דמָטַת</span>.]</div><div class=\"sense\"><b>Pa. חַמֵּיט</b> <div class=\"sense\"><i>to prostrate, subdue</i>. <span class=\"citation\">Targ. Ps. XVII, 13</span>. <span class=\"citation\">Ib. XVIII, 40</span> Reg. (ed. <a href=\"#\" data-headword=\"תְּבַרְתָּא\">תברתא</a>).</div></div><div class=\"sense\"><b>Af. אַחֲמִיט</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חֲמַט I\">same</a>. Ib. LXXVIII, 31.</div></div><div class=\"sense\"><b>Ithpe. אִיחֲמַט</b> <div class=\"sense\"><i>to knock against, be battered</i>. <span class=\"citation\">Sabb. 54ᵇ</span> דלא לִיחַמְטָן אליתייהו Ms. M. (ed. incorr.) that their tails may not knock against (the rocks &amp;c., Rashi; Ar.: ‘may not ulcerate’; v. Syr. <span dir=\"rtl\">חמטא</span> pustula, ulcus, P. Sm. 1303; v. <a href=\"#\" data-headword=\"חֲמַט I\">preced.</a>).</div></div>","alt":[]},"11444":{"h":"חֲמָטָה","r":"H01171","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲמִיטָה\">חֲמִיטָה</a></div>","alt":[]},"11445":{"h":"חֲמִי","r":"H01172","html":"<div class=\"sense\"> (Arab. <i>ḥama</i> tueri) [<i>to surround, guard</i>, v. <a href=\"#\" data-headword=\"חוֹמָה\">חוֹמָה</a>,] <i>to observe, see</i> (in Y. dialect). <span class=\"citation\">Targ. Y. Gen. I, 4</span> (O. <span dir=\"rtl\">חזא</span>); a. v. fr.—<span class=\"citation\">Targ. Prov. XXIII, 33</span> Ms. (ed. <span dir=\"rtl\">ויחַוְור׳</span>).—Y. Peah III, 17ᵈ bot. <span dir=\"rtl\">אתא חמי</span> (= <span dir=\"rtl\">תא חזי</span>, h. <span dir=\"rtl\">בא וראה</span>) come and see. <span class=\"citation\">Gen. R. s. 14</span> <span dir=\"rtl\">דאת חָמֵי לאפויי וכ׳</span> (not <span dir=\"rtl\">דאתח׳</span>) that thou shalt see his face in the hereafter; <span class=\"citation\">Midr. Till. to Ps. II; Yalk. ib. 62</span>1 <span dir=\"rtl\">חמוי</span> (corr. acc.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חַמְתֵיה</span> (fr. <span dir=\"rtl\">חמה</span>) he saw him. Pesik. Eth Korb. p. 57ᵇ (v. Bub. note 15) <span dir=\"rtl\">חַמְתִי אכיל חַמְתִי שתי</span> did he (Moses) see me (the Lord) eat &amp;c.?; <span class=\"citation\">Yalk. Num. 776</span> <span dir=\"rtl\">חַמְתֵיה וכ׳</span> did he see Him &amp;c.?; a. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"חֲמִי\">חֲמֵי</a> (v. <a href=\"#\" data-headword=\"חֲזִי\">חֲזִי</a>) <i>fit, worthy</i>. <span class=\"citation\">Targ. Ps. XV, 1</span>. <span class=\"citation\">Ib. LVIII, 2</span> (ed. <a href=\"#\" data-headword=\"חֲמִי\">חֲמִי</a>); a. fr.—Fem. <a href=\"#\" data-headword=\"חַלְיָא\">חַמְיָא</a>. <span class=\"citation\">Targ. Y. Ex. XXII, 16</span>.</div><div class=\"sense\"><b>Af. אַחֲמֵי</b> <div class=\"sense\"><b>1)</b>  (followed by (followed by <span dir=\"rtl\">מ־</span>, cmp. <a href=\"#\" data-headword=\"סוּר I\">סור</a>) <i>to turn </i>(<i>the eye</i>)<i> from</i>. <span class=\"citation\">Targ. Prov. XXVIII, 27</span> (Ar. <span dir=\"rtl\">מהמי</span>, h. text <span dir=\"rtl\">מעלים</span>, v. Syr. <span dir=\"rtl\">המא</span> P. Sm. 1017).</div><div class=\"sense\"><b>—2)</b> <i>to cause to see, to show</i>. <span class=\"citation\">Targ. Y. Gen. XLI, 28</span>; a. e.—<span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\">ואַחְמִין ליה וכ׳</span> and showed him a measure full of denars. Ib. <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד כות׳ 1) <span dir=\"rtl\">דכל עמא מַחְמִין לי וכ׳</span> that all people point at me with their fingers.</div></div><div class=\"sense\"><b>Pa. חַמֵּי</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חֲמָטָה\">same</a>. Y. Kil. IX, 32ᵇ bot.; Y. Keth. XII, 35ᵃ bot. <span dir=\"rtl\"><a href=\"#\" data-headword=\"חֲמִי\">חַמֵּי</a> (<a href=\"#\" data-headword=\"סְפִקוּלָא\">לה</a>) <a href=\"#\" data-headword=\"לֵי\">לי</a></span> let me see it (the tooth).</div></div><div class=\"sense\"><b>Ithpa. אִתְחַמֵּי</b> </div><div class=\"sense\"><b>Ithpe. אִתְחֲמֵי</b> <div class=\"sense\"><i>to be seen, to appear</i>. <span class=\"citation\">Targ. Y. Gen. VIII, 5</span>; a. fr.—[<span class=\"citation\">Targ. Ps. XLII, 3</span> אִתַּחֲמֵי Ms. (<i>Ittaf.</i>) <i>I shall appear before</i> (h. text <span dir=\"rtl\">אֵרָאֶה</span>, Var. a. ed. <a href=\"#\" data-headword=\"חֲמִי\">אֶחְמֵי</a>)].—<span class=\"citation\">M. Kat. 25ᵇ</span> <span dir=\"rtl\">אִתְחֲמִיאוּ וכ׳</span> stars were seen in day time. Y. Peah VIII, end, 21ᵇ דחמי ולא מִתְחֲמֵי He who sees but cannot be seen. Lam. R. introd. (R. Joḥ. 1) <span dir=\"rtl\">מִתְחַמְאִין</span>, v. <a href=\"#\" data-headword=\"*מַשְׁתָּיֵי\">מַשְׁתָּיֵי</a>; a. e.</div></div>","alt":["חֲמָא","חֲמָה"]},"11446":{"h":"חָמֵיד","r":"H01173","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲמַד\">חֲמַד</a></div>","alt":[]},"11447":{"h":"חֲמִידְתָּא","r":"H01174","html":"<div class=\"sense\"> f. ch. = h. <a href=\"#\" data-headword=\"חֶמְדָּה\">חֶמְדָּה</a>. <span class=\"citation\">Targ. Am. V, 11</span> (ed. Wil. <a href=\"#\" data-headword=\"חֶמְדָּתָא\">חֶמְדָתָא</a>, ed. Lag. <a href=\"#\" data-headword=\"חֶמְדָּתָא\">חֶמְדָּאתָא</a>). <span class=\"citation\">Targ. Is. XXXII, 12</span>.—<span class=\"citation\">Ib. XXVI, 8</span> <span dir=\"rtl\">חֲמִידַת</span> constr.</div>","alt":[]},"11448":{"h":"זֵכֶר","r":"G00469","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>memorial, remembrance, symbol, mnemonical allusion</i>. <span class=\"citation\">Succ. III, 12</span> <span dir=\"rtl\">ז׳ למקדש</span> as a reminiscence of the Temple usages; <span class=\"citation\">Pes. 115ᵃ</span>. <span class=\"citation\">Ib. 116ᵃ</span> <span dir=\"rtl\">ז׳ לתפוח</span> typical of the apple tree (<span class=\"citation\">Cant. VIII, 5</span>; v. <span class=\"citation\">Sot. 11ᵇ</span>); <span dir=\"rtl\">ז׳ לטיט</span> typical of the clay (which the Israelites had to tread). <span class=\"citation\">Ber. 2ᵇ</span>; <span class=\"citation\">Tosef. Sabb. VII</span> (<span class=\"citation\">VIII), 4</span>, a. e. <span dir=\"rtl\">אע&quot;פ שאין … ז׳ לדבר</span> although there is no proof for it (in the Bible), there is a mnemonical allusion to it; a. fr.</div>","alt":["זֶכֶר"]},"11449":{"h":"זִכָּרוֹן","r":"G00470","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <a href=\"#\" data-headword=\"זֵכֶר\">same</a>, <i>memory, memorial</i>. <span class=\"citation\">Kidd. 31ᵇ</span>, a. e. <span dir=\"rtl\">זִכְרוֹנוֹ לברכה</span> (abbr. <span dir=\"rtl\">ז&quot;ל</span>) of blessed memory, v. <a href=\"#\" data-headword=\"זָכַר\">זָכַר</a>. <span class=\"citation\">Y. Shek. II, 47ᵃ</span> top <span dir=\"rtl\">דבריהן הן זִכְרוֹנָן</span> their words are their monument; <span class=\"citation\">Gen. R. s. 82</span> <span dir=\"rtl\">זִכְרוֹנֵיהֶם</span> (pl.). <span class=\"citation\">R. Hash. 27ᵃ</span> <span dir=\"rtl\">ז׳ ליום ראשון</span> typical of the first day of creation; a. fr.—Esp. <i>a Biblical verse in which Divine remembrance is alluded to, citation of verses</i> &amp;c. <span class=\"citation\">R. Hash. IV, 6</span> <span dir=\"rtl\">ז׳ … של פורענות</span> citation of remembrance … for evil. <span class=\"citation\">Ib. 32ᵇ</span> <span dir=\"rtl\">ז׳ של יחיד</span> a verse treating of the remembrance by the Lord of an individual; a. fr.—Pl. <span dir=\"rtl\">זִכְרוֹנוֹת</span>. <span class=\"citation\">Ber. 6ᵃ</span> <span dir=\"rtl\">ספר הז׳</span> the Divine records; a. fr.—Esp. <i>Zikhronoth, that portion of the Musaf of the New Year’s Day which treats of Divine remembrance</i>. <span class=\"citation\">R. Hash. IV, 5</span>, sq.; a. fr.—Constr. <span dir=\"rtl\">זִכְרוֹנֵי</span>, v. supra.</div>","alt":[]},"11450":{"h":"זַכְרוּת","r":"G00471","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"זָכָר\">זָכָר</a>) </div><div class=\"sense\"><b>1)</b> <i>male genitals; male sex</i>. <span class=\"citation\">Y. Snh. X, 28ᵈ</span> bot.; <span class=\"citation\">Num. R. s. 20</span>, end.—<span class=\"citation\">Ab. Zar. 44ᵃ</span> (expl. <a href=\"#\" data-headword=\"מִפְלֶצֶת\">מפלצת</a>, <span class=\"citation\">II Chr. XV, 16</span>) <span dir=\"rtl\">כמין ז׳</span> a phallus. <span class=\"citation\">Men. 6ᵃ</span> <span dir=\"rtl\">תמות וז׳ בבהמה</span> unblemished condition and male sex of sacrifices are required only of cattle. <span class=\"citation\">Y. Yeb. VIII, end, 9ᵈ</span> <span dir=\"rtl\">צד ז׳</span> the male side of the hermaphrodite; <span dir=\"rtl\">מכח זַכְרוּתוֹ</span> in as much as he is a male; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>the thin and pointed side of a double tool</i>. <span class=\"citation\">Bets. 31ᵇ</span> <span dir=\"rtl\">ז׳ שלו</span> the sharper side of a hatchet (used for splitting), opp. <span dir=\"rtl\">נקבות שלו</span> the broader side. <span class=\"citation\">Cant. R. to I, 3</span> [read:] <span dir=\"rtl\">כאדם שמטביל זַכְרוּתוֹ של מכחול בים</span> as much as one takes up when dipping the point of the painting staff into the paint bottle.</div><div class=\"sense\"><b>—3)</b> <i>the fructifying principle, germ, bud, eye</i> or <i>strophiole</i> (in plants); <i>germinating spot</i> (in eggs) &amp;c., v. next w.—<span class=\"citation\">Y. Sabb. VII, 9ᵈ</span> bot.; XII, 13ᶜ bot. <span dir=\"rtl\">כדי ליטע זַכְרוּתָהּ של חיטה</span> deep enough to plant the wheat grain up to its eye (so that it can take root). <span class=\"citation\">Y. Ter. X, end, 47ᶜ</span> <span dir=\"rtl\">ז׳ של חלמון</span> that part of the yolk where germination sets in; <span class=\"citation\">ib.</span> <span dir=\"rtl\">ז׳ של מוח</span> the germinating point in the white of the egg (the more substantial and cohesive part).</div><div class=\"sense\"><b>—4)</b> <i>the bony inside of an animal’s horn</i> or <i>hoofs, the bony projection over which the horny substance grows</i>. <span class=\"citation\">R. Hash. 27ᵇ</span>. <span class=\"citation\">Y. Erub. I, 19ᵇ</span> bot. <span class=\"citation\">Bekh. 44ᵃ</span> (<span class=\"citation\">Tosef. ib. II (I), 2</span> <span dir=\"rtl\">הזָכָר</span>). [<span class=\"citation\">Zeb. 63ᵃ</span> <span dir=\"rtl\">בזכרות</span>, v. <a href=\"#\" data-headword=\"זוּטַר II\"><span dir=\"rtl\">זוּטְרָא</span> I</a>.]</div>","alt":[]},"11451":{"h":"זַכְרוּתא","r":"G00472","html":"<div class=\"sense\"><b>1)</b> <i>male genitals</i>. <span class=\"citation\">Y. Ab. Zar. II, 40ᵈ</span> bot. <span dir=\"rtl\">מן זכרותיה דדוהי</span>; <span class=\"citation\">Y. Sabb. XIV, 14ᵈ</span> bot. <span dir=\"rtl\">מן יברותה דדידי</span> or <span dir=\"rtl\">דדירי</span>; Tosaf. to <span class=\"citation\">Ab. Zar. 27ᵇ</span> <span dir=\"rtl\">זכרות דחווי</span>, read: <span dir=\"rtl\">מן זכרותא דדַחְוֵוי</span> (v. <a href=\"#\" data-headword=\"*דַּחֲוָא\">דַּחֲוָא</a>, <a href=\"#\" data-headword=\"דַּחְיָיא\">דַּחְיָיא</a>) a medicinal drink prepared of the phallus of Dionysian revellers; [oth. opin. v. infra].</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"זַכְרוּת\">preced.</a> 3) <i>source, fountain-head, feeder</i>. <span class=\"citation\">Bekh. 55ᵃ</span> <span dir=\"rtl\">ז׳ דירדנא וכ׳</span> the chief supply of the Jordan comes from the cave of Paneas. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ז׳ דדמא וכ׳</span> the liver is the fountain-head of the blood. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ז׳ דמיא וכ׳</span> (<span class=\"citation\">Yalk. Gen. 22</span> <a href=\"#\" data-headword=\"דברותא\">דברותא</a>, read <span dir=\"rtl\">דַּכְרוּתָא</span> or <a href=\"#\" data-headword=\"זָךְ\">זַכְ׳</a>) the Euphrates is the supplier of water (for the world), cmp. <a href=\"#\" data-headword=\"אַוְותֶּנְטִי\">אֶוְותַּנְטִי</a>.—[Y. Ab. Zar. l. c. <span dir=\"rtl\">מן ז׳ דדוהי</span> from the source of menstruation, v. supra.] [<span class=\"citation\">Zeb. 63ᵃ</span>, v. <a href=\"#\" data-headword=\"זוּטַר II\"><span dir=\"rtl\">זוּטְרָא</span> I</a>.]</div>","alt":[]},"11452":{"h":"זְכַרְיָה","r":"G00473","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Zechariah</i>, </div><div class=\"sense\"><b>1)</b>  the prophet-priest slain in the Temple court (<span class=\"citation\">II Chr. XXIV, 20</span>, sq.). <span class=\"citation\">Targ. Lam. II, 20</span>.—<span class=\"citation\">Gitt. 57ᵇ</span>; <span class=\"citation\">Y. Taan. IV, 69ᵃ</span> bot.; <span class=\"citation\">Lam. R. to II, 2</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>Zechariah</i>, the prophet. <span class=\"citation\">Erub. 21ᵃ</span>. <span class=\"citation\">Macc. 24ᵇ</span>. <span class=\"citation\">Snh. 99ᵃ</span>; a. e.</div><div class=\"sense\"><b>—3)</b>  Z. ben <i>K’butal,</i> a survivor of the Second Temple. <span class=\"citation\">Yoma I, 6</span>; <span class=\"citation\">ib. 19ᵇ</span> (v. Rabb. D. S. a. l. notes 3, 4).—4) R. Z. son of Eucolus, a Tannai. <span class=\"citation\">Tosef. Sabb. XVI</span> (<span class=\"citation\">XVII), 6</span>, v. <a href=\"#\" data-headword=\"אֶבְקוֹלָס\">אֶבְקוֹלָס</a>; <span class=\"citation\">Gitt. 56ᵃ</span>; a. e.—5) R. Z., the butcher’s son, a Tannai. <span class=\"citation\">Eduy. VIII, 2</span>. <span class=\"citation\">B. Bath. 111ᵃ</span>; a. e.—6) name of several Amoraim. <span class=\"citation\">Y. Snh. I, 18ᵇ</span> top. <span class=\"citation\">Y. Pes. I, 27ᵇ</span> top; Y. Sot. I, 16ᵈ <a href=\"#\" data-headword=\"זְבַדְיָה\">זבדיה</a>; <span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">זכר׳</span>.—<span class=\"citation\">Snh. 67ᵇ</span>; a. e.</div>","alt":["זְכַרְיָהוּ"]},"11453":{"h":"זַכְרָן","r":"G00474","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זָכַר\">זָכַר</a>) <i>one having a good memory</i>. <span class=\"citation\">Der. Er. Zuta ch. III</span> <span dir=\"rtl\">כונס וז׳</span> a receptive and retentive mind.</div>","alt":[]},"11454":{"h":"זָל","r":"G00475","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זוּל\">זוּל</a>, <a href=\"#\" data-headword=\"זְלַל\"><a href=\"#\" data-headword=\"זְלַל\">זְלַל</a>.</a></div>","alt":["זַל"]},"11455":{"h":"זְלָא","r":"G00476","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*זְלֵי\">זְלֵי</a></div>","alt":[]},"11456":{"h":"זָלַג","r":"G00477","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">זלח</span>, <span dir=\"rtl\">זלף</span>) <i>to drip, flow</i>. <span class=\"citation\">Sot. VII, 8</span>; <span class=\"citation\">Pes. 118ᵃ</span> <span dir=\"rtl\">זָלְגוּ עיניו דמעות</span> his eyes shed tears. Y. Snh. IV, 23ᵇ bot. <span dir=\"rtl\">זלגו עיניהם</span> (sub. <span dir=\"rtl\">דמעות</span>). <span class=\"citation\">Yalk. Job 897</span> <span dir=\"rtl\">עינו של ימין זוֹלֶגֶת דם</span> his right eye was dripping blood; <span class=\"citation\">Gen. R. s. 93</span> <span dir=\"rtl\">שני שלטונין זולגות</span> (corr. acc.); a. e.</div>","alt":[]},"11457":{"h":"זְלַג","r":"G00478","html":"<div class=\"sense\"> ch <a href=\"#\" data-headword=\"זָלַג\">same</a>. <span class=\"citation\">Targ. Ps. LXXVII, 3</span>. <span class=\"citation\">Targ. Lam. I, 2</span> זָלְגָּן Ar. (ed. <span dir=\"rtl\">זליג</span>); a. e.</div>","alt":[]},"11458":{"h":"זַלְדְּקַן","r":"G00479","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a comp. of <a href=\"#\" data-headword=\"זָל\">זל</a>, v. <span dir=\"rtl\">זלל</span>, a. <a href=\"#\" data-headword=\"דְּקַן\">דְּקַן</a>) <i>thin-bearded, one with a downy beard</i>. <span class=\"citation\">Snh. 100ᵇ</span> (a citation fr. Ben Sira) <span dir=\"rtl\">ז׳ קורטמן</span> (Ms. M. <span dir=\"rtl\">דלדקן</span>, Var. <span dir=\"rtl\">דל דקן</span>, <span dir=\"rtl\">זיל ד׳</span> &amp;c., v. Rabb. D. S. a. l. note) a thin-bearded person is sharp-minded. <span class=\"citation\">Y. Taan. IV, beg. 67ᵇ</span>; <span class=\"citation\">Y. Meg. IV, 75ᶜ</span> top <span dir=\"rtl\">הוה מעבר ז׳</span> removed one with a downy beard (from pronouncing the priestly benediction).</div>","alt":[]},"11459":{"h":"זְלוֹחאָה","r":"G00480","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">זלח</span>) <i>sprinkler</i>.—Pl. <span dir=\"rtl\">זְלוֹחָאֵי</span>. <span class=\"citation\">Ḥull. 60ᵃ</span> <span dir=\"rtl\">הני … ז׳ וכ׳</span> these (the winds and rains) are the sweepers and sprinklers that march before the Lord.</div>","alt":[]},"11460":{"h":"זְלוּעַ","r":"G00481","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (זלע Syr. to draw water, P. Sm. 1129; v. <a href=\"#\" data-headword=\"דלי\">דלי</a>) <i>pitcher</i>. <span class=\"citation\">Targ. Jer. XIX, 1</span>; a. e.</div>","alt":[]},"11461":{"h":"זִלּוּף","r":"G00482","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זִילּוּף\">זִילּוּף</a></div>","alt":[]},"11462":{"h":"*זְלוּקְפָא","r":"G00483","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (transpos. of <span dir=\"rtl\">זלפק׳</span>, Palel of <span dir=\"rtl\">זפק</span>, v. <a href=\"#\" data-headword=\"זֶפֶק\">זֶפֶק</a>) <i>craw</i> of birds. <span class=\"citation\">Targ. Y. Lev. I, 16</span> Ar. (ed. <a href=\"#\" data-headword=\"זָרוֹקְפָא\">זָרוֹקְפָא</a>; Ar. s. v. <span dir=\"rtl\">לקט</span>: <span dir=\"rtl\">זַלְפְּקָקָא</span>).</div>","alt":[]},"11463":{"h":"זַלְזִילָא","r":"G00484","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">זלזל</span>, v. <a href=\"#\" data-headword=\"זוּל I\">זול</a> a. <span dir=\"rtl\">זלזל</span>)<i>spendthrift, debauchee</i>.—Pl. <span dir=\"rtl\">זַלְזִילי</span>. <span class=\"citation\">Targ. Prov. XXVIII, 7</span> (ed. Lag. a. oth. <span dir=\"rtl\">זְלִילֵי</span>).</div>","alt":[]},"11464":{"h":"זִלְזֵל","r":"G00485","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זָלַל\">זָלַל</a>, <a href=\"#\" data-headword=\"זְלַל\"><a href=\"#\" data-headword=\"זְלַל\">זְלַל</a>.</a></div>","alt":["זַלְזֵל"]},"11465":{"h":"זַלְזְלָנָא","r":"G00486","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זִלְזֵל\">preced.</a>) <i>intemperate, gluttonous</i>.—Pl. <a href=\"#\" data-headword=\"זַלְזְלָנָא\">זַלְזְלָנֵי</a>. <span class=\"citation\">Keth. 60ᵇ</span></div>","alt":[]},"11466":{"h":"זָלַח","r":"G00487","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">זלג</span>) </div><div class=\"sense\"><b>1)</b> <i>to drip, be wet</i>. Y. B. Mets. VI, beg. 10ᵈ <span dir=\"rtl\">שדהו זָלְחָה</span> his field was too wet (for work).</div><div class=\"sense\"><b>—2)</b> <i>to sprinkle</i> aromatic fluids. <span class=\"citation\">Num. R. s. 13</span>, beg. <span dir=\"rtl\">מכבדות וזולחות וכ׳</span> (not <span dir=\"rtl\">וזוחלות</span>) the winds sweep and sprinkle all the perfumes &amp;c.; <span class=\"citation\">Yalk. Cant. 988</span> <span dir=\"rtl\">זולחת ומכבדת</span>, read: <span dir=\"rtl\">מכ׳ וזוֹחֶלֶת</span>; cmp. <a href=\"#\" data-headword=\"זְלוֹחאָה\">זְלוֹחָאָה</a>.—<span class=\"citation\">Tosef. Shek. I, 12</span> <span dir=\"rtl\">יִזְלַח לו זֶלַח וכ׳</span> (or <span dir=\"rtl\">יְזַלֵּחַ</span>) one may use it for sprinkling before his bier (Y. ib. II, 47ᵃ top <span dir=\"rtl\">יעשה לו זלוף</span>).</div><div class=\"sense\"><b>Pi. זִילֵּחַ</b> <div class=\"sense\"><i>to sprinkle</i> the floor for cooling or perfuming the air. <span class=\"citation\">Tosef. Sabb. XVI</span> (<span class=\"citation\">XVII), 3</span> <span dir=\"rtl\">אין מְזַלְּחִין את הבית וכ׳</span> (not <span dir=\"rtl\">החבית</span>) one must not (on the Sabbath) sprinkle the house with any kind of sprinkling fluids.</div></div>","alt":[]},"11467":{"h":"זְלַח","r":"G00488","html":"<div class=\"sense\">, <i>to sprinkle, rain</i>. <span class=\"citation\">Targ. Job XXXVI, 28</span> (Ms. <a href=\"#\" data-headword=\"זְחַל I\">זחל</a>). <span class=\"citation\">Targ. Cant. V, 13</span>; a. e. [<span class=\"citation\">Targ. Is. XXX, 14</span>, v. <a href=\"#\" data-headword=\"דְּלַח\">דְּלַח</a>.]</div><div class=\"sense\"><b>Af. אַזְלִיחַ  אַזְלַח</b> <div class=\"sense\"><i>to cause a flux </i>or<i> diarrhœa</i> by fright. <span class=\"citation\">Targ. Ps. XXIX, 9</span> (h. text <span dir=\"rtl\">יחולל</span>).</div></div><div class=\"sense\"><b>Ithpe. אִזְדְּלַח</b> <div class=\"sense\"><i>to be sprinkled, to gurgle forth</i>, v. <a href=\"#\" data-headword=\"זִלְחָא\">זִלְחָא</a>. <span class=\"citation\">Targ. Job XXVIII, 4</span> <span dir=\"rtl\">מִיזְדְלַח מרזביא</span> (Ms. <span dir=\"rtl\">מזדלף</span>) gurgling (and forming) gutters (h. text <a href=\"#\" data-headword=\"גֵּר\">גָּר</a>).</div></div>","alt":[]},"11468":{"h":"זֶלַח","r":"G00489","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְלַח\">preced.</a> wds.) <i>sprinkling fluid, perfume</i>. <span class=\"citation\">Tosef. Shek. I, 12</span>, v. <a href=\"#\" data-headword=\"זָלַח\">זָלַח</a>.—Pl. <span dir=\"rtl\">זְלָחִין</span>. Sifra B’har, Par. 1, ch. I <span dir=\"rtl\">ולא לעשות … ז׳</span> but not for preparing perfumes, v. <a href=\"#\" data-headword=\"זִילּוּף\">זִילּוּף</a>. <span class=\"citation\">Tosef. Sabb. XVI</span> (<span class=\"citation\">XVII), 3</span>, v. <a href=\"#\" data-headword=\"זָלַח\">זָלַח</a>.</div>","alt":[]},"11469":{"h":"זִלְחָא","r":"G00490","html":"<div class=\"sense\">, <i>sprinkling, gurgling, jet</i> of water. <span class=\"citation\">Sabb. 95ᵃ</span> <span dir=\"rtl\">שרי זי׳</span> permitted sprinkling the floors on the Sabbath. <span class=\"citation\">Meg. 28ᵇ</span> <span dir=\"rtl\">ז׳ דמטרא</span> a shower.—Pl. constr. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"זִילּוּף\">זַלְ׳</a>) <span dir=\"rtl\">זִלְחֵי</span></span>, <a href=\"#\" data-headword=\"זְמַן II\">זִי׳</a>. <span class=\"citation\">Targ. Job XXVIII, 11</span> Regia (ed. <span dir=\"rtl\">קלילי</span>, h. text <a href=\"#\" data-headword=\"בכי\">בכי</a>). <span class=\"citation\">Targ. Ps. XLII, 8</span> <span dir=\"rtl\">ז׳ מרזביין</span> the gurgling of gutters, v. <a href=\"#\" data-headword=\"זְלַח\">זְלַח</a> <i>Ithpe.</i></div>","alt":["זִילְחָא"]},"11470":{"h":"*זְלֵי","r":"G00491","html":"<div class=\"sense\"><i>to flow, glide</i>. <span class=\"citation\">Targ. Prov. IV, 21</span> (v. <a href=\"#\" data-headword=\"זְלַל\">זְלַל</a>).</div>","alt":["זְלָא"]},"11471":{"h":"זָלֵיל","r":"G00492","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <span dir=\"rtl\">זלל</span>) = h. <a href=\"#\" data-headword=\"זוֹלֵל\">זוֹלֵל</a>, <i>reckless in spending and eating</i>. <span class=\"citation\">Targ. O. Deut. XXI, 20</span> <span dir=\"rtl\">זָ׳ בסר</span> (ed. Amst. <a href=\"#\" data-headword=\"זִילּוּף\">זַלֵּ׳</a>) wasteful in buying and eating meat; cmp. <a href=\"#\" data-headword=\"זוּל\">זוּל</a> I h. a. <a href=\"#\" data-headword=\"זוֹל\">זוֹל</a>.</div>","alt":[]},"11472":{"h":"זְלִיל","r":"G00493","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">זלל</span>) <i>light, easy; insignificant, valueless</i>. <span class=\"citation\">Targ. II Chr. IX, 27</span>. <span class=\"citation\">Targ. Prov. XIV, 6</span>.—<span class=\"citation\">Y. Pes. IV, end, 31ᵇ</span>,ᶜ <span dir=\"rtl\">כמיש וז׳</span> shrunk and cheap.</div>","alt":["זְלִילָא I"]},"11473":{"h":"זְלִילָא II","r":"G00494","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְלִיל\">preced.</a>) <i>common man, humble; low</i>. <span class=\"citation\">Targ. Prov. XII, 9</span>.—Pl. <span dir=\"rtl\">זְלִילֵי</span>. <span class=\"citation\">Ib. XXVIII, 7</span> (some ed. <span dir=\"rtl\">זַלְזִילֵי</span>).</div>","alt":[]},"11474":{"h":"זְלִילָה","r":"G00495","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(<a href=\"#\" data-headword=\"זְלִילָא II\">preced.</a>) <i>cheap</i>. <span class=\"citation\">Y. B. Mets. V, 10ᶜ</span> bot. <span dir=\"rtl\">בשער ז׳ … שתא</span> (not <span dir=\"rtl\">בשעה</span>, <span dir=\"rtl\">בשעת</span>) at the lowest price of the entire year.</div>","alt":[]},"11475":{"h":"זְלִיפָה","r":"G00496","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זָלַף\">זָלַף</a>) <i>emptying</i> from vessel to vessel. <span class=\"citation\">Ab. Zar. 36ᵃ</span> <span dir=\"rtl\">זְלִיפָתָן של … אוסרתן</span> the fact that they pour (into their oil vessels) residues of unclean (of forbidden) vessels makes their oil forbidden.</div>","alt":[]},"11476":{"h":"זְלִיקָא","r":"G00497","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">זלק</span>, cmp. P. Sm. 1125; 1131, a. <span dir=\"rtl\">זרק</span>) <i>spark</i>.—Pl. <span dir=\"rtl\">זְלִיקֵי</span>. <span class=\"citation\">Targ. Prov. XVI, 27</span>.</div>","alt":[]},"11477":{"h":"זָלַל","r":"G00498","html":"<div class=\"sense\"> (b. h; cmp. <span dir=\"rtl\">דלל</span>) <i>to be light, slender</i>.—<a href=\"#\" data-headword=\"זוֹלֵל\">זוֹלֵל</a>, v. <a href=\"#\" data-headword=\"זוּל\">זוּל</a>.</div><div class=\"sense\"><b>Pilp. זִלְזֵל</b> <div class=\"sense\"><b>1)</b> <i>to treat lightly, to despise, neglect</i> (with <a href=\"#\" data-headword=\"ב\">ב</a>). <span class=\"citation\">Ber. 6ᵇ</span> (ref. to <span class=\"citation\">Ps. XII, 9</span>) <span dir=\"rtl\">ובני אדם מְזַלְזְלִין בהן</span> and which people treat slightly. Y. Peah I, 15ᵈ, sq. <span dir=\"rtl\">מז׳ בבני וכ׳</span> they despise the sons of the handmaids; <span class=\"citation\">Gen. R. s. 84</span>. <span class=\"citation\">Sabb. 62ᵇ</span> <span dir=\"rtl\">המְזַלְזֵל וכ׳</span> he who is neglectful in the observance &amp;c. <span class=\"citation\">Ab. Zar. 36ᵃ</span> לודאי מזלזלין הן Ms. M. (ed. <span dir=\"rtl\">דמזלזלו</span>) the Lyddeans are neglectful of religious observances; a. e.</div><div class=\"sense\"><b>—2)</b>  ז׳ מעות <i>to disregard money-matters</i>. Y. Snh. VIII, 26ᵇ top; ib. XI, beg. 30ᵃ (the rebellious son that took what belonged to his father) <span dir=\"rtl\">אינו חייב עד שיְזַלְזֵל מ׳</span> cannot be made responsible, unless he disregards money, expl. ib. ‘he takes an object and sells it for its exact cost price’ (thus proving both his rationality and his wastefulness).</div></div>","alt":[]},"11478":{"h":"זְלַל","r":"G00499","html":"<div class=\"sense\">, <i>to be of little value, disregarded</i>. <span class=\"citation\">Targ. Prov. III, 21</span> <span dir=\"rtl\">לא נִזַל בעינך</span> (h. text <span dir=\"rtl\">ילזו</span>). <span class=\"citation\">Ib. IV, 21</span> לא נִיזְלָן בעיניך Var. ed. Lag. a. oth. ed. (ed. Lag. <span dir=\"rtl\">בעיניך</span>, v. <a href=\"#\" data-headword=\"*זְלֵי\">זְלֵי</a>; h. text <span dir=\"rtl\">יליזו מ־</span>).</div><div class=\"sense\"><b>Palp. זַלְזֵל</b> <div class=\"sense\"><b>1)</b> <i>to disregard, despise</i>. <span class=\"citation\">Targ. Y. Deut. XXVII, 16</span>. <span class=\"citation\">Targ. Y. Gen. XVI, 4</span> <span dir=\"rtl\">זלזלת</span> (ed. pr. <span dir=\"rtl\">זַלְּלַת</span>) she disregarded.—<span class=\"citation\">Ḥull. 133ᵃ</span> <span dir=\"rtl\">זַלְזוּלֵי קא מְזַלְזֵל וכ׳</span> does he show that he treats religious observances with disrespect?, opp. <a href=\"#\" data-headword=\"חָבַב I\">חבב</a>.—<span class=\"citation\">Ab. Zar. 35ᵃ</span> ואתי לזַלְזוּלֵי בה Ms. M. (ed. <span dir=\"rtl\">לזִילְזוּלָא</span>) and he may be induced to disregard it; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to count the lowest price</i>. <span class=\"citation\">B. Mets. 52ᵇ</span> <span dir=\"rtl\">מְזַלְזְלִינָן במעשר שני</span> in redeeming second tithes we are permitted to count closely. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">תרי זילי לא מז׳</span> two lowerings of value must not be applied to it (to value closely and then to count a defective coin for full).</div></div><div class=\"sense\"><b>Ithpalp. אִיזְרַּלְזֵל</b> <div class=\"sense\">; contr. <a href=\"#\" data-headword=\"זְלַל\">אִיזַּלְזֵל</a> <i>to be despised; to lower one’s self</i>. <span class=\"citation\">Targ. Job XL, 4</span>. <span class=\"citation\">Targ. Koh. IX, 16</span>.—<span class=\"citation\">Targ. Y. Deut. XXVIII, 16</span>.</div></div>","alt":[]},"11479":{"h":"זָלַף","r":"G00500","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">זלח</span>, <span dir=\"rtl\">דלף</span>) </div><div class=\"sense\"><b>1)</b> <i>to pour, empty over</i>. <span class=\"citation\">M. Kat. II, 1</span>, sq. <span dir=\"rtl\">זוֹלֵף וכ׳</span> he may empty the contents of the vat into the press and finish the process &amp;c. Y. ib. 81ᵃ bot. <span dir=\"rtl\">זוֹלְפִין את יינו</span> they put his grapes for him into the press. <span class=\"citation\">Toh. X, 7</span> <span dir=\"rtl\">הזוֹלֵף את הבור</span> if one empties the wine or oil pit.</div><div class=\"sense\"><b>—2)</b> <i>to sprinkle.</i> <span class=\"citation\">Par. VI, 2</span> <span dir=\"rtl\">זָלַף וכ׳</span> (R. S. <a href=\"#\" data-headword=\"זָלַף\">זִילֵּף</a>) if he used all the water for sprinkling. Ib. 3 <span dir=\"rtl\">יזלף</span> ed. (comm. <span dir=\"rtl\">זוֹלֵף</span>; <span class=\"citation\">Yoma 58ᵃ</span> <span dir=\"rtl\">זולף והולך</span>) he may sprinkle &amp;c. (Bart. a. Rashi to Yoma l. c. he may empty the water into bottles &amp;c.). Ib. VII, 8 <span dir=\"rtl\">זולף</span> (Maim.: he empties &amp;c.); a. fr.</div><div class=\"sense\"><b>Pi. זִילֵּף</b> <div class=\"sense\"><i>to drip, sprinkle.</i> <span class=\"citation\">Par. VI, 2</span>, sq., v. supra.—Y. Sabb. IX, 12ᵃ <span dir=\"rtl\">מְזַלְּפִין וכ׳</span> you may drip hot water on the wound; <span class=\"citation\">Tosef. ib. XV</span> (<span class=\"citation\">XVI), 4</span>. <span class=\"citation\">Sabb. XIX, 3</span>; a. e.</div></div><div class=\"sense\"><b>Hif. הִזְלִיף</b> <div class=\"sense\"><i>to flow, squirt</i> (neut. verb). <span class=\"citation\">Ab. Zar. 59ᵇ</span> <span dir=\"rtl\">מַזְלִיף</span> (Ms. M. <span dir=\"rtl\">מזלף</span>; <span class=\"citation\">Tosef. ib. VII</span> (<span class=\"citation\">VIII), 5</span> <span dir=\"rtl\">מנתז</span>).</div></div>","alt":[]},"11480":{"h":"זְלַף","r":"G00501","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Job XXXVI, 27</span> יִזְלְפוּן Ms. (ed. <span dir=\"rtl\">יזַלְּ׳</span> <i>Pa.</i>).—<span class=\"citation\">Y. Ab. Zar. IV, 44ᵇ</span> bot. Ib. 44ᵃ bot. <span dir=\"rtl\">וזַלְפוּן וכ׳</span> and receive the wine at his hands.—Part. <a href=\"#\" data-headword=\"זְלַף\">זָלֵיף</a>. Targ. <span class=\"citation\">Hab. II, 15</span>.</div><div class=\"sense\"><b>Pa. זַלֵּיף</b> <div class=\"sense\"><i>to squirt, drip</i>. <span class=\"citation\">Targ. Job XXIX, 6</span>.—<span class=\"citation\">Keth. 67ᵇ</span> <span dir=\"rtl\">מְזַלְּפֵי ליה וכ׳</span> they sprinkled old wine before him as a perfume, v. <span dir=\"rtl\">זלח</span>.</div></div><div class=\"sense\"><b>Ithpe. אִזְדְּלַף</b> <div class=\"sense\"><i>to flow out, to empty itself</i>. <span class=\"citation\">Targ. Job XX, 28</span>. <span class=\"citation\">Ib. XXVIII, 4</span>, v. <a href=\"#\" data-headword=\"זְלַח\">זְלַח</a>.</div></div>","alt":[]},"11481":{"h":"זֶלֶף","r":"G00502","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"זִילּוּף\">זִילּוּף</a></div>","alt":[]},"11482":{"h":"זַלְתָּא","r":"G00503","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">זלל</span>; cmp. <a href=\"#\" data-headword=\"זְלוּעַ\">זְלוּעַ</a>) <i>bucket, hod</i>. <span class=\"citation\">Yeb. 46ᵃ</span> ז׳ דטינא Ar. (ed. <a href=\"#\" data-headword=\"זולטא\">זולטא</a>, prob. corrupt. of <span dir=\"rtl\">זלועא</span>) a hod with clay. [<span class=\"citation\">Sabb. 55ᵇ</span> <a href=\"#\" data-headword=\"זַלְתָּא\">זלתא</a>, v. <a href=\"#\" data-headword=\"זוּל\">זוּל</a> I h.]</div>","alt":[]},"11483":{"h":"זְמָא","r":"G00504","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְמֵי I\">זְמֵי</a></div>","alt":[]},"11484":{"h":"זַמְבְּלִיגָא","r":"G00505","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זַבְלִיגָא\">זַבְלִיגָא</a></div>","alt":[]},"11485":{"h":"זִמָּה","r":"G00506","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זִימָּה\">זִימָּה</a></div>","alt":[]},"11486":{"h":"זְמוּם","r":"G00507","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (זָמַם II) <i>muzzle, bit</i>.—<i>Pl</i>. <span dir=\"rtl\">זְמוּמִים</span>. <span class=\"citation\">Gen. R. s. 60</span> (interpret. <span dir=\"rtl\">ויפתח</span>, <span class=\"citation\">Gen. XXIV, 32</span>) <span dir=\"rtl\">התיר זְמוּמֵיהֶם</span> he took their muzzles off; <span class=\"citation\">Yalk. Gen. 109</span> <span dir=\"rtl\">זְמָמֵיהֶן</span>, v. <a href=\"#\" data-headword=\"זְמָם II\"><span dir=\"rtl\">זְמָם</span> II</a>.</div>","alt":[]},"11487":{"h":"זִמּוּן","r":"G00508","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זִימּוּן\">זִימּוּן</a></div>","alt":[]},"11488":{"h":"זְמוֹרָא","r":"G00509","html":"<div class=\"sense\"> c. (v. P. Sm. 1138; prob. from the color of peeled vine shoots, v. <a href=\"#\" data-headword=\"זְמוֹרָה\">זְמוֹרָה</a>) <i>bluish-black</i> or <i>bluish-gray</i>.—<i>Pl</i>. f. <a href=\"#\" data-headword=\"זְמוֹרָא\">זְמוֹרָן</a>. <span class=\"citation\">Gen. R. s. 85</span> <span dir=\"rtl\">הוין עינוהי ז׳</span></div>","alt":[]},"11489":{"h":"זְמוֹרַד","r":"G00510","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אזמורד\">אזמורד</a></div>","alt":[]},"11490":{"h":"זְמוֹרָה","r":"G00511","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>vine-shoot, vine-rod</i>. <span class=\"citation\">Sabb. XVII, 6</span> <span dir=\"rtl\">ז׳ שהיא וכ׳</span> a rod which is tied to a pitcher (to let it down into the well); a. e.—Esp. <i>the rod as an officer’s badge and punishing instrument</i>. <span class=\"citation\">Num. R. s. 18</span> <span dir=\"rtl\">וליתן לו ז׳</span> and to give him the rod (appoint him an officer).—בעל הז׳ <i>carrier of the rod</i> (among the Romans <i>Centurio</i>, v. Sm. Ant. s. v.). <span class=\"citation\">Sabb. 145ᵇ</span> ובעלי ז׳ Ms. M. (ed. <span dir=\"rtl\">ובעל</span>) and Centuriones, v. <a href=\"#\" data-headword=\"הֶגְמוֹן\">הֶגְמוֹן</a>. <span class=\"citation\">Y. Sot. IX, 24ᵇ</span> top (rank of officers) <span dir=\"rtl\">בעל האגמון בעל הז׳ וכ׳</span> cane-bearer, rod-bearer, strap-bearer; <span class=\"citation\">Tosef. ib. XV, 7</span> (variously corrupted, v. Var. in ed. Zuck.). <span class=\"citation\">Midr. Till. to Ps. LXXIII</span>, end; <span class=\"citation\">Yalk. ib. 808</span>. <span class=\"citation\">Ex. R. s. 21</span>, end; a. fr.—<i>Pl</i>. <a href=\"#\" data-headword=\"זָהוֹר\">זְמוֹרוֹת</a>. <span class=\"citation\">Gen. R. s. 31</span>, end <span dir=\"rtl\">ז׳ לפילים</span> vine-rods as food for elephants; <span dir=\"rtl\">ז׳ לנטיעות</span> shoots for future plantation.</div><div class=\"sense\"><b>—2)</b> <i>membrum virile, phallus</i>. Tanḥ. Ki Thetsé 10 the Israelites did not know <span dir=\"rtl\">מה טיבה של ז׳</span> the idolatrous function of the phallus (with ref. to <span class=\"citation\">Ez. VIII, 17</span>). Ib. <span dir=\"rtl\">חיכך … את הז׳</span> Esau giggled and produced the phallus; Pesik. Zakhor, p. 27ᵇ. <span class=\"citation\">Num. R. s. 13</span>. <span class=\"citation\">Pesik. R. s. 7</span> <span dir=\"rtl\">בחירופיו … ובז׳</span> with his (Amalek’s) blasphemies and by throwing up the phallus (taken from the mutilated Israelitish bodies). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">זְמוֹרָתָם של וכ׳</span> the membra of Israelites; <span class=\"citation\">Num. R. s. 13</span> <span dir=\"rtl\">(זַכְרוּתָן</span>).</div>","alt":[]},"11491":{"h":"זְמוּרְתָּא","r":"G00512","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (זְמַר II) <i>song</i>. <span class=\"citation\">Sabb. 106ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"גְּמָרָא\">גְּמָרָא</a>.</div>","alt":[]},"11492":{"h":"זַמְזוּמֵי","r":"G00513","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (infin. of <span dir=\"rtl\">זמזם</span> <i>tinnire</i>, P. Sm. 1132, v. <a href=\"#\" data-headword=\"זָמַם I\"><span dir=\"rtl\">זָמַם</span> I</a>) <i>playing on a tingling instrument</i>. <span class=\"citation\">Erub. 104ᵃ</span> <span dir=\"rtl\">כי קלא דז׳</span> as the sound of tingling; [Ms. M. <span dir=\"rtl\">דמן מזומה</span>, Ms. Alf. <span dir=\"rtl\">כי זמומי</span>; Asheri: <span dir=\"rtl\">כמו זִימְזוּמֵי</span>; Sefer ha-Ittim <span dir=\"rtl\">כמַזְמוּטֵי</span>].</div>","alt":[]},"11493":{"h":"זְמֵי I","r":"G00514","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"זָמַם II\"><span dir=\"rtl\">זָמַם</span> II</a>) <i>to bind over, to fine</i> (cmp. <span dir=\"rtl\">אסר</span>, <a href=\"#\" data-headword=\"חוּב\">חוב</a> &amp;c.). <span class=\"citation\">Targ. Y. Deut. XXII, 19</span> (h. text <span dir=\"rtl\">ענש</span>).</div><div class=\"sense\"><b>Af. אַזְמֵי</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"זַמְזוּמֵי\">same</a>. <span class=\"citation\">Ruth R. to I, 1</span> <span dir=\"rtl\">יזמי להון</span>, read <span dir=\"rtl\">מַזְמֵי</span> he (the Roman officer) fines them; <span class=\"citation\">Yalk. Prov. 959</span> <span dir=\"rtl\">מומי להון</span> (corr. <span dir=\"rtl\">מז׳</span>); Pesik. Shek., p. 11ᵇ <span dir=\"rtl\">ומומיה ליה</span>, Ms. O. <span dir=\"rtl\">ומזמי ליה</span>; <span class=\"citation\">Yalk. Ex. 386</span> (corr. acc.).</div></div><div class=\"sense\"><b>Ithpe. אִזְדְּמֵי</b> <div class=\"sense\"><i>to be fined; to lose</i>. <span class=\"citation\">Lev. R. s. 34</span> דבני אחתיה מִזְדַּמְיָין ת&quot;ש וכ׳ Ar. (ed. <span dir=\"rtl\">מתבעין מן מלכותא</span>) that his sister’s son will be fined (or lose) seven hundred Denars. Ib. <span dir=\"rtl\">או אתון מארמאין</span> (read: <span dir=\"rtl\">מִזְדַּמָּאִין</span>, <i>Ithpa.</i>; <span class=\"citation\">Yalk. Lev. 665</span> <span dir=\"rtl\">מזדמיין</span>) or you will pay &amp;c. Ib. <span dir=\"rtl\">דילמא … דאנן מז׳</span> (Yalk. l. c. <span dir=\"rtl\">דאינון</span>, corr. acc.) didst thou know that we are destined to lose &amp;c.? Ib. <span dir=\"rtl\">דאינון מארסוון</span> (Yalk. l. c. <span dir=\"rtl\">דאתון מזדמיין</span>), v. <a href=\"#\" data-headword=\"אֲנַס\">אֲנַס</a>.</div></div>","alt":["זְמָא"]},"11494":{"h":"זְמֵי II","r":"G00515","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">זמם</span> I a. <a href=\"#\" data-headword=\"דמי\">דמי</a>) <i>to think</i>. Denom. <a href=\"#\" data-headword=\"זִימְיוֹנָא\">זִימְיוֹנָא</a>.</div>","alt":[]},"11495":{"h":"זִמְיוֹן","r":"G00516","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זִמְרָה\">זִימְ׳</a></div>","alt":["זִמְיוֹנָא"]},"11496":{"h":"זְמֵימ־","r":"G00517","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְמָם I\"><span dir=\"rtl\">זְמָם</span> I</a></div>","alt":[]},"11497":{"h":"זְמִין","r":"G00518","html":"<div class=\"sense\">, part. pass. of <a href=\"#\" data-headword=\"זְמַן I\">זְמַן</a>.</div>","alt":[]},"11498":{"h":"זְמִינָא I","r":"G00519","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זְמַן I\">זְמַן</a>) <i>invited guest</i>. <span class=\"citation\">Ned. 24ᵃ</span>.—<i>Pl</i>. <span dir=\"rtl\">זְמִינַיָּא</span>. <span class=\"citation\">Targ. I Sam. IX, 22</span> (ed. Wil. <span dir=\"rtl\">זַמְנ׳</span>, corr. acc.).</div>","alt":[]},"11499":{"h":"זְמִינָא II","r":"G00520","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Z’mina</i> (interch. with <a href=\"#\" data-headword=\"זְבִינָא I\">זְבִינָא</a>). <span class=\"citation\">Y. Bicc. III, 65ᵈ</span> top <span dir=\"rtl\">ר׳ ז׳</span>.—<span class=\"citation\">Y. Kil. IX, 32ᵈ</span> top <span dir=\"rtl\">אבא בר זבינא</span>; <span class=\"citation\">Y. Shek. V, beg. 48ᶜ</span> <a href=\"#\" data-headword=\"זִימְיוֹנָא\">זמ׳</a>; <span class=\"citation\">Sabb. 112ᵇ</span> <span dir=\"rtl\">רבא בר זימונא</span> ed. (Ms. M. <a href=\"#\" data-headword=\"זִימְנָא\">זימנא</a>); a. fr.</div>","alt":[]},"11500":{"h":"זְמִיר","r":"G00521","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זָמַר I\"><span dir=\"rtl\">זְמַר</span> I</a></div>","alt":[]},"11501":{"h":"זְמִירָא","r":"G00522","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"זִמְרָא\">זִמְרָא</a>, <i>song</i>. <span class=\"citation\">Esth. R. to III, 1</span> (<span class=\"citation\">Yalk. Esth. 1054</span> <a href=\"#\" data-headword=\"זִמְרִי\">זמרי</a>).</div>","alt":[]},"11502":{"h":"זְמִירָה I","r":"G00523","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (זָמַר I) <i>pruning the vine</i>. <span class=\"citation\">Y. Kil. VIII, 31ᶜ</span> top; <span class=\"citation\">Y. Sabb. VII, 10ᵃ</span>; a. e.</div>","alt":[]},"11503":{"h":"זְמִירָה II","r":"G00524","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , pl. <span dir=\"rtl\">זְמִירוֹת</span> <i>songs</i>. <span class=\"citation\">Cant. R. to II, 12</span>. <span class=\"citation\">Sot. 35ᵃ</span> <span dir=\"rtl\">קרא לד&quot;ת ז׳</span> he called the words of the Law songs (an entertaining secular study); v. <a href=\"#\" data-headword=\"זֶמֶר I\"><span dir=\"rtl\">זֶמֶר</span> I</a>.</div>","alt":[]},"11504":{"h":"זָמִית","r":"G00525","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">זום</span> = <span dir=\"rtl\">זהם</span>; Syr. <span dir=\"rtl\">זמיתא</span>, P. Sm. 1134) [<i>foam</i>,] name of <i>a brine</i>. <span class=\"citation\">Ber. 36ᵃ</span>; <span class=\"citation\">40ᵇ</span> (Ms. F. <span dir=\"rtl\">זו׳</span>); <span class=\"citation\">Ned. 55ᵇ</span> <span dir=\"rtl\">זו׳</span>.</div>","alt":["(זוֹמִית)"]},"11505":{"h":"זָמַם I","r":"G00526","html":"<div class=\"sense\"><i>to mumble; to meditate, plan</i> (mostly in an evil sense, cmp. <a href=\"#\" data-headword=\"דִּבָּה\">דִּבָּה</a>).—<i>Part.</i> זוֹמֵם <i>planning evil</i>, esp. (with ref. to <span class=\"citation\">Deut. XIX, 19</span>) a) <i>giving false testimony, amenable to the law of retaliation;</i> b) <i>rebutting witness</i>. <span class=\"citation\">Tosef. Macc. I, 1</span> <span dir=\"rtl\">עד ז׳</span> a witness convicted of false testimony; a. fr.—<i>Fem.</i> <span dir=\"rtl\">זוֹמֶמֶת</span> (sub. <a href=\"#\" data-headword=\"עֵדוּת\">עדות</a>). <span class=\"citation\">Macc. I, 9</span> <span dir=\"rtl\">נמצאת אחת מהן ז׳</span> if one evidence (of one set of witnesses) has been disproved; a. e.—Pl. <span dir=\"rtl\">זוֹמְמִין</span>, <span dir=\"rtl\">זוֹמְמִים</span>. <span class=\"citation\">Ib. 4</span> <span dir=\"rtl\">אין אלו ז׳</span> they do not come under the law of retaliation. Ib. <span dir=\"rtl\">נעשים ז׳</span> are declared amenable to the law &amp;c.; a. fr.—Tosef. ib. I, 10 <span dir=\"rtl\">זוֹמְמֵיהֶן</span> those witnesses on whose evidence they had been declared guilty of false testimony. Y. ib. I, beg. 31ᵃ <span dir=\"rtl\">זוֹמְמָיו</span> those who witnessed falsely against him. <span class=\"citation\">Tosef. Snh. VIII, 2</span> <span dir=\"rtl\">העדים וזוממיהן וזוֹמְמֵי זוממיהן</span> the original witnesses and their refuters, and the refuters of their refuters; a. fr.</div><div class=\"sense\"><b>Hif. הֵזֵים</b> <div class=\"sense\"><i>to make a person a</i> <span dir=\"rtl\">זוֹמֵם</span>, <i>to refute witnesses by testifying to an alibi, to rebut</i>. <span class=\"citation\">Macc. I, 5</span> if other witnesses came again <span dir=\"rtl\">והֵזֵימּוּם</span> and rebutted them. <span class=\"citation\">Keth. 20ᵃ</span>, v. <a href=\"#\" data-headword=\"כָּחַשׁ\">כָּחַשׁ</a>; a. fr. <span class=\"citation\">Macc. I, 4</span> (<span class=\"citation\">5ᵃ</span>) <span dir=\"rtl\">שיזימו</span> Bab. ed., read <span dir=\"rtl\">שיזומו</span>, v. infra.</div></div><div class=\"sense\"><b>Hof. הוּזַם</b> </div><div class=\"sense\"><b>Nif. נִיזּוֹם</b> <div class=\"sense\"><i>to be refuted, to be declared liable to the law of retaliation</i>. <span class=\"citation\">Snh. 10ᵃ</span> <span dir=\"rtl\">פלוני … והוּזַמּוּ</span> if witnesses declared, This man did &amp;c., and were declared guilty &amp;c. <span class=\"citation\">Macc. 3ᵃ</span> <span dir=\"rtl\">הוּזַמְּנוּ וכ׳</span> we have been convicted &amp;c. before that certain court, and made to pay. <span class=\"citation\">Ib. I, 4</span> <span dir=\"rtl\">עד שיִזּוֹמּוּ את עצמן</span> (Ar. <span dir=\"rtl\">בעצמן</span>, Bab. ed. <span dir=\"rtl\">שיזימו</span> corr. acc.) unless an alibi is established against their own persons (not an alibi of any of the alleged actors in the case). Ib. 5ᵇ <span dir=\"rtl\">עד שיזומו שניהם</span> unless both of them are refuted; a. fr.</div></div><div class=\"sense\"><b>Pi. זִמֵּם</b> <div class=\"sense\"><i>to rebut</i>. Part. <span dir=\"rtl\">מְזַמֵּם</span>, pl. <span dir=\"rtl\">מְזַמְּמִין</span>, contr. <span dir=\"rtl\">מְזַמִּים</span>. Y. ib. I, 31ᵇ top.—<i>Part. pass</i>. <span dir=\"rtl\">מְזוּמָּם</span> <i>one accused by false witnesses</i>. <span class=\"citation\">Snh. VI, 2</span> <span dir=\"rtl\">אם היה יודע שהוא מ׳</span> if he knew that he was innocent.</div></div><div class=\"sense\"><b>Nithpa. נִזְדַּמֵּם</b> <div class=\"sense\"><b>1)</b> <i>to be refuted</i> &amp;c., v. <i>Hof</i>. Y. Macc. I, beg. 31ᵃ <span dir=\"rtl\">נִזְדַּמְּמוּ</span> = <span dir=\"rtl\">נִיזוֹמּוּ</span>.</div><div class=\"sense\"><b>—2)</b> <i>to be mumbled</i>. <span class=\"citation\">Gen. R. s. 81</span>, beg. (ref. to <span dir=\"rtl\">זמות</span>, <span class=\"citation\">Prov. XXX, 32</span>) <span dir=\"rtl\">אם נִזְדַּמְּמוּ אחריך דברים וכ׳</span> (<span class=\"citation\">Yalk. Prov. 964</span> נִזְמְמוּ <i>Nif.</i>) if thou hast been slandered, put thy hand to thy mouth; v. <a href=\"#\" data-headword=\"זָמַם II\"><span dir=\"rtl\">זָמַם</span> II</a>.—Denom. <a href=\"#\" data-headword=\"זְמָם I\"><span dir=\"rtl\">זְמָם</span> I</a>.</div></div>","alt":[]},"11506":{"h":"זְמַם I","r":"G00527","html":"<div class=\"sense\"><b>Af. אַזֵּים</b> <div class=\"sense\"> = <a href=\"#\" data-headword=\"זָמַם I\">preced.</a> <i>Hif.</i> <span class=\"citation\">Targ. Y. Deut. XIX, 18</span> <span dir=\"rtl\">דמַזְמִין</span> who rebut.—<span class=\"citation\">B. Kam. 73ᵇ</span> bot. <span dir=\"rtl\">דאפכינהו ואַזְמִינְהוּ</span> they reversed their statement of the case and also testified to an alibi as to time and place.</div></div><div class=\"sense\"><b>Ithpa. אִיתַּזֵּים  אִיתַּזַּם</b> <div class=\"sense\"><i>to be proven a false witness</i>. Ib. 73ᵃ <span dir=\"rtl\">כי מִתַּזְּמֵי אטביחה</span> when they were proven false witnesses with reference to slaughtering; <span dir=\"rtl\">ואִיתַּזְּמוּ להו אגניבה</span> and they are considered as false witnesses also with reference to stealing. Ib. <span dir=\"rtl\">אטביחה דקא מִיתַּזְּמֵי אִיתַּזּוּם</span> as regards the testimony to slaughtering on which they were refuted, they are refuted; a. e.—<i>Ithpe.</i> <span dir=\"rtl\">אִתְּזוֹם</span>. <span class=\"citation\">Macc. 3ᵇ</span> <span dir=\"rtl\">א׳ חד מינייהו</span> against one of them an alibi was proven.</div></div>","alt":[]},"11507":{"h":"זָמַם II","r":"G00528","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"צָמַם\">צמם</a>) <i>to tie up, to muzzle</i> (b. h. <a href=\"#\" data-headword=\"חָסַם I\">חָסַם</a>). <span class=\"citation\">Ber. 63ᵇ</span> (ref. to <span dir=\"rtl\">זמות</span>, <span class=\"citation\">Prov. XXX, 32</span>, v. <a href=\"#\" data-headword=\"זְמַם I\">preced. w.</a>) <span dir=\"rtl\">אם ז׳ וכ׳</span> if he muzzles his mouth (is ashamed to ask his teacher), he will have to put his hand to the mouth (when he in turn is asked). <span class=\"citation\">Ter. IX, 3</span> <span dir=\"rtl\">לא זוֹמֵם</span> he does not muzzle his animal (complies with the law, <span class=\"citation\">Deut. XXV, 4</span>); a. e.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"זְמוּם\">זָמוּם</a>, f. <span dir=\"rtl\">זְמוּמָה</span>; pl. <span dir=\"rtl\">זְמוּמִים</span>, <span dir=\"rtl\">זְמוּמוֹת</span> <i>muzzled, prevented from grazing</i>. <span class=\"citation\">Gen. R. s. 41</span>. <span class=\"citation\">Pesik. R. s. 3</span>. <span class=\"citation\">Gen. R. s. 59</span>, end; a. e.—Denom. <a href=\"#\" data-headword=\"זְמָם II\"><span dir=\"rtl\">זְמָם</span> II</a>.</div>","alt":[]},"11508":{"h":"זְמַם","r":"G00529","html":"<div class=\"sense\">, <i>tomuzzle</i>. <span class=\"citation\">Targ. Y. II, Gen. XIII, 7</span>.</div><div class=\"sense\"><b>Pa. זַמֵּים</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"זָמַם II\">same</a>. <span class=\"citation\">Targ. Y. Deut. XXV, 4</span>.</div></div>","alt":[]},"11509":{"h":"זָמַם III","r":"G00530","html":"<div class=\"sense\"><i>to be filthy</i>, v. <a href=\"#\" data-headword=\"*זוּם\">זוּם</a>.</div>","alt":[]},"11510":{"h":"*זְמַם III","r":"G00531","html":"<div class=\"sense\">, <i>Ithpe.</i> <span dir=\"rtl\">אִתְזְמֵים</span> (cmp. <a href=\"#\" data-headword=\"דָּמַם\">דמם</a>) <i>to be confounded</i>. <span class=\"citation\">Targ. Is. XXIX, 9</span> <span dir=\"rtl\">אִתְזְמִימוּ</span> (ed. Wil. <span dir=\"rtl\">אִדְזַמִימוּ</span> fr. <a href=\"#\" data-headword=\"דָּמַם\">דמם</a>; absent in ed. Lag.; h. text <span dir=\"rtl\">השתעשעו</span>, rendered by <span dir=\"rtl\">אשתגישו</span> a. our w., of which one is a gloss). [For <span dir=\"rtl\">אדז׳</span> cmp. <span dir=\"rtl\">הִדַּקִּי</span> s. v. <a href=\"#\" data-headword=\"דְּקַק\">דְּקַק</a>.]</div>","alt":[]},"11511":{"h":"זְמָם I","r":"G00532","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (זָמַם I) <i>false testimony</i>. <span class=\"citation\">Macc. 2ᵇ</span> בגניבתו ולא בזְמָמוֹ ‘one is sold for theft’ (<span class=\"citation\">Ex. XXII, 2</span>), but not for false testimony (which might eventually have caused the sale of the alleged thief); Y. Sot. III, end, 19ᵇ; <span class=\"citation\">Tosef. Macc. I, 1</span> <span dir=\"rtl\">בזְמֵימוֹ</span>.</div>","alt":["זָמֵם"]},"11512":{"h":"חֲמִיטָא","r":"H01175","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַמִּיתָא\">אַמִּיתָא</a></div>","alt":[]},"11513":{"h":"חֲמִיטָה","r":"H01176","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (חמט II, cmp. <a href=\"#\" data-headword=\"*חוּבְטָא\">חוּבְטָא</a>, <a href=\"#\" data-headword=\"חָבִיץ\">חָבִיץ</a>) <i>a batter of which flat cakes are made, batter-cake</i>. <span class=\"citation\">T’bul Yom I, 1</span>. <span class=\"citation\">Ib. II, 4</span>; <span class=\"citation\">Tosef. ib. II, 2</span> (ed. Zuck. <a href=\"#\" data-headword=\"חמיתה\">חמיתה</a>, corr. acc.). <span class=\"citation\">Maasr. I, 7</span> <span dir=\"rtl\">נותן לחמי׳</span> ed. Y. a. Ms. M. (Bab. ed. a. Mish. <span dir=\"rtl\">לחֲמָטָה</span>) he may put (the oil) on the cake (Maim.: into the <i>pan</i>); Tosef. ib. I, 7; 9 <span dir=\"rtl\">נותן להם מיטה</span> ed. Zuck. (Var. <span dir=\"rtl\">לחמיתה</span>, carr. acc.)—Pl. <span dir=\"rtl\">חֲמִיטוֹת</span>. Y. Ter. X, 47ᵃ bot. <span dir=\"rtl\">חמטתינו</span> (read: <span dir=\"rtl\">חֲמִיטוֹתֵינוּ</span> or <a href=\"#\" data-headword=\"חֵימָרָא\">חֲמָ׳</a>).</div>","alt":[]},"11514":{"h":"חמיטליא","r":"H01177","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הֵמְטַלְיָא\">הֵמְטַלְיָא</a></div>","alt":[]},"11515":{"h":"חֲמִילָה","r":"H01178","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָמַל\">חמל</a>; cmp. Syr. <a href=\"#\" data-headword=\"חָמַל\">חמל</a>, P. Sm. 1303, sq.) <i>a blanket of thick, coarse stuff</i>. <span class=\"citation\">Ned. VII, 3</span>. <span class=\"citation\">Ib. 55ᵇ</span>; <span class=\"citation\">Tosef. Sabb. V</span> (<span class=\"citation\">VI), 14</span> <a href=\"#\" data-headword=\"מָלֵא I\">מילא</a> ed. Zuck. (Var. <span dir=\"rtl\">המלא</span>, <a href=\"#\" data-headword=\"חמלא\">חמלא</a>).—Pl. <span dir=\"rtl\">חֲמִילוֹת</span>. <span class=\"citation\">Tosef. Kel. B. Bath. V, 11</span>. <span class=\"citation\">Tosef. Neg. V, 14</span> <a href=\"#\" data-headword=\"חמולות\">חמולות</a> (corr. acc.).</div>","alt":[]},"11516":{"h":"חַמִּים","r":"H01179","html":"<div class=\"sense\"> c. = h. <a href=\"#\" data-headword=\"חָם II\"><span dir=\"rtl\">חָם</span> II</a>, <i>warm, hot, fresh</i>. <span class=\"citation\">Targ. I Sam. XXI, 7</span>; a. e.—<span class=\"citation\">Y. Shebi. IV, 35ᵃ</span> bot., a. e. <span dir=\"rtl\">פיתא ח׳</span> fresh bread. <span class=\"citation\">Erub. 3ᵃ</span>; <span class=\"citation\">B. Bath. 24ᵇ</span> (prov.) <span dir=\"rtl\">קדרא … לא ח׳ וכ׳</span> a pot belonging to two partners is neither warm nor cold. <span class=\"citation\">Ḥull. 6ᵇ</span> <span dir=\"rtl\">בר … ליכול ח׳</span> let the scholar eat fresh food, and I shall be contented with cold; a. fr.—Pl. <span dir=\"rtl\">חַמִּימִין</span>, <span dir=\"rtl\">חַמִּימֵי</span> <i>hot water</i> (v. <a href=\"#\" data-headword=\"חָם II\"><span dir=\"rtl\">חָם</span> II</a>). <span class=\"citation\">Y. Ab. Zar. IV, 44ᵇ</span> bot. <span dir=\"rtl\">חמר וח׳</span> wine mixed with hot water. <span class=\"citation\">Ḥull. 46ᵇ</span>.—<span class=\"citation\">Sabb. 55ᵃ</span> <span dir=\"rtl\">רישך בקרירי … בח׳</span> thy chief (I) shall be punished with cold water, but thy chief’s chief (the Resh Galutha) with boiling water (he is reponsible); a. e.</div>","alt":["חַמִּימָא"]},"11517":{"h":"חַמִּימוּתָא","r":"H01180","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חַמִּים\">preced.</a>) <i>heat, heated state</i>. <span class=\"citation\">Pes. 76ᵃ</span> <span dir=\"rtl\">מחמת ח׳ דחרס</span> through the heat of the earthen vessel.</div>","alt":[]},"11518":{"h":"חֲמִימָתָא","r":"H01181","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (cmp. Arab. <i>ḥamâm</i>) [<i>dark-colored</i>] <i>a species of doves, ring-doves</i> (?). <span class=\"citation\">Gitt. 69ᵇ</span> (oth. opin. <i>hens</i>).</div>","alt":[]},"11519":{"h":"חַמִּין","r":"H01182","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"חַמִּים\">חַמִּים</a>. <span class=\"citation\">Y. Ber. IV, 7ᵇ</span> top <span dir=\"rtl\">שמשא ח׳</span> it is warm in the sun, <span dir=\"rtl\">טולא ח׳</span> in the shade. [<span class=\"citation\">Midr. Till. to Ps. XXIV</span> <span dir=\"rtl\">ימא דח׳</span>, v. <a href=\"#\" data-headword=\"חֲמָץ\">חֲמָץ</a>.] [<a href=\"#\" data-headword=\"ח׳\">ח׳</a>, pl. of <a href=\"#\" data-headword=\"חָם II\"><span dir=\"rtl\">חָם</span> II</a>.]</div>","alt":[]},"11520":{"h":"*חֲמִיסִין","r":"H01183","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>those using such words as ḥamis</i> (ἥμισυ, cmp. <span dir=\"rtl\">חומס</span>), a mockery on Talmudic scholars using foreign words. <span class=\"citation\">Snh. 14ᵃ</span> כל מן דין … לא מסרמיסין ולא מסרמיטין מח׳ וכ׳ Ms. F. a. Ag. Hatt. (v. Rabb. D. S. a. l. note 7; ed. <span dir=\"rtl\">ואמרי לה לא מח׳</span>) such men (as R. Ammi &amp;c.) appoint for us, but do not appoint for us any of those using such words like <i>sermis</i> (semis, ἥμισυ) <i>sermit</i> (prob. distortion of tremis), <i>hemis</i> or <i>tremis</i> (cmp. Y. Gitt. IV, 47ᵇ quot. s. v. <a href=\"#\" data-headword=\"גּוֹרְדְּיָינִי\">גּוֹרְדְּיָינִי</a>). [Oth. opin. v. Rashi, a. Ar. s. v.]</div>","alt":[]},"11521":{"h":"חֲמֵיסַר","r":"H01184","html":"<div class=\"sense\"> (= <span dir=\"rtl\">חמיש עסר</span>) <i>fifteen; the fifteenth</i>. <span class=\"citation\">Targ. Y. Lev. XXIII, 6</span>. <span class=\"citation\">Ib. XII, 4</span>; a. e.—<span class=\"citation\">Meg. 5ᵇ</span> <a href=\"#\" data-headword=\"חִירְיָא\">בר ח׳</a> one observing Purim on the fifteenth of Ădar; a. e.</div>","alt":[]},"11522":{"h":"חֲמֵיסְרָאָה","r":"H01185","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲמֵיסַר\">preced.</a>) <i>the fifteenth</i>. <span class=\"citation\">Targ. I Chr. XXIV, 14</span>.</div>","alt":[]},"11523":{"h":"חֲמִיעַ","r":"H01186","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲמַע I\">חמע</a>) </div><div class=\"sense\"><b>1)</b> <i>sour</i>. <span class=\"citation\">Lam. R. to III, 40</span>, v. <a href=\"#\" data-headword=\"בְּסִימָא\">בְּסִימָא</a>.</div><div class=\"sense\"><b>—2)</b>  (Targ. Y. <a href=\"#\" data-headword=\"חֲמִיעַ\">חָמִיעַ</a>) = h. <a href=\"#\" data-headword=\"חָמֵץ I\">חָמֵץ</a>, <i>leavened</i> (<i>bread</i>). <span class=\"citation\">Targ. Ex. XII., 15</span>; a. fr.—Y. Snh. III, 21ᵇ <span dir=\"rtl\">הורו מיפי ח׳ וכ׳</span> they permitted to bake leavened bread on Passover (for the troops).</div>","alt":["חֲמִיעָא"]},"11524":{"h":"חֲמֵיץ","r":"H01187","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲמַץ\">חֲמַץ</a></div>","alt":[]},"11525":{"h":"חֲמֵיצ־","r":"H01188","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חָמֵץ I\">חָמֵץ</a></div>","alt":[]},"11526":{"h":"חֲמִיר I","r":"H01189","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"חָמוּר\">חָמוּר</a> </div><div class=\"sense\"><b>1)</b> <i>loaded</i>. <span class=\"citation\">Targ. Y. Gen. XLIX, 14</span> <span dir=\"rtl\">ח׳ באורייתא</span> loaded with the (knowledge of the) Law.</div><div class=\"sense\"><b>—2)</b> <i>grave, strict, stringent</i>. <span class=\"citation\">Targ. Y. Num. XIV, 30</span>.—<span class=\"citation\">Ḥull. 10ᵃ</span> <span dir=\"rtl\">ח׳ סכנתא וכ׳</span> regulations concerning health and life are made more stringent than ritual laws; a. fr.—Pl. f. <a href=\"#\" data-headword=\"חֲמִימָתָא\">חֲמִירָתָא</a> <i>restrictions, strict measures</i>. <span class=\"citation\">Y. Ab. Zar. II, 41ᵈ</span> bot. <span dir=\"rtl\">מן ח׳ דרב</span> one of Rab’s strict regulations.</div>","alt":["חֲמִירָא"]},"11527":{"h":"חֲמִיר II","r":"H01190","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (חֲמַר II) <i>strong leaven</i>(h. ; <i>leavened bread</i>. <span class=\"citation\">Targ. Ex. XII, 15</span>; a. fr.—<span class=\"citation\">Pes. 5ᵇ</span>, v. <a href=\"#\" data-headword=\"בְּעַר I\">בְּעַר</a>.—<span class=\"citation\">Ab. Zar. 66ᵃ</span> <span dir=\"rtl\">ח׳ דשערי</span> leaven of barley flour. <span class=\"citation\">Men. 43ᵃ</span>, v. <a href=\"#\" data-headword=\"*אַרְכְּסָא\">אַרְכְּסָא</a>; a. fr.</div>","alt":["(חָמִיר)","חֲמִירָא"]},"11528":{"h":"חֲמֵישׁ","r":"H01191","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲמֵשׁ\">חֲמֵשׁ</a></div>","alt":[]},"11529":{"h":"חֲמִישָׁאָה","r":"H01192","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲמִישַׁי\">חֲמִישַׁי</a></div>","alt":["חֲמִישַׁאי"]},"11530":{"h":"חֲמִישִׁי","r":"H01193","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>fifth;</i> (sub. <a href=\"#\" data-headword=\"יוֹם\">יום</a>) <i>the fifth day of the week</i>. <span class=\"citation\">Meg. I, 2</span>, sq.; a. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"חֲמִישִׁי\">חֲמִישִׁית</a>. <span class=\"citation\">Ib. III, 4</span> <span dir=\"rtl\">בח׳</span> on the fifth Sabbath; a. fr.—Esp. (<span class=\"citation\">Lev. V, 24</span>) <i>the penalty of the fifth part</i> added to the indemnity. <span class=\"citation\">B. Kam. 65ᵇ</span>.—Pl. <span dir=\"rtl\">חֲמִישִׁיּוֹת</span>. <span class=\"citation\">Ib.</span> (ref. to <span dir=\"rtl\">חֲמִשִׁתָיו</span>, Lev. l. c.) <span dir=\"rtl\">ח׳ הרבה וכ׳</span> (ed. <a href=\"#\" data-headword=\"חֲמִשִׁי\">חֲמִשִׁ׳</a>) repeated penalties connected with one object of indemnity.</div>","alt":[]},"11531":{"h":"חֲמִישַׁי","r":"H01194","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. I, 23</span> (ed. Amst. <span dir=\"rtl\">שָׁאִי …</span>); a. fr.—<i>Fem.</i> <span dir=\"rtl\">חֲמִישֵׁיתָא</span>, <span dir=\"rtl\">שִׁיתָא …</span> <span class=\"citation\">Targ. Lev. XIX, 25</span>.—<span class=\"citation\">Pesik. R. s. 23</span> (ed. Fr. p. 115ᵇ) <a href=\"#\" data-headword=\"חַמְשִׁיתָא\">חֲמִישְׁתָּא</a>; <span class=\"citation\">ib.</span> (p. 120ᵃ) <a href=\"#\" data-headword=\"חַמְשִׁיתָא\">חמשיתא</a> (corr. acc.) the fifth day of the week.—V. <a href=\"#\" data-headword=\"חַמְשִׁיתָא\">חֲמְשִׁיתָא</a>.</div>","alt":["שַׁאי","שָׁאָה"]},"11532":{"h":"חַמִּיתָא","r":"H01195","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַמִּיתָא\">אַמִּיתָא</a></div>","alt":["תָה"]},"11533":{"h":"חמיתה","r":"H01196","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲמִיטָה\">חֲמִיטָה</a></div>","alt":[]},"11534":{"h":"חָמַל","r":"H01197","html":"<div class=\"sense\"> (b. h.) [<i>to be warm</i>,] <i>to have compassion</i>. <span class=\"citation\">Men. 53ᵇ</span> (play on <span dir=\"rtl\">המולה</span>, <span class=\"citation\">Jer. XI, 16</span>) <span dir=\"rtl\">חָמַלְתִּי עליהם</span> I had mercy on them.</div>","alt":[]},"11535":{"h":"חמלא","r":"H01198","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲמִילָה\">חֲמִילָה</a></div>","alt":[]},"11536":{"h":"חֲמַלְתָּא","r":"H01199","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הִימַלְתָּא\">הִימַלְתָּא</a></div>","alt":[]},"11537":{"h":"חֲמָם","r":"H01200","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"חָמַם\">next w.</a>; cmp. ἄμωμον, v. Sm. Ant. s. v.) <i>amomum</i>, an Indian (also Syriac) spice. <span class=\"citation\">Ukts. III, 5</span> (some ed. incorr. <a href=\"#\" data-headword=\"חמס\">חמס</a>); <span class=\"citation\">Nidd. 51ᵇ</span> <a href=\"#\" data-headword=\"חימות\">חימות</a> (corr. acc.); <span class=\"citation\">Sifré Deut. 107</span> <span dir=\"rtl\">חימום</span>; Y. Erub. IX, end, 25ᵈ <a href=\"#\" data-headword=\"חכם\">חכם</a> (corr. acc.); <span class=\"citation\">Y. Ḥag. III, 79ᶜ</span> <span dir=\"rtl\">חמה</span> (corr. acc.).—<span class=\"citation\">Gen. R. s. 45</span>, beg. <span dir=\"rtl\">הִ׳ היא צריכה</span> (<a href=\"#\" data-headword=\"הימוס\">הימוס</a>, corr. acc.) she needs amomum (as medicine for sterility). Cmp. <a href=\"#\" data-headword=\"הִימַלְתָּא\">הִימַלְתָּא</a>, <a href=\"#\" data-headword=\"אַמִּיתָא\">אַמִּיתָא</a>.</div>","alt":["(חִימּוּם)"]},"11538":{"h":"חָמַם","r":"H01201","html":"<div class=\"sense\"> (b. h.) <i>to be warm, hot;</i> [(of color) <i>to be dark, red</i>; (of taste) <i>to be pungent, sour, bitter</i>]. <i>Part.</i> <a href=\"#\" data-headword=\"חָם I\">חָם</a>, q. v.</div><div class=\"sense\"><b>Pi. חִמֵּם</b> <div class=\"sense\"><i>to heat, warm, boil</i>. Y. Ned. IV, 38ᶜ bot. <span dir=\"rtl\">לחַמֵּם בו את ידיו</span> to warm his hands against it (the bread). <span class=\"citation\">Gen. R. s. 14</span>, end <span dir=\"rtl\">מְחַמֶּמֶת הגוף</span> keeps the body warm. <span class=\"citation\">Sabb. 40ᵇ</span> <span dir=\"rtl\">ומְחַמַּמְתָּהּ וכ׳</span> and warms it (her hand) before the fire; a. fr.</div></div><div class=\"sense\"><b>Hif. הֵיחֵם</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חֲמָם\">same</a>. <span class=\"citation\">Bets. II, 5</span> <span dir=\"rtl\">לא יֵחֵם וכ׳</span> one must not prepare warm water for &amp;c. <span class=\"citation\">Sabb. 40ᵃ</span> <span dir=\"rtl\">התחילו … להָחֵם בשבת</span> the bathers began to heat (the water) on the Sabbath; a. fr.—Part. <a href=\"#\" data-headword=\"מֵיחַם\">מֵיחֵם</a>, <a href=\"#\" data-headword=\"מֵחַם\">מֵחֵם</a>, pl. <span dir=\"rtl\">מְחַמִּין</span>. Ib.ᵇ; Tosef. ib. III (IV), 7 <span dir=\"rtl\">מיחם אדם וכ׳</span> (ed. Zuck. <span dir=\"rtl\">מייחם</span>, read: <span dir=\"rtl\">מֵיחֵים</span>), v. <a href=\"#\" data-headword=\"אֲלוּנְטִית I\"><span dir=\"rtl\">אְלוּנְטִית</span> I</a>; [Y. ib. XIX, 17ᵃ bot. <span dir=\"rtl\">מחמין הוא אדם</span> (read as ib. IX, 12ᵃ bot. <span dir=\"rtl\">מְחַמֵּם הוא וכ׳</span>].—Ib. <span dir=\"rtl\">אם מפני הסכנה מְחַמִּין לו וכ׳</span> if it is for the sake of averting danger to life, may we not even boil water on the Sabbath?—<span class=\"citation\">Bets. 22ᵃ</span>; a. v. fr.</div></div><div class=\"sense\"><b>Nif. נָחַם  נֵחוֹם</b> <div class=\"sense\"><i>to be warmed</i>. <span class=\"citation\">Sabb. III, 5</span> (<span class=\"citation\">41ᵃ</span>) <span dir=\"rtl\">בשביל שיֵחַמּוּ</span> that they become warm; <span class=\"citation\">Sabb. 41ᵇ</span> <span dir=\"rtl\">שיֵחוֹמּוּ</span>; <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">IV), 5</span> <span dir=\"rtl\">שׁיֵיחַמּוּ</span>; a. e.</div></div><div class=\"sense\"><b>Hof. הוּחָם</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"חֲמָם\">same</a>. <span class=\"citation\">Sabb. 134ᵇ</span> <span dir=\"rtl\">שהוּחַמּוּ</span>, v. <a href=\"#\" data-headword=\"חָם II\"><span dir=\"rtl\">חָם</span> II</a>. Y. Bets. II, 61ᶜ; a. fr.—<span class=\"citation\">B. Mets. VI, 3</span> <span dir=\"rtl\">הוּחַמָּה</span> the animal was overtaken by the heat.</div></div><div class=\"sense\"><b>Hithpa. הִתְחַמֵּם</b> </div><div class=\"sense\"><b>Nithpa. נִתְחַמֵּם</b> <div class=\"sense\"><i>to warm one’s self; to become heated</i>. <span class=\"citation\">Bets. II, 5</span>; Tosef. Sabb. l. c. <span class=\"citation\">Tam. I, 1</span>. <span class=\"citation\">Ab. II, 10</span> <span dir=\"rtl\">הוי מִתְחַמֵּם וכ׳</span> warm thyself by the fire of the scholars (try to associate with them); a. fr.—Y. Sot. I, 16ᶜ bot. <a href=\"#\" data-headword=\"חטי\">נתח׳</a> was heated (had pollution). <span class=\"citation\">Gen. R. s. 24</span> <span dir=\"rtl\">מִתְחַמְּמִים</span>, <span dir=\"rtl\">מִתְחַמְּמוֹת</span> <i>conceived</i></div></div>","alt":[]},"11539":{"h":"חֲמַם","r":"H01202","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Gen. XVIII, 1</span>; a. e.; v. <a href=\"#\" data-headword=\"חוּם\">חוּם</a></div><div class=\"sense\"><b>Pa. חַמֵּים</b> <div class=\"sense\"><i>to warm, heat</i>.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"מְחַמַּר\">מְחַמַּם</a>. <span class=\"citation\">Targ. Hos. VII, 7</span>.</div></div><div class=\"sense\"><b>Af. אַחֵים</b> <div class=\"sense\"><i>to heat, excite</i>, v. <a href=\"#\" data-headword=\"חוּם\">חוּם</a>.—2) <a href=\"#\" data-headword=\"אַחְמַר\">אַחְמַם</a> <i>to become hot; to have pollution</i>. <span class=\"citation\">Nidd. 43ᵃ</span> <span dir=\"rtl\">כל אחְמוּמֵי והדר א׳ וכ׳</span> getting heated once and again immediately after.</div></div><div class=\"sense\"><b>Ithpa. אִתְחַמֵּם</b> </div><div class=\"sense\"><b>Ithpe. אִיחֲמַם</b> <div class=\"sense\"><b>1)</b> <i>to warm one’s self</i>. <span class=\"citation\">Targ. Y. II, Gen. XVIII, 1</span>.—<span class=\"citation\">Sabb. 110ᵇ</span> <span dir=\"rtl\">כד איח׳</span> ed. (Ms. M. <a href=\"#\" data-headword=\"חֲרַק\">אַחְ׳</a>, v. supra) when he had warmed himself.—* </div><div class=\"sense\"><b>2)</b> <i>to restrain one’s anger</i>. Targ. II Esth. V, 10 [prob. to be read: <span dir=\"rtl\">ואִתְחַמַּס</span>, v. <a href=\"#\" data-headword=\"חֲמַס\">חֲמַס</a>; cmp. <a href=\"#\" data-headword=\"חֲסַן I\">חֲסַן</a>].</div></div>","alt":[]},"11540":{"h":"חַמָּן","r":"H01203","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"חַמָּה\">חַמָּה</a>) <i>solar columns</i>, [prob. <i>a phallus</i>, cmp. <a href=\"#\" data-headword=\"חֲנִיסְנְסַיָּא\">חֲנִיסְנְסַיָּא</a>]. Sifra B’har ch. IX, end (ref. to <span dir=\"rtl\">לא תקימו</span>, <span class=\"citation\">Lev. XXVI, 1</span>) <span dir=\"rtl\">אלו הח׳ וכ׳</span> that means the <i>ḥammanim</i> on roof-tops. Mekh. Bo, s. 11 (ref. to <span class=\"citation\">Ex. XII, 2</span> <span dir=\"rtl\">משכי מחַמָּנֵיכֶם</span> withdraw from your ḥ. Ib. Yithro, s. 5, end <span dir=\"rtl\">לח׳</span>. <span class=\"citation\">Ib. s. 6</span> <span dir=\"rtl\">מן הח׳</span> (ed. Weiss a. Fr. everywhere <span dir=\"rtl\">ע&quot;ז</span>).</div>","alt":["חַמָּנִים"]},"11541":{"h":"חמס","r":"H01204","html":"<div class=\"sense\">, <span class=\"citation\">Ukts. III, 5</span>, v. <a href=\"#\" data-headword=\"חֲמָם\">חֲמָם</a></div>","alt":[]},"11542":{"h":"חָמַס","r":"H01205","html":"<div class=\"sense\"> v. Ges. H. Dict.<sup>10</sup> s. v.) [<i>to be heated, passionate</i>,] <i>to insult, do violence, to rob</i>. <span class=\"citation\">Y. Ab. Zar. II, 40ᵈ</span> bot. <span dir=\"rtl\">לא סוף … אלא חֲמוֹס וכ׳</span> finally one does not say to another man, Kill that man, but, Attack &amp;c. <span class=\"citation\">Gen. R. s. 45</span> (ref. to <span dir=\"rtl\">חמסי</span>, <span class=\"citation\">ib. XVI, 5</span>) <span dir=\"rtl\">חוֹמְסֵנִי את בדברים וכ׳</span> thou provokest me to speak harshly, because thou seest &amp;c. <span class=\"citation\">Gen. R. s. 65</span>, beg. <span dir=\"rtl\">מלכות … גוזלת וחוֹמֶסֶת</span> the wicked government (Rome) robs and extorts; a. fr.—<span class=\"citation\">Lev. R. s. 26</span> <span dir=\"rtl\">דור ודור וחוֹמְסָיו</span> each generation with its violent men.—Part. pass. <span dir=\"rtl\">חָמוּס</span>. Ib. s. 30 גזול אני ח׳ אני I have been taken by force, by extortion.</div><div class=\"sense\"><b>Nif. נֶחְמַס</b> <div class=\"sense\"><i>to be ruined</i> (cmp. <a href=\"#\" data-headword=\"חָבַל\">חָבַל</a>). <span class=\"citation\">Lam. R. to II, 6</span> <span dir=\"rtl\">כגנה שנ׳ מעיינה וכ׳</span> like a garden the spring of which has been ruined, so that its vegetables fade.</div></div><div class=\"sense\"><b>Pi. חִימֵּס</b> <div class=\"sense\"> (of beasts of prey) <i>to seize with fangs, scratch with nails</i>. <span class=\"citation\">Gen. R. s. 45</span> (play on <span dir=\"rtl\">חמסי</span>, v. supra) <span dir=\"rtl\">חִימְּסָה פניו</span> Ar. (ed. <span dir=\"rtl\">בפניו</span>, some ed. <a href=\"#\" data-headword=\"חימסא\">חימסא</a>, incorr.) she scratched his face; Y’lamd. to Gen. l. c. (quot. in Ar.) <span dir=\"rtl\">חיטטה אותו וחימסה פניו כנמיה</span> she scratched him and marked his face like a marten; Yalk. ib. 79 (not <span dir=\"rtl\">חומסה</span>).</div></div>","alt":[]},"11543":{"h":"חֲמַס","r":"H01206","html":"<div class=\"sense\">—Denom. <a href=\"#\" data-headword=\"חוֹמָסָא\">חומָסָא</a>.</div><div class=\"sense\"><b>*. אִתְחַמֵּס</b> <div class=\"sense\"><i>to do violence to one’s self, to restrain one’s self</i>. Targ. II Esth. V, 10, v. <a href=\"#\" data-headword=\"חֲמַם\">חֲמַם</a>. [<span class=\"citation\">Targ. Y. Gen. VII, 21</span> <span dir=\"rtl\">אתחמסי</span>, read: <a href=\"#\" data-headword=\"מְסֵי\">אִתְמְסִי</a> or <span dir=\"rtl\">אִתְהַמְסִי</span>, v. <a href=\"#\" data-headword=\"מְסִבְּתָא\">מְסִי</a>.]</div></div>","alt":[]},"11544":{"h":"חָמָס","r":"H01207","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"חֲמַס\">preced.</a>) <i>violence, extortion</i>. <span class=\"citation\">Y. B. Mets. IV, 9ᶜ</span> bot. (ref. to <span class=\"citation\">Gen. VI, 13</span>) <span dir=\"rtl\">מה היה חֲמָסָן</span> what was the nature of their violence? <span class=\"citation\">Gen. R. s. 31</span> (distinction between <a href=\"#\" data-headword=\"ח׳\">ח׳</a> a. <a href=\"#\" data-headword=\"גָּזֵל\">גֶּזֶל</a>); a. e.—Pl. <span dir=\"rtl\">חֲמָסִים</span>. <span class=\"citation\">Gen. R. s. 65</span> … <span dir=\"rtl\">שלא גזילות ח׳</span> that thou wilt not give me to eat what has been obtained by robbery or extortion. <span class=\"citation\">Lev. R. s. 2</span>. <span class=\"citation\">Koh. R. to III, 9</span>; a. e.</div>","alt":[]},"11545":{"h":"חַמְסָן","r":"H01208","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"חָמָס\">preced.</a>) <i>violent man, extortioner</i>. <span class=\"citation\">B. Kam. 62ᵃ</span> (defining the difference between the <a href=\"#\" data-headword=\"ח׳\">ח׳</a> and the <a href=\"#\" data-headword=\"גַּזְלָן\">גַּזְלָן</a>) <span dir=\"rtl\">ח׳ יהיב וכ׳</span> the <i>ḥamsan</i> takes by force and pays.—Pl. <span dir=\"rtl\">חַמְסָנִים</span>, <span dir=\"rtl\">חַמְסָנִין</span>. <span class=\"citation\">Snh. 25ᵇ</span> <span dir=\"rtl\">הוסיפו עליהן … והח׳</span> (Ar. <span dir=\"rtl\">והחוֹ׳</span>) they added to them (the class of persons disqualified for judges or witnesses) the robbers and those taking forcibly (and paying); Y. Shebu. VII, 37ᵈ bot.; Y. R. Hash. I, 57ᶜ top.</div>","alt":["חומְסָן"]},"11546":{"h":"*חָמֵעַ","r":"H01209","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"חָמֵץ I\">חָמֵץ</a>; <i>Pi</i>. <a href=\"#\" data-headword=\"חֲמַע I\">חִמֵּעַ</a>. <span class=\"citation\">Ab. Zar. 68ᵃ</span> <span dir=\"rtl\">לחַמֵּעַ</span>, Ms. M. <span dir=\"rtl\">לחַמֵּץ</span>.</div>","alt":[]},"11547":{"h":"חֲמַע I","r":"H01210","html":"<div class=\"sense\"><i>to be sour; to be leavened</i>. <span class=\"citation\">Targ. O. Ex. XII, 34</span>; a. e.; v. <a href=\"#\" data-headword=\"חֲמִיעַ\">חֲמִיעַ</a>.—<span class=\"citation\">Y. Pes. II, end, 29ᶜ</span> <span dir=\"rtl\">בגין דיִחְמַע</span> that it might turn sour (vinegar).</div><div class=\"sense\"><b>Pa. חַמֵּעַ</b> <div class=\"sense\"><i>to leaven</i>. <span class=\"citation\">Pes. 41ᵃ</span> <span dir=\"rtl\">חַמּוּעֵי מְחַמֵּעַ</span> (not <span dir=\"rtl\">מחמעא</span>; Rashi: <span dir=\"rtl\">אַחְמוּעֵי מַחְמַע</span> <i>Af.</i>) (the flour) causes leavening.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"מַחְמַע\">מְחַמַּע</a>, v. infra.</div></div><div class=\"sense\"><b>Af. אַחְמַע</b> <div class=\"sense\"><b>1)</b> <i>to turn sour, leaven, ferment</i>. Targ. Y. Ex. l. c.</div><div class=\"sense\"><b>—2)</b> <i>to cause leavening</i>. <span class=\"citation\">Targ. Y. II, Lev. II, 11</span> <span dir=\"rtl\">דמַחְמַע</span> (Var. <span dir=\"rtl\">דמְחַמַּע</span>); v. supra.</div></div>","alt":[]},"11548":{"h":"חָמַץ","r":"H01211","html":"<div class=\"sense\"> [<i>to be hot,</i>] <i>to do violence, to wrong</i>. <span class=\"citation\">Snh. 35ᵃ</span> (ref. to <span class=\"citation\">Is. I, 17</span>) <span dir=\"rtl\">אשרו חָמוּץ ולא חוֹמֵץ</span> right the oppressed, but not the oppressor (listen to the complainant first); <span class=\"citation\">Yoma 39ᵇ</span></div>","alt":[]},"11549":{"h":"חָמֵץ I","r":"H01212","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"חָמַץ\">preced.</a>) [<i>to be hot</i>,] <i>to ferment, be sour</i>. Ad. Zar. 68ᵇ <span dir=\"rtl\">מי גרם לה שתֶּחְמַץ וכ׳</span> what was the cause that it (the dough) became leavened (rose) in one hour?</div><div class=\"sense\"><b>Pi. חִמֵּץ</b> <div class=\"sense\"><i>to cause leavening</i>. Ib.ᵃ ראויה לחַמֵּץ וכ׳ Ms. M. (ed. <span dir=\"rtl\">לחַמֵּעַ</span>) fit to leaven with it many other doughs. Ib. <span dir=\"rtl\">וחִימְּצוּ</span>; <span class=\"citation\">Orl. II, 11</span> <span dir=\"rtl\">נצטרפו וחִמְּצוּ</span> (Y. ed. <span dir=\"rtl\">הצטרפו וחִימֵּיצוּ</span>) and the two combined produced the required leavening, Ib. 9 <span dir=\"rtl\">וחִמְּצָהּ</span> (Y. ed. <span dir=\"rtl\">וחִימֵּיצָהּ</span>; Ab. Zar. l. c. <span dir=\"rtl\">והֶחְמִיצָהּ</span>) and it made the dough rise. <span class=\"citation\">Orl. II 6</span> <span dir=\"rtl\">כל המְחַמֵּץ</span> whatever is used for producing fermentation; a. fr.—Trnsf. <i>to mature, to continue a case over night, to reserve judgment</i>. <span class=\"citation\">Snh. 35ᵃ</span> (ref. to <span class=\"citation\">Is. I, 17</span>, v. <a href=\"#\" data-headword=\"חָמַץ\">preced.</a>) <span dir=\"rtl\">אשרו דיין שמְחַמֵּץ את וכ׳</span> Ms. K. (ed. <span dir=\"rtl\">אשרי</span>, v. Rabb. D. S. a. l. note 20) praise the judge (in capital cases) who reserves his judgment (over night); <span class=\"citation\">Yalk. Is. 257</span>.</div></div><div class=\"sense\"><b>Hif. הֶחְמִיץ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"חָמַץ\">same</a>. <span class=\"citation\">Pes. 40ᵃ</span> <span dir=\"rtl\">מי פירות אינן מַחְמִיצִין</span> juice of fruits produces no leavening (in the ritual sense). <span class=\"citation\">Ab. Zar. 68ᵃ</span> <span dir=\"rtl\">כדי להחמיץ</span> (<span class=\"citation\">Orl. II, 8</span> <span dir=\"rtl\">לחַמֵּץ</span>) enough to leaven the dough. Mekh. Bo s. 10 <span dir=\"rtl\">שאור שהוא מַחְמִיץ לאחרים</span> leaven which is used for leavening other doughs; a. fr.—Trnsf. <i>to procrastinate</i>. Ib. s. 9 (play on <span dir=\"rtl\">המַצּוֹת</span>, <span class=\"citation\">Ex. XII, 17</span>) <span dir=\"rtl\">כדרך … אין מַחְמִיצִין את המִצְוָה</span> as well as you must not allow the <i>matsah</i> to become sour, so you must not allow the <i>mitsvah</i> (religious act) to become sour by postponement; <span class=\"citation\">Yalk. Ex. 201</span>.</div><div class=\"sense\"><b>—2)</b> <i>to turn sour, to ferment</i>. <span class=\"citation\">Ab. Zar. 68ᵇ</span> <span dir=\"rtl\">ראויה להַחְמִיץ וכ׳</span> (Ms. M. <span dir=\"rtl\">לחמע</span>) is likely to ferment in two hours. <span class=\"citation\">Nidd. IX, 7</span> <span dir=\"rtl\">מי רגלים שהֶחְמִיצוּ</span> urin which ferments.—Trnsf. <i>to degenerate, become wicked</i>. <span class=\"citation\">R. Hash. 3ᵇ</span> <span dir=\"rtl\">קודם שה׳</span> before he (the Persian King) changed for the worse.</div></div><div class=\"sense\"><b>Nithpa. נִתְחַמֵּץ</b> <div class=\"sense\"><i>to become sour</i> <a href=\"#\" data-headword=\"חָמֵץ I\">(חָמֵץ</a>). <span class=\"citation\">Pes. 28ᵇ</span>; <span class=\"citation\">43ᵃ</span> <span dir=\"rtl\">נ׳ מאליו</span> became sour of itself (not through a leavening means).</div></div>","alt":[]},"11550":{"h":"חֲמַץ","r":"H01213","html":"<div class=\"sense\">(<a href=\"#\" data-headword=\"חָמֵץ I\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>to be hot</i>, (of color) <i>red</i>, v. <a href=\"#\" data-headword=\"חִימּוּצָא\">חִימּוּצָא</a>, <a href=\"#\" data-headword=\"חִימּוּצָתָא\"><a href=\"#\" data-headword=\"חִימּוּצָתָא\">חִימּוּצָתָא</a>.</a></div><div class=\"sense\"><b>—2)</b> <i>to be sour, salty</i></div><div class=\"sense\"><b>Pa. חַמֵּיץ</b> <div class=\"sense\"><i>to put to shame</i>. <span class=\"citation\">Targ. Prov. X, 1</span> (h. text <span dir=\"rtl\">תוגת</span>), v. <a href=\"#\" data-headword=\"חִימּוּצָא\">חִימּוּצָא</a>.</div></div><div class=\"sense\"><b>Af. אַחְמִיץ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"חָמֵץ I\">same</a>. Ib. XXV, 8; XXVIII, 7 (Ms. <a href=\"#\" data-headword=\"חָמֵץ I\">same</a>. Ib. XXV, 8; XXVIII, 7 (Ms. <i>Pa.</i>; h. text <a href=\"#\" data-headword=\"כָּלַם\">הכלים</a>).</div><div class=\"sense\"><b>—2)</b> <i>to degenerate</i>. <span class=\"citation\">R. Hash. 4ᵃ</span> <span dir=\"rtl\">מנלן דא׳</span> what evidence have we that he became wicked?, v. <a href=\"#\" data-headword=\"חָמֵץ I\">preced.</a></div></div>","alt":[]},"11551":{"h":"חָמֵץ II","r":"H01214","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"חֲמַץ\">preced.</a> wds.) <i>leavened bread, anything containing leavened substance</i> (of the five species of grain, v. <span class=\"citation\">Ḥall. I, 1</span>, sq.). <span class=\"citation\">Pes. I, 1</span>, v. <a href=\"#\" data-headword=\"בָּדַק\">בָּדַק</a>. <span class=\"citation\">Ib. II, 2</span> ח׳ של עכ&quot;ום וכ׳ <i>ḥ</i><i>amets</i> belonging to a gentile over which the Passover passed (which existed during the Passover week). <span class=\"citation\">Ib. 3</span> <span dir=\"rtl\">על חֲמֵצוֹ</span> (trad. pronunc. <span dir=\"rtl\">חֶמְצוֹ</span> as if fr. <a href=\"#\" data-headword=\"חָמֵץ I\">חֵמֶץ</a>) on ḥ. belonging to him. <span class=\"citation\">Y. Shebi. VIII, 38ᵇ</span> bot. <span dir=\"rtl\">חֲמֵיצָן של וכ׳</span> ḥ. belonging to Samaritans; <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> bot. <span dir=\"rtl\">אכל חמצין</span> (read: <span dir=\"rtl\">חֲמֵיצָן</span>) ate their (the Samaritans’) ḥ. (immediately after Passover); a. v. fr.—Pl. <span dir=\"rtl\">חֲמֵצִים</span>, <span dir=\"rtl\">חֲמֵצין</span> <i>salads</i>, v. <a href=\"#\" data-headword=\"חוּמְצָן\">חוּמְצָן</a>.</div>","alt":[]},"11552":{"h":"חֲמָץ","r":"H01215","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Gr. Ἔμεσα, Ἔμισσα) <i>Ḥămâts, Emesa</i> (mod. <i>Hums</i>) a city of Syria on the Eastern bank of the Orontes. <span class=\"citation\">Gen. R. s. 37</span>; <span class=\"citation\">Y. Meg. I, 71ᵇ</span> bot. (expl. <a href=\"#\" data-headword=\"צְמָרִי\">צמרי</a>, <span class=\"citation\">Gen. X, 18</span>).—<span class=\"citation\">Y. Kil. IX, 32ᶜ</span> bot.; <span class=\"citation\">Y. Keth. XII, 35ᵇ</span> bot. <span dir=\"rtl\">ימא דח׳</span> the Lake of E. (an artificial bay made under Diocletian); <span class=\"citation\">Midr. Till. to Ps. XXIV</span> <span dir=\"rtl\">ימא דחמין</span> (corr. acc.).—Denom. <span dir=\"rtl\">חֲמָצָאֵי</span>, <a href=\"#\" data-headword=\"חוֹמְצָאֵי\">חוֹמְצָאֵי</a> m. pl. <i>inhabitants of Emesa</i>. <span class=\"citation\">Targ. Y. Gen. X, 18</span>; <span class=\"citation\">Targ. I Chr. I, 16</span>.</div>","alt":[]},"11553":{"h":"חִמְצָא","r":"H01216","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֵימָרָא\">חִימְ׳</a>.—[<span dir=\"rtl\">חמצין</span>, <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> bot., v. <a href=\"#\" data-headword=\"חָמֵץ II\"><span dir=\"rtl\">חָמץ</span> II</a>.]</div>","alt":[]},"11554":{"h":"חַמְצָן","r":"H01217","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"חָמַץ\">(חָמַץ</a>), <span dir=\"rtl\">בן ח׳</span> <i>a grasping person</i>. <span class=\"citation\">Yoma 39ᵃ</span>, sq. (Ms. O. omits <a href=\"#\" data-headword=\"בֵּן\">בן</a>); <span class=\"citation\">Kidd. 53ᵃ</span>; v. <a href=\"#\" data-headword=\"חָאפוּן\">חָאפוּן</a>.</div>","alt":[]},"11555":{"h":"חָמַר I","r":"H01218","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"חָבַר\">חָבַר</a>) </div><div class=\"sense\"><b>1)</b> <i>to join; to pile up, to load.</i> <span class=\"citation\">Ukts. II, 5</span> <span dir=\"rtl\">והבצלים שחֲמָרָן</span> and the onions which one has piled up; v. <a href=\"#\" data-headword=\"אָמַן\">אָמַן</a>.—<span class=\"citation\">Zeb. 53ᵃ</span> <span dir=\"rtl\">וחוֹמֵר בגודלו וכ׳</span> and loads (i.e. supports the index finger) with his thumb on top and the little finger below (like a balanced load, v. <a href=\"#\" data-headword=\"חֶבֶר\">חֶבֶר</a> a. <a href=\"#\" data-headword=\"אֵבֶר\">אֵבֶר</a>); [Var. <a href=\"#\" data-headword=\"סוֹמֶךְ\">סוֹמֵךְ</a>, v. Rabb. D. S. a. l. note 3]; <span class=\"citation\">Yalk. Lev. 469</span>.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"חָמוּר\">חָמוּר</a>) <i>to be weighty, stringent.</i> Ohol. XIV, 3 <span dir=\"rtl\">אל יֶחְמוֹר זה וכ׳</span> this must not be made more stringent than &amp;c.; [ed. Dehr. <span dir=\"rtl\">יַחְמִיר</span>.]</div><div class=\"sense\"><b>Hif. הֶחְמִיר</b> <div class=\"sense\"> [<i>to put a load on</i>,] <i>to pass a restrictive law, to incline to the stricter opinion</i>, opp. <a href=\"#\" data-headword=\"קָלַל\">היקל</a> to make easy. <span class=\"citation\">Yeb. 88ᵃ</span> <span dir=\"rtl\">מתיך חומר שהֶחְמַרְתָּ עליה וכ׳</span> on account of the restrictions under which the law puts her in the end (if she marries again and her first husband appears), it is made easy for her in the beginning (by allowing her to marry again), i.e. her heavy responsibility will make her cautious; Y. Gitt. I, beg. 43ᵃ (add: <a href=\"#\" data-headword=\"מִתּוֹךְ\">מתוך</a>). <span class=\"citation\">Nidd. 66ᵃ</span>, a. fr. <span dir=\"rtl\">הֶחְמִירוּ על עצמן</span> they placed themselves under greater restrictions (than the law requires). <span class=\"citation\">Ned. I, 1</span> <span dir=\"rtl\">להחְמִיר</span>, v. <a href=\"#\" data-headword=\"חָכַךְ II\"><span dir=\"rtl\">חָכַךְ</span> II</a>. <span class=\"citation\">Eduy. III, 10</span>, a. e. <span dir=\"rtl\">מַחְמִיר כדברי וכ׳</span> he adopts the stricter opinion of &amp;c.; a. v. fr.</div></div><div class=\"sense\"><b>[. חִמֵּר</b> <div class=\"sense\">, v. <a href=\"#\" data-headword=\"חַמָּר II\"><span dir=\"rtl\">חַמָּר</span> II</a>.]</div></div>","alt":[]},"11556":{"h":"חֲמַר","r":"H01219","html":"<div class=\"sense\"><b>Pa. חַמַּר</b> </div><div class=\"sense\"><b>Af. אַחְמִיר</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"חָמַר I\">preced.</a> <i>Hif.</i>—Y. Shek. VII, 50ᶜ bot. [read:] <span dir=\"rtl\">חמתון מקילין לון וחַ׳ וכ׳</span> he saw them to be lax in their practices, and he enjoined strictness on them. <span class=\"citation\">Yeb. 88ᵃ</span> <span dir=\"rtl\">לא לִיחַמֵּיר וכ׳</span> let one not put her under heavy restrictions (in the end), and not make it too easy for her (in the beginning, v. <a href=\"#\" data-headword=\"חָמַר I\">preced.</a>). <span class=\"citation\">Nidd. 66ᵃ</span> <span dir=\"rtl\">היכא דאַחְמוּר וכ׳</span> in those cases in which they have placed themselves under greater restrictions (than the law requires, v. <a href=\"#\" data-headword=\"חָמַר I\">preced.</a>), they have done so (and follow the usage like a law), but where they have not &amp;c. (you cannot extend the adopted usage by analogy); a. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"מְחַמַּר\">מַחְמַר</a>, <a href=\"#\" data-headword=\"מְחַמַּר\">מְחַמַּר</a> <i>piled up, ruins;</i> v. <a href=\"#\" data-headword=\"מְחַמַּר\">מַחְמר</a> a. <a href=\"#\" data-headword=\"דִּמְחַמְרָא\">דִּמְחַמְרָא</a>.</div></div><div class=\"sense\"><b>Ithpa. אִתְחַמַּר</b> <div class=\"sense\"><i>to be piled up, to form a pile of ruins</i> (cmp. <a href=\"#\" data-headword=\"גַּל\">גַּל</a>). <span class=\"citation\">Targ. Is. XVII, 9</span>; <span class=\"citation\">XXX, 13</span>.</div></div>","alt":[]},"11557":{"h":"חָמַר II","r":"H01220","html":"<div class=\"sense\"> (b. h.) [<i>to be hot</i>,] </div><div class=\"sense\"><b>1)</b> <i>to glow, to parch</i> (cmp. <a href=\"#\" data-headword=\"כָּמַר\">כָּמַר</a>). <span class=\"citation\">Snh. VII, 2</span> <span dir=\"rtl\">וחוֹמֶרֶת את וכ׳</span> and parches his entrails; (Ar., v. <a href=\"#\" data-headword=\"חָמַד\">חָמַד</a>).</div><div class=\"sense\"><b>Nif. נֶחְמַר</b> <div class=\"sense\"><i>to be parched</i>. <span class=\"citation\">Ḥull. III, 3</span> <span dir=\"rtl\">נפלה לאור ונֶחְמְרוּ וכ׳</span> if the bird fell into fire, and (on examination after slaughtering it was found that) its bowels were affected by inhaling heat (Ar., v. <a href=\"#\" data-headword=\"חָמַד\">חָמַד</a>). <span class=\"citation\">Gen. R. s. 38</span>, end.</div></div>","alt":[]},"11558":{"h":"חֲמַר ²","r":"H01221","html":"<div class=\"sense\"><b>1)</b> <i>to be hot, parched</i>. <span class=\"citation\">Targ. Job XXX, 27</span> <span dir=\"rtl\">חֲמַרוּ</span> (Var. <span dir=\"rtl\">חֲמָרוּ</span>, Ms. <span dir=\"rtl\">חַמָּרוּ</span> <i>Pa.</i>; h. text <span dir=\"rtl\">רתח׳</span>).</div><div class=\"sense\"><b>—2)</b> <i>to ferment</i>, v. <a href=\"#\" data-headword=\"חֲמַר III\">next w.</a>, a. <a href=\"#\" data-headword=\"חֲמִיר I\">חֲמִירָא</a>.</div>","alt":[]},"11559":{"h":"חֲמַר III","r":"H01222","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲמַר ²\">preced.</a>) <i>wine</i>(b. h. . <span class=\"citation\">Targ. Num. VI, 3</span>; a. fr.—<span class=\"citation\">Targ. Hos. III, 1</span> <span dir=\"rtl\">בחַמְרֵיה</span> ed. Lag. (ed. <span dir=\"rtl\">בחבריה</span>, corr. acc.) in his wine (intoxication).—<span class=\"citation\">Sabb. 77ᵃ</span>, a. e., v. <a href=\"#\" data-headword=\"דְּרֵי II\"><span dir=\"rtl\">דְּרֵי</span> II</a>. <span class=\"citation\">Ḥull. 112ᵃ</span> <span dir=\"rtl\">קרי ליה חמר בשר</span> (Ar. <span dir=\"rtl\">המר</span>) called it (that juice) meat-wine.—<span class=\"citation\">Gen. R. s. 91</span> end <span dir=\"rtl\">ח׳ קטף</span> wine mixed with resin.—<span class=\"citation\">Erub. 53ᵇ</span>, v. <a href=\"#\" data-headword=\"אִימַּר\">אִימַּר</a>; a. fr.—Pl. <span dir=\"rtl\">חַמְרִין</span>. <span class=\"citation\">Targ. Y. Gen. L, 1</span>.</div>","alt":["חַמְרָא I"]},"11560":{"h":"חֲמָר","r":"H01223","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>ass;</i> trnsf. <i>workingman’s contrivance, jack</i> &amp;c. <span class=\"citation\">Targ. Is. XXI, 7</span>. <span class=\"citation\">Targ. Ex. XIII, 13</span>; a. fr.—<span class=\"citation\">Sabb. 66ᵇ</span>; Y. ib. VI, 8ᶜ, v. <a href=\"#\" data-headword=\"*אָנְקִטְמִין\">אָנְקִטְמִין</a>; a. v. fr.—Pl. <span dir=\"rtl\">חֲמָרִין</span>, <span dir=\"rtl\">חֲמָרַיָּא</span>, <span dir=\"rtl\">חֲמָרֵי</span>. <span class=\"citation\">Targ. Gen. XII, 16</span> (Y. ed. Amst. <span dir=\"rtl\">חַמְרִין</span>). Ib. XXXVI, 24 (Y. ed. Amst. <span dir=\"rtl\">חַמְרַיָּא</span>); a. e.—<span class=\"citation\">Gen. R. s. 38</span> (ref. to <span dir=\"rtl\">בני האדם</span>, <span class=\"citation\">Gen. XI, 5</span>) <span dir=\"rtl\">וכי מה נאמר בני ח׳</span> could we think young asses (built it)?—Y. Dem. I, 21ᵈ bot. Ib. 22ᵃ top; a. fr.</div><div class=\"sense\"><b>—2)</b>  ח׳ דמיא <i>sea-ass</i>, name of a sea fish, <i>hake</i> (v. Sm. Ant. s. v. Onos). <span class=\"citation\">Ab. Zar. 39ᵃ</span></div>","alt":["חֲמָרָא","(חַמְרָא  II)"]},"11561":{"h":"חַמָּר I","r":"H01224","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(v. <a href=\"#\" data-headword=\"חֲמַר III\"><span dir=\"rtl\">חֲמַר</span> II</a>; cmp. <a href=\"#\" data-headword=\"חָמַם\">חָמַם</a>) <i>dark; </i>trnsf. <i>mourning</i>. <span class=\"citation\">Targ. Ps. XXXV, 14</span>; <span class=\"citation\">XXXVIII, 7</span> Ms. (ed. <a href=\"#\" data-headword=\"חַכִּיר\">חַכִּיר</a>, Lev. <span dir=\"rtl\">הביר</span>; h. text <a href=\"#\" data-headword=\"קָדַר I\">קֹדֵר</a>).</div>","alt":[]},"11562":{"h":"חַמָּר II","r":"H01225","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(denom. of <a href=\"#\" data-headword=\"חֲמוֹר\">חֲמוֹר</a>) <i>ass-driver, attendant of beasts of burden</i>. <span class=\"citation\">Kidd. IV, 14</span>, a. e., v. <a href=\"#\" data-headword=\"גַּמָּל\">גַּמָּל</a>. <span class=\"citation\">Kel. XXVI, 5</span> (<span class=\"citation\">6</span>) <span dir=\"rtl\">עור החמיר ועור הח׳</span> Maim. (v. comment. ed. Dehr.; Mish. ed. <span dir=\"rtl\">עור הח׳</span>, Talm. ed. <span dir=\"rtl\">עור החמור</span>) the ass’ leather cover and the ass-driver’s apron; a. fr.—<span dir=\"rtl\">ח׳ גמל</span>, v. <a href=\"#\" data-headword=\"גַּמָּל\">גַּמָּל</a>.—Pl. <a href=\"#\" data-headword=\"חַמָּן\">חַמָּרִים</a>, <span dir=\"rtl\">חַמָּרִין</span>. <span class=\"citation\">Dem. IV, 7</span>. Kidd. l. c. a. fr.—Denom.: <a href=\"#\" data-headword=\"חָמַר I\">חִמֵּר</a> <i>to direct a loaded beast’s motions by walking behind it, to load a beast</i>. <span class=\"citation\">Sabb. 153ᵇ</span>; <span class=\"citation\">Ab. Zar. 15ᵃ</span> <span dir=\"rtl\">המְחַמֵּר אחר וכ׳</span> he who drives his beast of burden by walking behind it. Sabb. l. c. <span dir=\"rtl\">והלא מחמר</span> but does he not violate the Sabbath as a driver (by placing his money bag on the ass)?—<span class=\"citation\">Pes. 66ᵇ</span> <span dir=\"rtl\">מח׳ כלאחר יד הוא</span> it is an act of driving in an unusual way (the lamb usually not being used as a beast of burden); a. fr.</div>","alt":[]},"11563":{"h":"חַמָּר","r":"H01226","html":"<div class=\"sense\"> <span class=\"citation\">Y. Taan. I, 64ᵇ</span> bot. <span dir=\"rtl\">ח׳ אנא</span> I am an ass-driver. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">פלן ח׳ יצלי</span> let that certain ass-driver pray. [<span class=\"citation\">Ib.</span> <span dir=\"rtl\">חמר עבין ההוא גוברא וכ׳</span>, read: <span dir=\"rtl\">חמש עבירן וכ׳</span>, v. margin ed. Krot.]—<span class=\"citation\">Y. Snh. VI, beg. 23ᵇ</span> <span dir=\"rtl\">הא שאלתא דח׳</span> in that form it would be an ass-driver’s question.—Pl. <span dir=\"rtl\">חַמָּרַיָּיא</span>. Y. Taan. IV, 67ᶜ bot.</div>","alt":["חַמָּרָא"]},"11564":{"h":"חַמְרָא","r":"H01227","html":"<div class=\"sense\"><i>wine</i>, v. <a href=\"#\" data-headword=\"חֲמַר III\"><span dir=\"rtl\">חֲמַר</span> III</a>.</div>","alt":[]},"11565":{"h":"חֲמָרָא","r":"H01228","html":"<div class=\"sense\"><i>ass</i>, v. <a href=\"#\" data-headword=\"חֲמָר\">חֲמָר</a>.</div>","alt":["חַמְרָא"]},"11566":{"h":"חֵמָרָא","r":"H01229","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֵימָרָא\">חֵימָרָא</a></div>","alt":[]},"11567":{"h":"חַמֶּרֶת","r":"H01230","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חַמָּר\">חַמָּר</a>) <i>a company of ass-drivers, caravan</i>. <span class=\"citation\">Snh. X, 5</span> (<span class=\"citation\">111ᵇ</span>); <span class=\"citation\">B. Bath. 8ᵃ</span>. <span class=\"citation\">Tosef. Dem. I, 10</span> (contrad. to <span dir=\"rtl\">חַמָּר אהד</span>); Y. ib. I, 22ᵃ bot. (incorr. version).</div>","alt":[]},"11568":{"h":"חֲמָרְתָּא","r":"H01231","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"חֲמוֹרָה\">חֲמוֹרָה</a>. <span class=\"citation\">Y. Dem. I, 21ᵈ</span> bot.; <span class=\"citation\">Y. Shek. V, 48ᵈ</span> top; <span class=\"citation\">Gen. R. s. 60</span> <span dir=\"rtl\">חֲמָרְתֵּיה דר׳ וכ׳</span> the sheass of R. &amp;c. <span class=\"citation\">Y. Yeb. IV, 6ᵃ</span> bot. <span dir=\"rtl\">חֲמָרְתִּי</span> my ass. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חֲמָרְתִּה</span>, v. <a href=\"#\" data-headword=\"פָּחַת\">פָּחַת</a></div>","alt":[]},"11569":{"h":"חָמֵשׁ","r":"H01232","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>five</i> (numeral letter <a href=\"#\" data-headword=\"ה׳\">ה׳</a>). <span class=\"citation\">Snh. V, 3</span> <span dir=\"rtl\">בחמש</span> (sub. <a href=\"#\" data-headword=\"שָׁעוּת\">שעות</a>) during the fifth hour of the day. Ib. <span dir=\"rtl\">בחמשה</span> (sub. <span dir=\"rtl\">ימים</span>) on the fifth of the month.—<span class=\"citation\">Sabb. 77ᵇ</span> <span dir=\"rtl\">חמשה אימות וכ׳</span> (sub. <span dir=\"rtl\">מִינֵי</span>), v. <a href=\"#\" data-headword=\"אֵימָה\">אֵימָה</a>. <span class=\"citation\">B. Mets. IV, 9</span> <span dir=\"rtl\">תשלומי ארבעה וח׳</span> fines of the fourfold or fivefold value (<span class=\"citation\">Ex. XXI, 37</span>); a. v. fr.—Pl. <span dir=\"rtl\">חֲמִשִּׁים</span> (<a href=\"#\" data-headword=\"נ׳\">נ׳</a>) <i>fifty</i>. <span class=\"citation\">R. Hash. 21ᵇ</span>. <span class=\"citation\">Ab. V, 21</span> <span dir=\"rtl\">בן ח׳</span> at the age of fifty years; a. v. fr.—Denom. <span dir=\"rtl\">חִמֵּשׁ</span> <i>to divide into five</i>.—<i>Part. pass</i>. <span dir=\"rtl\">מְחוּמָּשׁ</span>; f. <span dir=\"rtl\">מְחוּמֶּשֶׁת</span>, pl. <span dir=\"rtl\">מְחוּמָּשׁוֹת</span>. <span class=\"citation\">B. Bath. 150ᵃ</span> <span dir=\"rtl\">ובלבד שיהו מח׳</span> provided the minimum of wool required is equally divided between the five lambs.—<span dir=\"rtl\">חֲמֵשׁ עֶשְׂרֵה</span> f.; <span dir=\"rtl\">חֲמִשָּׁה עָשָׂר</span> m. (<span dir=\"rtl\">ט&quot;ו</span>) <i>fifteen</i>. <span class=\"citation\">Y. Sabb. VI, 8ᵇ</span> (ref. to <span dir=\"rtl\">וחמשים</span>, <span class=\"citation\">Ex. XIII, 18</span>) <span dir=\"rtl\">בח׳ ע׳ מיני וכ׳</span> with fifteen kinds of arms. <span class=\"citation\">Taan. IV, 8</span> <span dir=\"rtl\">כח׳ ע׳ באב</span> like the celebration of the fifteenth of Ab; a. fr.—Constr. of <a href=\"#\" data-headword=\"חָמֵשׁ\">חֲמִשָּׁה</a>; <span dir=\"rtl\">חֲמֵשֶׁת</span>. <span class=\"citation\">Kidd. 30ᵃ</span> <span dir=\"rtl\">ח׳ אלפים</span> five thousand; a. fr.</div>","alt":["חֲמִשָּׁה"]},"11570":{"h":"חֲמֵשׁ","r":"H01233","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">Targ. Gen. XLV, 11</span>. <span class=\"citation\">Ib. XLVII, 2</span>; a. fr.—<span class=\"citation\">Yoma 84ᵃ</span> <span dir=\"rtl\">ח׳ ומעלי וכ׳</span> on Thursday and on Friday; a. fr.—Pl. <a href=\"#\" data-headword=\"חַרְשִׁין\">חַמְשִׁין</a> <i>fifty</i>. <span class=\"citation\">Targ. Num. XXXI, 47</span>; a. fr.—<span class=\"citation\">B. Mets. 51ᵃ</span>; a. fr.—<span dir=\"rtl\">חֲמֵישַׁת עַשְׂרָה</span> (<span dir=\"rtl\">חֲמֵישְׁתְּ</span>) <i>fifteen</i>. <span class=\"citation\">Targ. O. Lev. XXIII, 6</span>; a. fr.; v. <a href=\"#\" data-headword=\"חֲמֵיסַר\">חֲמֵיסַר</a>.</div>","alt":["חַמְשָׁא","חַמְשָׁה"]},"11571":{"h":"חֲמִשִׁי","r":"H01234","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲמִי\">חֲמִי׳</a></div>","alt":["חֲמִשַׁי"]},"11572":{"h":"חַמְשִׁיתָא","r":"H01235","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֲמִשִׁי\">preced.</a> wds.) <i>a collection of five</i>. <span class=\"citation\">Y. Meg. II, 73ᵇ</span> bot.; <span class=\"citation\">Y. Ber. II, 4ᵈ</span> <span dir=\"rtl\">ח׳ קדמייתא</span> the first five (mentioned <span class=\"citation\">Ter. I, 1</span>); <span dir=\"rtl\">ח׳ בתרייתא</span> the second five (mentioned ib. 6); (Readings vary <span dir=\"rtl\">חמשתיה</span>, <a href=\"#\" data-headword=\"חַמְשִׁיתָא\">חמשתא</a>).</div>","alt":["חֲמַשְׁתָּא"]},"11573":{"h":"חֵמֶת","r":"H01236","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>the skin of a goat</i> drawn off the body without opening the belly and sewed up and pitched at the ends where the legs and the tail were cut off (v. Sm. Bible Dict. s. v. <i>Bottle</i>), <i>bottle, bag.</i> <span class=\"citation\">Kel. XIX, 8</span> <span dir=\"rtl\">הח׳ שבצים וכ׳</span> a bottle (of a skin of a he-goat) whose scrotum (originally made to receive liquids in connection with the bottle) became defective. <span class=\"citation\">Ib. XX, 2</span> <span dir=\"rtl\">חֵמַת חלילין</span> bag of the bagpipe (ascaula). <span class=\"citation\">Ib. XXVIII, 5</span> <span dir=\"rtl\">ח׳ שעשאה שטיח</span> a closed up pouched skin which (by cutting open) was made a spread skin. <span class=\"citation\">Sabb. 152ᵃ</span> a woman is <span dir=\"rtl\">ח׳ מלא דם</span>(!) a bag full of blood (v. vers. Ms. O. in Rabb. D. S. a. l. note 7). <span class=\"citation\">Tosef. Kel. B. Kam. VI, 13</span>. <span class=\"citation\">Ib. VII, 11</span> <span dir=\"rtl\">הח׳ מעור הדג</span> a bag made of the skin of a fish. Y. Ab. Zar. IV, end, 44ᵇ bot. <span dir=\"rtl\">בחֶמְתּוֹ</span> (not <span dir=\"rtl\">מח׳</span>) in his wine bottle; a. fr.—Pl. <span dir=\"rtl\">חֲמָתוֹת</span>. <span class=\"citation\">Kel. XXVI, 4</span> (<span class=\"citation\">5</span>) <span dir=\"rtl\">כל ח׳</span> Mish. ed. (Talm. ed. <a href=\"#\" data-headword=\"כלי\">כלי</a>, corr. acc.); <span class=\"citation\">Men. 37ᵇ</span>. <span class=\"citation\">Ḥull. 107ᵇ</span> <span dir=\"rtl\">בבלאי ח׳</span> with pieces of goat skins wrapt around their hands (like gloves).—<span class=\"citation\">Midr. Till. to Ps. CXXXVII</span> <a href=\"#\" data-headword=\"חָמוֹת\">חֵמוֹת</a>.</div>","alt":[]},"11574":{"h":"חַמָּת","r":"H01237","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Ḥammath</i>, name of a demon (<i>fever</i>, cmp. <a href=\"#\" data-headword=\"חֵימְתָא\">חֵימְתָא</a>). <span class=\"citation\">Snh. 101ᵃ</span> <span dir=\"rtl\">זיקא דח׳ וכ׳</span> the blast (breath; Ms. M. <a href=\"#\" data-headword=\"רֵיקָא\">ריקא</a> the spittle) of Ḥ. do I see in thy face (an eruption).</div>","alt":[]},"11575":{"h":"חַמַּת","r":"H01238","html":"<div class=\"sense\">, constr. of <a href=\"#\" data-headword=\"חַמָּה\">חַמָּה</a> <i>heat of;</i> מֵחַ׳ <i>through the heat of, from the effect of, in consequence of</i>. <span class=\"citation\">B. Mets. VI, 3</span> <span dir=\"rtl\">מח׳ המעלה</span> overcome by heat through the exertion of climbing up the ascent. <span class=\"citation\">Ḥull. 4ᵇ</span> <span dir=\"rtl\">מתו אחיו מח׳ מילה</span> his brothers had died in consequence of the circumcision.  <span class=\"citation\">Nidd. 36ᵇ</span> <span dir=\"rtl\">מח׳ עצמה</span> spontaneously; <span dir=\"rtl\">מח׳ ולד</span> in consequence of travailing; <span dir=\"rtl\">מח׳ אונס</span> from an accidental cause; a. fr.—(Also in Chald. phraseology) Targ. II, <span class=\"citation\">Esth. VII, 9</span> <span dir=\"rtl\">מחמת ד־</span> (ed. Lag. <span dir=\"rtl\">מהֵימַת</span>) because they take &amp;c.—<span class=\"citation\">B. Kam. 114ᵃ</span> <span dir=\"rtl\">כל אונסא דאתי מֵחַמְתֵיה</span> any injury that may arise from his action (of selling). <span class=\"citation\">Ab. Zar. 15ᵃ</span> <span dir=\"rtl\">אזל מחמתיה</span> (the animal) moves at his instance; a. fr.</div>","alt":[]},"11576":{"h":"זְמָם II","r":"G00533","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (זָמַם II) <i>muzzle</i> (v. <a href=\"#\" data-headword=\"זְמוּם\">זְמוּם</a>). <span class=\"citation\">Gen. R. s. 81</span> (play on <span dir=\"rtl\">זמות</span>, <span class=\"citation\">Prov. XXX, 32</span>, v. <a href=\"#\" data-headword=\"זָמַם I\"><span dir=\"rtl\">זָמַם</span> I</a>) <span dir=\"rtl\">אם חשבת … נוח לך ליתן ז׳ וכ׳</span> if thou hast planned to do a good deed …, it would have been better for thee to put a muzzle on thy mouth. <span class=\"citation\">Gen. R. s. 75</span> (ref. to <span dir=\"rtl\">זממו</span>, <span class=\"citation\">Ps. CXL, 9</span>) <span dir=\"rtl\">עשה לו ז׳ וכ׳</span> put a bit to Esaw (Rome); … <span dir=\"rtl\">ומהו ז׳ וכ׳</span> and what is the bit (to check Rome’s power) &amp;c.?; <span class=\"citation\">Meg. 6ᵃ</span> bot. <span dir=\"rtl\">זְמָמוֹ אל תפק וכ׳</span> ‘do not loosen his bit’ (Ps. l. c.), that means Germania &amp;c.—Pl. <span dir=\"rtl\">זְמָמִים</span>, v. <a href=\"#\" data-headword=\"זְמוּם\">זְמוּם</a>.</div>","alt":[]},"11577":{"h":"זְמַם ²","r":"G00534","html":"<div class=\"sense\">, also the camel’s <i>ring</i> or <i>staff through the nose </i>and the<i> basket</i> fastened thereto. <span class=\"citation\">Targ. Is. XXXVII, 29</span>. <span class=\"citation\">Targ. Ps. XXXII, 9</span>; a. fr.—<span class=\"citation\">Sabb. 107ᵃ</span>, v. <a href=\"#\" data-headword=\"אִיכּוּ\">אִיכּוּ</a>. <span class=\"citation\">Ib. 111ᵇ</span>, sq. <span dir=\"rtl\">קיטרא דקטרי בז׳</span> the loop which is made to fasten the camel’s basket to the ring; <span dir=\"rtl\">קיטרא דז׳ גופיה</span> the (permanent) knot in the bit itself; v. <a href=\"#\" data-headword=\"אִיסְטְרִידָא\">אִיסְטְרִידָא</a>.</div>","alt":["זְמָמָא"]},"11578":{"h":"זָמַן","r":"G00535","html":"<div class=\"sense\"><i>to arrange, designate</i>.</div><div class=\"sense\"><b>Pi. זִימֵּן</b> <div class=\"sense\"><b>1)</b> <i>to invite</i>, esp. <i>to a meal</i>. <span class=\"citation\">B. Kam. 79ᵇ</span>; a. v. fr.—<i>Part. pass</i>. <span dir=\"rtl\">מְזוּמָּן</span>, f. <span dir=\"rtl\">מְזוּמֶּנֶת</span>; pl. <span dir=\"rtl\">מְזוּמָּנִים</span>, <span dir=\"rtl\">מְזוּמָּנוֹת</span> a) <i>invited</i>. <span class=\"citation\">Pesik. R. s. 41</span>, end <span dir=\"rtl\">מי שהוא מ׳ לסעודה</span> he who is invited to the feast. <span class=\"citation\">Ib.</span> (expl. <span dir=\"rtl\">מקראי</span>, <span class=\"citation\">Is. XLVIII, 12</span>) <span dir=\"rtl\">מְזוּמָּנִי</span> My invited guest (Israel); a. e.—b) <i>designated, chosen</i>. <span class=\"citation\">Ber. 43ᵃ</span> <span dir=\"rtl\">הוא מ׳ לברכה</span> he is the one designated (by the host) to say grace. <span class=\"citation\">Ab. Zar. 17ᵃ</span> <span dir=\"rtl\">מז׳ לחיי וכ׳</span> chosen for the bliss of futurity.—<span class=\"citation\">Snh. 102ᵃ</span> <span dir=\"rtl\">עת היא מ׳ וכ׳</span> there is a time designated for &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">יום מזומן</span> (not <span dir=\"rtl\">עת היא</span>, v. Rabb. D. S. a. l. note 8); <span class=\"citation\">Yalk. Is. 330</span>; ib. Jer. 287.—c) <i>ready at hand, in one’s possession</i>. <span class=\"citation\">B. Mets. 102ᵃ</span>; <span class=\"citation\">Sifré Deut. 227</span>, a. e. <span dir=\"rtl\">כי יקרא פרט למ׳</span> ‘if it chance’ (<span class=\"citation\">Deut. XXII, 6</span>) this excludes that which is at thy disposal (in thy court yard); a. e.—2) <i>to appoint a meal in common</i>, so as to say grace together; <i>to preface the grace after meal by saying, Let us praise</i> &amp;c.; v. <a href=\"#\" data-headword=\"זִימּוּן\">זִימּוּן</a>. <span class=\"citation\">Ber. VII, 1</span> <span dir=\"rtl\">שלשה … חייבין לזַמֵּן</span> if three dine together, they are bound to make an appointment for common grace. Ib. <span dir=\"rtl\">מְזַמְּנִין עליו</span> common grace may be appointed by making him one of the party (offering him something to eat). Ib. <span dir=\"rtl\">אין מ׳ עליהן</span> you cannot count them in (to make up the requisite number). Ib. 2 <span dir=\"rtl\">עד כמה מזמנין</span> how much must one eat of the meal in order to be counted one of the company? Ib. 3 <span dir=\"rtl\">כיצד מ׳</span> how is the appeal for common grace made?; a. fr.</div></div><div class=\"sense\"><b>Hif. הִזְמִין</b> <div class=\"sense\"><b>1)</b> <i>to cause to prepare, to notify.</i> <span class=\"citation\">Dem. VII, 1</span> <span dir=\"rtl\">המַזְמִין את הבירו וכ׳</span> if one notifies his friend that he will dine with him (on the Sabbath).</div><div class=\"sense\"><b>—2)</b> <i>to designate for use;</i> v. <a href=\"#\" data-headword=\"הַזְמָנָה\">הַזְמָנָה</a>. <span class=\"citation\">Ber. 26ᵃ</span> <span dir=\"rtl\">הִזְמִינוֹ וכ׳</span></div><div class=\"sense\"><b>—3)</b> <i>to summon</i>, v. <a href=\"#\" data-headword=\"זְמַן I\">next w.</a></div></div><div class=\"sense\"><b>Nithpa. נִזְדַּמֵּן</b> <div class=\"sense\"><b>1)</b> <i>to meet, to come to hand</i> (providentially); <i>to join one’s self to</i>. <span class=\"citation\">Snh. 96ᵃ</span> <span dir=\"rtl\">אותו מלאך שנ׳ לו וכ׳</span> that angel who was commissioned to accompany Abraham. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נ׳ לו רגלי אחד</span> a footman was joined to him (to meet his challenge). <span class=\"citation\">Ab. Zar. 25ᵇ</span> <span dir=\"rtl\">ישראל שנ׳ לו וכ׳</span> (<span class=\"citation\">Ḥull. 91ᵃ</span> <span dir=\"rtl\">שנטפל</span>) an Israelite whom a gentile joins on the road. <span class=\"citation\">Shebi. VII, 4</span> <span dir=\"rtl\">שנִזְדַּמְּנוּ להם וכ׳</span> who accidentally caught unclean animals; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to make an appointment for meeting one another</i>. <span class=\"citation\">Pesik. R. s. 33</span>, v. <a href=\"#\" data-headword=\"זִימּוּן\">זִימּוּן</a>.</div></div>","alt":[]},"11579":{"h":"זְמַן I","r":"G00536","html":"<div class=\"sense\">—<i>Part. pass</i>. <a href=\"#\" data-headword=\"זְמִין\">זְמִין</a> <i>ready, prepared</i>. <span class=\"citation\">Targ. Ex. XXXIV, 2</span> (Y. <a href=\"#\" data-headword=\"זְמִין\">זַמִין</a>, <span dir=\"rtl\">זַמְיַן</span>, incorr.).—Ib. XIX, 11; 15 <span dir=\"rtl\">זְמִינִין</span> (Y. II <span dir=\"rtl\">מְזַמְנַן</span>, v. infra).—V. <a href=\"#\" data-headword=\"זְמִינָא I\">זְמִינָא</a>.</div><div class=\"sense\"><b>Pa. זַמֵּין</b> <div class=\"sense\"><b>1)</b> <i>to invite; to appoint; to summon; to prepare</i>. <span class=\"citation\">Targ. Mic. III, 5</span>. <span class=\"citation\">Targ. Ex. XIX, 10</span>; <span class=\"citation\">14</span> (ed. Berl. <span dir=\"rtl\">זָמֵין</span>, v. Berl. Targ. O. II, p. 25); a. fr. [Ib. XXV, 22 <span dir=\"rtl\">ואִיזַמָן</span>, ed. Berl. <span dir=\"rtl\">ואֵיזָמֵין</span>, Y. <span dir=\"rtl\">אֵיזְמַן</span>, Ithpe.].—<span class=\"citation\">M. Kat. 16ᵃ</span> <span dir=\"rtl\">מְזַמְּנִינָן ליה וכ׳</span> we summon him &amp;c. <span class=\"citation\">Cant. R. to V, 13</span> <span dir=\"rtl\">ביומוי דזַמְּנִינָן וכ׳</span> (not <span dir=\"rtl\">דזמניין</span>) in those my days when we invited two parties of scholars (for discussions).—<i>Part. pass</i>. <a href=\"#\" data-headword=\"מזמן\">מְזַמַּן</a> (hebraism: <span dir=\"rtl\">מְזוּמָּן</span>). <span class=\"citation\">Targ. Ps. LXXII, 17</span> (h. text <span dir=\"rtl\">ינון</span>).—Pl. constr. <span dir=\"rtl\">מְזַמְּנֵי</span>. <span class=\"citation\">Targ. Y. Num. I, 16</span> (h. text <span dir=\"rtl\">קריאי</span>). [<span class=\"citation\">Ib. XXVI, 9</span> מנמנמי Ar., read <span dir=\"rtl\">מזמני</span>; ed. <span dir=\"rtl\">מערעי</span>).</div><div class=\"sense\"><b>—2)</b> <i>to appoint a meal in common, to say grace in common</i>. <span class=\"citation\">Ber. 45ᵇ</span> <span dir=\"rtl\">ניהדר ונְזַמֵּן</span> let us go back and agree (retrospectively) to make our meal a common one.</div></div><div class=\"sense\"><b>Af. אַזְמֵין</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"זָמַן\">same</a>. <span class=\"citation\">Targ. Y. Gen. XXIV, 7</span>. <span class=\"citation\">Targ. I Sam. XVI, 3</span>. <span class=\"citation\">Targ. Ex. XIX, 10</span> <span dir=\"rtl\">ותַזְ׳</span> some ed. v. supra; a. fr.—<span class=\"citation\">Ber. 50ᵇ</span> <span dir=\"rtl\">אַזְמוּן עלייהו</span> they counted them in for common grace, v. <a href=\"#\" data-headword=\"זָמַן\">preced.</a> <i>Pi.</i>—<span class=\"citation\">Snh. 48ᵃ</span> <span dir=\"rtl\">דאַזְמְנֵיה וכ׳</span> which one designated for &amp;c.—<span class=\"citation\">B. Bath. 58ᵃ</span> sq. <span dir=\"rtl\">אי אתי אינש מעלמא ומַזְמִין ליה לדינא</span> Ms. M. (ed. incorr.) if any unknown man will come and sue him; a. fr.</div></div><div class=\"sense\"><b>Ithpa. אִזְדַּמֵּן</b> <div class=\"sense\"><b>1)</b>  as <a href=\"#\" data-headword=\"זָמַן\">preced.</a> <i>Nithpa.</i> <span class=\"citation\">Targ. Job XXXIII, 23</span>.—<span class=\"citation\">Targ. Y. II, Gen. XIX, 31</span> <span dir=\"rtl\">למִיזְדַּמְנָא וכ׳</span> to join us in wedlock (cmp. <a href=\"#\" data-headword=\"זְוַג\">זְוַג</a>).—<span class=\"citation\">Targ. Am. III, 3</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to prepare one’s self</i>. <span class=\"citation\">Targ. Josh. VII, 13</span>; a. e. [<span class=\"citation\">Targ. Y. II, Gen. XXII, 8</span> <span dir=\"rtl\">יזדמן</span>, read <span dir=\"rtl\">יְזַמֵּן</span>.]—Contr. <span dir=\"rtl\">אִיזַּמֵּן</span>, <i>Ithpe.</i> <span dir=\"rtl\">אִיזְּמִין</span>, v. supra.</div></div>","alt":[]},"11580":{"h":"זְמָן","r":"G00537","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"זְמַן I\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>appointed time, term, time</i>. <span class=\"citation\">Kidd. I, 7</span>, a. fr. <span dir=\"rtl\">הז׳ גרמא</span>, v. <a href=\"#\" data-headword=\"גְּרָמָא\">גְּרָמָא</a>.—<span class=\"citation\">B. Kam. 113ᵃ</span> <span dir=\"rtl\">קובעים ז׳ וכ׳</span> we appoint (in the summons to appear before court) a Monday, Thursday and Monday in succession. <span class=\"citation\">Gitt. 72ᵃ</span>, a. fr. <span dir=\"rtl\">זְמַנּוֹ של שטר</span> the date of the document.—<span class=\"citation\">Taan. 14ᵇ</span>, a. fr. <span dir=\"rtl\">בז׳ הזה</span> in our days (after the dissolution of the Jewish common-wealth). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הכל לפי הז׳</span> all depends on the season (whether it is advanced or retarded, v. Rabb. D. S. a. l. note 400). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">זְמַנָּהּ של רביעה</span> the rainy season; a. v. fr.—Pl. <span dir=\"rtl\">זְמַנִּים</span>. <span class=\"citation\">Meg. 2ᵃ</span> <span dir=\"rtl\">ז׳ הרבה</span> various dates (for reading the Megillah).—בִּזְמַן שֶׁ־ <i>in the case of, when, if</i>. <span class=\"citation\">Erub. VI, 7</span> <span dir=\"rtl\">אימתי בז׳ וכ׳</span> in what case (is this said)? When they carry &amp;c. <span class=\"citation\">Ib. 6</span> <span dir=\"rtl\">ומודים בז׳ וכ׳</span> they all agree that, if some of them &amp;c.; a. v. fr.—<span dir=\"rtl\">בִּזְמַנּוֹ</span>, <span dir=\"rtl\">בִּזְמַנָהּ</span> &amp;c. <i>in its prescribed</i>, <i>due time;</i> חוּץ לִזְמַנּוֹ &amp;c. <i>out of time</i>, <i>beyond its due time</i>. <span class=\"citation\">Zeb. I, 1</span>. <span class=\"citation\">Ib. II, 3</span>; a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>festive season</i> (cmp. <a href=\"#\" data-headword=\"מִקְרָא\">מִקְרָא</a>, <a href=\"#\" data-headword=\"מְאָרְעָא\">מְאַרְעָא</a>); <i>‘Z’man’,that section of the benediction on the entrance of a Festival which refers to the return of the festive season</i> <span dir=\"rtl\">(שהחיינו והגיענו לזמן הזה …</span>). <span class=\"citation\">Pes. 102ᵇ</span> <span dir=\"rtl\">מדלא אמר ז׳</span> since he did not mention the benediction of <i>Z’man</i>, v. <span dir=\"rtl\">יקנה&quot;ז</span>. <span class=\"citation\">Succ. 48ᵃ</span> <span dir=\"rtl\">שמיני … ז׳ בפני עצמו</span> the eighth day (of Succoth) … is a festive season for itself, requiring the insertion of <i>Z’man;</i> a. fr.—<i>Pl.</i> as above. <span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> <span dir=\"rtl\">ג׳ ז׳ בבבל</span> there are three festive seasons (idolatrous fairs) in Babylonia. <span class=\"citation\">Tosef. Ber. III, 13</span> <span dir=\"rtl\">חותם ברוך … והז׳</span> you must close with ‘Blessed be He … who sanctifies the Sabbath, Israel, and the Seasons.—[<span class=\"citation\">Snh. 101ᵃ</span> <span dir=\"rtl\">הקורא … שלא בזמנו</span> he who cites a Biblical verse at a banquet out of its <i>context</i> (perverting its sense for lascivious purposes); Treat. Kallah beg.]</div>","alt":[]},"11581":{"h":"זְמַן II","r":"G00538","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Gen. XVIII, 14</span> (Y. <span dir=\"rtl\">ז׳ חגא</span>, h. text <span dir=\"rtl\">מועד</span>). Ib. II, 23 <span dir=\"rtl\">הדא ז׳</span> this time (h. text <span dir=\"rtl\">הפעם</span>); a. fr.—<span class=\"citation\">Targ. Jer. XVIII, 7</span>; <span class=\"citation\">9</span> <span dir=\"rtl\">ז׳ … וז׳</span> at one time … another time.—<span class=\"citation\">Ḥull. 105ᵇ</span> <span dir=\"rtl\">ליקבע לי מר ז׳ וכ׳</span> set me a term, and I shall pay. <span class=\"citation\">M. Kat. 16ᵃ</span> <span dir=\"rtl\">דקבעינן ז׳</span> that (in legal summons) a date is fixed for appearing in court. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ז׳ בתר ז׳</span> one term after the ofther (in case of failing to appear on the first summons). <span class=\"citation\">Ḥag. 4ᵇ</span> <span dir=\"rtl\">אזיל בלא זִימְנֵיה</span> dies before his destined time; a. v. fr.—<span class=\"citation\">B. Bath. 73ᵇ</span>, a. fr. <span dir=\"rtl\">ז׳ חדא</span> once upon a time (introducing a story).—Pl. <span dir=\"rtl\">זִמְנִין</span>, <a href=\"#\" data-headword=\"זְמַן II\">זִי׳</a>. <span class=\"citation\">Targ. Ex. XXIII, 17</span>; a. e.—<span class=\"citation\">Zeb. 94ᵇ</span>, a. fr. <span dir=\"rtl\">ז׳ סגיאין</span> many times.—<span dir=\"rtl\">ז׳</span>—ז׳ <i>at times</i> … <i>at other times</i>. <span class=\"citation\">Ber. 20ᵇ</span>, a. fr.—<span dir=\"rtl\">מַשְׁכֵּן זִימְנָא</span> = h. <span dir=\"rtl\">אֹהֶל מוֹעֵד</span>. <span class=\"citation\">Targ. Ex. XXVIII, 43</span>; a. fr.—<span class=\"citation\">Targ. Ps. LXXIV, 4</span> <span dir=\"rtl\">זִמְנָיִךְ</span> = <span dir=\"rtl\">משכני זי׳</span>.—<span class=\"citation\">Targ. Jer. XLVII, 6</span> <span dir=\"rtl\">לבית ז׳</span> to thy destined home (the sheath; h. text <span dir=\"rtl\">הֵרָגְעִי</span>!).—[<span class=\"citation\">Targ. Ps. CXLI, 4</span> בזמן משתיהון Ms (ed. <span dir=\"rtl\">בזמר בית מ׳</span>) at their <i>appointed banquets</i>, v. <a href=\"#\" data-headword=\"זְמָן\">preced.</a> wds.]</div>","alt":["זְמַנָּא","זִמְנָא","זִי׳"]},"11582":{"h":"זָמַר I","r":"G00539","html":"<div class=\"sense\"> (b. h.) <i>to nip; to prune; to cut</i>. <span class=\"citation\">Sabb. 73ᵇ</span> <span dir=\"rtl\">זוֹמֵר וצריך וכ׳</span> if one trims a tree (on the Sabbath) for making use of the wood. <span class=\"citation\">Snh. 26ᵃ</span> <span dir=\"rtl\">כהן וזומר</span> (not <span dir=\"rtl\">וזמר</span>) a priest is he, and he prunes the vine (in the sabbatical year)!; a. fr.</div><div class=\"sense\"><b>Nif. נִזְמַר</b> <div class=\"sense\"><i>to be pruned</i>, trnsf. <i>to be checked, unnerved, defeated</i>. <span class=\"citation\">Cant. R. to II, 12</span> (ref. to <a href=\"#\" data-headword=\"זְמִיר\">זמיר</a> ib.) <span dir=\"rtl\">הגיע זמנה של ערלה שתִּזָּמֵר</span> the time for pruning the preputium (circumcision) has come (v. <span class=\"citation\">Ex. R. s. 19</span>); <span dir=\"rtl\">הגיע … שיִזָּמֵרוּ</span> the time has come for the Egyptians to be checked; Pesik. Haḥod., p. 50ᵃ; <span class=\"citation\">Pesik. R. s. 15</span>.—<span class=\"citation\">Lev. R. s. 9</span>, beg. Akhan is named Zimri (<span class=\"citation\">I Chr. II, 6</span>, cmp. with <span class=\"citation\">Josh. VII, 24</span>) <span dir=\"rtl\">שנִזְמְרוּ … על ידו</span> because through him the Israelites were unnerved (<span class=\"citation\">Josh. VII, 5</span>); a. e.</div></div>","alt":[]},"11583":{"h":"זְמַר","r":"G00540","html":"<div class=\"sense\"><i>Af.</i> <a href=\"#\" data-headword=\"זְמֵי I\">אַזְמֵיר</a> same. <span class=\"citation\">Y. Shebi. IV, 35ᵃ</span> <span dir=\"rtl\">חמא חד אַ׳ וכ׳</span> (not <a href=\"#\" data-headword=\"*אִזְתַּוְודָּא\">איז׳</a>) saw one prune &amp;c. (in the Sabbatical year).</div>","alt":[]},"11584":{"h":"זָמַר II","r":"G00541","html":"<div class=\"sense\"><i>to tingle, make music, sing</i>. V. <a href=\"#\" data-headword=\"זֶמֶר I\">זֶמֶר</a>.</div><div class=\"sense\"><b>Pi. זִמֵּר</b> <div class=\"sense\"><b>1)</b> <i>to sing one’s praise</i>. <span class=\"citation\">Cant. R. to II, 16</span> <span dir=\"rtl\">הוא זִמְּרַנִי … זִמַּרְתִּיו</span> (or <span dir=\"rtl\">זְמָרַנִי</span>, <span dir=\"rtl\">זְמַרְתִּיו</span>) He praised me, and I &amp;c.—<span class=\"citation\">Gen. R. s. 91</span>, end (expl. <span dir=\"rtl\">מזמרת</span>, <span class=\"citation\">Gen. XLIII, 11</span>) <span dir=\"rtl\">דברים שהן מְזַמְּרִין וכ׳</span> things which men praise all over the world.</div><div class=\"sense\"><b>—2)</b> <i>to review a lesson in recitative chant</i> (v. <a href=\"#\" data-headword=\"זִמְרָה\">זִמְרָה</a>). <span class=\"citation\">Snh. 99ᵇ</span> top <span dir=\"rtl\">זַמֵּר בכל יום</span> chant every day; <span class=\"citation\">Tosef. Ohol. XVI, 8</span> <span dir=\"rtl\">זַ׳ בי תדירה זַ׳</span> (the Law says) review me steadily &amp;c.; ib. <span class=\"citation\">Par. IV</span> (<span class=\"citation\">III), 7</span>; cmp. <a href=\"#\" data-headword=\"גְּמָרָא\">גְּמָרָא</a>.</div></div>","alt":[]},"11585":{"h":"זְמַר ²","r":"G00542","html":"<div class=\"sense\"><i>Pa.</i> <a href=\"#\" data-headword=\"זְמִיר\">זַמֵּיר</a> same, </div><div class=\"sense\"><b>1)</b> <i>to sing</i>. <span class=\"citation\">Targ. Ps. XVIII, 50</span>; a. e.—<span class=\"citation\">Sot. 48ᵃ</span> <span dir=\"rtl\">זַמְּרי גברי וכ׳</span> when men sing and women respond.</div><div class=\"sense\"><b>—2)</b> <i>to sing a satire, deride</i>. <span class=\"citation\">Targ. Lam. III, 14</span>.</div>","alt":[]},"11586":{"h":"*זָמַר III","r":"G00543","html":"<div class=\"sense\">, <i>Hif.</i> <a href=\"#\" data-headword=\"זָהֵר\">הִזְמִיר</a> (cmp. <a href=\"#\" data-headword=\"זְמוֹרָא\">זְמוֹרָא</a>) <i>to look bluish</i>. Y’lamd. to Num. XXV, 14, quot. in Ar. (play on <a href=\"#\" data-headword=\"זִמְרִי\">זִמְרִי</a>) <span dir=\"rtl\">עד שה׳ בשרו כביצה מוזרת</span> until his flesh (through his lewdness) had the color of a smashed (rotten) egg; (cmp. Tanḥ. Pinḥ. 2, <span class=\"citation\">Num. R. s. 21</span>, beg., <span class=\"citation\">Snh. 82ᵇ</span>—where our w. is omitted).</div>","alt":[]},"11587":{"h":"זֶמֶר I","r":"G00544","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (זָמַר II) <i>music, song</i>; <span dir=\"rtl\">כלי ז׳</span> (or sub. <a href=\"#\" data-headword=\"כלי\">כלי</a>) <i>musical instrument</i>. <span class=\"citation\">Sot. 48ᵃ</span> <span dir=\"rtl\">בארבעה מיני ז׳</span> to the music of four instruments. Y. ib. VII, 21ᶜ top <span dir=\"rtl\">לעז לז׳</span> Greek is adapted for song; <span class=\"citation\">Y. Meg. I, 71ᵇ</span> bot.—<span class=\"citation\">Snh. 101ᵃ</span> <span dir=\"rtl\">ועושה אותו כמין ז׳</span> and treats it (a verse of Song of Songs) like a (secular) song; <span class=\"citation\">Yalk. Prov. 953</span>; a. fr.</div>","alt":[]},"11588":{"h":"זֶמֶר II","r":"G00545","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (זָמַר I; cmp. <span dir=\"rtl\">זמרה</span>, <span class=\"citation\">Gen. XLIII, 11</span>) <i>fruits</i>, (grapes &amp;c.), <i>dessert</i>. <span class=\"citation\">Y. Pes. X, 37ᵈ</span> bot. (expl. <a href=\"#\" data-headword=\"אֶפִּיקוֹמוֹן\">אפיקומין</a>) <span dir=\"rtl\">מיני ז׳</span> various dessert fruits (Bab. <span class=\"citation\">ib. 119ᵇ</span> <span dir=\"rtl\">תמרים וכ׳</span>; <span class=\"citation\">Tosef. ib. X, 11</span> <span dir=\"rtl\">אגוזים וכ׳</span>).</div>","alt":[]},"11589":{"h":"זַמָּר","r":"G00546","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (זָמַר I) <i>musician, singer.</i> <span class=\"citation\">Kel. XVI, 7</span> <span dir=\"rtl\">מרכוף של ז׳</span>, v. <a href=\"#\" data-headword=\"מַרְכּוֹף\">מַרְכּוֹף</a>. Yalk. Lam. 1001.</div>","alt":[]},"11590":{"h":"זַמָּרָא","r":"G00547","html":"<div class=\"sense\">—<i>Pl.</i> <span dir=\"rtl\">זַמָּרַיָּא</span>. <span class=\"citation\">Targ. Koh. II, 8</span>.—Fem. pl. <a href=\"#\" data-headword=\"זַמַּרְתָּא\">זַמַּרְיָתָא</a>. Ib.</div>","alt":[]},"11591":{"h":"זְמָרָא I","r":"G00548","html":"<div class=\"sense\">—<span dir=\"rtl\">(<span dir=\"rtl\">זַיְינֵי</span>) <span dir=\"rtl\">זְנֵי ז׳</span></span> = (<a href=\"#\" data-headword=\"כְּלֵי\">כְּלֵי</a>) <span dir=\"rtl\">מִינֵי זֶמֶר</span> <i>musical instruments.</i> <span class=\"citation\">Dan. III, 5</span>; a. e.—<span class=\"citation\">Targ. Koh. II, 8</span>.—<span class=\"citation\">Targ. Ez. XXXIII, 32</span> <span dir=\"rtl\">זְמַר אבובין</span> flute-music.—Pl. <span dir=\"rtl\">זְמָרַיָּא</span>. <span class=\"citation\">Targ. Lam. V, 14</span>.—<span class=\"citation\">Ib. III, 63</span> <span dir=\"rtl\">זְמָרֵיהוֹן</span> object of their derisive songs, v. <a href=\"#\" data-headword=\"זָמַר II\"><span dir=\"rtl\">זְמַר</span> II</a>.</div>","alt":[]},"11592":{"h":"זִמְרָא","r":"G00549","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"זְמָרָא I\">same</a>, <i>song, music</i>. <span class=\"citation\">Gitt. 7ᵃ</span> <span dir=\"rtl\">ז׳ מנא לן וכ׳</span> how is it proved that music (at banquets, after the destruction of the Temple) is forbidden? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ז׳ דמנא</span> instrumental music, <span dir=\"rtl\">ז׳ דפומא</span> vocal music. <span class=\"citation\">Sot. 48ᵃ</span> <span dir=\"rtl\">ז׳ בביתא וכ׳</span> music in the house—destruction at the threshold. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בטיל ז׳</span> prohibited musical entertainments.—<span class=\"citation\">Sabb. 118ᵇ</span> <span dir=\"rtl\">פסוקי דז׳</span> verses of praise (<span class=\"citation\">Ps. CXLVIII</span> a. <span class=\"citation\">CL</span>; v. Rabb. D. S. a. l. note 200).—Pl. <a href=\"#\" data-headword=\"זִבְרִין\">זִמְרִין</a>, <a href=\"#\" data-headword=\"זְמַן II\">זִי׳</a>. <span class=\"citation\">Y. Meg. III, 74ᵃ</span> bot. <span dir=\"rtl\">הוה דמיך וקאים בזי׳</span> used to go to bed and rise with music.—V. <a href=\"#\" data-headword=\"זִמְרָה\">זִמְרָה</a>.</div>","alt":["זִימְ׳ I"]},"11593":{"h":"זִמְרָא ²","r":"G00550","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Zimra</i>, father of R. Yosé, v. <a href=\"#\" data-headword=\"יוֹסֵי\">יוֹסֵי</a>. <span class=\"citation\">Keth. 96ᵃ</span>; a. fr.</div>","alt":["זִי׳ II"]},"11594":{"h":"זְמַרְגַּד","r":"G00551","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (σμάραγδος) <i>smaragd, emerald, colored crystal</i> (v. Sm. Ant. s. v.). <span class=\"citation\">Targ. Prov. XXV, 12</span>; a. fr. (in the sense of a precious stone [v. next w.], and as crystal or spar of copper mine).—<i>Pl. h</i>. <a href=\"#\" data-headword=\"זְמַרַגְדִּין\">זְמַרְגְּדִין</a>. <span class=\"citation\">Lev. R. s. 2</span> (precious stones).</div>","alt":["זְמַרְגְּדָא","(זמרגדד","זמרגדז)"]},"11595":{"h":"זְמַרַגְדִּין","r":"G00552","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (σμαράγδιον) <i>emerald</i>, a precious stone. <span class=\"citation\">Targ. Y. II, Ex. XXVIII, 19</span>, v. <a href=\"#\" data-headword=\"אִזְמַרְגַּד\">אִזְמַרְגַּד</a>.</div>","alt":["זְמַרְגַּדִּין"]},"11596":{"h":"זְמֹרָה","r":"G00553","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זְמוֹרָה\">זְמוֹֹרָה</a></div>","alt":[]},"11597":{"h":"זִמְרָה","r":"G00554","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (זָמַר II) <i>chant on reciting Talmudic lessons</i>. <span class=\"citation\">Meg. 32ᵃ</span> (some ed. <a href=\"#\" data-headword=\"(זִימְרָא\">זימרא</a>); <span class=\"citation\">Treat. Sof’rim III, 10</span>.</div>","alt":["זִימְ׳"]},"11598":{"h":"זִמְרִי","r":"G00555","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Zimri</i>, slain by Phinehas (<span class=\"citation\">Num. XXV, 14</span>). <span class=\"citation\">Snh. 82ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"*זָמַר III\"><span dir=\"rtl\">זָמַר</span> III</a>. <span class=\"citation\">Y. Taan. III, 66ᶜ</span> bot. <span dir=\"rtl\">כמה ז׳ וכ׳</span> how mani Zimris (lewd men) are in our days!; a. fr.</div>","alt":[]},"11599":{"h":"זַמַּרְתָּא","r":"G00556","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"זַמָּרָא\">זַמָּרָא</a></div>","alt":["זַמַּרְיָתָא"]}};
